    public interface LwM2M {

        /** Permissive defaults for LwM2M-sourced data: the registry states no ceiling for instances or blobs. */
        enum _DefaultMaxLengthOf {
            Arrays  = 65_535,
            Maps    = 65_535,
            Sets    = 65_535,
            Strings = 65_535,
        }

        /**
        LwM2M Objlnk value: a reference to an object instance, 16-bit object id and 16-bit instance id.
        Used only as a field type, so it stays a non-transmittable value pack.
        */
        class ObjectLink {
            ushort object_id;
            ushort instance_id;
        }

        // ═════════════════════════ 0.xml: LWM2M Security (urn:oma:lwm2m:oma:0:1.2) ═════════════════════════
        /**
        This LwM2M Object provides the keying material of a LwM2M Client appropriate to access a specified LwM2M
        Server. One Object Instance SHOULD address a LwM2M Bootstrap-Server.
        These LwM2M Object Resources MUST only be changed by a LwM2M Bootstrap-Server or Bootstrap from Smartcard and
        MUST NOT be accessible by any other LwM2M Server.
        */
        class LWM2M_Security {
            public const ushort lwm2m_object_id          = 0;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:0:1.2";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.2";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = true;

            /**
            Uniquely identifies the LwM2M Server or LwM2M Bootstrap-Server. The format of the CoAP URI is defined in
            Section 6 of RFC 7252.
            */
            [D(+255), ResourceId(0), Mandatory] string LWM2M_Server_URI;

            /**
            Determines if the current instance concerns a LwM2M Bootstrap-Server (true) or a standard LwM2M Server (false)
            */
            [ResourceId(1), Mandatory] bool Bootstrap_Server;

            /**
            Determines which security mode is used
            0: Pre-Shared Key mode
            1: Raw Public Key mode
            2: Certificate mode
            3: NoSec mode
            4: Certificate mode with EST
            */
            [MinMax(0, 4), ResourceId(2), Mandatory] byte Security_Mode;

            /**
            Stores the LwM2M Client's certificate, public key (RPK mode) or PSK Identity (PSK mode).
            */
            [D(65535), ResourceId(3), Mandatory] Binary[,,] Public_Key_or_Identity;

            /**
            Stores the LwM2M Server's, respectively LwM2M Bootstrap-Server's, certificate, public key (RPK mode) or trust
            anchor. The Certificate Mode Resource determines the content of this resource.
            */
            [D(65535), ResourceId(4), Mandatory] Binary[,,] Server_Public_Key;

            /**
            Stores the secret key (PSK mode) or private key (RPK or certificate mode).
            */
            [D(65535), ResourceId(5), Mandatory] Binary[,,] Secret_Key;

            /**
            Determines which SMS security mode is used:
            0: Reserved for future use
            1: DTLS mode (Device terminated) PSK mode assumed
            2: Secure Packet Structure mode (Smartcard terminated)
            3: NoSec mode
            4: Reserved mode (DTLS mode with multiplexing Security Association support)
            5-203 : Reserved for future use
            204-255: Proprietary modes
            */
            [ResourceId(6)] byte? SMS_Security_Mode;

            /**
            Stores the KIc, KID, SPI and TAR.
            */
            [D(6), ResourceId(7)] Binary[,,] SMS_Binding_Key_Parameters;

            /**
            Stores the values of the key(s) for the SMS binding.
            */
            [D(48), ResourceId(8)] Binary[,,] SMS_Binding_Secret_Key_s;

            /**
            MSISDN used by the LwM2M Client to send messages to the LwM2M Server via the SMS binding.
            */
            [ResourceId(9)] string LwM2M_Server_SMS_Number;

            /**
            This identifier uniquely identifies each LwM2M Server configured for the LwM2M Client.
            This Resource MUST be set when the Bootstrap-Server Resource has a value of 'false'.
            The values ID:0 and ID:65535 values MUST NOT be used for identifying the LwM2M Server.
            */
            [MinMax(1, 65534), ResourceId(10)] ushort? Short_Server_ID;

            /**
            The number of seconds to wait before initiating a Client Initiated Bootstrap once the LwM2M Client has
            determined it should initiate this bootstrap mode.
            In case client initiated bootstrap is supported by the LwM2M Client, this resource MUST be supported. This
            information is relevant for use with a Bootstrap-Server only.
            */
            [ResourceId(11), Units("s")] DurationInSeconds? Client_Hold_Off_Time;

            /**
            The LwM2M Client MUST purge the LwM2M Bootstrap-Server Account after the timeout value given by this resource.
            The lowest timeout value is 1.
            If the value is set to 0, or if this resource is not instantiated, the Bootstrap-Server Account lifetime is
            infinite.
            */
            [ResourceId(12), Units("s")] DurationInSeconds? Bootstrap_Server_Account_Timeout;

            /**
            The Matching Type Resource specifies how the certificate or raw public key in in the Server Public Key is
            presented. Four values are currently defined:
            0: Exact match. This is the default value and also corresponds to the functionality of LwM2M v1.0. Hence, if
            this resource is not present then the content of the Server Public Key Resource corresponds to this value.
            1: SHA-256 hash [RFC6234]
            2: SHA-384 hash [RFC6234]
            3: SHA-512 hash [RFC6234]
            */
            [MinMax(0, 3), ResourceId(13)] byte? Matching_Type;

            /**
            This resource holds the value of the Server Name Indication (SNI) value to be used during the TLS handshake.
            When this resource is present then the LwM2M Server URI acts as the address of the service while the SNI value
            is used for matching a presented certificate, or PSK identity.
            */
            [ResourceId(14)] string SNI;

            /**
            The Certificate Usage Resource specifies the semantic of the certificate or
            raw public key stored in the Server Public Key Resource, which is used to match
            the certificate presented in the TLS/DTLS handshake. The currently defined values are
            0 for "CA constraint", 1 for "service certificate constraint", 2 for "trust anchor
            assertion", and 3 for "domain-issued certificate". When this resource is absent,
            value (3) for domain issued certificate mode is assumed. More details about the
            semantic of each value can be found in the security consideration section of the
            LwM2M specification.
            */
            [MinMax(0, 3), ResourceId(15)] byte? Certificate_Usage;

            /**
            When this resource is present it instructs the TLS/DTLS client to propose the indicated ciphersuite(s) in the
            ClientHello of the handshake. A ciphersuite is indicated as a 32-bit integer value. The IANA TLS ciphersuite
            registry is maintained at https://www.iana.org/assignments/tls-parameters/tls-parameters.xhtml. As an example,
            the TLS_PSK_WITH_AES_128_CCM_8 ciphersuite is represented with the following string "0xC0,0xA8". To form an
            integer value the two values are concatenated. In this example, the value is 0xc0a8 or 49320.
            */
            [ResourceId(16)] ulong[,,] DTLS_TLS_Ciphersuite;

            /**
            If this resource is defined, it provides a link to the OSCORE Object Instance and OSCORE MUST be used by the
            LwM2M Client with the linked OSCORE Object Instance.
            */
            [ResourceId(17)] ObjectLink? OSCORE_Security_Mode;

            /**
            If this resource is defined, it indicates what groups the LwM2M Client should use with a LwM2M Server/LwM2M
            Bootstrap-Server (ordered from most preferred to least preferred). Resource instance 0 indicates the most
            preferred group. The values are taken from Section 4.2.7 of RFC 8446. An example is secp256r1 (0x0017).
            */
            [ResourceId(18)] ushort[,,] Groups_To_Use_by_Client;

            /**
            If this resource is defined, it indicates what signature algorithms the LwM2M Server/LwM2M Bootstrap-Server
            supports. The values are taken from Section 4.2.3 of RFC 8446. An example is ecdsa_secp256r1_sha256(0x0403).
            */
            [ResourceId(19)] ushort[,,] Signature_Algorithms_Supported_by_Server;

            /**
            If this resource is defined, it indicates what signature algorithms the LwM2M Client should use with a LwM2M
            Server/LwM2M Bootstrap-Server (ordered from most preferred to least preferred). Resource instance 0 indicates
            the most preferred group. The values are taken from Section 4.2.3 of RFC 8446. An example is
            ecdsa_secp256r1_sha256(0x0403).
            */
            [ResourceId(20)] ushort[,,] Signature_Algorithms_To_Use_by_Client;

            /**
            If this resource is defined, it indicates what certificate-specific signature algorithms the the LwM2M
            Server/LwM2M Bootstrap-Server supports. The values are taken from Section 4.2.3 of RFC 8446. An example is
            ecdsa_secp256r1_sha256(0x0403).
            */
            [ResourceId(21)] ushort[,,] Signature_Algorithm_Certs_Supported_by_Server;

            /**
            If this resource is defined, it indicates which features the LwM2M Client should use with the respective LwM2M
            Server/LwM2M Bootstrap-Server. The bitmask values listed below are defined. A bit value of '0' means the
            feature should not be used. bit(0) - PSK Plain, bit(1) - 0-RTT, bit(2) - PSK with PFS, bit(3) -
            Certificate-based Authentication. Bit(4) to bit(31) are reserved.
            */
            [ResourceId(22)] ushort? TLS_1_3_Features_To_Use_by_Client;

            /**
            If this resource is defined, it indicates what extensions the LwM2M Server/LwM2M Bootstrap-Server supports in
            form of a bitmap.  The following values are defined: bit(0) - Server Name Indication (RFC 6066), bit (1) - Max
            Fragment Length (RFC 6066), bit (2) - Status Request (RFC 6066), bit (3) - Heartbeat (RFC 6520), bit (4) -
            Application Layer Protocol Negotiation (RFC 7301), bit (5) - Signed Certificate Timestamp (RFC 6962), bit (6)
            - Certificate Compression (draft-ietf-tls-certificate-compression), bit (7) - Record Size Limit (RFC 8449),
            bit (8) - Ticket Pinning (draft-ietf-tls-pinning-ticket), bit (9) - Certificate Authorities (RFC 8446), bit
            (10) - OID Filters (RFC 8446), bit (11) - Post Handshake Auth (RFC 8446), bit (12) - Connection ID
            (draft-ietf-tls-dtls-connection-id/draft-ietf-tls-dtls13). Bit(13) to bit(31) are reserved.
            */
            [ResourceId(23)] ushort? TLS_Extensions_Supported_by_Server;

            /**
            If this resource is defined, it indicates what extensions the LwM2M Client should use with the LwM2M
            Server/LwM2M Bootstrap-Server in form of a bitmap. The following values are defined: bit(0) - Server Name
            Indication (RFC 6066), bit (1) - Max Fragment Length (RFC 6066), bit (2) - Status Request (RFC 6066), bit (3)
            - Heartbeat (RFC 6520), bit (4) - Application Layer Protocol Negotiation (RFC 7301), bit (5) - Signed
            Certificate Timestamp (RFC 6962), bit (6) - Certificate Compression (draft-ietf-tls-certificate-compression),
            bit (7) - Record Size Limit (RFC 8449), bit (8) - Ticket Pinning (draft-ietf-tls-pinning-ticket), bit (9) -
            Certificate Authorities (RFC 8446), bit (10) - OID Filters (RFC 8446), bit (11) - Post Handshake Auth (RFC
            8446), bit (12) - Connection ID (draft-ietf-tls-dtls-connection-id/draft-ietf-tls-dtls13). Bit(13) to bit(31)
            are reserved.
            */
            [ResourceId(24)] ushort? TLS_Extensions_To_Use_by_Client;

            /**
            If this resource is present then the LwM2M Server URI in the Security Object, Resource ID 0, is augmented with
            information about further LwM2M Server URIs that can be used with the same security information found in the
            LwM2M Security Object. This is useful when a LwM2M Server is reachable via two different transport bindings
            (i.e. URIs). For example when the same server is reachable with two different URIs, such as a "coaps" and a
            "coaps+tcp" URI scheme.
            */
            [D(+255), ResourceId(25)] string[,,] Secondary_LwM2M_Server_URI;

            /**
            If this resource is defined, it provides a link to a MQTT Server Object Instance, which offers additional
            configuration information for use with this MQTT server. This Resource is used only when the URI scheme in the
            LwM2M Server URI Resource indicates the use of MQTT.
            */
            [ResourceId(26)] ObjectLink? MQTT_Server;

            /**
            If this resource is defined, it provides a links to LwM2M COSE Object Instances, which contain
            security-relevant configuration information for use with COSE.
            */
            [ResourceId(27)] ObjectLink[,,] LwM2M_COSE_Security;

            /**
            This resource provides the default RDS Destination Port Number (as defined in 3GPP TS 24.250) to use for
            contacting the LwM2M or Bootstrap Server when communicating through the SCEF across the Non-IP binding.
            */
            [MinMax(0, 15), ResourceId(28)] byte? RDS_Destination_Port;

            /**
            This resource provides the default RDS Source Port Number (as defined in 3GPP TS 24.250) to use for contacting
            the LwM2M or Bootstrap Server when communicating through the SCEF across the Non-IP binding.
            */
            [MinMax(0, 15), ResourceId(29)] byte? RDS_Source_Port;

            /**
            This resource provides the Application ID (as defined in 3GPP TS 24.250) to use for querying the SCEF for the
            source and destination port numbers for contacting the LwM2M or Bootstrap Server when communicating through
            the SCEF across the Non-IP binding.
            */
            [ResourceId(30)] string RDS_Application_ID;
        }

        // ═════════════════════════ 1.xml: LwM2M Server (urn:oma:lwm2m:oma:1:1.2) ═════════════════════════
        /**
        This LwM2M Objects provides the data related to a LwM2M Server. A Bootstrap-Server has no such an Object
        Instance associated to it.
        */
        class LwM2M_Server {
            public const ushort lwm2m_object_id          = 1;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:1:1.2";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.2";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = true;

            /**
            Used as link to associate server Object Instance.
            */
            [MinMax(1, 65534), ResourceId(0), Operations("R"), Mandatory] ushort Short_Server_ID;

            /**
            Specify the lifetime of the registration in seconds (see Client Registration Interface). If the value is set
            to 0, the lifetime is infinite.
            */
            [ResourceId(1), Operations("RW"), Units("s"), Mandatory] DurationInSeconds Lifetime;

            /**
            The default value the LwM2M Client should use for the Minimum Period of an Observation in the absence of this
            parameter being included in an Observation.
            If this Resource doesn’t exist, the default value is 0.
            */
            [ResourceId(2), Operations("RW"), Units("s")] DurationInSeconds? Default_Minimum_Period;

            /**
            The default value the LwM2M Client should use for the Maximum Period of an Observation in the absence of this
            parameter being included in an Observation.
            */
            [ResourceId(3), Operations("RW"), Units("s")] DurationInSeconds? Default_Maximum_Period;

            /**
            A period to disable the Server. After this period, the LwM2M Client MUST perform registration process to the
            Server. If this Resource is not set, a default timeout value is 86400 (1 day).
            */
            [ResourceId(5), Operations("RW"), Units("s")] DurationInSeconds? Disable_Timeout;

            /**
            If true, the LwM2M Client stores "Notify" operations to the LwM2M Server while the LwM2M Server account is
            disabled or the LwM2M Client is offline. After the LwM2M Server account is enabled or the LwM2M Client is
            online, the LwM2M Client reports the stored "Notify" operations to the Server.
            If false, the LwM2M Client discards all the "Notify" operations or temporarily disables the Observe function
            while the LwM2M Server is disabled or the LwM2M Client is offline.
            The default value is true.
            The maximum number of storing Notifications per Server is up to the implementation.
            */
            [ResourceId(6), Operations("RW"), Mandatory] bool Notification_Storing_When_Disabled_or_Offline;

            /**
            The possible values are those listed in the LwM2M Core Specification. This Resource defines the transport
            binding configured for the LwM2M Client.
            If the LwM2M Client supports the binding specified in this Resource, the LwM2M Client MUST use that transport
            for the Current Binding Mode.
            */
            [ResourceId(7), Operations("RW"), Mandatory] string Binding;

            /**
            If this resource is defined, it provides a link to the APN connection profile Object Instance (OMNA registered
            Object ID:11) to be used to communicate with this server.
            */
            [ResourceId(10), Operations("RW")] ObjectLink? APN_Link;

            /**
            If this resource is defined, it contains the most recent TLS / DTLS alert message received from the LwM2M
            Server respective represented by the AlertDescription defined in Section 7.2 of RFC 5246. This resource set by
            the LwM2M Client may help the LwM2M Bootstrap-Server to determine the cause of TLS/DTLS connection failure
            with the respective LwM2M Server.
            */
            [ResourceId(11), Operations("R")] byte? TLS_DTLS_Alert_Code;

            /**
            If this resource is defined, it represents the last time that the bootstrap server updated this LwM2M Server
            Account. The LwM2M Client is responsible for updating this value. When the Bootstrap Server detects that this
            LwM2M Server Account is "out-of-date", the Bootstrap Server can update the LwM2M Server Account as represented
            by the LwM2M Server object instance.
            */
            [ResourceId(12), Operations("R")] DateTime? Last_Bootstrapped;

            /**
            The LwM2M Client sequences the LwM2M Server registrations in increasing order of this value. If this value is
            not defined, registration attempts to this server are not impacted by other server registrations.
            */
            [ResourceId(13), Operations("R")] ulong? Registration_Priority_Order;

            /**
            The delay, in seconds, before registration is attempted for this LwM2M Server based upon the completion of
            registration of the previous LwM2M Server in the registration order. This is only applied until the first
            successful registration after a successful bootstrapping sequence.
            */
            [ResourceId(14), Operations("RW"), Units("s")] DurationInSeconds? Initial_Registration_Delay_Timer;

            /**
            When set to true and registration to this LwM2M server fails, the LwM2M Client blocks registration to other
            servers in the order. When set to false, the LwM2M Client proceeds with registration to the next server in the
            order.
            */
            [ResourceId(15), Operations("R")] bool? Registration_Failure_Block;

            /**
            If set to true, this indicates that the LwM2M Client should re-bootstrap when either registration is
            explicitly rejected by the LwM2M Server or registration is considered as failing as dictated by the other
            resource settings. If set to false, the LwM2M Client will continue with the registration attempts as dictated
            by the other resource settings.
            */
            [ResourceId(16), Operations("R")] bool? Bootstrap_on_Registration_Failure;

            /**
            The number of successive communication attempts before which a communication sequence is considered as failed.
            */
            [ResourceId(17), Operations("RW")] ulong? Communication_Retry_Count;

            /**
            The delay, in seconds, between successive communication attempts in a communication sequence. This value is
            multiplied by two to the power of the communication retry attempt minus one (2**(retry attempt-1)) to create
            an exponential back-off.
            */
            [ResourceId(18), Operations("RW"), Units("s")] ulong? Communication_Retry_Timer;

            /**
            The delay, in seconds, between successive communication sequences. A communication sequence is defined as the
            exhaustion of the Communication Retry Count and Communication Retry Timer values. A communication sequence can
            be applied to server registrations or bootstrapping attempts. MAX_VALUE means do not perform another
            communication sequence.
            */
            [ResourceId(19), Operations("RW"), Units("s")] DurationInSeconds? Communication_Sequence_Delay_Timer;

            /**
            The number of successive communication sequences before which a registration attempt is considered as failed.
            */
            [ResourceId(20), Operations("RW")] ulong? Communication_Sequence_Retry_Count;

            /**
            Using the Trigger Resource a LwM2M Client can indicate whether it is reachable over SMS (value set to 'true')
            or not (value set to 'false'). The default value (resource not present) is 'false'. When set to 'true' the
            LwM2M Server MAY, for example, request the LwM2M Client to perform operations, such as the "Update" operation
            by sending an "Execute" operation on "Registration Update Trigger" Resource via SMS. No SMS response is
            expected for such a message.
            */
            [ResourceId(21), Operations("RW")] bool? Trigger;

            /**
            Only a single transport binding SHALL be present. When the LwM2M client supports multiple transports, it MAY
            use this transport to initiate a connection. This resource can also be used to switch between multiple
            transports e.g. a non-IP device can switch to UDP transport to perform firmware updates.
            */
            [Range("The possible values are those listed in the LwM2M Core Specification"), ResourceId(22), Operations("RW")] string Preferred_Transport;

            /**
            If true or the Resource is not present, the LwM2M Client Send command capability is de-activated.
            If false, the LwM2M Client Send Command capability is activated.
            */
            [ResourceId(23), Operations("RW")] bool? Mute_Send;

            /**
            If this resource is defined, it provides links to alternate APN connection profile Object Instance (OMNA
            registered Object ID:11) to be used to communicate with this server if Resource 10 has configuration
            conflicts.
            */
            [ResourceId(24), Operations("RW")] ObjectLink[,,] Alternate_APN_Links;

            /**
            This resource provides the supported enabler versions of the server to the client as a set of strings. Format
            for each string is 1*DIGIT"."1*DIGIT"."1*DIGIT where the third DIGIT is optional.
            */
            [ResourceId(25), Operations("RW")] string[,,] Supported_Server_Versions;

            /**
            This resource indicates the default mode for observations to be sent: 0 = Non-Confirmable, 1 = Confirmable.
            */
            [MinMax(0, 1), ResourceId(26), Operations("RW")] byte? Default_Notification_Mode;

            /**
            If this resource is defined, it contains the hash algorithm the LwM2M Server would prefer the LwM2M Client to
            use with the dynamically generated mode of creating Profile IDs. The numerical ID value of the 'Suite
            Identifiers' registered by RFC 6920 is used in this Resource.
            */
            [ResourceId(27), Operations("RW")] byte? Profile_ID_Hash_Algorithm;

            /**
            If this Resource is executed, this LwM2M Server Object is disabled for a certain period defined in the
            Disabled Timeout Resource. After receiving "Execute" operation, LwM2M Client MUST send response of the
            operation and perform de-registration process, and underlying network connection between the Client and Server
            MUST be disconnected to disable the LwM2M Server account.
            After the above process, the LwM2M Client MUST NOT send any message to the Server and ignore all the messages
            from the LwM2M Server for the period.
            Execute operation on resource 4 (Disable); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E")] public class Disable_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            If this Resource is executed the LwM2M Client MUST perform an "Update" operation with this LwM2M Server. The
            LwM2M Client can use a transport binding supported in the Current Binding Mode, Preferred Transport resource
            or the transport specified as an argument in the Registration Update Trigger.
            Execute operation on resource 8 (Registration Update Trigger); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E"), Mandatory] public class Registration_Update_Trigger_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            When this Resource is executed the LwM2M Client MUST initiate a "Client Initiated Bootstrap" procedure in
            using the LwM2M Bootstrap-Server Account.
            Execute operation on resource 9 (Bootstrap-Request Trigger); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Bootstrap_Request_Trigger_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 2.xml: LwM2M Access Control (urn:oma:lwm2m:oma:2:1.1) ═════════════════════════
        /**
        Access Control Object is used to check whether the LwM2M Server has access right for performing an operation.
        */
        class LwM2M_Access_Control {
            public const ushort lwm2m_object_id          = 2;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:2:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Resources 0 and 1 point to the Object Instance for which the Instances of the ACL Resource of that Access
            Control Object Instance are applicable.
            */
            [MinMax(1, 65534), ResourceId(0), Operations("R"), Mandatory] ushort Object_ID;

            /**
            See above
            */
            [ResourceId(1), Operations("R"), Mandatory] ushort Object_Instance_ID;

            /**
            The Resource Instance ID MUST be the Short Server ID of a certain LwM2M Server for which associated access
            rights are contained in the Resource Instance value.
            The Resource Instance ID 0 is a specific ID, determining the ACL Instance which contains the default access
            rights.
            Each bit set in the Resource Instance value, grants an access right to the LwM2M Server to the corresponding
            operation.
            The bit order is specified as below.
            1st LSB: R(Read, Observe, Write-Attributes)
            2nd LSB: W(Write)
            3rd LSB: E(Execute)
            4th LSB: D(Delete)
            5th LSB: C(Create)
            Other bits are reserved for future use.
            */
            [MinMax(0, 31), ResourceId(2), Operations("RW")] byte[,,] ACL;

            /**
            Short Server ID of a certain LwM2M Server; only such an LwM2M Server can manage the Resources of this Object
            Instance.
            The specific value MAX_ID=65535 means this Access Control Object Instance is created and modified during a
            Bootstrap phase only.
            */
            [ResourceId(3), Operations("RW"), Mandatory] ushort Access_Control_Owner;
        }

        // ═════════════════════════ 3.xml: Device (urn:oma:lwm2m:oma:3:1.3) ═════════════════════════
        /**
        This LwM2M Object provides a range of device related information which can be queried by the LwM2M Server, and
        a device reboot and factory reset function.
        */
        class Device {
            public const ushort lwm2m_object_id          = 3;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:3:1.3";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.3";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = true;

            /**
            Human readable manufacturer name
            */
            [ResourceId(0), Operations("R")] string Manufacturer;

            /**
            A model identifier (manufacturer specified string)
            */
            [ResourceId(1), Operations("R")] string Model_Number;

            /**
            Serial Number
            */
            [ResourceId(2), Operations("R")] string Serial_Number;

            /**
            Current firmware version of the Device.The Firmware Management function could rely on this resource.
            */
            [ResourceId(3), Operations("R")] string Firmware_Version;

            /**
            0: DC power
            1: Internal Battery
            2: External Battery
            3: Fuel Cell
            4: Power over Ethernet
            5: USB
            6: AC (Mains) power
            7: Solar
            The same Resource Instance ID MUST be used to associate a given Power Source (Resource ID:6) with its Present
            Voltage (Resource ID:7) and its Present Current (Resource ID:8)
            */
            [MinMax(0, 7), ResourceId(6), Operations("R")] byte[,,] Available_Power_Sources;

            /**
            Present voltage for each Available Power Sources Resource Instance. The unit used for this resource is in mV.
            */
            [ResourceId(7), Operations("R")] long[,,] Power_Source_Voltage;

            /**
            Present current for each Available Power Source. The unit used for this resource is in mA.
            */
            [ResourceId(8), Operations("R")] long[,,] Power_Source_Current;

            /**
            Contains the current battery level as a percentage (with a range from 0 to 100). This value is only valid for
            the Device internal Battery if present (one Available Power Sources Resource Instance is 1).
            */
            [MinMax(0, 100), ResourceId(9), Operations("R"), Units("/100")] byte? Battery_Level;

            /**
            Estimated current available amount of storage space which can store data and software in the LwM2M Device
            (expressed in kilobytes). Note: 1 kilobyte corresponds to 1000 bytes.
            */
            [ResourceId(10), Operations("R")] long? Memory_Free;

            /**
            0=No error
            1=Low battery power
            2=External power supply off
            3=GPS module failure
            4=Low received signal strength
            5=Out of memory
            6=SMS failure
            7=IP connectivity failure
            8=Peripheral malfunction
            9..15=Reserved for future use
            16..32=Device specific error codes
            When the single Device Object Instance is initiated, there is only one error code Resource Instance whose
            value is equal to 0 that means no error. When the first error happens, the LwM2M Client changes error code
            Resource Instance to any non-zero value to indicate the error type. When any other error happens, a new error
            code Resource Instance is created. When an error associated with a Resource Instance is no longer present,
            that Resource Instance is deleted. When the single existing error is no longer present, the LwM2M Client
            returns to the original no error state where Instance 0 has value 0.
            This error code Resource MAY be observed by the LwM2M Server. How to deal with LwM2M Client’s error report
            depends on the policy of the LwM2M Server. Error codes in between 16 and 32 are specific to the Device and may
            have different meanings among implementations.
            */
            [MinMax(0, 32), ResourceId(11), Operations("R"), Mandatory] byte[,,] Error_Code;

            /**
            Current UNIX time of the LwM2M Client.
            The LwM2M Client should be responsible to increase this time value as every second elapses.
            The LwM2M Server is able to write this Resource to make the LwM2M Client synchronized with the LwM2M Server.
            */
            [ResourceId(13), Operations("RW")] DateTime? Current_Time;

            /**
            Indicates the UTC offset currently in effect for this LwM2M Device. UTC+X [ISO 8601].
            */
            [ResourceId(14), Operations("RW")] string UTC_Offset;

            /**
            Indicates in which time zone the LwM2M Device is located, in IANA Timezone (TZ) database format.
            */
            [ResourceId(15), Operations("RW")] string Timezone;

            /**
            Indicates which bindings and modes are supported in the LwM2M Client. The possible values are those listed in
            the LwM2M Core Specification.
            */
            [ResourceId(16), Operations("R"), Mandatory] string Supported_Binding_and_Modes;

            /**
            Type of the device (manufacturer specified string: e.g. smart meters / dev Class / ...)
            */
            [ResourceId(17), Operations("R")] string Device_Type;

            /**
            Current hardware version of the device
            */
            [ResourceId(18), Operations("R")] string Hardware_Version;

            /**
            Current software version of the device (manufacturer specified string). On elaborated LwM2M device, SW could
            be split in 2 parts: a firmware one and a higher level software on top.
            Both pieces of Software are together managed by LwM2M Firmware Update Object (Object ID 5)
            */
            [ResourceId(19), Operations("R")] string Software_Version;

            /**
            This value is only valid for the Device Internal Battery if present (one Available Power Sources Resource
            Instance value is 1).
            Battery
            Status	Meaning	Description
            0	Normal	The battery is operating normally and not on power.
            1	Charging	The battery is currently charging.
            2	Charge Complete	The battery is fully charged and still on power.
            3	Damaged	The battery has some problem.
            4	Low Battery	The battery is low on charge.
            5	Not Installed	The battery is not installed.
            6	Unknown	The battery information is not available.
            */
            [MinMax(0, 6), ResourceId(20), Operations("R")] byte? Battery_Status;

            /**
            Total amount of storage space which can store data and software in the LwM2M Device (expressed in kilobytes). 
            Note: 1 kilobyte corresponds to 1000 bytes.
            */
            [ResourceId(21), Operations("R")] long? Memory_Total;

            /**
            Reference to external "Device" object instance containing information. For example, such an external device
            can be a Host Device, which is a device into which the Device containing the LwM2M client is embedded. This
            Resource may be used to retrieve information about the Host Device.
            */
            [ResourceId(22), Operations("R")] ObjectLink[,,] ExtDevInfo;

            /**
            Reboot the LwM2M Device to restore the Device from unexpected firmware failure.
            Execute operation on resource 4 (Reboot); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E"), Mandatory] public class Reboot_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Perform factory reset of the LwM2M Device to make the LwM2M Device to go through initial deployment sequence
            where provisioning and bootstrap sequence is performed. This requires client ensuring post factory reset to
            have minimal information to allow it to carry out one of the bootstrap methods specified in section 5.2.3.
            When this Resource is executed, "De-register" operation MAY be sent to the LwM2M Server(s) before factory
            reset of the LwM2M Device.
            No Argument or Argument = 0 indicates that the Client MUST preserve its IDevID upon factory reset.
            Argument = 1 indicates that the Client MUST preserve both IDevID and LDevID upon factory reset.
            Execute operation on resource 5 (Factory Reset); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Factory_Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Delete all error code Resource Instances and create only one zero-value error code that implies no error, then
            re-evaluate all error conditions and update and create Resources Instances to capture all current error
            conditions.
            Execute operation on resource 12 (Reset Error Code); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E")] public class Reset_Error_Code_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 4.xml: Connectivity Monitoring (urn:oma:lwm2m:oma:4:1.3) ═════════════════════════
        /**
        This LwM2M Object enables monitoring of parameters related to network connectivity.
        In this general connectivity Object, the Resources are limited to the most general cases common to most
        network bearers. It is recommended to read the description, which refers to relevant standard development
        organizations (e.g. 3GPP, IEEE).
        The goal of the Connectivity Monitoring Object is to carry information reflecting the more up to date values
        of the current connection for monitoring purposes. Resources such as Link Quality, Radio Signal Strength, Cell
        ID are retrieved during connected mode at least for cellular networks.
        */
        class Connectivity_Monitoring {
            public const ushort lwm2m_object_id          = 4;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:4:1.3";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.3";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates the network bearer used for the current LwM2M communication session from the network bearer list
            below.
            The number range is split into three categories:
            0 - 20 are Cellular Bearers
            21 - 40 are Wireless Bearers
            41 - 50 are Wireline Bearers
            More specifically:
            0: GSM cellular network
            1: TD-SCDMA cellular network
            2: WCDMA cellular network
            3: CDMA2000 cellular network
            4: WiMAX cellular network
            5: LTE-TDD cellular network
            6: LTE-FDD cellular network
            7: NB-IoT
            8: 5G-NR TDD
            9: 5G-NR FDD
            10 - 20: Reserved for other types of cellular network
            21: WLAN network
            22: Bluetooth network
            23: IEEE 802.15.4 network
            24 - 40: Reserved for other types of local wireless network
            41: Ethernet
            42: DSL
            43: PLC
            44 - 50: reserved for other types of wireline networks.
            */
            [MinMax(0, 50), ResourceId(0), Operations("R"), Mandatory] byte Network_Bearer;

            /**
            Indicates a list of current available network bearer. Each Resource Instance has a value from the network
            bearer list.
            */
            [MinMax(0, 50), ResourceId(1), Operations("R"), Mandatory] byte[,,] Available_Network_Bearer;

            /**
            Indicates the average value of the received signal strength indication used in the
            current network bearer (as indicated by Resource 0 of this Object). The value is expressed in dBm. For the
            following network bearers the signal strength parameters indicated below are represented by this resource:
            GSM:    RSSI
            UMTS:   RSCP
            LTE:    RSRP
            NB-IoT: NRSRP
            For more details on Network Measurement Report, refer to the appropriate Cellular or Wireless Network
            standards, (e.g. for LTE Cellular Network
            refer to 3GPP TS 36.133 specification).
            */
            [ResourceId(2), Operations("R"), Units("dBm"), Mandatory] long Radio_Signal_Strength;

            /**
            This contains received link quality  e.g. LQI for IEEE 802.15.4 (range 0...255), RxQual Downlink for GSM
            (range 0...7, refer to [3GPP 44.018] for more details on Network Measurement Report encoding), RSRQ for LTE,
            (refer to [3GPP 36.214]), NRSRQ for NB-IoT (refer to [3GPP 36.214]).
            */
            [ResourceId(3), Operations("R")] long? Link_Quality;

            /**
            The IP addresses assigned to the connectivity interface. (e.g. IPv4, IPv6, etc.)
            */
            [ResourceId(4), Operations("R"), Mandatory] string[,,] IP_Addresses;

            /**
            The IP address of the next-hop IP router, on each of the interfaces specified in resource 4 (IP Addresses).
            Note: This IP Address doesn't indicate the Server IP address.
            */
            [ResourceId(5), Operations("R")] string[,,] Router_IP_Addresses;

            /**
            The percentage indicating the average utilization of the link to the next-hop IP router.
            */
            [MinMax(0, 100), ResourceId(6), Operations("R"), Units("/100")] byte? Link_Utilization;

            /**
            Access Point Name in case Network Bearer Resource is a Cellular Network.
            */
            [ResourceId(7), Operations("R")] string[,,] APN;

            /**
            Serving Cell ID in case Network Bearer Resource is a Cellular Network.
            As specified in TS [3GPP 23.003] and in [3GPP. 24.008]. Range (0...65535) in GSM/EDGE
            UTRAN Cell ID has a length of 28 bits.
            Cell Identity in WCDMA/TD-SCDMA. Range: (0...268435455).
            LTE Cell ID has a length of 28 bits.
            Parameter definitions in [3GPP 25.331].
            */
            [ResourceId(8), Operations("R")] long? Cell_ID;

            /**
            Serving Mobile Network Code. This is applicable when the Network Bearer Resource value is referring to a
            cellular network.
            As specified in TS [3GPP 23.003].
            */
            [MinMax(0, 999), ResourceId(9), Operations("R")] ushort? SMNC;

            /**
            Serving Mobile Country Code. This is applicable when the Network Bearer Resource value is referring to a
            cellular network.
            As specified in TS [3GPP 23.003].
            */
            [MinMax(0, 999), ResourceId(10), Operations("R")] ushort? SMCC;

            /**
            SINR: Signal to Interference plus Noise Ratio SINR is the ratio of the strength of the received signal to the
            strength of the received interference signal (noise and interference).
            */
            [ResourceId(11), Operations("R"), Units("dB")] long? SignalSNR;

            /**
            Location Area Code in case Network Bearer Resource is a Cellular Network. As specified in TS [3GPP 23.003] and
            in [3GPP. 24.008]
            */
            [ResourceId(12), Operations("R")] long? LAC;

            /**
            Indicates the Coverage Enhancement Level of the UE in the serving cell. The Coverage Enhancement levels are
            defined and specified in 3GPP TS 36.331 and 36.213.
            0: No Coverage Enhancement in the serving cell
            1: Coverage Enhancement level 0
            2: Coverage Enhancement level 1
            3: Coverage Enhancement level 2
            4: Coverage Enhancement level 3
            */
            [MinMax(0, 4), ResourceId(13), Operations("R")] byte? Coverage_Enhancement_Level;
        }

        // ═════════════════════════ 5.xml: Firmware Update (urn:oma:lwm2m:oma:5:1.2) ═════════════════════════
        /**
        This LwM2M Object enables management of firmware which is to be updated. This Object includes installing a
        firmware package, updating firmware, and performing actions after updating firmware. The firmware update MAY
        require to reboot the device; it will depend on a number of factors, such as the operating system architecture
        and the extent of the updated software.
        The envisioned functionality is to allow a LwM2M Client to connect to any LwM2M Server to obtain a firmware
        image using the object and resource structure defined in this section experiencing communication security
        protection using TLS/DTLS. There are, however, other design decisions that need to be taken into account to
        allow a manufacturer of a device to securely install firmware on a device. Examples for such design decisions
        are how to manage the firmware update repository at the server side (which may include user interface
        considerations), the techniques to provide additional application layer security protection of the firmware
        image, how many versions of firmware images to store on the device, and how to execute the firmware update
        process considering the hardware specific details of a given IoT hardware product. These aspects are
        considered to be outside the scope of this version of the specification.
        A LwM2M Server may also instruct a LwM2M Client to fetch a firmware image from a dedicated server (instead of
        pushing firmware images to the LwM2M Client). The Package URI resource is contained in the Firmware object and
        can be used for this purpose.
        A LwM2M Client MUST support block-wise transfer [CoAP_Blockwise] if it implements the Firmware Update object.
        A LwM2M Server MUST support block-wise transfer. Other protocols, such as HTTP/HTTPs, MAY also be used for
        downloading firmware updates (via the Package URI resource). For constrained devices it is, however,
        RECOMMENDED to use CoAP for firmware downloads to avoid the need for additional protocol implementations.
        */
        class Firmware_Update {
            public const ushort lwm2m_object_id          = 5;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:5:1.2";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.2";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Firmware package
            */
            [D(65535), ResourceId(0), Operations("W"), Mandatory] Binary[,,] Package;

            /**
            URI from where the device can download the firmware package by an alternative mechanism. As soon the device
            has received the Package URI it performs the download at the next practical opportunity.
            The URI format is defined in RFC 3986. For example, coaps://example.org/firmware is a syntactically valid URI.
            The URI scheme determines the protocol to be used. For CoAP this endpoint MAY be a LwM2M Server but does not
            necessarily need to be. A CoAP server implementing block-wise transfer is sufficient as a server hosting a
            firmware repository and the expectation is that this server merely serves as a separate file server making
            firmware images available to LwM2M Clients.
            */
            [D(+255), ResourceId(1), Operations("RW"), Mandatory] string Package_URI;

            /**
            Indicates current state with respect to this firmware update. This value is set by the LwM2M Client.
            0: Idle (before downloading or after successful updating)
            1: Downloading (The data sequence is on the way)
            2: Downloaded
            3: Updating
            If writing the firmware package to Package Resource has completed, or, if the device has downloaded the
            firmware package from the Package URI the state changes to Downloaded.
            Writing an empty string to Package URI Resource or setting the Package Resource to NULL (‘\0’), resets the
            Firmware Update State Machine: the State Resource value is set to Idle and the Update Result Resource value is
            set to 0.
            The device should remove the downloaded firmware image when the state is reset to Idle.
            When in Downloaded state, and the executable Resource Update is triggered, the state changes to Updating if
            the update starts immediately. For devices that support a user interface and the deferred update
            functionality, the user may be allowed to defer the firmware update to a later time. In this case, the state
            stays in Downloaded state and the Update Result is set to 11. Once a user accepted the firmware update, the
            state changes to Updating.
            When the user deferred the update, the device will continue operations normally until the user approves the
            firmware update or an automatic update starts. It will not block any operation on the device.
            If the Update Resource failed, the state may return to either Downloaded or Idle depending on the underlying
            reason of update failure, e.g. Integrity Check Failure results in the client moving to the Idle state.
            If performing the Update or Cancel operation was successful, the state changes to Idle.
            The firmware update state machine is illustrated in the respective LwM2M specification.
            */
            [MinMax(0, 3), ResourceId(3), Operations("R"), Mandatory] byte State;

            /**
            Contains the result of downloading or updating the firmware
            0: Initial value. Once the updating process is initiated (Download /Update), this Resource MUST be reset to
            Initial value.
            1: Firmware updated successfully.
            2: Not enough flash memory for the new firmware package.
            3: Out of RAM during downloading process.
            4: Connection lost during downloading process.
            5: Integrity check failure for new downloaded package.
            6: Unsupported package type.
            7: Invalid URI.
            8: Firmware update failed.
            9: Unsupported protocol. A LwM2M client indicates the failure to retrieve the firmware image using the URI
            provided in the Package URI resource by writing the value 9 to the /5/0/5 (Update Result resource) when the
            URI contained a URI scheme unsupported by the client. Consequently, the LwM2M Client is unable to retrieve the
            firmware image using the URI provided by the LwM2M Server in the Package URI when it refers to an unsupported
            protocol.
            10: Firmware update cancelled. A Cancel operation has been executed successfully.
            11: Firmware update deferred.
            */
            [MinMax(0, 11), ResourceId(5), Operations("R"), Mandatory] byte Update_Result;

            /**
            Name of the Firmware Package
            */
            [D(+255), ResourceId(6), Operations("R")] string PkgName;

            /**
            Version of the Firmware package
            */
            [D(+255), ResourceId(7), Operations("R")] string PkgVersion;

            /**
            This resource indicates what protocols the LwM2M Client implements to retrieve firmware images. The LwM2M
            server uses this information to decide what URI to include in the Package URI. A LwM2M Server MUST NOT include
            a URI in the Package URI object that uses a protocol that is unsupported by the LwM2M client.
            For example, if a LwM2M client indicates that it supports CoAP and CoAPS then a LwM2M Server must not provide
            an HTTP URI in the Packet URI.
            The following values are defined by this version of the specification:
            0: CoAP (as defined in RFC 7252) with the additional support for block-wise transfer. CoAP is the default
            setting.
            1: CoAPS (as defined in RFC 7252) with the additional support for block-wise transfer
            2: HTTP 1.1 (as defined in RFC 7230)
            3: HTTPS 1.1 (as defined in RFC 7230)
            4: CoAP over TCP (as defined in RFC 8323)
            5: CoAP over TLS (as defined in RFC 8323)
            Additional values MAY be defined in the future. Any value not understood by the LwM2M Server MUST be ignored.
            */
            [MinMax(0, 5), ResourceId(8), Operations("R")] byte[,,] Firmware_Update_Protocol_Support;

            /**
            The LwM2M Client uses this resource to indicate its support for transferring firmware images to the client
            either via the Package Resource (=push) or via the Package URI Resource (=pull) mechanism.
            0: Pull only
            1: Push only
            2: Both. In this case the LwM2M Server MAY choose the preferred mechanism for conveying the firmware image to
            the LwM2M Client.
            */
            [MinMax(0, 2), ResourceId(9), Operations("R"), Mandatory] byte Firmware_Update_Delivery_Method;

            /**
            Severity of the firmware image.
            0: Critical
            1: Mandatory
            2: Optional
            This information is useful when the device provides option for the deferred update. Default value is 1.
            */
            [MinMax(0, 2), ResourceId(11), Operations("RW")] byte? Severity;

            /**
            This resource stores the time when the State resource is changed. Device updates this resource before making
            any change to the State.
            */
            [ResourceId(12), Operations("R")] DateTime? Last_State_Change_Time;

            /**
            The number of seconds a user can defer the software update.
            When this time period is over, the device will not prompt the user for update and install it automatically.
            If the value is 0, a deferred update is not allowed.
            */
            [ResourceId(13), Operations("RW"), Units("s")] DurationInSeconds? Maximum_Defer_Period;

            /**
            Determines if the Firmware Upgrade will proceed automatically when the firmware download has completed. Value
            true means that the server does not need to instruct the device to proceed with the firmware upgrade when the
            firmware download is complete. Value false means that the server will have to instruct the device to proceed
            with the firmware upgrade when the firmware download is complete. When this is set to false, the server will
            use the Update resource to trigger the upgrade.
            */
            [ResourceId(14), Operations("RW")] bool? Automatic_Upgrade_at_Download;

            /**
            Updates firmware by using the firmware package stored in Package, or, by using the firmware downloaded from
            the Package URI.
            This Resource is only executable when the value of the State Resource is Downloaded.
            Execute operation on resource 2 (Update); sent by the Server to the Client.
            */
            [ResourceId(2), Operations("E"), Mandatory] public class Update_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Cancels firmware update.
            Cancel can be executed if the device has not initiated the Update process. If the device is in the process of
            installing the firmware or has already completed installation it MUST respond with Method Not Allowed error
            code.
            Upon successful Cancel operation, Update Result Resource is set to 10 and State is set to 0 by the device.
            Execute operation on resource 10 (Cancel); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Cancel_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 6.xml: Location (urn:oma:lwm2m:oma:6) ═════════════════════════
        /**
        This LwM2M Object provides a range of location telemetry related information which can be queried by the LwM2M
        Server.
        */
        class Location {
            public const ushort lwm2m_object_id          = 6;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:6";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            The decimal notation of latitude, e.g. -43.5723 [World Geodetic System 1984].
            */
            [ResourceId(0), Operations("R"), Units("lat"), Mandatory] double Latitude;

            /**
            The decimal notation of longitude, e.g. 153.21760 [World Geodetic System 1984].
            */
            [ResourceId(1), Operations("R"), Units("lon"), Mandatory] double Longitude;

            /**
            The decimal notation of altitude in meters above sea level.
            */
            [ResourceId(2), Operations("R"), Units("m")] double? Altitude;

            /**
            The value in this resource indicates the radius of a circular area in meters. The circular area is used to
            describe uncertainty about a point for coordinates in a two-dimensional coordinate reference systems (CRS).
            The center point of a circular area is specified by using the Latitude and the Longitude Resources.
            */
            [ResourceId(3), Operations("R"), Units("m")] double? Radius;

            /**
            The velocity of the LwM2M Client, as defined in [3GPP-TS_23.032].
            */
            [D(65535), ResourceId(4), Operations("R")] Binary[,,] Velocity;

            /**
            The timestamp of when the location measurement was performed.
            */
            [ResourceId(5), Operations("R"), Mandatory] DateTime Timestamp;

            /**
            Speed is the time rate of change in position of a LwM2M Client without regard for direction: the scalar
            component of velocity.
            */
            [ResourceId(6), Operations("R"), Units("m/s")] double? Speed;
        }

        // ═════════════════════════ 7.xml: Connectivity Statistics (urn:oma:lwm2m:oma:7) ═════════════════════════
        /**
        This LwM2M Objects enables client to collect statistical information and enables the LwM2M Server to retrieve
        these information, set the collection duration and reset the statistical parameters.
        Note: When reporting the Tx Data or Rx Data, the LwM2M Client reports the total KB transmitted/received over
        IP bearer(s), including all protocol header bytes up to and including the IP header. This does not include
        lower level retransmissions/optimizations (e.g. RAN, header compression) or SMS messages.
        */
        class Connectivity_Statistics {
            public const ushort lwm2m_object_id          = 7;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:7";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicate the total number of SMS successfully transmitted during the collection period.
            */
            [ResourceId(0), Operations("R")] long? SMS_Tx_Counter;

            /**
            Indicate the total number of SMS successfully received during the collection period.
            */
            [ResourceId(1), Operations("R")] long? SMS_Rx_Counter;

            /**
            Indicate the total amount of data (IP / non-IP) transmitted during the collection period expressed in
            kilobytes.
            */
            [ResourceId(2), Operations("R")] long? Tx_Data;

            /**
            Indicate the total amount of data (IP / non-IP) received during the collection period expressed in kilobytes.
            */
            [ResourceId(3), Operations("R")] long? Rx_Data;

            /**
            The maximum IP message size that is used during the collection period.
            */
            [ResourceId(4), Operations("R"), Units("B")] long? Max_Message_Size;

            /**
            The average IP message size that is used during the collection period.
            */
            [ResourceId(5), Operations("R"), Units("B")] long? Average_Message_Size;

            /**
            The default collection period in seconds. The value 0 indicates that the collection period is not set.
            */
            [ResourceId(8), Operations("RW"), Units("s")] DurationInSeconds? Collection_Period;

            /**
            Reset resources 0-5 to 0 and start to collect information, If resource 8 (Collection Period) value is 0, the
            client will keep collecting information until resource 7 (Stop) is executed, otherwise the client will stop
            collecting information after specified period ended.
            Note:When reporting the Tx Data or Rx Data, the LwM2M Client reports the total KB transmitted/received over IP
            bearer(s), including all protocol header bytes up to and including the IP header. This does not include lower
            level retransmissions/optimizations (e.g. RAN, header compression) or SMS messages.
            Execute operation on resource 6 (Start); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stop collecting information, but do not reset resources 0-5.
            Execute operation on resource 7 (Stop); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E"), Mandatory] public class Stop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 8.xml: Lock and Wipe (urn:oma:lwm2m:oma:8) ═════════════════════════
        /**
        This LWM2M objects provides the resources needed to perform the lock and wipe operations.
        */
        class Lock_and_Wipe {
            public const ushort lwm2m_object_id          = 8;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:8";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            State of the device:
            0: unlocked state Normal operation.
            1: partially locked state
            To render the device inoperable the device has been partially locked. The "lock target" resource allows
            specifying the target(s) for this operation.
            2: fully locked state
            To render the device fully inoperable the device has been fully locked.
            */
            [MinMax(0, 2), ResourceId(0), Operations("RW"), Mandatory] byte State;

            /**
            To specify one or several targets for the lock operation. This allows partially locking the device by
            selecting specific components or interfaces to be locked.
            */
            [ResourceId(1), Operations("W"), Mandatory] string[,,] Lock_target;

            /**
            Indicates which data can be wiped from the device. This resource could be e.g. representing a directory.
            */
            [ResourceId(2), Operations("R")] string[,,] Wipe_item;

            /**
            To specify one or several targets for the wipe operation. This allows selecting specific data, or, memory
            areas for the wipe operation.
            */
            [ResourceId(4), Operations("W"), Mandatory] string[,,] Wipe_target;

            /**
            Contains the result of a lock and wipe operation
            0: Default
            1: Partially Lock operation successful
            2: Fully Lock operation successful
            3: Unlock operation successful
            4: Wipe operation successful
            5: Partially Lock operation failed
            6: Fully Lock operation failed
            7: Unlock operation failed
            8: Wipe operation failed
            This Resource MAY be reported by sending Observe operation.
            */
            [MinMax(0, 8), ResourceId(5), Operations("R"), Mandatory] byte Lock_or_Wipe_Operation_Result;

            /**
            To permanently erase data from the device.
            Execute operation on resource 3 (Wipe); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E"), Mandatory] public class Wipe_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 9.xml: LWM2M Software Management (urn:oma:lwm2m:oma:9:1.1) ═════════════════════════
        /**
        This LwM2M objects provides the resources needed to perform software management on the device. Each software
        component is managed via a dedicated Software Management Object instance.
        */
        class LWM2M_Software_Management {
            public const ushort lwm2m_object_id          = 9;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:9:1.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Name of the software package
            */
            [D(+255), ResourceId(0), Operations("R"), Mandatory] string PkgName;

            /**
            Version of the software package
            */
            [D(+255), ResourceId(1), Operations("R"), Mandatory] string PkgVersion;

            /**
            Software package
            The package can be in one single software component, or any delivery material used by the Device to determine
            the software component(s) and proceed to their installation.
            Can be archive file, executable, manifest. This resource to be used when it is single block of delivery.
            */
            [D(65535), ResourceId(2), Operations("W")] Binary[,,] Package;

            /**
            URI from where the device can download the software package by an alternative mechanism. As soon the device
            has received the Package URI it performs the download at the next practical opportunity.
            Can be direct link to a single software component or link to archive file, executable, or manifest, used by
            the Device to determine, then access to the software component(s). This resource to be used when it is single
            block of delivery.
            */
            [D(+255), ResourceId(3), Operations("W")] string Package_URI;

            /**
            Link to a "Checkpoint" object which allows to specify conditions/dependencies for a software update. E.g.
            power connected, sufficient memory, target system.
            */
            [ResourceId(5), Operations("R")] ObjectLink? Checkpoint;

            /**
            Indicates current state with respect to this software update. This value is set by the LwM2M Client.
            0: INITIAL
            Before downloading.
            (see 5.1.2.1)
            1: DOWNLOAD STARTED
            The downloading process has started and is on-going.
            (see 5.1.2.2)
            2: DOWNLOADED
            The package has been completely downloaded
            (see 5.1.2.3)
            3: DELIVERED
            In that state, the package has been correctly downloaded and is ready to be installed.
            (see 5.1.2.4)
            If executing the Install Resource failed, the state remains at DELIVERED.
            If executing the Install Resource was successful, the state changes from DELIVERED to INSTALLED.
            After executing the UnInstall Resource, the state changes to INITIAL.
            4: INSTALLED
            In that state the software is correctly installed and can be activated or deactivated according to the
            Activation State Machine.
            (see 5.1.2.5)
            */
            [MinMax(0, 4), ResourceId(7), Operations("R"), Mandatory] byte Update_State;

            /**
            If this value is true, the LwM2M Client MUST inform the registered LwM2M Servers of Objects and Object
            Instances parameter by sending an Update or Registration message after the software update operation at the
            next practical opportunity if supported Objects in the LwM2M Client have changed, in order for the LwM2M
            Servers to promptly manage newly installed Objects.
            If false, Objects and Object Instances parameter MUST be reported at the next periodic Update message.
            The default value is false.
            */
            [ResourceId(8), Operations("RW")] bool? Update_Supported_Objects;

            /**
            Contains the result of downloading or installing/uninstalling the software
            0: Initial value. Prior to download any new package in the Device, Update Result MUST be reset to this initial
            value. One side effect of executing the Uninstall resource is to reset Update Result to this initial value
            "0".
            1: Downloading. The package downloading process is on-going.
            2: Software successfully installed.
            3: Successfully Downloaded and package integrity verified
            (( 4-49, for expansion, of other scenarios))
            50: Not enough storage for the new software package.
            51: Out of memory during downloading process.
            52: Connection lost during downloading process.
            53: Package integrity check failure.
            54: Unsupported package type.
            56: Invalid URI
            57: Device defined update error
            58: Software installation failure
            59: Uninstallation Failure during forUpdate(arg=0)
            60-200 : (for expansion, selection to be in blocks depending on new introduction of features)
            This Resource MAY be reported by sending Observe operation.
            */
            [MinMax(0, 200), ResourceId(9), Operations("R"), Mandatory] byte Update_Result;

            /**
            Indicates the current activation state of this software:
            0: DISABLED
            Activation State is DISABLED if the Software Activation State Machine is in the INACTIVE state or not alive.
            1: ENABLED
            Activation State is ENABLED only if the Software Activation State Machine is in the ACTIVE state
            */
            [ResourceId(12), Operations("R"), Mandatory] bool Activation_State;

            /**
            Link to "Package Settings" object which allows to modify at any time software configuration settings. This is
            an application specific object.
            Note: OMA might provide a template for a Package Settings object in a future release of this specification.
            */
            [ResourceId(13), Operations("RW")] ObjectLink? Package_Settings;

            /**
            User Name for access to SW Update Package in pull mode.
            Key based mechanism can alternatively use for talking to the component server instead of user name and
            password combination.
            */
            [D(+255), ResourceId(14), Operations("W")] string User_Name;

            /**
            Password for access to SW Update Package in pull mode.
            */
            [D(+255), ResourceId(15), Operations("W")] string Password;

            /**
            Contains the status of the actions done by the client on the SW Component(s) referred by the present SW Update
            Package. The status is defined in Appendix B.
            */
            [ResourceId(16), Operations("R")] string Status_Reason;

            /**
            Reference to SW Components downloaded and installed in scope of the present SW Update Package Note: When
            resource 17 objlink exist, resources 2, 3 and 12 in this table are ignored.
            */
            [ResourceId(17), Operations("R")] ObjectLink[,,] Software_Component_Link;

            /**
            Software Component tree length indicates the number of instances existing for this software package in the
            Software Component Object.
            */
            [ResourceId(18), Operations("R")] byte? Software_Component_tree_length;

            /**
            Indicates the current operational state of the software application:
            0: Initializing
            1: Running
            2: Shutting Down
            3: Stopped
            4: Failed
            5: Defunct
            6-15: Reserved
            */
            [MinMax(0, 15), ResourceId(21), Operations("R"), Mandatory] byte Operational_State;

            /**
            Installs software from the package either stored in Package resource, or, downloaded from the Package URI.
            This Resource is only executable when the value of the State Resource is DELIVERED.
            Execute operation on resource 4 (Install); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E"), Mandatory] public class Install_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Uninstalls the software package.
            This executable resource may have one argument.
            If used with no argument or argument is 0, the Package is removed i from the Device. If the argument is 1
            ("ForUpdate"), the Client MUST prepare itself for receiving a Package used to upgrade the Software already in
            place. Update State is set back to INITIAL state.
            Execute operation on resource 6 (Uninstall); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class Uninstall_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action activates the software previously successfully installed (the Package Installation State Machine
            is currently in the INSTALLED state)
            Execute operation on resource 10 (Activate); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E"), Mandatory] public class Activate_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action deactivates softwareif the Package Installation State Machine is currently in the INSTALLED state.
            Execute operation on resource 11 (Deactivate); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E"), Mandatory] public class Deactivate_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action Starts the software application if the Software Activation State Machine is currently in the
            ACTIVE state.
            Execute operation on resource 19 (Start); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E"), Mandatory] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action Stops the software application if the Software Activation State Machine is currently in the ACTIVE
            state.
            Execute operation on resource 20 (Stop); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E"), Mandatory] public class Stop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action deletes existing local application data without modifying the application installation or
            activation states.
            Execute operation on resource 22 (Purge); sent by the Server to the Client.
            */
            [ResourceId(22), Operations("E")] public class Purge_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10.xml: LWM2M Cellular Connectivity (urn:oma:lwm2m:oma:10:1.1) ═════════════════════════
        /**
        This object specifies resources to enable a device to connect to a 3GPP or 3GPP2 bearer, including GPRS/EDGE,
        UMTS, LTE, NB-IoT, SMS. For cellular connectivity, this object focuses on Packet Switched (PS) connectivity
        and doesn't aim to provide comprehensive Circuit Switched (CS) connectivity management.
        Notes:
        (0) Resource 6 "Serving PLMN Rate control" was moved to the APN Connection Profile Object (#11) to correctly
        correspond to the 3GPP specifications.
        (1) PSM Timer, Active Timer and all eDRX parameters resources are controlled by the 3GPP network. A LwM2M
        server may write a suggested values to these resource. As soon a LwM2M server changes the current values the
        device then suggests the new values to the network upon the next practical opportunity e.g. by inclusion of
        the requested value in an Attach or TAU request. In case the network confirms the suggested value then the
        device shall apply that value. In case the network provides a different value then the value provided by the
        network shall be applied by the device and the resource value shall be set to that value.
        The LwM2M server may use the observe function to be notified upon any changes of PSM, Active timer or eDRX
        parameters. By using the observe function the LwM2M server will get notified in case the value suggested by
        the LwM2M server is not accepted by the network, or, if the value is changed by the network for any reason
        (e.g., if the device moves into new tracking areas there is no guarantee that the above values remain the same
        and are not altered by the network).
        */
        class LWM2M_Cellular_Connectivity {
            public const ushort lwm2m_object_id          = 10;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:10:1.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            E.164 address of SMSC.
            Applicable for 3GPP2 networks where SMSC is not available from a smart card, or for 3GPP/3GPP2 networks to
            provide the application with a customer specific SMSC.  The application decides how to use this parameter,
            e.g. precedence over UICC based SMSC address.
            */
            [ResourceId(0), Operations("RW")] string SMSC_address;

            /**
            Time period in MINUTES for which the device shall disconnect from cellular radio (PS detach, CS detach if
            applicable).
            Can be used to handle network overload situations.
            The value is a positive integer (0 to 65535), duration can be from 1 minute to 65535 minutes (approximately 45
            days)
            As soon the server writes a value which is &gt;0 the device SHALL disconnect. When the period has elapsed the
            device MAY reconnect.
            */
            [ResourceId(1), Operations("RW")] DurationInSeconds? Disable_radio_period;

            /**
            Configurable in case the application needs to issue a code (e.g. via AT command) to activate the module. e.g.
            "*98".
            */
            [ResourceId(2), Operations("RW")] string Module_activation_code;

            /**
            Links to a vendor specific object.
            */
            [ResourceId(3), Operations("R")] ObjectLink? Vendor_specific_extensions;

            /**
            PSM Timer = Extended T3412 as described in section 10.5.7.4a (GPRS Timer 3) of [3GPP-TS_24.008]. The value in
            seconds has to be compatible with Extended T3412, otherwise conversion will not be exact. It defines Max
            interval between periodic TAU if there is no other transmission from the device. During most of this time the
            device is considered as unreachable and can therefore go into a deep sleep mode while keeping the PDN
            connection(s) active.
            */
            [ResourceId(4), Operations("RW"), Units("s")] long? PSM_Timer;

            /**
            Active Timer = T3324 as described in section 10.5.7.3 (GPRS Timer) of [3GPP-TS_24.008]. The value in seconds
            has to be compatible with T3324, otherwise conversion will not be exact. This is the time a UE has to remain
            reachable after transitioning to idle state in case there is pending data from the NW to send out. At the end
            of T3324 UE can go into a deep sleep mode while keeping the PDN connection(s) active.
            */
            [ResourceId(5), Operations("RW"), Units("s")] long? Active_Timer;

            /**
            Extended DRX parameters (Paging Time Window and eDRX value) for Iu mode which the UE can request from the
            network. This resource is encoded as octet 3 in [3GPP-TS_24.008, clause 10.5.5.32].
            */
            [D(255), ResourceId(7), Operations("RW")] Binary[,,] eDRX_parameters_for_Iu_mode;

            /**
            Extended DRX parameters (Paging Time Window and eDRX value) for WB-S1 mode which the UE can request from the
            network. This resource is encoded as octet 3 in [3GPP-TS_24.008, clause 10.5.5.32].
            */
            [D(255), ResourceId(8), Operations("RW")] Binary[,,] eDRX_parameters_for_WB_S1_mode;

            /**
            Extended DRX parameters (Paging Time Window and eDRX value) for NB-S1 mode which the UE can request from the
            network. This resource is encoded as octet 3 in [3GPP-TS_24.008, clause 10.5.5.32].
            */
            [D(255), ResourceId(9), Operations("RW")] Binary[,,] eDRX_parameters_for_NB_S1_mode;

            /**
            Extended DRX parameters (Paging Time Window and eDRX value) for A/Gb mode which the UE can request from the
            network. This resource is encoded as octet 3 in [3GPP-TS_24.008, clause 10.5.5.32].
            */
            [D(255), ResourceId(10), Operations("RW")] Binary[,,] eDRX_parameters_for_A_Gb_mode;

            /**
            Links to instances of the "APN connection profile" object representing every APN connection profile that has
            an activated PDN connection.
            */
            [ResourceId(11), Operations("R"), Mandatory] ObjectLink[,,] Activated_Profile_Names;

            /**
            This Resource is used to indicate the Power Saving Modes supported by the LwM2M Client.
            Each bit set in the Resource Instance value corresponds to a supported mode. Several bit set, means several
            modes are supported.
            1st LSB: PSM
            2nd LSB: eDRX
            Other bits are reserved for future use
            */
            [ResourceId(12), Operations("R")] byte? Supported_Power_Saving_Modes;

            /**
            This Resource is used to indicate which Power Saving Mode(s) is (are) currently active in the LwM2M Client.
            Each bit set in the Resource Instance value corresponds to an active mode.
            1st LSB: PSM
            2nd LSB: eDRX
            Other bits are reserved for future use
            */
            [ResourceId(13), Operations("RW")] byte? Active_Power_Saving_Modes;

            /**
            This resource is used to indicate client configuration as to when it uses Release Assistance Indicator (RAI)
            as defined in 3GPP-TS_24.310, clause 9.9.4.25 to indicate to the NW when connection can be released.
            1st LSB: RAI not used
            2nd LSB: RAI used when transmitting last message which requires no application/transport layer response/
            confirmation
            3rd LSB: RAI used when transmitting last message which requires response/confirmation; when this bit is set,
            2nd LSB is also expected to be set.
            */
            [ResourceId(14), Operations("RW")] byte? Release_Assistance_Indication_Usage;
        }

        // ═════════════════════════ 11.xml: LWM2M APN Connection Profile (urn:oma:lwm2m:oma:11:1.1) ═════════════════════════
        /**
        This object specifies resources to enable a device to connect to an APN.
        Notes:
        (1)	For each activated PDP context request, the device may store at least one value of ‘Connection
        establishment time’, ‘connection establishment result’, ‘Connection end time’ and if activation is
        unsuccessful then a ‘connection establishment reject cause’.   It is a device decision how many instances to
        keep.
        (2)	These resources are used in case IP related parameters are defined statically, can also be used to reflect
        IP related parameters in case of dynamic IP address assignment.  The normal use case would be to have one IPv4
        and one IPv6 address which have each associated a prefix length (IPv6 only), a subnet mask, a gateway, and a
        primary and secondary DNS address.
        (3)	For LTE a higher QoS may be established by setting up an additional bearer ("dedicated bearer") in
        addition to the default bearer which is established to the default APN. A dedicated bearer which is set up by
        the network on request by the device containing a requested QCI value can either be established to the same
        APN as the default bearer or to another APN. The QoS of a dedicated bearer may be modified on request by the
        device. The association of QoS values and APNs for a subscriber is stored in the network and checked during
        the establishment of a bearer.
        */
        class LWM2M_APN_Connection_Profile {
            public const ushort lwm2m_object_id          = 11;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:11:1.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Human-readable identifier. Multiple connection profiles can share the same APN value but e.g. have different
            credentials.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Profile_name;

            /**
            Presented to network during connection to PDN e.g. ‘internet.15.234’.
            This resource is not included in case ‘Auto select APN by device’ resource has the value TRUE.
            If the APN resource is present but contains an empty string, then the device shall not provide an APN in the
            connection request (invoking default APN procedures in the network).
            */
            [ResourceId(1), Operations("RW")] string APN;

            /**
            If this resource is present for a connection profile, it enables the device to choose an APN according to a
            device specific algorithm. It provides a fall-back mechanism e.g. for some MVNO SIMs the configured APN may
            not work.  Resource not included or set to False in case the ‘APN’ resource is specified.
            */
            [ResourceId(2), Operations("RW")] bool? Auto_select_APN_by_device;

            /**
            Allows the profile to be remotely enabled or disabled. True: APN profile is enabled. False: APN profile is
            disabled. If the status is set to disabled (False) while a data connection for that profile is active, that
            data connection will be released.
            */
            [ResourceId(3), Operations("RW")] bool? Enable_status;

            /**
            Enumerated type:
            0: PAP
            1: CHAP
            2: PAP or CHAP
            3: None
            */
            [ResourceId(4), Operations("RW"), Mandatory] long Authentication_Type;

            /**
            Used with e.g. PAP.
            */
            [ResourceId(5), Operations("RW")] string User_Name;

            /**
            Used with e.g. PAP.
            */
            [ResourceId(6), Operations("RW")] string Secret;

            /**
            Comma separated list of retry delay values in seconds to be used in case of unsuccessful connection
            establishment attempts. e.g. "10,60,600,3600,86400"
            */
            [ResourceId(7), Operations("RW")] string Reconnect_Schedule;

            /**
            Coma separated mobile country code, then mobile network code - for which this APN is valid.
            */
            [ResourceId(8), Operations("RW")] string[,,] Validity_MCC_MNC;

            /**
            UTC time of connection request. See note (1)
            */
            [ResourceId(9), Operations("R")] DateTime[,,] Connection_establishment_time_1;

            /**
            0 = accepted
            1 = rejected
            */
            [ResourceId(10), Operations("R")] long[,,] Connection_establishment_result_1;

            /**
            Reject cause, see [3GPP-TS_24.008, 3GPP-TS_24.301]
            */
            [MinMax(0, 111), ResourceId(11), Operations("R")] byte[,,] Connection_establishment_reject_cause_1;

            /**
            UTC time of connection end.
            */
            [ResourceId(12), Operations("R")] DateTime[,,] Connection_end_time_1;

            /**
            Rolling counter for total number of bytes sent via this interface since last device reset.
            */
            [ResourceId(13), Operations("R")] long? TotalBytesSent;

            /**
            Rolling counter for total number of bytes received via this interface since last device reset.
            */
            [ResourceId(14), Operations("R")] long? TotalBytesReceived;

            /**
            May be IPv4 or IPv6 address.
            */
            [ResourceId(15), Operations("RW")] string[,,] IP_address_2;

            /**
            Associated with IPv6 address.
            */
            [ResourceId(16), Operations("RW")] string[,,] Prefix_length_2;

            /**
            Subnet mask.
            */
            [ResourceId(17), Operations("RW")] string[,,] Subnet_mask_2;

            /**
            Gateway.
            */
            [ResourceId(18), Operations("RW")] string[,,] Gateway_2;

            /**
            Primary DNS address.
            */
            [ResourceId(19), Operations("RW")] string[,,] Primary_DNS_address_2;

            /**
            Secondary DNS address.
            */
            [ResourceId(20), Operations("RW")] string[,,] Secondary_DNS_address_2;

            /**
            Quality of service Class Identifier QCI), applicable to LTE and NB-IoT only
            This resource enables the LWM2M server to signal the LWM2M client which QCI it shall request from the network.
            See [3GPP-TS_23.203, and 3GPP-TS_24.301] for a description of QCI values. See note (3).
            */
            [MinMax(1, 9), ResourceId(21), Operations("R")] byte? QCI_3;

            /**
            Links to a vendor specific object.
            */
            [ResourceId(22), Operations("R")] ObjectLink? Vendor_specific_extensions;

            /**
            Rolling counter for total number of packets sent via this interface since last device reset.
            */
            [ResourceId(23), Operations("R")] long? TotalPacketsSent;

            /**
            0=Non-IP
            1=IPv4
            2=IPv6
            3=IPv4v6
            */
            [ResourceId(24), Operations("RW")] long? PDN_Type;

            /**
            Determines the number of allowed uplink PDU transmissions per time interval per APN.
            Rate Control information is part of the Protocol Configuration Options (PCO) according to  [3GPP-TS_24.301],
            [3GPP-TS_24.008 and [3GPP-TS_27.060]
            */
            [ResourceId(25), Operations("R")] long? APN_Rate_Control;

            /**
            For data sent over NAS, this indicates the maximum number of messages the UE can send per time unit (Resource
            27) per PDN connection. See [3GPP-TS_23.401] clause 4.7.7.2 and [3GPP-TS_24.008] clause 10.5.6.3.2.
            */
            [ResourceId(26), Operations("RW")] ulong? Serving_PLMN_Rate_control;

            /**
            In association with APN Rate Control (Resource 28), this indicates the units of the period over which the
            maximum number of PDU transmissions are measured. [3GPP-TS_24.008] clause 10.5.6.3.2 specifies that
            0=unrestricted, 1=minute, 2=hour, 3=day and 4=week.
            */
            [MinMax(0, 4), ResourceId(27), Operations("RW")] byte? Uplink_Time_Unit;

            /**
            Determines the number of allowed uplink PDU transmissions for exception data per time interval for this APN.
            This
            Rate Control information is part of the Protocol Configuration Options (PCO) according to  [3GPP-TS_24.301],
            [3GPP-TS_24.008 and [3GPP-TS_27.060]
            */
            [ResourceId(28), Operations("R")] long? APN_Rate_Control_for_Exception_Data;

            /**
            In association with APN Rate Control for Exception Data (Resource 28), this indicates the units of the period
            over which the maximum number of messages is measured. [3GPP-TS_24.008] clause 10.5.6.3.2 specifies that
            0=unrestricted, 1=minute, 2=hour, 3=day and 4=week.
            */
            [MinMax(0, 4), ResourceId(29), Operations("RW")] byte? APN_Exception_Data_Uplink_Time_Unit;

            /**
            This resource specifies the supported RAT Types that the LWM2M Client can use for connecting to the specified
            APN.
            Each instance is one of these values:
            1: 3GPP PS
            2: 3GPP PS GSM (GPRS)
            3: 3GPP PS UMTS
            4: 3GPP PS LTE
            5: 1xEV-DO
            6: 3GPP CS
            12: 3GPP PS LTE with CIoT EPS optimisations, User Plane
            13: 3GPP PS LTE with CIoT EPS optimisations, Control Plane
            14: 3GPP PS NB-IoT Control Plane optimisations
            15: 3GPP PS NB-IoT User Plane optimisations
            16-100: Reserved for future use
            */
            [ResourceId(30), Operations("RW")] ulong[,,] Supported_RAT_Types;

            /**
            This resource provides the Application ID to correlate to the appropriate instance Ids of Resources 32 and 33.
            */
            [ResourceId(31), Operations("RW")] string[,,] RDS_Application_ID;

            /**
            This resource provides the correlated RDS Destination Port Number (as defined in 3GPP TS 24.250) to use for
            contacting the LwM2M Server identifed in Resource 29 when communicating through the SCEF across the Non-IP
            binding (Resource 24 must equal 0).
            */
            [MinMax(0, 15), ResourceId(32), Operations("RW")] byte[,,] RDS_Destination_Port;

            /**
            This resource provides the correlated RDS Source Port Number (as defined in 3GPP TS 24.250) to use for
            contacting the LwM2M Server identifed in Resource 29 when communicating through the SCEF across the Non-IP
            binding (Resource 24 must equal 0).
            */
            [MinMax(0, 15), ResourceId(33), Operations("RW")] byte[,,] RDS_Source_Port;
        }

        // ═════════════════════════ 12.xml: WLAN connectivity (urn:oma:lwm2m:oma:12:1.1) ═════════════════════════
        /**
        This object specifies resources to enable a device to connect to a WLAN bearer.
        Notes:
        (1)	WEP is supported by this object for legacy devices. All encryption parameter resources are optional e.g. a
        Wifi Alliance "HotSpot 2.0" device would not support WEP related resources.
        */
        class WLAN_connectivity {
            public const ushort lwm2m_object_id          = 12;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:12:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Human-readable identifier eg. wlan0
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Interface_name;

            /**
            0: Disabled
            1: Enabled
            Enable / Disable interface
            When disabled radio must also be disabled
            */
            [ResourceId(1), Operations("RW"), Mandatory] bool Enable;

            /**
            0: Disabled
            1: 2.4 GHz
            2: 5 GHz
            3: 0.9 GHz
            4: 3.7 GHz
            5: 45 GHz
            6: 60 GHz
            */
            [ResourceId(2), Operations("RW")] long? Radio_Enabled;

            /**
            0: Disabled
            1: UP (OK)
            2: Error
            */
            [ResourceId(3), Operations("R"), Mandatory] long Status;

            /**
            The MAC address of the interface, in hexadecimal form.
            */
            [D(+12), ResourceId(4), Operations("R"), Mandatory] string BSSID;

            /**
            The Service Set Identifier for this interface.
            */
            [D(+32), ResourceId(5), Operations("RW"), Mandatory] string SSID;

            /**
            0: Do not broadcast SSID 1: Broadcast SSID
            */
            [ResourceId(6), Operations("RW")] bool? Broadcast_SSID;

            /**
            0: Do not broadcast beacons 1: Broadcast beacons
            */
            [ResourceId(7), Operations("RW")] bool? Beacon_Enabled;

            /**
            0: Access Point
            1: Client (Station)
            2: Bridge
            3: Repeater
            */
            [ResourceId(8), Operations("RW"), Mandatory] long Mode;

            /**
            The current radio channel in use by this interface.
            */
            [ResourceId(9), Operations("RW"), Mandatory] byte Channel;

            /**
            0: Disabled 1: Enabled
            */
            [ResourceId(10), Operations("RW")] bool? Auto_Channel;

            /**
            Array of supported radio channels.
            */
            [ResourceId(11), Operations("RW")] long[,,] Supported_Channels;

            /**
            Array of channels which the access point has determined are ‘in use’.
            Including any channels in-use by access point itself.
            */
            [ResourceId(12), Operations("RW")] long[,,] Channels_In_Use;

            /**
            802.11d Regulatory Domain String.
            First two octets are ISO/IEC 3166-1 two-character country code.
            The third octet is either " " (all environments), "O" (outside) or "I" (inside).
            */
            [D(+3), ResourceId(13), Operations("RW")] string Regulatory_Domain;

            /**
            0: 802.11a
            1: 802.11b
            2: 802.11bg
            3: 802.11g
            4: 802.11n
            5: 802.11bgn
            6: 802.11ac
            7: 802.11ah
            */
            [ResourceId(14), Operations("RW"), Mandatory] long Standard;

            /**
            0: None (Open)
            1: PSK
            2: EAP
            3: EAP+PSK
            4: EAPSIM
            */
            [ResourceId(15), Operations("RW"), Mandatory] long Authentication_Mode;

            /**
            0: AES (WPA2)
            1: TKIP (WPA)
            2: WEP (1)
            */
            [ResourceId(16), Operations("RW")] long? Encryption_Mode;

            /**
            WPA/WPA2 Key expressed as a hex string. Write - Only.
            */
            [D(+64), ResourceId(17), Operations("W")] string WPA_Pre_Shared_Key;

            /**
            WPA/WPA2 Key Phrase. Write Only.
            */
            [D(+64), ResourceId(18), Operations("W")] string WPA_Key_Phrase;

            /**
            0: None
            1: 40-bit
            2: 104-bit
            */
            [ResourceId(19), Operations("RW")] long? WEP_Encryption_Type;

            /**
            Index of the default WEP key.
            */
            [MinMax(1, 4), ResourceId(20), Operations("RW")] byte? WEP_Key_Index;

            /**
            WPA/WPA2 Key Phrase. Write Only.
            */
            [D(+64), ResourceId(21), Operations("W")] string WEP_Key_Phrase;

            /**
            WEP Key 1 expressed as a hexadecimal string.
            10 Bytes for a 40 Bit key
            26 Bytes for a 104 Bit key
            */
            [D(+26), ResourceId(22), Operations("W")] string WEP_Key_1;

            /**
            WEP Key 2 expressed as a hexadecimal string.
            10 Bytes for a 40 Bit key
            26 Bytes for a 104 Bit key
            */
            [D(+26), ResourceId(23), Operations("W")] string WEP_Key_2;

            /**
            WEP Key 3 expressed as a hexadecimal string.
            10 Bytes for a 40 Bit key
            26 Bytes for a 104 Bit key
            */
            [D(+26), ResourceId(24), Operations("W")] string WEP_Key_3;

            /**
            WEP Key 4 expressed as a hexadecimal string.
            10 Bytes for a 40 Bit key
            26 Bytes for a 104 Bit key
            */
            [D(+26), ResourceId(25), Operations("W")] string WEP_Key_4;

            /**
            RADIUS Authentication Server Address
            */
            [D(+256), ResourceId(26), Operations("RW")] string RADIUS_Server;

            /**
            RADIUS Authentication Server Port Number
            */
            [ResourceId(27), Operations("RW")] long? RADIUS_Server_Port;

            /**
            RADIUS Shared Secret
            */
            [D(+256), ResourceId(28), Operations("W")] string RADIUS_Secret;

            /**
            0: WMM NOT Supported 1: WMM Wupported
            */
            [ResourceId(29), Operations("R")] bool? WMM_Supported;

            /**
            0: Disabled 1: Enabled
            */
            [ResourceId(30), Operations("RW")] bool? WMM_Enabled;

            /**
            0: Any Client MAC Address accepted 1: Client MAC address must exist in MACAddressList
            */
            [ResourceId(31), Operations("RW")] bool? MAC_Control_Enabled;

            /**
            Array of allowed client MAC addresses, in hexadecimal form.
            */
            [D(+12), ResourceId(32), Operations("RW")] string[,,] MAC_Address_List;

            /**
            Total number of bytes sent via this interface
            */
            [ResourceId(33), Operations("R")] long? Total_Bytes_Sent;

            /**
            Total number of bytes received via this interface
            */
            [ResourceId(34), Operations("R")] long? Total_Bytes_Received;

            /**
            Total packets sent via this interface
            */
            [ResourceId(35), Operations("R")] long? Total_Packets_Sent;

            /**
            Total packets received via this interface
            */
            [ResourceId(36), Operations("R")] long? Total_Packets_Received;

            /**
            Total number of packets which could not be transmitted because of errors.
            */
            [ResourceId(37), Operations("R")] long? Transmit_Errors;

            /**
            Total number of packets received with errors which prevented those packets from being delivered.
            */
            [ResourceId(38), Operations("R")] long? Receive_Errors;

            /**
            Count of Unicast Packets Sent
            */
            [ResourceId(39), Operations("R")] long? Unicast_Packets_Sent;

            /**
            Count of Unicast Packets Received
            */
            [ResourceId(40), Operations("R")] long? Unicast_Packets_Received;

            /**
            Count of Multicast Packets Sent
            */
            [ResourceId(41), Operations("R")] long? Multicast_Packets_Sent;

            /**
            Count of Multicast Packets Received
            */
            [ResourceId(42), Operations("R")] long? Multicast_Packets_Received;

            /**
            Count of Broadcast Packets Sent
            */
            [ResourceId(43), Operations("R")] long? Broadcast_Packets_Sent;

            /**
            Count of Broadcast Packets Received
            */
            [ResourceId(44), Operations("R")] long? Broadcast_Packets_Received;

            /**
            Count of valid outbound packets intentionally discarded without transmission, for example a packet may be
            discarded to manage buffer space.
            */
            [ResourceId(45), Operations("R")] long? Discard_Packets_Sent;

            /**
            Count of valid packets received and intentionally discarded without delivery to the system, for example a
            packet may be discarded to manage buffer space.
            */
            [ResourceId(46), Operations("R")] long? Discard_Packets_Received;

            /**
            Count of Unknown Packets Received
            */
            [ResourceId(47), Operations("R")] long? Unknown_Packets_Received;

            /**
            Links to a vendor specific object.
            */
            [ResourceId(48), Operations("R")] ObjectLink? Vendor_specific_extensions;
        }

        // ═════════════════════════ 13.xml: LWM2M Bearer Selection (urn:oma:lwm2m:oma:13:1.1) ═════════════════════════
        /**
        This object specifies resources to enable a device to choose a PLMN/network on which to attach/register and
        what type of bearer to then connect.
        This object allows via remote bearer and network configuration to overwrite automatic network and bearer
        selection e.g. as supported by the UICC. An equivalent example for overwriting automatic selection is a user
        doing manual network and bearer selection on a smart phone.
        Notes:
        (1)	Remote management of this communications bearer via LwM2M is currently not supported.
        (2)	See [3GPP-TS_23.401, section 4.3.5.10] for the Preferred Network Behaviour indication used by the UE to
        inform the network about its capabilities and preferences.
        */
        class LWM2M_Bearer_Selection {
            public const ushort lwm2m_object_id          = 13;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:13:1.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Used in network selection and, if applicable, in subsequent mobility management procedures:
            0: auto connect
            1: 3GPP PS preferred
            2: 3GPP PS GSM (GPRS) preferred (including EC-GSM-IoT)
            3: 3GPP PS UMTS preferred
            4: 3GPP PS LTE preferred
            5: 1xEV-DO preferred (1)
            6: 3GPP CS preferred (1)
            7: WLAN preferred
            8: Ethernet preferred (1)
            9: DSL preferred (1)
            10: Bluetooth preferred (1)
            11: WIMAX preferred (1)
            12: 3GPP PS LTE with CIoT EPS optimisations, User Plane preferred (2)
            13: 3GPP PS LTE with CIoT EPS optimisations, Control Plane preferred (2)14: 3GPP PS NB-IoT Control Plane
            optimisations preferred (2)
            15: 3GPP PS NB-IoT User Plane optimisations preferred (2)
            16: 3GPP 5G-NR preferred
            17-100: Reserved for future use
            The Preferred Communications Bearer resource specifies the preferred communications bearer that the LWM2M
            Client is requested to use for connecting to the LWM2M Server. If multiple preferred communications bearers
            are specified, the priority order is reflected by the resource instance order. E.g. the bearer which appears
            first in the list of resource instances is to have higher priority over the rest of available bearers. The
            LWM2M Client SHOULD use the preferred bearers with higher priority first if they are available. If none of
            indicated preferred bearers is available, the LWM2M Client SHOULD wait until one of them becomes available.
            */
            [MinMax(0, 100), ResourceId(0), Operations("RW")] byte[,,] Preferred_Communications_Bearer;

            /**
            Provides guide to the application when performing manual network selection.
            */
            [MinMax(-110, -48), ResourceId(1), Operations("RW")] sbyte? Acceptable_RSSI_GSM;

            /**
            Provides guide to the application when performing manual network selection.
            */
            [MinMax(-120, -25), ResourceId(2), Operations("RW")] sbyte? Acceptable_RSCP_UMTS;

            /**
            Provides guide to the application when performing manual network selection.
            */
            [MinMax(-140, -44), ResourceId(3), Operations("RW")] short? Acceptable_RSRP_LTE;

            /**
            Provides guide to the application when performing manual network selection.
            */
            [ResourceId(4), Operations("RW")] long? Acceptable_RSSI_1xEV_DO;

            /**
            Comma separated list of allowed Global Cell Identities.
            */
            [ResourceId(5), Operations("RW")] string Cell_lock_list;

            /**
            Comma separated list of MCC+MNC of operators, in priority order.
            Resource "operator list mode" indicates how to process this list.
            */
            [ResourceId(6), Operations("RW")] string Operator_list;

            /**
            Indicates whether resource "operator list" represents the allowed operator list (white list), or, the
            preferred operator list.
            0=preferred
            1=allowed
            */
            [ResourceId(7), Operations("RW")] bool? Operator_list_mode;

            /**
            Allows server to see results of network scan (e.g. result of AT+COPS=? as per 3GPP-TS_27.007)
            */
            [ResourceId(8), Operations("R")] string List_of_available_PLMNs;

            /**
            Link to a vendor specific object.
            */
            [ResourceId(9), Operations("R")] ObjectLink? Vendor_specific_extensions;

            /**
            Provides guide to the application when performing manual network selection.
            */
            [MinMax(-158, -44), ResourceId(10), Operations("RW")] short? Acceptable_RSRP_NB_IoT;

            /**
            Interval between periodic searches for higher priority PLMNs of the same country when camped on a visited
            PLMN, i.e. roaming scenario; based on SIM configuration, EFHPPLMN [3GPP-TS_31.102, section 4.2.6]
            */
            [ResourceId(11), Operations("RW")] long? Higher_Priority_PLMN_Search_Timer;

            /**
            False: attach with PDN connection
            True: attach without PDN connection
            */
            [ResourceId(12), Operations("RW")] bool? Attach_without_PDN_connection;
        }

        // ═════════════════════════ 14.xml: LWM2M Software Component (urn:oma:lwm2m:oma:14) ═════════════════════════
        /**
        If some Objects are not supported after software update, the LwM2M Client MUST delete all the Object Instances
        of the Objects that are not supported.
        */
        class LWM2M_Software_Component {
            public const ushort lwm2m_object_id          = 14;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:14";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Name or identifier of the software component
            */
            [D(+255), ResourceId(0), Operations("R")] string Component_Identity;

            /**
            Software components is stored in this resource
            */
            [D(65535), ResourceId(1), Operations("R")] Binary[,,] Component_Pack;

            /**
            Version of the software component.
            */
            [D(+255), ResourceId(2), Operations("R")] string Component_Version;

            /**
            Indicates the current activation state of this software component:
            0: DISABLED
            Activation State is DISABLED if the Software Component Activation State Machine is in the INACTIVE state or
            not alive.
            1: ENABLED
            Activation State is ENABLED only if the Software Component Activation State Machine is in the ACTIVE state.
            */
            [ResourceId(5), Operations("R")] bool? Activation_State;

            /**
            This action activates the software previously successfully installed (the SW Update Package Installation State
            Machine is currently in the INSTALLED state).
            Execute operation on resource 3 (Activate); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Activate_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This action deactivates software if the SW Update Package Installation State Machine is currently in the
            INSTALLED state.
            Execute operation on resource 4 (Deactivate); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E")] public class Deactivate_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 15.xml: DevCapMgmt (urn:oma:lwm2m:oma:15:2.0) ═════════════════════════
        /**
        This LWM2M Object is dedicated to manage the device capabilities of a device e.g. sensors, communication, etc.
        */
        class DevCapMgmt {
            public const ushort lwm2m_object_id          = 15;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:15:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            List of Device Capabilities inside a given Group.
            The format is a free list ASCII-represented integers separated by a semi colon. (e.g. 0;1;10)
            The list of capabilities per Group is given in Appendix B: Device Capabilities Vocabulary
            executable Resource can work with.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Property;

            /**
            Group name of Device Capabilities
            0: SENSOR: luminosity, presence,temp,humidity
            1: CONTROL: Light, Power, Sound
            2: CONNECTIVITY: Bluetooth, wifi, …
            3: NAVIGATION: gps, galieo
            4: STORAGE: external memory,
            5: VISION: cam, video-cam, night_cam.
            6: SOUND: speaker, buzzer
            7: ANALOG_INPUT: generic input
            8: ANALOG_OUTPUT: generic output
            9..15: reserved
            */
            [MinMax(0, 15), ResourceId(1), Operations("R"), Mandatory] byte Group;

            /**
            Device Capability Description
            (manufacturer specified string)
            */
            [ResourceId(2), Operations("R")] string Description;

            /**
            When the resource doesn’t exist, it means the associated Device Capability is not removable.
            When this resource is "False", it means the associated Device Capability is removable and is currently not
            attached to the device.
            When this resource is "True", it means the associated Device Capability - if removable - is currently attached
            to the Device.
            When a Device Capability is not removable, and the "Attached" Resource is present, the "Attached" value but be
            set to "True".
            */
            [ResourceId(3), Operations("R")] bool? Attached;

            /**
            This resource indicates whether the Device Capability is enabled regardless whether the Device Capability is
            attached or not. If the value of this resource is "True" the Device Capability is in Enabled State. If the
            value is "False" the Device Capability is in Disabled State;
            The ‘Attached’ and ‘Enabled’ resources are independent. A Device Capability MAY have ‘True’ as value for
            ‘Enabled’ Resource while having ‘False’ as value for the ‘Attached’ Resource. That means the Device Capability
            is still not available and can’t be used until it is attached to the Device, but will be useable once the
            Device Capability is attached.
            */
            [ResourceId(4), Operations("R"), Mandatory] bool Enabled;

            /**
            When the Resources "Enabled" or "Attached" are under "Observation", this resource specifies whether the LWM2M
            Server MUST be notified when the value of the Resource on "Observation" changed. If the Resource "NotifyEn" is
            not present or the value is ‘False’, the LWM2M Server will be not notified about this change. If the
            "NotifyEn" Resource is present and the value is ‘True’, the LWM2M Server will be notified.
            */
            [ResourceId(7), Operations("RW")] bool? NotifyEn;

            /**
            This command is used to enable the Device Capability to transfer the Device Capability from Disabled State to
            Enabled state.
            In Enabled State, the Device Capability is allowed to work when it is attached to the Device.
            Execute operation on resource 5 (opEnable); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E"), Mandatory] public class opEnable_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This command is used to disable the Device Capability to transfer the Device Capability from Enabled State to
            Disabled State.
            In Disabled state the Device Capability is not allowed to work.
            Execute operation on resource 6 (opDisable); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class opDisable_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 16.xml: Portfolio (urn:oma:lwm2m:oma:16) ═════════════════════════
        /**
        The Portfolio Object allows to extend the data storage capability of other Object Instances in the LwM2M
        system, as well as the services which may be used to authenticate and to protect privacy of data contained in
        those extensions. In addition, a service of data encryption is also defined
        */
        class Portfolio {
            public const ushort lwm2m_object_id          = 16;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:16";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Data Storage extension for other Object Instances.
            e.g  for [GSMA]  :
            0 : Host Device ID,
            1:  Host Device Manufacturer
            2:  Host Device Model
            3:  Host Device Software Version,
            This Resource contains data that the GetAuthData executable Resource can work with.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string[,,] Identity;

            /**
            Buffer which contains the data generated by the  process triggered by a GetAuthData request
            */
            [ResourceId(2), Operations("R")] Blob[,,] AuthData;

            /**
            This Resource contains the state related to the process triggered by GetAuthData  request.
            0 :  IDLE_STATE :  AuthData doesn’t contain any valid data
            1 :  DATA_AVAIL_STATE : AuthData  contains a valid data
            2 :  ERROR_STATE :  an error occurred
            This state is reset to IDLE_STATE, when the executable resource "GetAuthData" is triggered or when the
            AuthData resource has been returned to the LwM2M Server (READ / NOTIFY) .
            */
            [MinMax(0, 2), ResourceId(3), Operations("R")] byte? AuthStatus;

            /**
            Executable resource to trigger Services described in Section 5.2.2
            Arguments definitions are described in Section 5.2.1 as well as in table 2 of this document
            Execute operation on resource 1 (GetAuthData); sent by the Server to the Client.
            */
            [ResourceId(1), Operations("E")] public class GetAuthData_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 19.xml: BinaryAppDataContainer (urn:oma:lwm2m:oma:19) ═════════════════════════
        /**
        This LwM2M Objects provides the application service data related to a LwM2M Server, eg. Water meter data.
        There are several methods to create instance to indicate the message direction based on the negotiation
        between Application and LwM2M. The Client and Server should negotiate the instance(s) used to exchange the
        data. For example:
        - Using a single instance for both directions communication, from Client to Server and from Server to Client.
        - Using an instance for communication from Client to Server and another one for communication from Server to
        Client
        - Using several instances
        */
        class BinaryAppDataContainer {
            public const ushort lwm2m_object_id          = 19;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:19";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates the application data content.
            */
            [ResourceId(0), Operations("RW"), Mandatory] Blob[,,] Data;

            /**
            Indicates the Application data priority:
            0:Immediate
            1:BestEffort
            2:Latest
            3-100: Reserved for future use.
            101-254: Proprietary mode.
            */
            [ResourceId(1), Operations("RW")] long? Data_Priority;

            /**
            Indicates the Data instance creation timestamp.
            */
            [ResourceId(2), Operations("RW")] DateTime? Data_Creation_Time;

            /**
            Indicates the data description.
            e.g. "meter reading".
            */
            [D(+32), ResourceId(3), Operations("RW")] string Data_Description;

            /**
            Indicates the format of the Application Data.
            e.g. YG-Meter-Water-Reading
            UTF8-string
            */
            [D(+32), ResourceId(4), Operations("RW")] string Data_Format;

            /**
            Indicates the destination Application ID.
            */
            [ResourceId(5), Operations("RW")] long? App_ID;
        }

        // ═════════════════════════ 20.xml: Event Log (urn:oma:lwm2m:oma:20:3.1) ═════════════════════════
        /**
        The Event Log Object is a multiple Instances Object defined for logging data in a straightforward and generic
        way.
        The Resources of that Object are based on the OMA LwM2M set of reusable Resources dedicated to logging event
        activity.
        As an extension to the definition of resource 4013 (LogStatus), within the context of this Object starting
        with version 2.1, the 4th LSB, defined in the Resource Description as "reserved", shall mean:
        1=LogDataIncremental collection active, 0=LogDataIncremental collection stopped.
        */
        class Event_Log {
            public const ushort lwm2m_object_id          = 20;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:20:3.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "3.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Define the Log Event Class: 0: generic (default)  1: system   2: security  3: event   4: trace   5: panic   6:
            charging [7-99]: reserved [100-255]: vendor specific
            */
            [Range("255"), ResourceId(4010), Operations("RW")] long? LogClass;

            /**
            Data Collection process status: Each bit of this Resource Instance value defines specific status: 1st LSB
            0=running, 1=stopped 2nd LSB 1=LogData contains Valid Data 0=LogData doesn't contain Valid Data 3rd LSB
            1=Error occurred during Data Collection 0=No error [4th -7th ] LSB:reserved 8th LSB: vendor specific.
            */
            [Range("8-Bits"), ResourceId(4013), Operations("R")] long? LogStatus;

            /**
            Read Access on that Resource returns the Data Collection associated to the current Object Instance.
            */
            [D(65535), ResourceId(4014), Operations("R"), Mandatory] Binary[,,] LogData;

            /**
            when set by the Server, this Resource indicates to the Client, what is the Server preferred data format to use
            when the LogData Resource is returned
            . when retrieved by the Server, this Resource indicates which specific data format is used when the LogData
            Resource is returned to the Server
            0  or Resource not present : no specific data format (sequence of bytes)
            1 : OMA-LwM2M TLV format (only container for logs; does not define any semantics for the logs themselve)
            2 : OMA-LwM2M JSON format (only container for logs; does not define any semantics for the logs themselve)
            3 : OMA-LwM2M CBOR format (only container for logs; does not define any semantics for the logs themselve)
            4 : Syslog Format(RFC5424)
            5 : Common Log Format(RFC6872)
            [6..99] reserved
            [100..255] vendor specific data format
            */
            [Range("255"), ResourceId(4015), Operations("RW")] long? LogDataFormat;

            /**
            Log data collected since the last Send operation described for the LogDataIncremental Minimum Send Interval
            resource, or since that interval has been set to a positive value if the first Send operation has not yet been
            performed.
            The data shall have the same format as the LogData resource, but its collection and emptying is independent
            from it and from the LogStart/LogStop logic.
            This resource may only be included in a Send operation payload. Attempting to access it via the Device
            Management and Service Enablement Interface shall result in generating the Method Not Allowed error.
            */
            [D(65535), ResourceId(4016)] Binary[,,] LogDataIncremental;

            /**
            Minimum number of seconds between consecutive Send operations containing the LogDataIncremental resource. If
            this resource is zero or not present, then LogDataIncremental shall never be sent in a Send operation. If set
            to a positive number, a Send operation containing the LogDataIncremental resource shall be performed after the
            specified number of seconds since the previous one or when a new log information is generated, whichever
            happens later, and the data collection shall be atomically emptied upon successful delivery.
            If the LwM2M client is connected to multiple servers, this resource SHOULD be handled independently for each
            server.
            */
            [ResourceId(4017), Operations("RW")] ulong? LogDataIncrementalMinimumSendInterval;

            /**
            A unique local-scope identifier for distinguishing edge applications within a specific deployment environment.
            */
            [ResourceId(4050), Operations("RW"), Mandatory] ulong AppID;

            /**
            Actions:
            a) Start data collection(DC)
            b) LogStatus is set to 0 (running)
            c) DC is emptied (default) or extended according arg'0' value
            Arguments definitions are described in the table below.
            Execute operation on resource 4011 (LogStart); sent by the Server to the Client.
            */
            [ResourceId(4011), Operations("E")] public class LogStart_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Actions: a) Stop data collection(DC) b)  1st LSB of LogStatus is set to "1"(stopped) c) DC is kept (default)
            or emptied according arg'0' value Arguments definitions are described in the table below.
            Execute operation on resource 4012 (LogStop); sent by the Server to the Client.
            */
            [ResourceId(4012), Operations("E")] public class LogStop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 21.xml: LWM2M OSCORE (urn:oma:lwm2m:oma:21:2.0) ═════════════════════════
        /**
        This LwM2M Object provides the keying material and related information of a LwM2M Client appropriate to access
        a specified LwM2M Server using OSCORE. One Object Instance MAY address a LwM2M Bootstrap-Server. These LwM2M
        Object Resources MUST only be changed by a LwM2M Bootstrap-Server or Bootstrap from Smartcard and MUST NOT be
        accessible by any other LwM2M Server.
        Instances of this Object are linked from Instances of Object 0 using the OSCORE Security Mode Resource of
        Object 0. Instances of this Object MUST NOT be linked from more than one Instance of Object 0.
        */
        class LWM2M_OSCORE {
            public const ushort lwm2m_object_id          = 21;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:21:2.0";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource MUST be used to store the pre-shared key used in LwM2M Client and LwM2M Server/Bootstrap-Server,
            called the Master Secret.
            */
            [D(65535), ResourceId(0), Mandatory] Binary[,,] OSCORE_Master_Secret;

            /**
            This resource MUST store an OSCORE identifier for the LwM2M Client called the Sender ID.
            */
            [D(65535), ResourceId(1), Mandatory] Binary[,,] OSCORE_Sender_ID;

            /**
            This resource MUST store an OSCORE identifier for the LwM2M Client called the Recipient ID.
            */
            [D(65535), ResourceId(2), Mandatory] Binary[,,] OSCORE_Recipient_ID;

            /**
            This resource MUST be used to store the encoding of the AEAD Algorithm as defined in Table 10 of RFC 8152. The
            AEAD is used by OSCORE for encryption and integrity protection of CoAP message fields.
            */
            [ResourceId(3)] long? OSCORE_AEAD_Algorithm;

            /**
            This resource MUST be used to store the encoding of the HMAC Algorithm used in the HKDF. The encoding of HMAC
            algorithms are defined in Table 7 of RFC 8152. The HKDF is used to derive the security context used by OSCORE.
            */
            [ResourceId(4)] long? OSCORE_HMAC_Algorithm;

            /**
            This resource MUST be used to store a non-secret random value called the Master Salt. The Master Salt is used
            to derive the security context used by OSCORE.
            */
            [D(65535), ResourceId(5)] Binary[,,] OSCORE_Master_Salt;

            /**
            This resource MUST be used to store an OSCORE identifier called ID Context. This identifier is used to
            identify the Common Context and derive the security context used by OSCORE.
            */
            [D(65535), ResourceId(6)] Binary[,,] OSCORE_ID_Context;
        }

        // ═════════════════════════ 22.xml: Virtual Observe Notify (urn:oma:lwm2m:oma:22:1.1) ═════════════════════════
        /**
        The Virtual Observe Notify Object provides a main function to notify multiple resources to a LwM2M Server in
        one notification message whether the resources are in one object/object instance or across multiple objects.
        The Virtual Observe Notify Object also provides some functions to implement more efficient multi-resource
        report.
        Notes:
        (1)	When the ResourceFilter is set to TRUE, this condition takes precedence over any pmax. Namely, when the
        LwM2M Server set the Resource ResourceFilter to TRUE, whatever the pmax attribute is attached to any resource
        included in the ObserveLinks, the Report is only populated by the LwM2M Client each time the resources
        included in the ObserveLinks are changed.
        (2)	Any default pmax and pmin values which have been configured in the Server Object should not apply to
        VirtualObserveNotify and each instance of this object should use explicit pmin and pmax as requested by the
        LwM2M Server when setting up notifications.
        */
        class Virtual_Observe_Notify {
            public const ushort lwm2m_object_id          = 22;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:22:1.1";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Array of Core Links where each element includes a Resource ID or Object Instance ID to be observed and its
            observation criteria (lt, gt, st, pmin, pmax).
            When the LwM2M Server write the resources or object instances to this Resource, the LwM2M Client starts to
            observe these resources.
            When the LwM2M Server write empty string to this Resource, the LwM2M Client stop to observe resources.
            */
            [D(+4096), ResourceId(0), Operations("RW"), Mandatory] string[,,] ObserveLinks;

            /**
            This resource is populated by the LwM2M Client each time an observed resource from ObserveLinks meets its
            observation criteria, thereby resulting in a notification to a LwM2M Server that is observing Report resource.
            The type MUST be SenML JSON
            */
            [ResourceId(1), Operations("R"), Mandatory] string Report;

            /**
            Used by the LwM2M Server to indicate the LwM2M Client whether send all or changed resources.
            False: report all Resources,
            True: report only changed Resources.
            When it is absent, the LwM2M Client shall report all Resources as default.
            */
            [ResourceId(2), Operations("RW")] bool? ResourceFilter;

            /**
            Array of Core Links where each element includes the Resources ID to be included in the notification.
            If ReportLinks Resource is absent, the notification sent to the LwM2M Server will only include the Resources
            in ObserveLinks  .
            If the ReportLinks Resource is present, the notification sent to the LwM2M Server will only include the
            Resources that are listed in ReportLinks and not include the value of the Resource ObserveLinks.
            To provide maximum flexibility to the server the Notifications will not comprise the union of resources in
            ObserveLinks and ReportLinks when both present.
            */
            [D(+4096), ResourceId(3), Operations("RW")] string[,,] ReportLinks;

            /**
            Used by the server to indicate the AND/OR logic relationship combination between or among resources included
            in ObserveLinks Resource.
            0: OR
            1: AND
            2: reserved value.
            */
            [ResourceId(4), Operations("RW")] long? ObserveRelation;

            /**
            If present, it specifies the content format LwM2M Client will use to populate Virtual Observe Report Resource.
            Values will be either as per Tables 7.4.1 and 7.4.2 of LwM2M Core TS or another IANA registered Media Type.
            Default value of SenML JSON is assumed when this resource is not present.
            */
            [ResourceId(5), Operations("RW")] long? Virtual_Observe_Report_Format;

            /**
            If present this resource is populated by the LwM2M Client following exactly the same rules as those used to
            populate Resource 4, Report Resource.
            The only difference is that this resource is formatted as defined by Resource 5
            */
            [D(65535), ResourceId(6), Operations("R")] Binary[,,] Virtual_Observe_Report;
        }

        // ═════════════════════════ 23.xml: LwM2M COSE (urn:oma:lwm2m:oma:23) ═════════════════════════
        /**
        This Object provides the keying material and related information for use with COSE.
        */
        class LwM2M_COSE {
            public const ushort lwm2m_object_id          = 23;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:23";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource is used to indicate the key identifier.
            */
            [ResourceId(0), Mandatory] string KID;

            /**
            This resource is used to store the encoding of the AEAD Algorithm as defined in Table 10 of RFC 8152.
            */
            [ResourceId(1), Mandatory] long AEAD_Algorithm;

            /**
            This resource is used to store the key for use with the indicated AEAD algorithm.
            */
            [ResourceId(2), Mandatory] string Key;
        }

        // ═════════════════════════ 24.xml: MQTT Server (urn:oma:lwm2m:oma:24) ═════════════════════════
        /**
        This object defines configuration parameters for an MQTT client to interact with a MQTT server.
        */
        class MQTT_Server {
            public const ushort lwm2m_object_id          = 24;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:24";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The Will Retain value to declare in the MQTT CONNECT message.
            */
            [ResourceId(0), Operations("RW")] bool? Will_Retain;

            /**
            The Will Topic to include in the MQTT CONNECT message.
            */
            [ResourceId(1), Operations("RW")] string Will_Topic;

            /**
            The Will Message to include in the MQTT CONNECT message.
            */
            [ResourceId(2), Operations("RW")] string Will_Message;

            /**
            The Clean Session value to declare in the MQTT CONNECT message.
            */
            [ResourceId(3), Operations("RW")] bool? Clean_Session;

            /**
            The Will QoS value to declare in the MQTT CONNECT message.
            */
            [MinMax(0, 3), ResourceId(4), Operations("RW")] byte? Will_QoS;

            /**
            The Keep Alive value to declare in the MQTT CONNECT message.
            */
            [ResourceId(5), Operations("RW")] ushort? Keep_Alive;

            /**
            The Client Identifier identifies the MQTT client to the MQTT server. MQTT server must support ClientIds which
            are between 1 and 23 UTF-8 encoded bytes in length, and that contain only the characters
            "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ". MQTT server may allow ClientId's that
            contain more than 23 encoded bytes and may support ClientId's that contain characters not included in the
            list.
            */
            [ResourceId(6), Operations("RW"), Mandatory] string Client_Identifier;

            /**
            The User Name to declare in the MQTT CONNECT message. It must be a UTF-8 encoded string. It can be used by the
            MQTT server for authentication and authorization.
            */
            [ResourceId(7), Operations("RW")] string User_Name;

            /**
            The Password value to declare in the MQTT CONNECT message.
            */
            [D(65535), ResourceId(8), Operations("RW")] Binary[,,] Password;
        }

        // ═════════════════════════ 25.xml: LwM2M Gateway (urn:oma:lwm2m:oma:25:2.0) ═════════════════════════
        /**
        This object is used by a LwM2M Gateway to maintain the IoT Devices connected to the LwM2M Gateway.
        */
        class LwM2M_Gateway {
            public const ushort lwm2m_object_id          = 25;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:25:2.0";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource identifies the IoT Device connected to the LwM2M Gateway.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Device_ID;

            /**
            This resource defines what prefix MUST be used for access to LwM2M Objects of this IoT Device.
            */
            [ResourceId(1), Operations("R"), Mandatory] string Prefix;

            /**
            This resource contains the Objects and Object Instances exposed by the LwM2M Gateway on behalf of the IoT
            Device. It uses the same CoreLnk format as Registration Interface.
            */
            [D(+4096), ResourceId(3), Operations("R"), Mandatory] string IoT_Device_Objects;
        }

        // ═════════════════════════ 26.xml: LwM2M Gateway Routing (urn:oma:lwm2m:oma:26) ═════════════════════════
        /**
        This object is used by a LwM2M Gateway to maintain the routing table.
        */
        class LwM2M_Gateway_Routing {
            public const ushort lwm2m_object_id          = 26;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:26";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource identifies mapping the LwM2M Object ID that is mapped with the Mapping Info Resource. It defines
            the source of the mapping.
            */
            [ResourceId(0), Operations("R"), Mandatory] ulong LwM2M_Object_ID;

            /**
            This resource defines the target of the mapping. This Resource may be empty in which case the mapping is the
            identity function.
            */
            [D(+4096), ResourceId(1), Operations("R"), Mandatory] string Mapping_Info;
        }

        // ═════════════════════════ 27.xml: 5GNR Connectivity (urn:oma:lwm2m:oma:27) ═════════════════════════
        /**
        This is a device management object that should be used for 5G-NR capable devices.
        */
        class N5GNR_Connectivity {
            public const ushort lwm2m_object_id          = 27;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:27";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates the connectivity option.
            1 = Core Network: EPC; Master RAT: LTE; Secondary RAT: -
            3 = Core Network: EPC; Master RAT: LTE; Secondary RAT: NR
            2 = Core Network: 5GC; Master RAT: NR; Secondary RAT: -
            4 = Core Network: 5GC; Master RAT: NR; Secondary RAT: eLTE
            5 = Core Network: 5GC; Master RAT: eLTE; Secondary RAT: -
            7 = Core Network: 5GC; Master RAT: eLTE; Secondary RAT: NR
            */
            [ResourceId(0), Operations("R"), Mandatory] long Connectivity_Option;

            /**
            Indicates the Operating NR Bands supported by UE in NSA mode. Value represents the integer value of band
            mentioned in 3GPP  Spec 38.104 (Table: Table 5.2-1 and Table 5.2-2)
            */
            [ResourceId(1), Operations("R")] long[,,] NR_Band_Support_available;

            /**
            Indicates the Operating NR Bands on which UE is attached. Value represents the integer value of band mentioned
            in 3GPP  Spec 38.104 (Table: Table 5.2-1 and Table 5.2-2)
            */
            [ResourceId(2), Operations("R")] long[,,] NR_Band_attached;

            /**
            Indicates the Single - Network Slice Selection Assistance Information for 5G Standalone mode
            0 = eMBB
            1 = URLLC
            2 = MIoT
            3 = Custom
            4-7 = Reserved
            */
            [ResourceId(3), Operations("R")] long[,,] S_NSSAI;

            /**
            Data Network Name in case of Network Bearer Resource is a 5G SA (FDD/TDD) Cellular Network.
            */
            [ResourceId(4), Operations("R")] string DNN_Name;

            /**
            Indicates the PDU Session ID over which LwM2M session is established for 5G SA (FDD/TDD) Cellular Network.
            */
            [MinMax(1, 15), ResourceId(5), Operations("R")] byte? PDU_Session_Id;

            /**
            Indicates the Session and Service Continuity mode for 5G SA (FDD/TDD) Cellular Network.
            */
            [MinMax(1, 3), ResourceId(6), Operations("R")] byte? SSC_Mode;

            /**
            Indicates the type of PDU session over which LwM2M connection is established for 5G SA (FDD/TDD) Cellular
            Network.
            1 = IPv4
            2 = IPv6
            3 = IPv4v6
            4 = Unstructured
            5 = Ethernet
            8 = Reserved (Spec Ref.)
            */
            [ResourceId(7), Operations("R")] long? PDU_Session_Type;

            /**
            Indicates the 5G QoS Identifier for 5G SA (FDD/TDD) Cellular Network.
            1-9,65,66,67,69,70,75,79,80,81,82,83,84,85 = Standard
            128 to 254 = Operator specific 0,255 = Reserved
            Remaining = Spare (Spec Ref.)
            */
            [ResourceId(8), Operations("R")] long? N5QI;

            /**
            Indicates whether SDAP is enabled or not for 5G SA (FDD/TDD) Cellular Network.
            0 = in UL only
            1 = In DL Only
            2 = In UL and DL both
            */
            [ResourceId(9), Operations("R")] long? SDAP_Enablement;

            /**
            Indicates the QoS Flow identifier for 5G SA (FDD/TDD) Cellular Network. (Spec Ref.)
            */
            [MinMax(1, 63), ResourceId(10), Operations("R")] byte? QFI;

            /**
            Indicates the Session Aggregate Maximum Bit Rate as per the 5G 3GPP Spec for 5G SA (FDD/TDD) Cellular Network.
             (Spec Ref.)
            */
            [MinMax(1, 25), ResourceId(11), Operations("R")] byte? Session_AMBR;

            /**
            The Aggregate Maximum Bitrate which is applicable to a given APN over which LwM2M session is established for
            5G SA (FDD/TDD) Cellular Network.
            */
            [ResourceId(12), Operations("R"), Units("dB")] long? APN_AMBR;

            /**
            Indicates the QoS at NAS layer  for 5G SA (FDD/TDD) Cellular Network.
            0 = Disabled
            1 = Enabled
            */
            [ResourceId(13), Operations("R")] bool? NAS_Reflective_QOS;

            /**
            Indicates the QoS for Access Stratum (RRC) for 5G SA (FDD/TDD) Cellular Network..
            0 = Absent
            1 = Present
            */
            [ResourceId(14), Operations("R")] bool? Access_Stratum_Reflective_QoS;

            /**
            Index for the P-CSCF address for 5G SA (FDD/TDD) Cellular Network.
            */
            [ResourceId(15), Operations("R")] long? P_CSCF_Address_Index;

            /**
            Indicates the Authentication type for PDU Session
            PDU session Authentication
            0 = Primary
            1 = Secondary
            2 = Both
            */
            [ResourceId(16), Operations("R")] long? PDU_session_Authentication;

            /**
            Indicates the PLMN ID over which UE is currently attached for 5G SA (FDD/TDD) Cellular Network.
            Allows server to see the currennt PLMN in string format (e.g. formatted as result of AT+COPS=? as per
            3GPP-TS_27.007)
            */
            [ResourceId(17), Operations("R")] string PLMN_ID;

            /**
            Indicates whether LADN (Local Area Data Network) is supported or not for 5G SA (FDD/TDD) Cellular Network.
            0 = Not Supported
            1 = Supported
            */
            [ResourceId(18), Operations("R")] bool? LADN_Support;

            /**
            Current state of the Integrity Protection on Data Radio Bearer for 5G SA (FDD/TDD) Cellular Network.
            0 = Disabled
            1 = Enabled with 64-Kbps
            2 = Enabled with Peak Rate
            */
            [ResourceId(19), Operations("R")] long? Integrity_Protection_on_DRB;

            /**
            Indicates the Access Type preference for 5G SA (FDD/TDD) Cellular Network.
            0 = 3GPP
            1 = Non-3GPP
            */
            [ResourceId(20), Operations("R")] bool? Access_type_Preference;
        }

        // ═════════════════════════ 28.xml: Device RF Capabilities (urn:oma:lwm2m:oma:28) ═════════════════════════
        /**
        This is a device management object that should be used for capturing the RF capabilities of the device.
        */
        class Device_RF_Capabilities {
            public const ushort lwm2m_object_id          = 28;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:28";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates the list of supported LTE bands
            */
            [ResourceId(0), Operations("R")] long? Supported_LTE_Band_Information;

            /**
            Indicates the list of supported EGPRS bands
            */
            [ResourceId(1), Operations("R")] long? Supported_EGPRS_Band_Information;

            /**
            Indicates the list of supported TD-SCDMA bands
            */
            [ResourceId(2), Operations("R")] long? Supported_TD_SCDMA_Band_Information;

            /**
            Indicates the list of supported WCDMA bands
            */
            [ResourceId(3), Operations("R")] long? Supported_WCDMA_Band_Information;

            /**
            Indicates the list of supported CDMA-2000 bands
            */
            [ResourceId(4), Operations("R")] long? Supported_CDMA_2000_Band_Information;

            /**
            Indicates the list of supported WiMAX bands
            */
            [ResourceId(5), Operations("R")] long? Supported_WiMAX_Band_Information;

            /**
            Indicates the list of supported NB-IoT bands
            */
            [ResourceId(6), Operations("R")] long? Supported_NB_IoT_Band_Information;

            /**
            Indicates the list of supported 5G-NR bands
            */
            [ResourceId(7), Operations("R")] long? Supported_5G_Band_Information;
        }

        // ═════════════════════════ 500.xml: CoAP Config (urn:oma:lwm2m:oma:500) ═════════════════════════
        /**
        This object is used to configure the CoAP transmission parameters (RFC7252) and other parameters that affect
        CoAP transmission.
        */
        class CoAP_Config {
            public const ushort lwm2m_object_id          = 500;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:500";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Identify the network bearer for which these parameters are applicable. The value is from the network bearer
            list defined in the Connectivity Monitoring Object (ID: 4). Please, verify the list of currently reserved
            values.
            */
            [ResourceId(0), Operations("RW"), Mandatory] byte Network_Bearer;

            /**
            The initial value of retransmission timeout in CoAP. Default is set to that of RFC7252, that is 2 seconds.
            */
            [ResourceId(1), Operations("RW"), Units("s"), Mandatory] long ACK_TIMEOUT;

            /**
            The initial value of retransmission timeout in CoAP. Default is set to that of RFC7252, that is a value of
            1.5.
            */
            [ResourceId(2), Operations("RW"), Mandatory] double ACK_RANDOM_FACTOR;

            /**
            The maximum number of retransmissions. Default is set to that of RFC7252, that is 4 retransmissions.
            */
            [ResourceId(3), Operations("RW"), Mandatory] long MAX_RETRANSMIT;

            /**
            Number of simultaneous outstanding interactions that the LwM2M client can accept from a given LwM2M Server. An
            outstanding interaction is either a CON for which an ACK has not yet been received but is still expected
            (message layer) or a request for which neither a response nor an Acknowledgment message has yet been received
            but is still expected. Default is set to that of RFC7252, that is 1 interaction.
            */
            [ResourceId(4), Operations("RW"), Mandatory] long NSTART;

            /**
            If a server does decide to respond to a multicast request, it should not respond immediately. Instead, it
            should pick based on RFC7252, Section 8.2. If the LwM2M Client does not have data to compute the Leisure time
            it should use that of Default Leisure as specified in RFC7252.
            */
            [ResourceId(5), Operations("RW"), Units("s")] long? DEFAULT_LEISURE;

            /**
            This resource represents the maximum probing rate accepted by this LwM2M Client in bytes per second.
            */
            [ResourceId(6), Operations("RW"), Units("B/s")] long? PROBING_RATE;

            /**
            The LwM2M Server may modify the initial DTLS retransmission timer value of 1 second into a different value.
            This will have effects on latency as well as on congestion, thus the timer value should be handled carefully.
            */
            [ResourceId(7), Operations("RW"), Units("s")] long? DTLS_Retransmission_Timer;

            /**
            The maximum time in seconds the device will wait for a separate response to a request.
            */
            [ResourceId(8), Operations("RW")] long? Max_Response_Waiting_Time;

            /**
            Applies the parameters specifed in the resources to the CoAP connections on this interface.
            Execute operation on resource 9 (Apply); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Apply_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 501.xml: LTE-MTC Band Config (urn:oma:lwm2m:oma:501) ═════════════════════════
        /**
        This object is used to configure the cellular band used by the device as well as to change the band. It is
        intended to be used on LTE bands, as in NB-IoT and LTE Cat M1 frequency bands.
        */
        class LTE_MTC_Band_Config {
            public const ushort lwm2m_object_id          = 501;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:501";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            E-UTRA Absolute Radio Frequency Channel Number (EARFCN), the carrier frequency of the device radio.
            */
            [ResourceId(1), Operations("RW"), Mandatory] ushort EARFCN;

            /**
            The current frequency used in the current band in MHz (Downlink).
            */
            [ResourceId(2), Operations("R"), Units("MHz"), Mandatory] double Current_Frequency_Downlink;

            /**
            The current frequency used in the current band in MHz (Uplink).
            */
            [ResourceId(3), Operations("R"), Units("MHz")] double? Current_Frequency_Uplink;

            /**
            Indicates a list of currently supported EARFCNs in priority order. Each Resource Instance has a value from the
            band list.
            */
            [ResourceId(4), Operations("RW"), Mandatory] long[,,] Prioritized_Channels;

            /**
            The application type of the sensor or actuator as a string depending on the use case.
            */
            [ResourceId(5750), Operations("RW")] string Application_Type;

            /**
            Time that the device will wait until reset once the Reset Resource is triggered.
            */
            [ResourceId(5), Operations("RW"), Units("s"), Mandatory] double Reset_Timeout;

            /**
            This resource links to a vendor specific object.
            */
            [ResourceId(48), Operations("R")] ObjectLink? Vendor_specific_extensions;

            /**
            Execuring this resource resets the radio interface of the device.
            Execute operation on resource 6 (Reset); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 502.xml: CO Detector (urn:oma:lwm2m:oma:502) ═════════════════════════
        /**
        This is an alarm that should be raised if the sensor detects a higher than threshold CO level.
        */
        class CO_Detector {
            public const ushort lwm2m_object_id          = 502;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:502";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Verbose identification of the location of the CO sensor.
            */
            [ResourceId(0), Operations("RW")] string CO_Sensor_Location_Tag;

            /**
            0 = false (CO NOT detected), 1 = true (CO Detected)
            */
            [ResourceId(1), Operations("R"), Mandatory] bool CO_Detected;

            /**
            CO value (in ppm) received for the area.
            */
            [Range("0..12800"), ResourceId(2), Operations("RW"), Units("ppm")] double? Ambient_CO_Value;

            /**
            Last or Current Measured CO Value (in ppm) from the Sensor.
            */
            [Range("0..12800"), ResourceId(3), Operations("R"), Units("ppm"), Mandatory] double CO_Value;

            /**
            The minimum value that can be measured by the sensor (in ppm).
            */
            [Range("0..12800"), ResourceId(4), Operations("R"), Units("ppm")] double? Min_CO_Range_Value;

            /**
            The maximum value that can be measured by the sensor.
            */
            [Range("0..12800"), ResourceId(5), Operations("R"), Units("ppm")] double? Max_CO_Range_Value;

            /**
            Indicate range of the accuracy for the temperature Sensor.
            */
            [Range("0..12800"), ResourceId(6), Operations("R"), Units("ppm")] double? CO_Detection_Accuracy;

            /**
            The minimum CO value (in ppm) measured by the sensor since power ON or reset.
            */
            [Range("0..12800"), ResourceId(7), Operations("R"), Units("ppm")] double? Minimum_Measured_CO_Value;

            /**
            The maximum CO value measured (in ppm) by the sensor since power ON or reset
            */
            [Range("0..12800"), ResourceId(8), Operations("R"), Units("ppm")] double? Maximum_Measured_CO_Value;

            /**
            Indicate the Upper threshold for the CO Value (in ppm).
            */
            [Range("0..12800"), ResourceId(9), Operations("RW"), Units("ppm")] double? Upper_CO_Threshold;

            /**
            Indicate the loudness of the alarm.
            */
            [ResourceId(6048), Operations("R"), Units("dB")] double? Alarm_loudness;

            /**
            The decimal notation of latitude, e.g. -43.5723 (World Geodetic System 1984).
            */
            [ResourceId(5514), Operations("R")] string Latitude;

            /**
            The decimal notation of longitude, e.g. 153.21760 (World Geodetic System 1984).
            */
            [ResourceId(5515), Operations("R")] string Longitude;

            /**
            Altitude above sea level in meters.
            */
            [ResourceId(6039), Operations("R"), Units("m")] double? Altitude;

            /**
            Current remaining battery level.
            */
            [Range("0.00..100.00"), ResourceId(6044), Operations("R")] double? Battery_Percentage;

            /**
            Reset the "CO" object related parameters to default
            Execute operation on resource 10 (Reset); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 503.xml: Fire Alarm (urn:oma:lwm2m:oma:503) ═════════════════════════
        /**
        This is an alarm that should be raised if the sensor(s) detect fire, based on the values reported from
        Temperature, Humidity, Smoke (CO2).
        */
        class Fire_Alarm {
            public const ushort lwm2m_object_id          = 503;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:503";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Verbose identification of the location of the Temperature sensor location
            */
            [ResourceId(0), Operations("RW")] string Temperature_Sensor_Location_Tag;

            /**
            Temperature Units: 0 = Celsius, 1 = Fahrenheit, 2 = Kelvin. All temperature values are represented in this
            unit.
            */
            [ResourceId(1), Operations("RW"), Mandatory] long Temperature_Unit;

            /**
            Temperature for the area.
            */
            [ResourceId(2), Operations("RW")] double? Ambient_Temperature;

            /**
            Last or Current Measured Temperature Value from the Sensor. The value 65534 indicates that the Sensor data is
            not available.
            */
            [ResourceId(3), Operations("R"), Mandatory] double Temperature_Value;

            /**
            The minimum Temperature value measured by the sensor since power ON or reset.
            */
            [ResourceId(4), Operations("R")] double? Minimum_Measured_Temperature_Value;

            /**
            The maximum Temperature value measured by the sensor since power ON or reset.
            */
            [ResourceId(5), Operations("R")] double? Maximum_Measured_Temperature_Value;

            /**
            The minimum temperature value that can be measured by the sensor.
            */
            [ResourceId(6), Operations("RW")] double? Min_Temperature_Range_Value;

            /**
            The maximum temperature value that can be measured by the sensor.
            */
            [ResourceId(7), Operations("RW")] double? Max_Temperature_Range_Value;

            /**
            Indicates the lower end of the accuracy range for the temperature sensor.
            */
            [ResourceId(8), Operations("RW")] double? Lower_Temperature_Accuracy;

            /**
            Indicates the upper end of the accuracy range for the temperature sensor.
            */
            [ResourceId(9), Operations("RW")] double? Upper_Temperature_Accuracy;

            /**
            Indicates the maximum threshold for the temperature.
            */
            [ResourceId(10), Operations("RW")] double? Temperature_Threshold;

            /**
            Temperature Sensor Error: 0 = false (Working correctly), 1 = true (Faulty).
            */
            [ResourceId(11), Operations("R")] bool? Temperature_Sensor_Error;

            /**
            Indicates the loudness of temperature alarm.
            */
            [ResourceId(13), Operations("RW"), Units("dB")] double? Temperature_Alarm_Loudness;

            /**
            Verbose identification of the location of the Humidity sensor.
            */
            [ResourceId(14), Operations("RW")] string Humidity_Sensor_Location_Tag;

            /**
            Relative humidity for the area.
            */
            [Range("0.0..100.0"), ResourceId(15), Operations("RW"), Units("%RH")] double? Ambient_Relative_Humidity;

            /**
            Last or Current Measured Humidity Value from the Sensor. The value 0 indicates that the Sensor data is not
            available.
            */
            [Range("0.0..100.0"), ResourceId(16), Operations("R"), Units("/100"), Mandatory] double Humidity_Value;

            /**
            The minimum Humidity value measured by the sensor since power ON or reset.
            */
            [Range("0.0..100.0"), ResourceId(17), Operations("R"), Units("/100")] double? Minimum_Measured_Humidity_Value;

            /**
            The maximum Humidity value measured by the sensor since power ON or reset.
            */
            [Range("0.0..100.0"), ResourceId(18), Operations("R"), Units("/100")] double? Maximum_Measured_Humidity_Value;

            /**
            Indicate the accuracy for the Humidity Sensor.
            */
            [Range("0.0..100.0"), ResourceId(19), Operations("RW"), Units("/100")] double? Humidity_Accuracy;

            /**
            Indicate the threshold for the Humidity.
            */
            [Range("0.0..100.0"), ResourceId(20), Operations("RW"), Units("/100")] double? Humidity_Threshold;

            /**
            Humidity Sensor Error: 0 = false (Working correctly), 1 = true (Faulty)
            */
            [ResourceId(21), Operations("R")] bool? Humidity_Sensor_Error;

            /**
            Indicates the loudness of the Humidity alarm.
            */
            [ResourceId(23), Operations("RW"), Units("dB")] double? Humidity_Alarm_Loudness;

            /**
            Verbose identification of the location of the Smoke sensor.
            */
            [ResourceId(24), Operations("RW")] string Smoke_Sensor_Location_Tag;

            /**
            0 = False (CO2 alarm threshold not exceeded), 1 = True (CO2 alarm threshold exceeded).
            */
            [ResourceId(25), Operations("R"), Mandatory] bool CO2_Alarm_State;

            /**
            CO2 value for the area.
            */
            [ResourceId(26), Operations("R"), Units("ppm")] double? Ambient_CO2_Value;

            /**
            Last or Current Measured CO2 Value from the sensor. The value 0 indicates that the Sensor data is not
            available.
            */
            [ResourceId(27), Operations("R"), Units("ppm"), Mandatory] double CO2_Value;

            /**
            The minimum CO2 value measured by the sensor since power ON or reset.
            */
            [ResourceId(28), Operations("R"), Units("ppm")] double? Minimum_Measured_CO2_Value;

            /**
            The maximum CO2 value measured by the sensor since power ON or reset.
            */
            [ResourceId(29), Operations("R"), Units("ppm")] double? Maximum_Measured_CO2_Value;

            /**
            Indicate the alarm threshold for the CO2.
            */
            [ResourceId(30), Operations("RW"), Units("ppm")] double? CO2_Threshold;

            /**
            Smoke Sensor Error: 0 = false (Working correctly), 1 = true (Faulty)
            */
            [ResourceId(31), Operations("R")] bool? Smoke_Sensor_Error;

            /**
            Indicates the loudness of smoke alarm
            */
            [ResourceId(33), Operations("R"), Units("dB")] double? Smoke_Alarm_Loudness;

            /**
            Current remaining battery level.
            */
            [Range("0.00..100.00"), ResourceId(6044), Operations("R")] double? Battery_Percentage;

            /**
            The decimal notation of latitude, e.g. -43.5723 (World Geodetic System 1984).
            */
            [ResourceId(5514), Operations("R")] string Latitude;

            /**
            The decimal notation of longitude, e.g. 153.21760 (World Geodetic System 1984).
            */
            [ResourceId(5515), Operations("R")] string Longitude;

            /**
            Altitude above sea level in meters.
            */
            [ResourceId(6039), Operations("R"), Units("m")] double? Altitude;

            /**
            Reset the "Temperature" related parameters to default.
            Execute operation on resource 12 (Reset Temperature); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E")] public class Reset_Temperature_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Reset the "Humidity" related parameters to default.
            Execute operation on resource 22 (Reset Humidity); sent by the Server to the Client.
            */
            [ResourceId(22), Operations("E")] public class Reset_Humidity_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Reset the "Smoke" related parameters to default.
            Execute operation on resource 32 (Reset Smoke Detection); sent by the Server to the Client.
            */
            [ResourceId(32), Operations("E")] public class Reset_Smoke_Detection_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 504.xml: Remote SIM Provisioning (urn:oma:lwm2m:oma:504) ═════════════════════════
        /**
        This is a device management object that should be used for Remote SIM Provisioning according to GSMA standards
        */
        class Remote_SIM_Provisioning {
            public const ushort lwm2m_object_id          = 504;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:504";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Provides the information about the currently being used SIM Type:
            0: UICC (removable)
            1: eUICC (removable)
            2: eUICC (non-removable)
            3: iUICC
            4-24: Reserved for future use
            */
            [MinMax(0, 3), ResourceId(0), Operations("R"), Mandatory] byte Current_SIM_Type;

            /**
            Provides the information about the currently supported SIM Types:
            0: UICC (removable)
            1: eUICC (removable)
            2: eUICC (non-removable)
            3: iUICC
            4-24: Reserved for future use
            */
            [MinMax(0, 3), ResourceId(1), Operations("R"), Mandatory] byte[,,] Supported_SIM_Type;

            /**
            Provides the name of the Service Provider assocatiated with the downloaded profile or the profile currently
            being downloaded.
            */
            [ResourceId(2), Operations("R")] string Service_Provider_Name;

            /**
            URI, or formatted data containing the URI (e.g. GSMA SGP.22 Activation Code), from where the device can
            download the profile package by an alternative mechanism.
            The URI format is defined in RFC 3986.
            */
            [D(+255), ResourceId(3), Operations("RW")] string Download_URI_Information;

            /**
            Indicates current state with respect to the executed RSP action(s) in the RSP update resource. This value is
            set by the LwM2M Client.
            0: Idle (before downloading a profile or after successful completetion of the action(s))
            1: Downloading (The data sequence is on the way)
            2: Downloaded profile ready for installation
            3: Installing
            5: Enabling
            6: Disabling
            7: Deleting
            8: Resetting memory
            9: Pending end-user consent
            10: Pending confirmation code
            11-24: Reserved for future use
            */
            [MinMax(0, 10), ResourceId(5), Operations("R")] byte? RSP_Update_State;

            /**
            Contains the result of the executed RSP action(s) in the RSP update resource.
            0: Initial value. Once the updating process is initiated (Download /Update), this Resource MUST be reset to
            Initial value.
            1: RSP action completed successfully.
            2: Not enough SIM memory for the new Profile package.
            3. Out of RAM during downloading process.
            4: Connection lost during downloading process.
            5: Integrity check failure for new downloaded profile package.
            6: Unsupported profile package type.
            7: Invalid URI
            8: Unsupported protocol.
            9: Not authorized to download profile at the given URI.
            10: Failed to authenticate server given by the URI.
            11: Generic download and installation error.
            12: Error in profile package format
            13: Failed to enable profile.
            14: Failed to disable profile.
            15: Failed to delete profile.
            16: Failed to reset memory.
            17-24: Reserved for future use
            */
            [MinMax(0, 16), ResourceId(6), Operations("R")] byte? RSP_Update_Result;

            /**
            Name of the downloaded profile / profile package or the profile / profile package currently being downloaded.
            */
            [D(+255), ResourceId(7), Operations("R")] string Profile_Name;

            /**
            Version of the downloaded profile / profile package or the profile / profile package currently being
            downloaded.
            */
            [D(+255), ResourceId(8), Operations("R")] string Profile_Package_Version;

            /**
            Estimated current available amount of storage space on SIM which can store data and software in the LwM2M
            Device (expressed in kibibytes).
            */
            [ResourceId(9), Operations("R"), Units("KiB")] long? Free_Memory_on_SIM;

            /**
            Total amount of storage space which can store data and software in the LwM2M Device
            */
            [ResourceId(10), Operations("R"), Units("KiB")] long? Total_Memory_on_SIM;

            /**
            This resource provides the unique identification number for each installed profile of the current SIM in case
            of RSP support or
            the unique identification number of the current SIM in case of current SIM being a UICC with no RSP support.
            Please refer ETSI TS 102.22.1. In case of multiple installed profiles,
            the currently active profile is the first instance.
            */
            [ResourceId(11), Operations("R"), Mandatory] string[,,] Integrated_Circuit_Card_Identifier_ICCID;

            /**
            eUICC-ID (a.k.a. EID), see GSMA SGP.02 and GSMA SGP.29 for definitions
            */
            [ResourceId(12), Operations("R")] string eUICC_ID;

            /**
            Provides the information about the Remote SIM Provisioning (RSP) type of the current SIM:
            0: No RSP support
            1: GSMA eSIM for M2M devices
            2: GSMA eSIM for consumer devices
            3-24: Reserved for future use
            */
            [ResourceId(13), Operations("R"), Mandatory] long RSP_Type;

            /**
            Indicates ICCID of profile selected for profile specific RSP operations. This resource must be present if
            multiple installed profiles is supported
            by the RSP implementation. In case of only support for a single profile at a time this resource is not
            required to be present for profile selection. After successful installation of
            a profile the value of this resource (if present) is updated to the ICCID of the installed profile.
            */
            [ResourceId(14), Operations("RW")] string Selected_ICCID_for_RSP_operation;

            /**
            Provides information on the requested user consent
            */
            [ResourceId(15), Operations("R")] string RSP_Consent_Reason;

            /**
            User consent decision. The following values are possible:
            0: Approved
            1: Rejected
            2-24: Reserved for future use
            */
            [MinMax(0, 1), ResourceId(16), Operations("W")] byte? RSP_User_Consent;

            /**
            Provides a confirmation code (see e.g. GSMA SGP.21/22)
            */
            [ResourceId(17), Operations("W")] string RSP_Confirmation_Code;

            /**
            RSP data type for set and get RSP data:
            0: SM-DP+ default address (see GSMA SGP.22)
            1: eUICCInfo2 (see GSMA SGP.22)
            2: DeviceInfo (see GSMA SGP.22)
            3: eSIM Profile Metadata (GSMA SGP.22 ProfileInfo default data for all installed profiles)
            5: ISD-P AID (see GSMA SGP.22) - for profile identified by resource 14
            6: Profile state (see GSMA SGP.22) - for profile identified by resource 14
            7: Profile Nickname (see GSMA SGP.22) - for profile identified by resource 14
            8: Service provider name (see GSMA SGP.22) - for profile identified by resource 14
            9: Profile name (see GSMA SGP.22) - for profile identified by resource 14
            10: Icon type (see GSMA SGP.22) - for profile identified by resource 14
            11: Icon (see GSMA SGP.22) - for profile identified by resource 14
            12: Profile Class (see GSMA SGP.22) - for profile identified by resource 14
            13: Notification Configuration Info (see GSMA SGP.22) - for profile identified by resource 14
            14: Profile Owner (see GSMA SGP.22) - for profile identified by resource 14
            15: SM-DP+ proprietary data (see GSMA SGP.22) - for profile identified by resource 14
            16: Profile Policy Rules (see GSMA SGP.22) - for profile identified by resource 14
            17: RSP formatted data request/response (RSP type specific)
            18-24: Reserved for future use
            */
            [MinMax(0, 17), ResourceId(18), Operations("RW")] byte? RSP_Data_Type;

            /**
            This resource is used to update the (e/i)UICC data / profile specific data of type according to resource 30.
            It is up to the RSP type whether update of the data is possible or not.
            */
            [D(65535), ResourceId(19), Operations("W")] Binary[,,] Set_RSP_Data;

            /**
            This resource is used to retrieve the (e/i)UICC data / profile specific data of type according to resource 30.
            It is up to the RSP type whether retrieval of the data is possible or not.
            */
            [D(65535), ResourceId(20), Operations("R")] Binary[,,] Get_RSP_Data;

            /**
            Executes one or more RSP actions. The actions are given as arguments and in case providing multiple actions
            comma separation is used, e.g. 0,1,2. The following values are possible:
            0: Download &amp; install profile
            1: Enable profile - for profile identified by resource 14
            2: Disable profile - for profile identified by resource 14
            3: Delete profile - for profile identified by resource 14
            4: Reset memory of current SIM
            5-24: Reserved for future use
            Execute operation on resource 4 (RSP Update); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E")] public class RSP_Update_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 505.xml: LwM2M SIM Provisioning (urn:oma:lwm2m:oma:505) ═════════════════════════
        /**
        This is a device management object that should be used for Remote SIM Provisioning from a LwM2M server.
        */
        class LwM2M_SIM_Provisioning {
            public const ushort lwm2m_object_id          = 505;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:505";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Provides the information about the currently being used SIM Type:
            0: UICC (removable)
            1: eUICC (removable)
            2: eUICC (non-removable)
            3: iUICC
            */
            [MinMax(0, 3), ResourceId(0), Operations("R"), Mandatory] byte Current_SIM_Type;

            /**
            Provides the information about the currently supported SIM Types:
            0: UICC (removable)
            1: eUICC (removable)
            2: eUICC (non-removable)
            3: iUICC
            */
            [MinMax(0, 3), ResourceId(1), Operations("R"), Mandatory] byte[,,] Supported_SIM_Type;

            /**
            Provides the Service Provider Name using which LwM2M is currently communicating to the Server.
            */
            [ResourceId(2), Operations("R"), Mandatory] string Service_Provider_Name;

            /**
            Profile Package is a personalised Profile using an interoperable description format that is transmitted to an
            eUICC to load and install a Profile.
            */
            [D(65535), ResourceId(3), Operations("W")] Binary[,,] Profile_Package;

            /**
            URI from where the device can download the profile package by an alternative mechanism. As soon the device has
            received the Profile package URI it performs the download at the next practical opportunity. The URI format is
            defined in RFC 3986. For example, coaps://example.org/profile is a syntactically valid URI. The URI scheme
            determines the protocol to be used. For CoAP this endpoint MAY be a LwM2M Server but does not necessarily need
            to be. A CoAP server implementing block-wise transfer is sufficient as a server hosting a firmware repository
            and the expectation is that this server merely serves as a separate file server making profile images
            available to LwM2M Clients. This server can be the future carrier server as well from which IoT devices would
            like to use the service.
            */
            [D(+255), ResourceId(4), Operations("RW")] string Profile_URI;

            /**
            Indicates current state with respect to this profile update. This value is set by the LwM2M Client.
            0: Idle (before downloading or after successful updating)
            1: Downloading (The data sequence is on the way)
            2: Downloaded
            3: Updating If writing the profile package to Package Resource is done, or, if the device has downloaded the
            profile package from the Package URI the state changes to Downloaded. Writing an empty string to Package URI
            Resource or setting the Package Resource to NULL (â€˜\0â€™), resets the Profile Update State Machine: the
            State Resource value is set to Idle and the Update Result Resource value is set to 0. When in Downloaded
            state, and the executable Resource Update is triggered, the state changes to Updating. If the Update Resource
            failed, the state returns at Downloaded. If performing the Update Resource was successful, the state changes
            from Updating to Idle.
            */
            [MinMax(0, 3), ResourceId(6), Operations("R"), Mandatory] byte Update_State;

            /**
            Contains the result of downloading or updating the Profile
            0: Initial value. Once the updating process is initiated (Download /Update), this Resource MUST be reset to
            Initial value.
            1: Profile updated successfully,
            2: Not enough SIM memory for the new Profile package.
            3. Out of RAM during downloading process.
            4: Connection lost during downloading process. 5: Integrity check failure for new downloaded package.
            6: Unsupported package type.
            7: Invalid URI
            8: Unsupported protocol.
            A LwM2M client indicates the failure to retrieve the Profile using the URI provided in the Package URI
            resource by writing the value 9 to the /x/0/7 (Update Result resource) when the URI contained a URI scheme
            unsupported by the client. Consequently, the LwM2M Client is unable to retrieve the Profile using the URI
            provided by the LwM2M Server in the Package URI when it refers to an unsupported protocol.
            */
            [MinMax(0, 8), ResourceId(7), Operations("R"), Mandatory] byte Update_Result;

            /**
            Name of the Profile Package.
            */
            [D(+255), ResourceId(8), Operations("R")] string Profile_Name;

            /**
            Version of the Profile package.
            */
            [D(+255), ResourceId(9), Operations("R")] string Profile_Package_Version;

            /**
            This resource indicates what protocols the LwM2M Client implements to retrieve Profiles. The LwM2M server uses
            this information to decide what URI to include in the Package URI. A LwM2M Server MUST NOT include a URI in
            the Package URI object that uses a protocol that is unsupported by the LwM2M client. For example, if a LwM2M
            client indicates that it supports CoAP and CoAPS then a LwM2M Server must not provide an HTTP URI in the
            Packet URI. The following values are defined by this version of the specification:
            0: CoAP (as defined in RFC 7252) with the additional support for block-wise transfer. CoAP is the default
            setting.
            1: CoAPS (as defined in RFC 7252) with the additional support for block-wise transfer
            2: HTTP 1.1 (as defined in RFC 7230)
            3: HTTPS 1.1 (as defined in RFC 7230) Additional values MAY be defined in the future. Any value not understood
            by the LwM2M Server MUST be ignored.
            */
            [MinMax(0, 3), ResourceId(10), Operations("R")] byte[,,] Profile_Update_Protocol_Support;

            /**
            The LwM2M Client uses this resource to
            indicate its support for transferring Profile
            images to the client either via the Package
            Resource (=push) or via the Package URI
            Resource (=pull) mechanism.
            0: Pull only
            1: Push only
            2: Both. In this case the LwM2M Server
            MAY choose the preferred mechanism for
            conveying the profile image to the
            LwM2M Client.
            */
            [MinMax(0, 2), ResourceId(11), Operations("R"), Mandatory] byte Profile_Update_Delivery_Method;

            /**
            Estimated current available amount of storage space on SIM which can store data and software in the LwM2M
            Device (expressed in kibibytes).
            */
            [ResourceId(12), Operations("R"), Units("KiB")] long? Free_Memory_on_SIM;

            /**
            Total amount of storage space which can store data and software in the LwM2M Device.
            */
            [ResourceId(13), Operations("R"), Units("KiB")] long? Total_Memory_on_SIM;

            /**
            This Elementary File (EF) provides a unique identification number for the UICC/Smart Cards. Please refer ETSI
            TS 102.22.1.
            */
            [ResourceId(14), Operations("R")] long[,,] Integrated_Circuit_Card_Identifier_ICCID;

            /**
            eUICC-ID (a.k.a. EID), see GSMA SGP.02 and GSMA SGP.29 for definitions.
            */
            [ResourceId(15), Operations("R")] string eUICC_ID;

            /**
            Free optional text produced by the SM-DP+ server. This is equivalent to the "Profile Description ID" as
            described in Annex B of SGP.21.
            */
            [ResourceId(16), Operations("R")] string Profile_Type;

            /**
            Updates profile by using the profile package stored in Package, or, by using the profile downloaded from the
            Package URI. This Resource is only executable when the value of the State Resource is Downloaded.
            Execute operation on resource 5 (Update Profile); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Update_Profile_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 507.xml: nuSIM Profile (urn:oma:lwm2m:oma:507) ═════════════════════════
        /**
        This device management object contains the elements of a nuSIM profile package according to nuSIM Technical
        Specification NTS.01.
        */
        class nuSIM_Profile {
            public const ushort lwm2m_object_id          = 507;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:507";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Encrypted nuSIM profile
            */
            [ResourceId(0), Operations("RW"), Mandatory] string encP;

            /**
            MAC value of encrypted nuSIM profile
            */
            [ResourceId(1), Operations("RW"), Mandatory] string mac;

            /**
            Ephemeral DP public key
            */
            [ResourceId(2), Operations("RW"), Mandatory] string eKpubDP;

            /**
            Signature of eKpubDP created with KpubDP
            */
            [ResourceId(3), Operations("RW"), Mandatory] string SigEKpubDP;

            /**
            nuSIM DP public key
            */
            [ResourceId(4), Operations("RW"), Mandatory] string KpubDP;

            /**
            Signature of KpubDP created with KpubCI
            */
            [ResourceId(5), Operations("RW"), Mandatory] string SigKpubDP;

            /**
            nuSIM CI public key
            */
            [ResourceId(6), Operations("RW"), Mandatory] string KpubCl;
        }

        // ═════════════════════════ 508.xml: nuSIM (urn:oma:lwm2m:oma:508) ═════════════════════════
        /**
        This device management object represents a nuSIM integrated SIM according to NTS.01 - nuSIM Integrated SIM
        Specification.
        */
        class nuSIM {
            public const ushort lwm2m_object_id          = 508;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:508";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Contains the unique identifier of the nuSIM.
            */
            [ResourceId(0), Operations("R"), Mandatory] string EID;

            /**
            Contains the ICCID of the currently loaded nuSIM profile.
            */
            [ResourceId(1), Operations("R"), Mandatory] string ICCID;

            /**
            Contains the supported nuSIM specification version and optional capabilities of the nuSIM.
            */
            [D(65535), ResourceId(2), Operations("R"), Mandatory] Binary[,,] nuSIM_Capabilities;

            /**
            Contains the individual nuSIM certificate CERT.NUSIM.ECDSA, if available.
            */
            [ResourceId(3), Operations("R")] string nuSIM_Cert;

            /**
            Points to an instance of the nuSIM profile object which is to be loaded by executing Load Profile, see
            Resource 5.
            */
            [ResourceId(4), Operations("RW"), Mandatory] ObjectLink nuSIM_Profile;

            /**
            Contains the result of the last Load Profile operation: 0=successful, 1=not successful, other values are
            implementation-specific.
            */
            [ResourceId(6), Operations("R"), Mandatory] byte Load_Profile_Result;

            /**
            Loads the profile instance referenced in Resource 4 to nuSIM.
            Execute operation on resource 5 (Load Profile); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E"), Mandatory] public class Load_Profile_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 509.xml: Measurement Metadata (urn:oma:lwm2m:oma:509) ═════════════════════════
        /**
        This object contains measurement metadata for sensor objects. The corresponding sensor is identified with an
        object link. If the LwM2M Client provides measurement quality information both inside the sensor objects and
        in the Measurement Metadata object, it MUST ensure that identical data is reported in corresponding object
        instances. The LwM2M Server SHOULD use the data from the Measurement Metadata object if both are available.
        The LwM2M Client also MUST ensure that no two Measurement Metadata object instances link to the same sensor
        object instance. If the LwM2M Server receives such non-conforming data, the Measurement Metadata object
        instance with largest Instance ID SHOULD be used.
        */
        class Measurement_Metadata {
            public const ushort lwm2m_object_id          = 509;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:509";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Link to the sensor object instance that this metadata relates to.
            */
            [ResourceId(0), Operations("R"), Mandatory] ObjectLink Linked_Sensor;

            /**
            Measurement quality degradation reason reported by a smart sensor. A degraded measurement has Measurement
            Quality Indicator value 1-3 or Measurement Quality Level less than 100.
            0: UNKNOWN Reason is unknown.
            1: UNDER_RANGE Measured value is under measurement range.
            2: OVER_RANGE Measured value is over measurement range.
            3: NOISY Measured value seems to change too quickly.
            4: STUCK_VALUE Measured value seems to change too slowly.
            5: STEP_TOO_HIGH Measured value has changed too much.
            6: CALIBRATION_EXPIRED Sensor calibration has expired.
            7: WARMING_UP Sensor is warming up.
            8: SERVICE_MODE Sensor is under service.
            9: HUMAN_INTERFERENCE Human presence near the sensor.
            10: NATURAL_INTERFERENCE Natural phenomenon or animal presence.
            11: CONTAMINATION Contamination of the sensor.
            12: HW_FAILURE Sensor hardware has failed.
            13: LACK_OF_DATA_SAMPLES Data sampling is lossy.
            14: OUT_OF_OPERATING_RANGE Environment conditions exceeded.
            15: AUTO_CALIBRATION Auto calibration in progress.
            16-127: RESERVED_GENERIC_BLOCK Reserved generic block.
            128-511: VENDOR_SPECIFIC_BLOCK Vendor specific block.
            512-1023: RESERVED_VENDOR_BLOCK Reserved vendor specific block.
            */
            [MinMax(0, 1023), ResourceId(1), Operations("R")] ushort[,,] Measurement_Quality_Reason_Code;

            /**
            Measurement quality indicator reported by a smart sensor.
            0: UNCHECKED No quality checks were done because they do not exist or can not be applied.
            1: REJECTED WITH CERTAINTY The measured value is invalid.
            2: REJECTED WITH PROBABILITY The measured value is likely invalid.
            3: ACCEPTED BUT SUSPICIOUS The measured value is likely OK.
            4: ACCEPTED The measured value is OK.
            5-15: Reserved for future extensions.
            16-23: Vendor specific measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;
        }

        // ═════════════════════════ 510.xml: Vendor Specific Measurement Quality Reason (urn:oma:lwm2m:oma:510) ═════════════════════════
        /**
        This object contains description for vendor specific measurement quality reason codes provided in a
        Measurement Metadata (509) object. Instances of this object define the mapping of vendor specific reason codes
        to reason description in the scope of an individual device.
        */
        class Vendor_Specific_Measurement_Quality_Reason {
            public const ushort lwm2m_object_id          = 510;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:510";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Measurement quality degradation reason reported by a smart sensor. Reason codes 0-127 are generic reason codes
            and they are defined in Measurement Metadata object description.
            128-511: VENDOR_SPECIFIC_BLOCK Vendor specific block. This block contains vendor specific quality reason
            codes.
            512-1023: RESERVED_VENDOR_BLOCK Reserved vendor specific block. This block is reserved for future use.
            */
            [MinMax(128, 1023), ResourceId(0), Operations("R"), Mandatory] ushort Vendor_Specific_Quality_Reason_Code;

            /**
            The name of the quality reason. It is used as a key to find a localized reason description. The name should be
            concise and unique in the localization scope.
            */
            [D(+128), ResourceId(1), Operations("R"), Mandatory] string Quality_Reason_Name;

            /**
            Description of the quality reason. This text can be used if a localized version is not found.
            */
            [ResourceId(2), Operations("R"), Mandatory] string Quality_Reason_Description;
        }

        // ═════════════════════════ 511.xml: Compact Composite (urn:oma:lwm2m:oma:511) ═════════════════════════
        /**
        This Object enables collecting a set of Resource values from other Objects into a single Resource
        representation.
        */
        class Compact_Composite {
            public const ushort lwm2m_object_id          = 511;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:511";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            One or more CoRE Links to Readable Single Resources and/or Resource Instances of Readable Multiple Resources
            in the same LwM2M Client, from which the values will be stored in the Compact Data array. Each link
            corresponds to an item in the Compact Data array: first link points to the resource instance with the value
            for the first array item, second link to the instance with the second array item, etc.
            */
            [D(+4096), ResourceId(0), Operations("RW"), Mandatory] string Target_Links;

            /**
            CBOR array of resource values in the same order as the links in the Target Links resource. CBOR simple value
            of undefined should be used as the array item if an error occurs while reading the value for the corresponding
            resource (e.g., link pointing to a resource that doesn't exist or the resource is not allowed to be read
            because of access control rules).
            */
            [D(65535), ResourceId(1), Operations("R"), Mandatory] Binary[,,] Compact_Data;

            /**
            Human-readable description of the Compact Data resulting from the Target Links.
            */
            [ResourceId(2), Operations("RW")] string Description;
        }

        // ═════════════════════════ 513.xml: AI Model Configuration (urn:oma:lwm2m:oma:513) ═════════════════════════
        /**
        This object can be used to provision and configure AI Model capabilities. A new AI model is provisioned using
        the Model, Model URI, and/or Model Description resources. The Input and Input labels resources can be used to
        configure where the model reads the input data and the Output and Output labels resources are used to
        configure where the model writes the output data. When output of one model is used as input of another model,
        the models are chained together. Input and Output transform resources can be used to transform data before
        reading or writing.
        */
        class AI_Model_Configuration {
            public const ushort lwm2m_object_id          = 513;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:513";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The binary representation of the executable model. When executable model is written here, that is used for
            execution when the "Enabled" resource is set to true.
            */
            [D(65535), ResourceId(1), Operations("RW")] Binary[,,] Model;

            /**
            The current version of the model being referred.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string Version;

            /**
            A URL pointing to information describing the operation executed by the function and possibly metadata related
            to the input and/or output.
            */
            [ResourceId(3), Operations("RW")] string Description_URL;

            /**
            URL where to retrieve the model to execute or URI to identify the model to execute (and retrieved with
            alternative methods). When this URI is written, the device attempts to retrieve the model using the URI and
            stores it in the Model resource.
            */
            [ResourceId(4), Operations("RW")] string Model_URI;

            /**
            Cryptographic checksum of the model when one is retrieved from a URI to ensure correctness and integrity of
            the downloaded model.
            */
            [ResourceId(5), Operations("RW")] string Model_Integrity;

            /**
            When a model description (e.g., ONEX file) is written to this resource, the device either 1) attempts to
            convert that into executable model 2) asks third party server to do the conversion or 3) executes the model in
            its native form. If conversion is done, the model is stored in the "Model" resource.
            */
            [D(65535), ResourceId(6), Operations("RW")] Binary[,,] Model_Description;

            /**
            A set of CoRE links / URLs that are pointing to resources at the device (e.g., "/3303/1/5700" for the current
            value of the temperature sensor instance #1) or external resources (e.g., "coaps://foo.example/ac-setpoint"
            for a setpoint of a home automation system). The output resources can be links to other AI Model config
            objects' input resources to enable chaining of models.
            */
            [ResourceId(7), Operations("RW"), Mandatory] string[,,] Inputs;

            /**
            Description of the transformation operations for transforming the data from a local resource / external source
            to format usable with the given model. The transformations functions used are matching the inputs indexes
            unless everything is processed using one function that manage all the inputs. In case of using the matching
            index transformations, the inputs without transformations are marked with empty string.
            */
            [ResourceId(8), Operations("RW")] string[,,] Input_transforms;

            /**
            Labels to describe which input source is connected to which input of the AI model. Label in the resource
            instance 0 describes the Inputs CoRE link instance 0, label in instance 1 the Inputs CoRE link instance 1,
            etc.
            */
            [ResourceId(9), Operations("RW"), Mandatory] string[,,] Input_labels;

            /**
            A set of CoRE links / URLs that are pointing to resources at the device (e.g., "/3308/1/5900" for the setpoint
            actuator set point value of the instance #1) or external resources (e.g., "coap://foo.example/ac-setpoint"
            setpoint of a home automation system). The output resources can be links to other AI Model config objects'
            input resources to enable chaining of models.
            */
            [ResourceId(10), Operations("RW"), Mandatory] string[,,] Outputs;

            /**
            Transforming output from a model specific format to the resource specific format; similar to input transforms.
            The transformations functions used are matching the outputs indexes unless everything is processed using one
            function that manage all the outputs. In case of using the matching index transformations, the output without
            transformations are marked with NULL
            */
            [ResourceId(11), Operations("RW")] string[,,] Output_transforms;

            /**
            Labels to describe which output is connected to which output of the AI model. Label in the resource instance 0
            describes the Inputs CoRE link instance 0, label in instance 1 the Inputs CoRE link instance 1, etc.
            */
            [ResourceId(12), Operations("RW"), Mandatory] string[,,] Output_labels;

            /**
            If true, the function is available to be used. If false, the model is currently inactive. Default value is
            true.
            */
            [ResourceId(13), Operations("RW")] bool? Enabled;

            /**
            Expression for triggering the execution of the model. If no expression is given, the model is executed every
            time any input resource value changes. When condition expression is given, the values of the input resources
            are evaluated using the condition expression. If the expression results in a true value, the model is
            executed. For a false value the model is not executed.
            */
            [ResourceId(14), Operations("RW")] string Condition_expression;
        }

        // ═════════════════════════ 514.xml: EDHOC (urn:oma:lwm2m:oma:514) ═════════════════════════
        /**
        This LwM2M Object provides the keying material and configuration to derive a security context using Ephemeral
        Diffie-Hellman Over COSE (EDHOC) defined in RFC 9528. These LwM2M Object Resources MUST only be
        changed by a LwM2M Bootstrap-Server or Bootstrap from Smartcard and MUST NOT be accessible by any other LwM2M
        Server.
        Normative references:
        - RFC 9528: G. Selander, J. Preuß Mattsson, F. Palombini, "Ephemeral Diffie-Hellman Over COSE (EDHOC)",
        https://www.rfc-editor.org/rfc/rfc9528.html
        - RFC 9668: F. Palombini, M. Tiloca, R. Höglund, S. Hristozov, G. Selander, "Using Ephemeral Diffie-Hellman
        Over COSE (EDHOC) with the Constrained Application Protocol (CoAP) and Object Security for Constrained RESTful
        Environments (OSCORE)", https://www.rfc-editor.org/rfc/rfc9668.html
        */
        class EDHOC {
            public const ushort lwm2m_object_id          = 514;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:514";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The ID_CRED_x of the credential stored in Peer Public Key.
            */
            [D(65535), ResourceId(0), Mandatory] Binary[,,] Peer_Public_Key_Identifier;

            /**
            Stores the Peer's public credential.
            */
            [D(65535), ResourceId(1), Mandatory] Binary[,,] Peer_Public_Key;

            /**
            The ID_CRED_x of the credential stored in Client Public Key. If this Resource is null or not instantiated, the
            LwM2M Client is to generate the ID_CRED_x matching the Client Public Key.
            */
            [ResourceId(2)] long? Client_Key_Identifier;

            /**
            Stores the LwM2M Client's public credential.
            If this Resource is null or not instantiated, the LwM2M Client is to use OOB credentials (e.g. by using EST),
            and the "Private Key" Resource must be null or not instantiated.
            */
            [D(65535), ResourceId(3)] Binary[,,] Client_Public_Key;

            /**
            Stores the LwM2M Client's private key.
            If this Resource is null or not instantiated, the LwM2M Client is to use OOB credentials (e.g. by using EST),
            and the Client Public Key Resource must be null or not instantiated.
            */
            [D(65535), ResourceId(4)] Binary[,,] Private_Key;

            /**
            The authentication method type value, as defined in
            https://www.iana.org/assignments/edhoc/edhoc.xhtml#edhoc-method-types.
            */
            [ResourceId(5), Mandatory] long Method;

            /**
            Indicates if the LwM2M Client is the EDHOC Initiator.
            If this Resource is not instantiated, the default value is True.
            */
            [ResourceId(6)] bool? Initiator;

            /**
            The label of the EDHOC cipher suite to use as the selected cipher suite. If the Initiator Resource is set to
            True, this Resource must be instantiated.
            */
            [ResourceId(7)] long? Selected_Cipher_Suite;

            /**
            The EDHOC CoAP URI path on the Server to use.
            If this Resource is not instantiated, the default value is "/.well-known/edhoc" when using CoAP.
            */
            [ResourceId(8)] string Peer_EDHOC_CoAP_URI_Path;

            /**
            Indicates if the peer supports EDHOC + OSCORE combined requests as defined in RFC 9668.
            If this Resource is not instantiated, the default value is True.
            */
            [ResourceId(9)] bool? EDHOC_OSCORE_Combined_Request_Support;
        }

        // ═════════════════════════ 600.xml: Cabinet Controller Status (urn:oma:lwm2m:oma:600) ═════════════════════════
        /**
        The OMA Cabinet Controller Status shall provide electrical measurements related to street lines.
        */
        class Cabinet_Controller_Status {
            public const ushort lwm2m_object_id          = 600;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:600";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Sum of current measured on all three lines.
            */
            [ResourceId(1), Operations("R"), Units("A"), Mandatory] double Total_Current_of_all_three_phases;

            /**
            Overall power factor.
            */
            [ResourceId(2), Operations("R")] double? Overall_Power_Factor;

            /**
            Set to True when the overall power factor is below low power factor threshold.
            */
            [ResourceId(3), Operations("R")] bool? Low_power_factor;

            /**
            Total active power import on the 3 lines.
            */
            [ResourceId(4), Operations("R"), Units("W"), Mandatory] double Total_active_power;

            /**
            Total reactive power import on the 3 lines.
            */
            [ResourceId(5), Operations("R"), Units("var"), Mandatory] double Total_reactive_power;

            /**
            Total apparent power import on the 3 lines.
            */
            [Range("-1..1"), ResourceId(6), Operations("R"), Units("VA")] double? Total_apparent_power;

            /**
            Active energy import (unified rate) on the 3 lines.
            */
            [ResourceId(7), Operations("R"), Units("Wh"), Mandatory] double Total_active_energy;

            /**
            Reactive energy import, unified rate, on the 3 lines.
            */
            [ResourceId(8), Operations("R"), Units("varh"), Mandatory] double Total_reactive_energy;

            /**
            Line frequency measured.
            */
            [ResourceId(9), Operations("R"), Units("Hz")] double? Frequency;

            /**
            Seconds over which averaging themeasurements. If 0 or omitted means thatthe measurements are instantaneous.
            */
            [ResourceId(10), Operations("R"), Units("s")] DurationInSeconds? Averaging_period;

            /**
            True if an excessive load is detected, e.g when too much current is being imported
            */
            [ResourceId(11), Operations("R")] bool? Excessive_load;

            /**
            True if an unexpected load is detected, e.g when current is imported despite the load being supposed to be
            disconnected
            */
            [ResourceId(12), Operations("R")] bool? Unexpected_load;

            /**
            Instantaneous voltage measured between line 1 and neutral.
            */
            [ResourceId(13), Operations("R"), Units("V"), Mandatory] double L1_Voltage;

            /**
            Instantaneous voltage measured between line 2 and neutral.
            */
            [ResourceId(14), Operations("R"), Units("V"), Mandatory] double L2_Voltage;

            /**
            Instantaneous voltage measured between line 3 and neutral.
            */
            [ResourceId(15), Operations("R"), Units("V"), Mandatory] double L3_Voltage;

            /**
            Set to True when voltage 1 is below low voltage threshold.
            */
            [ResourceId(16), Operations("R")] bool? L1_Low_voltage;

            /**
            Set to True when voltage 2 is below low voltage threshold.
            */
            [ResourceId(17), Operations("R")] bool? L2_Low_voltage;

            /**
            Set to True when voltage 3 is below low voltage threshold.
            */
            [ResourceId(18), Operations("R")] bool? L3_Low_voltage;

            /**
            Set to True when voltage 1 is above high voltage threshold.
            */
            [ResourceId(19), Operations("R")] bool? L1_High_voltage;

            /**
            Set to True when voltage 2 is above high voltage threshold.
            */
            [ResourceId(20), Operations("R")] bool? L2_High_voltage;

            /**
            Set to True when voltage 3 is above high voltage threshold.
            */
            [ResourceId(21), Operations("R")] bool? L3_High_voltage;

            /**
            Instantaneous current measured.
            */
            [ResourceId(22), Operations("R"), Units("A"), Mandatory] double L1_Current;

            /**
            Instantaneous current measured.
            */
            [ResourceId(23), Operations("R"), Units("A"), Mandatory] double L2_Current;

            /**
            Instantaneous current measured.
            */
            [ResourceId(24), Operations("R"), Units("A"), Mandatory] double L3_Current;

            /**
            Set to True when current 1 is below low current threshold.
            */
            [ResourceId(25), Operations("R")] bool? L1_Low_current;

            /**
            Set to True when current 2 is below low current threshold.
            */
            [ResourceId(26), Operations("R")] bool? L2_Low_current;

            /**
            Set to True when current 3 is below low current threshold.
            */
            [ResourceId(27), Operations("R")] bool? L3_Low_current;

            /**
            Set to True when current 1 is above high current threshold.
            */
            [ResourceId(28), Operations("R")] bool? L1_High_current;

            /**
            Set to True when current 2 is above high current threshold.
            */
            [ResourceId(29), Operations("R")] bool? L2_High_current;

            /**
            Set to True when current 3 is above high current threshold.
            */
            [ResourceId(30), Operations("R")] bool? L3_High_current;

            /**
            True if an unexpected load is detected on line 1, e.g when current is consumed despite the load is supposed to
            be disconnected
            */
            [ResourceId(31), Operations("R")] bool? L1_Unexpected_load;

            /**
            True if an unexpected load is detected on line 2, e.g when current is consumed despite the load is supposed to
            be disconnected
            */
            [ResourceId(32), Operations("R")] bool? L2_Unexpected_load;

            /**
            True if an unexpected load is detected on line 3, e.g when current is consumed despite the load is supposed to
            be disconnected
            */
            [ResourceId(33), Operations("R")] bool? L3_Unexpected_load;

            /**
            Can be used to eventually associateseparate sets of measurements beingprovided with different averaging
            periods
            */
            [ResourceId(34), Operations("R")] long? Meter_ID;

            /**
            Set to True when voltage is below low voltage threshold.
            */
            [ResourceId(35), Operations("RW"), Units("V")] double? Low_voltage_threshold;

            /**
            Threshold above which the high voltage resource is set to True.
            */
            [ResourceId(36), Operations("RW"), Units("V")] double? High_voltage_threshold;

            /**
            Threshold below which the low current resource is set to True.
            */
            [ResourceId(37), Operations("RW"), Units("A")] double? Low_current_threshold;

            /**
            Threshold above which the high current resource is set to True.
            */
            [ResourceId(38), Operations("RW"), Units("V")] double? High_current_threshold;

            /**
            Threshold below which the low power factor resource is set to True.
            */
            [ResourceId(39), Operations("RW")] double? Low_power_factor_threshold;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;
        }

