        // ═════════════════════════ 602.xml: Computational Performance (urn:oma:lwm2m:oma:602) ═════════════════════════
        /**
        The OMA Computational Performance object provides attributes to monitor the load on various aspects of the
        system.
        */
        class Computational_Performance {
            public const ushort lwm2m_object_id          = 602;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:602";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The ID of the process for which the measurements in this object instance were taken.
            0: refers to the computational resources cumulated usage of ALL the Processes / Tasks running on the device
            1-100: Reserved
            100-99999999: Process ID (can be custom defined by the vendor or taken directly from the Process ID / Task ID
            on the OS)
            */
            [ResourceId(0), Operations("R"), Mandatory] long Process_ID;

            /**
            String Identifying the name of the process for which the statics held in this object refer to. If present ,
            when Resource "Process ID" is set to 0, this resource should read "ALL processes"
            */
            [ResourceId(1), Operations("R")] string Process_Name;

            /**
            Time interval, in seconds. during which counters were gathered and statics calculated (i.e 60s = 1 min, 300s =
            5 min, 900s = 15 min rtc..)
            */
            [ResourceId(2), Operations("R")] DurationInSeconds? Measuring_period;

            /**
            The percentage of time in average that the CPU took processing the non-idle task(s) during the measuring
            period defined.
            This is a multi-instance resource, to be used if more than one CPU is present on the device and the vendor
            intends to provide visibility of its statistics. When multicore CPU architectures are used, Instance resource
            0 when used, always refers to the average usage of all cores.
            */
            [ResourceId(10), Operations("R"), Units("%")] long[,,] CPU_Usage;

            /**
            The average of  CPU load over the measuring period defined. CPU load is defined as the number of processes
            using or waiting to use one core at a single point in time.
            i,e. if the CPU load average is always below 0.8. This indicates that every process that needs to use the CPU
            can use it instantly without waiting. If the CPU load average is above 1, this indicates that there are
            processes that need to use the CPU but cannot at the moment due to the unavailability of the CPU.
            When multicore CPU architectures are used, Instance 0 when used, always refers to the average Load amongst all
            cores.
            This is a multi-instance resource, to be used if more than one CPU is present on the device and the vendor
            intends to provide visibility of its statistics. When multicore CPU architectures are used, Instance resource
            0 when used, always refers to the average usage of all cores.
            */
            [ResourceId(11), Operations("R"), Units("%")] long[,,] CPU_Load;

            /**
            The threshold for the percentage of CPU usage that once crossed, should be considered a critical event. If a
            device supports this threshold setting is is expected to also support the "High CPU Usage" resource, once the
            % threshold set in this resource is crossed "High CPU Usage"  resource should be set to 2.
            */
            [ResourceId(15), Operations("RW"), Units("%")] long[,,] Critical_CPU_usage_Threshold;

            /**
            High CPU Usage  state
            0: Low to Normal Usage
            1: Intensive CPU usage
            2: CPU usage running at capacity
            */
            [ResourceId(18), Operations("R")] long[,,] High_CPU_Usage;

            /**
            The percentage of time in average that the GPU took processing non-idle tasks during the measuring period
            defined.
            */
            [ResourceId(20), Operations("R"), Units("%")] long[,,] GPU_Usage;

            /**
            The percentage of available volatile memory consumed by the process(s) identified in resource 0.
            */
            [ResourceId(50), Operations("R"), Units("%")] long? Volatile_Memory_usage;

            /**
            The percentage of available non-volatile memory consumed by the process(s) identified in resource 0.
            */
            [ResourceId(51), Operations("R"), Units("%")] long[,,] Non_Volatile_Memory_usage;

            /**
            The threshold for the percentage of available volatile Memory usage that once crossed, should be considered a
            critical event. If a device supports this threshold setting is is expected to also support the "Low Memory"
            resource, once the % threshold set in this resource is crossed "Low memory" resource should be set to 2.
            */
            [ResourceId(55), Operations("R"), Units("%")] long? Critical_Low_Memory_Threshold;

            /**
            High Memory Usage state:
            0: Low to Normal Usage
            1: Intensive Memory usage
            2: Memory usage running at capacity
            */
            [ResourceId(58), Operations("R")] long? Low_Memory;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;
        }

        // ═════════════════════════ 607.xml: Radar Sensor (urn:oma:lwm2m:oma:607) ═════════════════════════
        /**
        Embedded radar sensor object providing presence, approach, and departure detection, with configurable
        sensitivity and response timing.
        */
        class Radar_Sensor {
            public const ushort lwm2m_object_id          = 607;
            public const string lwm2m_urn                = "urn:oma:lwm2m:oma:607";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Current detection state of the radar sensor. 0: No detection, 1: Approach, 2: Leave, 3: Generic detection
            */
            [MinMax(0, 3), ResourceId(0), Operations("R"), Mandatory] byte Detection_State;

            /**
            Total number of detection events
            */
            [ResourceId(1), Operations("R")] long? Detection_Counter;

            /**
            Sensitivity for approach detection
            */
            [MinMax(0, 100), ResourceId(4), Operations("RW"), Units("%")] byte? Approach_Sensitivity;

            /**
            Sensitivity for leave detection
            */
            [MinMax(0, 100), ResourceId(5), Operations("RW"), Units("%")] byte? Leave_Sensitivity;

            /**
            Response time for approach detection
            */
            [MinMax(16, 2048), ResourceId(6), Operations("RW"), Units("ms")] ushort? Approach_Response_Time;

            /**
            Response time for leave detection
            */
            [MinMax(16, 2048), ResourceId(7), Operations("RW"), Units("ms")] ushort? Leave_Response_Time;

            /**
            Velocity threshold used by the radar sensor for detection
            */
            [ResourceId(8), Operations("RW"), Units("m/s")] double? Target_Velocity;

            /**
            Enable or disable environmental noise filtering
            */
            [ResourceId(9), Operations("RW")] bool? Environment_Noise_Filter;

            /**
            Number of detections within the last hour
            */
            [ResourceId(10), Operations("R")] long? Hourly_Detection_Counter;

            /**
            Indicates a radar sensor communication failure
            */
            [ResourceId(11), Operations("R")] bool? Sensor_Communication_Failure;

            /**
            Total number of approach detection events
            */
            [ResourceId(12), Operations("R")] long? Approach_Detection_Counter;

            /**
            Total number of leave detection events
            */
            [ResourceId(13), Operations("R")] long? Leave_Detection_Counter;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            The application type of the sensor or actuator as a string depending on the use case.
            */
            [ResourceId(5750), Operations("RW")] string Application_Type;
        }

        // ═════════════════════════ 2048.xml: CmdhPolicy (urn:oma:lwm2m:ext:2048) ═════════════════════════
        /**
        This Object provides links to a set of rules associated with a specific CSE that governs the behavior of that
        CSE regarding rejecting, buffering and sending request or response messages via the Mcc reference point.
        */
        class CmdhPolicy {
            public const ushort lwm2m_object_id          = 2048;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:2048";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Contains the name of a CmdhPolicy Object Instance
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Name;

            /**
            1 reference to CmdhDefaults Object  Instance
            */
            [ResourceId(1), Operations("RW"), Mandatory] ObjectLink DefaultRule;

            /**
            1 or more references to CmdhLimits Object Instances
            */
            [ResourceId(2), Operations("RW"), Mandatory] ObjectLink[,,] LimiRules;

            /**
            1 or more references to CmdhNetworkAccessRules Object Instances
            */
            [ResourceId(3), Operations("RW"), Mandatory] ObjectLink[,,] NetworkAccessECRules;

            /**
            1 or more references to CmdhBuffer Object Instances
            */
            [ResourceId(4), Operations("RW"), Mandatory] ObjectLink[,,] BufferRules;
        }

        // ═════════════════════════ 2049.xml: ActiveCmdhPolicy (urn:oma:lwm2m:ext:2049) ═════════════════════════
        /**
        This Object provides a link to the currently active set of CMDH policies
        */
        class ActiveCmdhPolicy {
            public const ushort lwm2m_object_id          = 2049;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:2049";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Contains the reference to the CMDH policies (CmdhPolicy Object Instance) currently active for the associated
            CSE.
            */
            [ResourceId(0), Operations("RW"), Mandatory] ObjectLink ActiveLink;
        }

