            /**
            The current value of the analog input.
            */
            [ResourceId(5600), Operations("R"), Mandatory] double Analog_Input_Current_Value;

            /**
            The minimum value measured by the sensor since power ON or reset.
            */
            [ResourceId(5601), Operations("R")] double? Min_Measured_Value;

            /**
            The maximum value measured by the sensor since power ON or reset.
            */
            [ResourceId(5602), Operations("R")] double? Max_Measured_Value;

            /**
            The minimum value that can be measured by the sensor.
            */
            [ResourceId(5603), Operations("R")] double? Min_Range_Value;

            /**
            The maximum value that can be measured by the sensor.
            */
            [ResourceId(5604), Operations("R")] double? Max_Range_Value;

