        // ═════════════════════════ 3310.xml: Load Control (urn:oma:lwm2m:ext:3310:1.1) ═════════════════════════
        /**
        This Object is used for demand-response load control and other load control in automation application (not
        limited to power).
        */
        class Load_Control {
            public const ushort lwm2m_object_id          = 3310;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3310:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The event identifier as a string.
            */
            [ResourceId(5823), Operations("RW"), Mandatory] string Event_Identifier;

            /**
            Time when the event started.
            */
            [ResourceId(5824), Operations("RW"), Mandatory] DateTime Start_Time;

            /**
            The duration of the event in minutes.
            */
            [ResourceId(5825), Operations("RW"), Units("min"), Mandatory] DurationInMinutes Duration_In_Min;

            /**
            The criticality of the event. The device receiving the event will react in an appropriate fashion for the
            device.
            */
            [MinMax(0, 3), ResourceId(5826), Operations("RW")] byte? Criticality_Level;

            /**
            Defines the maximum energy usage of the receiving device, as a percentage of the device's normal maximum
            energy usage.
            */
            [MinMax(0, 100), ResourceId(5827), Operations("RW"), Units("/100")] byte? Avg_Load_AdjPct;

            /**
            Defines the duty cycle for the load control event, i.e, what percentage of time the receiving device is
            allowed to be on.
