        // ═════════════════════════ 3340.xml: Timer (urn:oma:lwm2m:ext:3340) ═════════════════════════
        /**
        This IPSO object is used to time events and actions, using patterns common to industrial timers. A write to
        the trigger resource or On/Off input state change starts the timing operation, and the timer remaining time
        shows zero when the operation is complete. The patterns supported are One-Shot (mode 1), On-Time or Interval
        (mode 2), Time delay on pick-up or TDPU (mode 3), and Time Delay on Drop-Out or TDDO (mode 4). Mode 0 disables
        the timer, so the output follows the input with no delay. A counter is provided to count occurrences of the
        timer output changing from 0 to 1. Writing a value of zero resets the counter. The Digital Input State
        resource reports the state of the timer output.
        */
        class Timer {
            public const ushort lwm2m_object_id          = 3340;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3340";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The duration of the time delay.
            */
            [ResourceId(5521), Operations("RW"), Units("s"), Mandatory] double Delay_Duration;

            /**
            The time remaining in an operation.
            */
            [ResourceId(5538), Operations("R"), Units("s")] double? Remaining_Time;

            /**
            The duration of the rearm delay (i.e. the delay from the end of one cycle until the beginning of the next, the
            inhibit time).
            */
            [ResourceId(5525), Operations("RW"), Units("s")] double? Minimum_Off_time;

            /**
            On/off control. Boolean value where True is On and False is Off.
            */
            [ResourceId(5850), Operations("RW")] bool? On_Off;

            /**
            The cumulative value of active state detected.
            */
            [ResourceId(5501), Operations("R")] long? Digital_Input_Counter;

            /**
            The total time in seconds that the timer input is true. Writing a 0 resets the time.
            */
            [ResourceId(5544), Operations("RW"), Units("s")] double? Cumulative_Time;

            /**
            The current state of the timer output.
            */
            [ResourceId(5543), Operations("R")] bool? Digital_State;

            /**
            Counts the number of times the timer output transitions from 0 to 1.
            */
            [ResourceId(5534), Operations("RW")] long? Counter;

            /**
            Type of timer pattern used by the timer. 1: One-shot, 2: On-Time or Interval, 3: Time delay on pick-up, 4:
            Time Delay on Drop-Out, 0: disables the timer.
            */
            [MinMax(0, 4), ResourceId(5526), Operations("RW")] byte? Timer_Mode;

            /**
            The application type of the sensor or actuator as a string depending on the use case.
            */
            [ResourceId(5750), Operations("RW")] string Application_Type;

            /**
            Trigger initiating actuation.
            Execute operation on resource 5523 (Trigger); sent by the Server to the Client.
            */
            [ResourceId(5523), Operations("E")] public class Trigger_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3341.xml: Addressable Text Display (urn:oma:lwm2m:ext:3341) ═════════════════════════
        /**
        This IPSO object is used to send text to a text-only or text mode graphics display. Writing a string of text
        to the text resource causes it to be displayed at the selected X and Y locations on the display. If X or Y are
        set to a value greater than the size of the display, the position "wraps around" to the modulus of the setting
        and the display size. Likewise, if the text string overflows the display size, the text "wraps around" and
        displays on the next line down or, if the last line has been written, wraps around to the top of the display.
        Brightness and Contrast controls are provided to allow control of various display types including STN and DSTN
        type LCD character displays. Writing an empty payload to the Clear Display resource causes the display to be
        erased.
        */
        class Addressable_Text_Display {
            public const ushort lwm2m_object_id          = 3341;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3341";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            A string of text.
            */
            [ResourceId(5527), Operations("RW"), Mandatory] string Text;

            /**
            X Coordinate.
            */
            [ResourceId(5528), Operations("RW")] long? X_Coordinate;

            /**
            Y Coordinate.
            */
            [ResourceId(5529), Operations("RW")] long? Y_Coordinate;

            /**
            The highest X coordinate the display supports before wrapping to the next line.
            */
            [ResourceId(5545), Operations("R")] long? Max_X_Coordinate;

            /**
            The highest Y coordinate the display supports before wrapping to the next line.
            */
            [ResourceId(5546), Operations("R")] long? Max_Y_Coordinate;

            /**
            Used to represent a level control such as audio volume.
            */
            [Range("0..100"), ResourceId(5548), Operations("RW"), Units("/100")] double? Level;

            /**
            Proportional control, integer value between 0 and 100 as a percentage.
            */
            [Range("0..100"), ResourceId(5531), Operations("RW"), Units("/100")] double? Contrast;

            /**
            The application type of the sensor or actuator as a string depending on the use case.
            */
            [ResourceId(5750), Operations("RW")] string Application_Type;

            /**
            Command to clear the display.
            Execute operation on resource 5530 (Clear Display); sent by the Server to the Client.
            */
            [ResourceId(5530), Operations("E")] public class Clear_Display_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

