        // ═════════════════════════ 3366.xml: macRachAttemptEvent (urn:oma:lwm2m:ext:3366) ═════════════════════════
        /**
        RACH information. Logged at RACH TX
        */
        class macRachAttemptEvent {
            public const ushort lwm2m_object_id          = 3366;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3366";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            RACH Attempt Counter
            */
            [ResourceId(0), Operations("R"), Mandatory] long rachAttemptCounter;

            /**
            0 = Success
            1 = Failure-At-Msg-2
            2 = Failure-At-Msg-4-CT-Timer-Expired
            3 = Failure-At-Msg-4-CT-Resolution-Not-Passed
            4 = Aborted
            */
            [ResourceId(1), Operations("R"), Mandatory] long MacRachAttemptEventType;

            /**
            1 = Contention based
            0 = otherwise
            */
            [ResourceId(2), Operations("R"), Mandatory] bool contentionBased;

            /**
            1 = MSG 1
            2 = MSG 2
            3 = MSG 3
            */
            [ResourceId(3), Operations("R"), Mandatory] long rachMessage;

            /**
            preambleIndex=There are 64 preambles available in each cell. Range is from 0-63. (3GPP 36.211)
            */
            [ResourceId(4), Operations("R"), Mandatory] long preambleIndex;

            /**
            preamblePowerOffset= stepsize*preamble transmission number
            */
            [ResourceId(5), Operations("R"), Mandatory] long preamblePowerOffset;

            /**
            Backoff Time
            */
            [ResourceId(6), Operations("R"), Mandatory] long backoffTime;

            /**
            1 = pass
            0 = fail
            */
            [ResourceId(7), Operations("R"), Mandatory] bool msg2Result;

            /**
            Timing Adjustment Value
            */
            [ResourceId(8), Operations("R"), Mandatory] long timingAdjustmentValue;
        }

