            ZadOFF Sequence Number (0..837)
            */
            [ResourceId(3), Operations("R"), Mandatory] long zadOffSeqNum;

            /**
            Random access preamble timing for a range of preamble formats (0..64)
            */
            [ResourceId(4), Operations("R"), Mandatory] long prachConfig;

            /**
            Preamble Format (0..4)
            */
            [ResourceId(5), Operations("R"), Mandatory] long preambleFormat;

            /**
            Max number of HARQ re-transmissions from UE for RACH message 3 (1..8)
            */
            [ResourceId(6), Operations("R"), Mandatory] long maxTransmissionMsg3;

            /**
            Window size for reception of RACH message 2 (2..10)
            */
            [ResourceId(7), Operations("R"), Mandatory] long raResponseWindowSize;

            /**
            RACH Request success/failure - 0=fail, 1=pass
            */
            [ResourceId(8), Operations("R"), Mandatory] bool RachRequestResult;

            /**
            CE_mode
            */
            [ResourceId(9), Operations("R"), Mandatory] long ce_mode;

            /**
            CE level
            */
            [ResourceId(10), Operations("R"), Mandatory] long ce_level;

            /**
            Number of PRACH Repetitions
            */
            [ResourceId(11), Operations("R"), Mandatory] long num_prach_repetition;

            /**
            PRACH Repetition seq
            */
            [ResourceId(12), Operations("R"), Mandatory] long prach_repetition_seq;
        }

