        // ═════════════════════════ 3395.xml: oA Logical Push-Button Sensor (urn:oma:lwm2m:ext:3395) ═════════════════════════
        /**
        The 'oA Logical Push-Button Sensor' represents the logical part of a standard, normally open, push-button
        input. The corresponding physical device is a button with a spring that returns the button to the un-pushed
        state once it is released.\nThe Object supports several events such as 'click', 'hold', 'double-click' and
        'release'. It also indicates if the button is 'stuck'. For physical devices with multiple push-button inputs,
        an instance of this Object is required to map each input.
        */
        class oA_Logical_Push_Button_Sensor {
            public const ushort lwm2m_object_id          = 3395;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3395";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            LWM2M Object versioning label.
            */
            [ResourceId(4001), Operations("R")] string ObjectVersion;

            /**
            Resource to hold a documentary text description of the object.
            */
            [D(+256), ResourceId(901), Operations("RW")] string Documentary_Description;

            /**
            This Resource represents the last generated Event by the push-button:\n* 0: RELEASE - push-button was
            released\n* 1: CLICK - single click detected\n* 2: HOLD - long press/hold detected\n* 3: DOUBLE-CLICK - two
            sequential clicks detected\n* 255: STUCK - button was detected as stuck.\n\t\t\t\n*Note* The Push-Button Event
            allows to filter part of the behaviour of the press/release actions from a user. Instead of reporting all
            press/release operations, this resource only reports a new value when a specific operation occurs.
            */
            [Range("0: RELEASE\n\t\t\t\t1: CLICK\n\t\t\t\t2: HOLD\n\t\t\t\t3: DOUBLE-CLICK\n\t\t\t\t255: STUCK"), ResourceId(202), Operations("R"), Mandatory] ulong Push_Button_Event_Value;

            /**
            Link to the Object Instance in CoRE Link Format [RFC6690](https://tools.ietf.org/html/rfc6690)
            */
            [D(+4096), ResourceId(909), Operations("RW"), Mandatory] string Executing_Object;

            /**
            Defines the maximum period of time the push-button can be pressed, in order to be recognized as 'click'. If
            the button is pressed longer than this time period, it is recognized as 'hold' press. See Resource description
            of Push-Button Event for details.\n*Note* the maximum limit for this value is 60s, as any press longer than
            that is considered 'stuck button'.
            */
            [MinMax(100, 60000), ResourceId(203), Operations("RW"), Units("ms"), Mandatory] ushort Single_Click_Time;

            /**
            Defines the period of time between repetitions of push-button event reporting messages with 'hold' value.
            After the 'hold' event is triggered and the first message is sent, the 'hold' message is repeated every time
            the 'Hold Repeat Time' is past, and until a 'release' or 'button stuck' state is reached.This value should
            always be higher than 'Single Click Time' and small intervals may significantly affect network
            performance.\n*Note* the maximum limit for this value is 60s, as any press longer than that is considered
            'stuck button'.
            */
            [MinMax(300, 60000), ResourceId(204), Operations("RW"), Units("ms")] ushort? Hold_Repeat_Time;

            /**
            The application group ID that the logical object is part of. This ID will define the application group the
            status reports are sent to. It is internally used as a pointer to the Group Object instance that hosts all the
            Group configurations.
            */
            [ResourceId(903), Operations("RW"), Mandatory] ushort Application_Group_ID;

            /**
            The time specified as status resend time is used to resend the actual status to the application group the
            object is a member of, even if nothing changed.\nThe status resend time is restarted after every event. The
            actual interval is a random time with the maximum duration given by this resource. Randomization helps to
            avoid massive ongoing message collisions after system power up.\nFor example: Status resend time is set to 10
            seconds;\n* 00:00 status is sent\n* 00:05 status changes and is sent immediatly\n* 00:15 (or before, depending
            on the randomization) status is sent even though it did not change
            */
            [MinMax(1, 600), ResourceId(904), Operations("RW"), Units("s"), Mandatory] ushort Status_Resend_Time;

            /**
            The ID of the status resource structure that is used to code the cyclic status report. See object 4012 'oA
            Status Report Structure' for more information
            */
            [ResourceId(919), Operations("RW"), Mandatory] byte Status_Report_Structure_ID;

            /**
            Enables the object test mode. The physical representation of the object will be disabled. Stimuli can be
            injected to test the object remotely using inject test event.
            */
            [ResourceId(905), Operations("RW")] bool? Debug_Mode_Enabled;

            /**
            Defines the test events to be injected into the system when debug mode is enabled. Event definition is vendor
            specific.
            */
            [ResourceId(906), Operations("W")] ushort? Inject_Test_Event;

            /**
            This resource allows to disable an object instance. \nIf an object instance is disabled it does process
            incoming events but does not create outgoing events.
            */
            [ResourceId(924), Operations("RW")] bool? Object_Enabled;

            /**
            When executed, a test event s specified in 906 will be injected \nIf an object instance is disabled it does
            process incoming events but does not create outgoing events.
            Execute operation on resource 934 (Object Enabled); sent by the Server to the Client.
            */
            [ResourceId(934), Operations("E")] public class Object_Enabled_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3396.xml: oA Physical Colour Light-Point Actuator (urn:oma:lwm2m:ext:3396) ═════════════════════════
        /**
        The 'oA_Physical_Colour_Light-Point_Actuator' represents a physical colour light-point actuator. It is
        necessary to map at least on Logical Light Point Actuator to control the intensity and one Logical Colour
        Light-Point to control the colour to the Physical Colour Light-Point.
        */
        class oA_Physical_Colour_Light_Point_Actuator {
            public const ushort lwm2m_object_id          = 3396;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3396";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            LWM2M Object versioning label.
            */
            [ResourceId(4001), Operations("R")] string ObjectVersion;

            /**
            Resource to hold a documentary text description of the object.
            */
            [D(+256), ResourceId(901), Operations("RW")] string Documentary_Description;

            /**
            Error status is a bit coded value that shows all current errors on the object. The error status changes as
            soon as a new error occurs or an old one is resolved. Bitwise: 0 (LSB): Hardware_Error, 1:
            Execution_Limit_LED_Temp, 2: Execution_Limit_Power_Restrictions, 3: Light-Point_Malfunction
            */
            [D(65535), ResourceId(907), Operations("R"), Mandatory] Binary[,,] Error_Status;

            /**
            Describes the location of the device within the building. The content of the string is site specific.
            */
            [D(+64), ResourceId(908), Operations("RW"), Units("B"), Mandatory] string Mounting_Location;

            /**
            On/off control. Boolean value where True is On and False is Off.
            */
            [ResourceId(5850), Operations("RW"), Mandatory] bool On_Off;

            /**
            This Resource represents the current intensity (0-1). This is a 'real-time' value, which is given
            independently of any ongoing dimming request.
            */
            [Range("0.0..1.0"), ResourceId(100), Operations("R"), Mandatory] double Current_Intensity;

            /**
            Remaining approximated time of any ongoing 'Set Intensity', 'Step' or 'Switch' process which requires a
            variation of the light output over a period of time higher or equal to one 100ms interval. When the process is
            started, the value is equal to the time value selected for the process and it is continuously decreased until
            completed (time=0), or a 'Stop Dimming' request is received.\n\t\t\t\t\n**NOTE:** If during a request the
            process reaches the Maximum/Minimum Intensity limits, the time is automatically set to '0' as the process is
            stopped. Scaling is 100ms per unit
            */
            [ResourceId(102), Operations("R"), Units("ms"), Mandatory] ushort Remaining_Transition_Time;

            /**
            This Resource represents the x value of the current colour. This is a 'real-time' value, which is given
            independently of any ongoing change request. Scaling is 0.0001 per unit
            */
            [MinMax(0, 10000), ResourceId(122), Operations("R"), Units("K"), Mandatory] ushort Current_Colour_Y;

            /**
            This Resource represents the y value of the current colour. This is a 'real-time' value, which is given
            independently of any ongoing change request. Scaling is 0.0001 per unit
            */
            [MinMax(0, 10000), ResourceId(123), Operations("R"), Units("K"), Mandatory] ushort Current_Colour_X;

            /**
            Remaining approximated time of any ongoing colour change process which requires a variation of the light
            output over a period of time higher or equal to one 100ms interval. When the process is started, the value is
            equal to the time value selected for the process and it is continuously decreased until completed (time=0), or
            a 'Stop' request is received.\n\t\t\t\t\n**NOTE:** If during a request the process reaches the colour limits,
            the time is automatically set to '0' as the process is stopped. Scaling is 100ms per unit
            */
            [ResourceId(124), Operations("R"), Units("ms"), Mandatory] ushort Remaining_Colour_Transition_Time;

            /**
            The total energy usage of the device (accumulated value)
            */
            [Range("0..18446744073709551615"), ResourceId(910), Operations("R"), Units("Ws"), Mandatory] ulong Total_Energy_Usage;

            /**
            The actual power usage of the device. Scaling is 0.1W per unit
            */
            [ResourceId(911), Operations("R"), Units("W"), Mandatory] uint Actual_Power_Usage;

            /**
            The accuracy class of the energy sensor on the device (using either % accuracy or a letter that defines the
            accuracy class)
            */
            [D(+64), ResourceId(912), Operations("R")] string Accuracy_Class;

            /**
            The total operating hours where the light point is on.
            */
            [ResourceId(930), Operations("R"), Units("h"), Mandatory] uint Operating_Hours;

            /**
            The total operating hours adjusted by the dim level of the luminaire.
            */
            [ResourceId(931), Operations("R"), Mandatory] uint Adjusted_Operating_Hours;

            /**
            Minimum intensity that can be set for this instance of a Light Point. This value is factory defined by
            luminaire or gear manufacturer.
            */
            [Range("0.000001..1.0"), ResourceId(103), Operations("R")] double? Physical_Minimum_Intensity;

            /**
            The value set in this Resource limits the minimum output of the Light Point. when performing any transition
            operation (e.g. Switch(ON),'Dim(DOWN)','Step(DOWN)' or Set_Intensity(x)') the minimum intensity value
            indicated by this Resource will override any other definition or request input parameter value.\nChanging this
            Resource stops any transition process, and the 'Remaining Transition Time' and 'Current Intensity' are
            updated.\n\t\t\t\n**Note:** This value must be greater or equal to 'Physical Minimum Intensity' and smaller or
            equal to 'Maximum Intensity'. If a Light Point with fixed output is used, the 'Minimum Intensity' and 'Maximum
            Intensity' MUST be defined with the same value.
            */
            [Range("0.000001..1.0"), ResourceId(104), Operations("RW"), Mandatory] double Minimum_Intensity;

            /**
            The value set in this Resource limits the maximum output of the Light Point. when performing any transition
            operation (e.g. Switch(ON),'Dim(UP)','Step(UP)' or Set_Intensity(x)') the maximum intensity value indicated by
            this Resource will override any other definition or request input parameter value.\nChanging this Resource
            stops any transition process, and the 'Remaining Transition Time' and 'Current Intensity' are
            updated.\n\t\t\t\n**Note:** This value must be greater or equal to 'Minimum Intensity'. If a Light Point with
            fixed output is used, the 'Minimum Intensity' and 'Maximum Intensity' MUST be defined with the same value.
            */
            [Range("0.000001..1.0"), ResourceId(105), Operations("RW"), Mandatory] double Maximum_Intensity;

            /**
            Defines the default behaviour of the light point when it is switched 'On'. The following options are
            possible:\n- *CONFIGURED_ON* intensity goes to the stored default value ('Power On Intensity') [default
            option]\n- *FULL_ON* intensity always goes to the maximum intensity value allowed\n- *RECALL* if available,
            the intensity is recalled from 'Stored Intensity', otherwise 'Power On Intensity' is used
            */
            [Range("0: CONFIGURED_ON\n\t\t\t\t1: FULL_ON\n\t\t\t\t2: RECALL"), ResourceId(110), Operations("RW")] ulong? Power_On_Behaviour;

            /**
            Defines the default Intensity used in switch operations that result in a 'On' state. It is used if no
            intensity is given in the switch request payload and if 'Power On Behaviour' is CONFIGURED_ON. When this
            Resource is not defined, the value to be used should be '1'.\n\t\t\t\t\n**Note:** When setting this value, the
            Minimum/Maximum intensity limits must be validated. A write request that requires the final value to be
            adjusted should send a reply message with the corrected value.
            */
            [Range("0.000001..1.0"), ResourceId(111), Operations("RW")] double? Power_On_Intensity;

            /**
            This Resource represents a copy of the last 'Current Intensity' that is bigger than 0, before a power cycle is
            triggered. It should be updated in NVM whenever a transition process is completed, and optionally if a power
            cycle is triggered.
            */
            [Range("0.000001..1.0"), ResourceId(114), Operations("R")] double? Stored_Intensity;

            /**
            This is the intensity value the light point goes to if the connection to the network is lost for longer than
            'System Failure Time'.\n\t\t\t\t\n**Note:** When setting the value of this Resource, the limits of 'Minimum
            Intensity' and 'Maximum Intensity' must be validated. A write operation that requires the final value to be
            adjusted should result in a reply message with the final corrected value.\nIndependently of the previous
            limits, a '0' value is allowed and it means, in case of network failure, the 'On/Off Status' is set to 'Off'.
            */
            [Range("0.000001..1.0"), ResourceId(115), Operations("RW")] double? System_Failure_Intensity;
        }

