        // ═════════════════════════ 3402.xml: oA Receiving Object (urn:oma:lwm2m:ext:3402) ═════════════════════════
        /**
        The 'oA Receiving Object' provides a resource for sensors/actuators to report their status message to. It is
        used with control objects as logical object that forwards the sensor and status data to the executing
        object.\nIt is also used to receive the 'go bootstrap' message, using the Struct-ID 255, in OOTB mode.
        */
        class oA_Receiving_Object {
            public const ushort lwm2m_object_id          = 3402;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3402";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            LWM2M Object versioning label.
            */
            [ResourceId(4001), Operations("R")] string ObjectVersion;

            /**
            Resource to hold a documentary text description of the object.
            */
            [D(+256), ResourceId(901), Operations("RW")] string Documentary_Description;

            /**
            Link to the Object Instance in CoRE Link Format [RFC6690](https://tools.ietf.org/html/rfc6690)
            */
            [D(+4096), ResourceId(909), Operations("RW"), Mandatory] string Executing_Object;

            /**
            The actuators and sensors report their status to this resource. It is also used to receive the 'go bootstrap'
            message, using the Struct-ID 255, in OOTB mode.
            */
            [D(65535), ResourceId(923), Operations("W"), Mandatory] Binary[,,] Status_Report;
        }

        // ═════════════════════════ 3403.xml: oA Reporting Object (urn:oma:lwm2m:ext:3403) ═════════════════════════
        /**
        The 'oA Reporting Object' packs several status messages available at the node into a single, size optimized
        message, as e.g. used with data collect or BMS interfacing.
        */
        class oA_Reporting_Object {
            public const ushort lwm2m_object_id          = 3403;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3403";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            LWM2M Object versioning label.
            */
            [ResourceId(4001), Operations("R")] string ObjectVersion;

            /**
            Resource to hold a documentary text description of the object.
            */
            [D(+256), ResourceId(901), Operations("RW")] string Documentary_Description;

            /**
            List of links to the reporting Object Instances in CoRE Link Format
            [RFC6690](https://tools.ietf.org/html/rfc6690)
            */
            [D(+4096), ResourceId(932), Operations("RW"), Mandatory] string[,,] Reporting_Object_Instances;

            /**
            Link to the target resource in CoRE Link Format [RFC6690](https://tools.ietf.org/html/rfc6690)\nNote taht the
            default for this entry is always the receiving object /4009/#/923. When Group communication is applied, the
            /#/ is determined by the group handling mechanisms and can be omitted.
            */
            [D(+4096), ResourceId(933), Operations("RW"), Mandatory] string Target_Resource;

            /**
            The time specified as status resend time is used to resend the actual status to the application group the
            object is a member of, even if nothing changed.\nThe status resend time is restarted after every event. The
            actual interval is a random time with the maximum duration given by this resource. Randomization helps to
            avoid massive ongoing message collisions after system power up.\nFor example: Status resend time is set to 10
            seconds;\n* 00:00 status is sent\n* 00:05 status changes and is sent immediatly\n* 00:15 (or before, depending
            on the randomization) status is sent even though it did not change
            */
            [MinMax(1, 600), ResourceId(904), Operations("RW"), Units("s"), Mandatory] ushort Status_Resend_Time;

            /**
            The ID of the status resource structure that is used to code the cyclic status report. See object 4012 'oA
            Status Report Structure' for more information
            */
            [MinMax(1, 600), ResourceId(919), Operations("RW"), Units("s"), Mandatory] ushort Status_Report_Structure_ID;

            /**
            The application group ID that the logical object is part of. This ID will define the application group the
            status reports are sent to. It is internally used as a pointer to the Group Object instance that hosts all the
            Group configurations.
            */
            [ResourceId(903), Operations("RW"), Units("s"), Mandatory] ushort Application_Group_ID;
        }

        // ═════════════════════════ 3404.xml: oA Scene (urn:oma:lwm2m:ext:3404) ═════════════════════════
        /**
        The 'oA Scene' represents a scene model. The scene holds defined values for each actuator in one group.
        */
        class oA_Scene {
