            LWM2M Object versioning label.
            */
            [ResourceId(4001), Operations("R")] string ObjectVersion;

            /**
            Resource to hold a documentary text description of the object.
            */
            [D(+256), ResourceId(901), Operations("RW")] string Documentary_Description;

            /**
            The ID that is used to recall the scene. This needs to be unique within one application group.
            */
            [ResourceId(650), Operations("RW"), Mandatory] ushort Scene_ID;

            /**
            The application group ID the scene definition applies to.
            */
            [ResourceId(651), Operations("RW"), Mandatory] ushort Application_Group_ID;

            /**
            If true, the settings for this scene can be changed using the User API.
            */
            [ResourceId(655), Operations("RW"), Mandatory] bool Changeable_by_User_API;

