        // ═════════════════════════ 3410.xml: Device Extension (urn:oma:lwm2m:ext:3410:2.0) ═════════════════════════
        /**
        The uCIFI device extension is an extension to the standard Lightweight M2M device (object ID 3) using the
        resource called "ExtDevInfo" (resource ID 22).
        */
        class Device_Extension {
            public const ushort lwm2m_object_id          = 3410;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3410:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Standard global trade-in international number for the control device.
            */
            [ResourceId(1), Operations("R")] string GTIN_model_number;

            /**
            Unique identifier of the manufacturer of the control device, equivalent to IEEE's OUI (Organizational Unique
            Identifier). This value should be a Hexadecimal value. This value may be used by an online uCIFI product
            catalog server, for software modules to retrieve the data model of a device using this attribute associated
            with the model number on the "Device" (Id=3) object.
            */
            [ResourceId(2), Operations("R"), Mandatory] string Manufacturer_identifier;

            /**
            User-readable name of the device set by the user.
            */
            [ResourceId(3), Operations("RW")] string User_given_name;

            /**
            Identifier of the asset (e.g. meter, luminaire, container) that is controlled by the device.
            */
            [ResourceId(4), Operations("RW")] string Asset_identifier;

            /**
            Installation date of the device.
            */
            [ResourceId(5), Operations("RW")] DateTime? Installation_date;

            /**
            Set to True while software within the device is being updated.
            */
            [ResourceId(6), Operations("RW")] bool? Software_update;

            /**
            Set to True when the device is in maintenance mode.
            */
            [ResourceId(7), Operations("RW")] bool? Maintenance;

            /**
            Cumulated number of hours during which the device has been powered on.
            */
            [ResourceId(9), Operations("R"), Units("h")] long? Device_operating_hours;

            /**
            Additional information about peripheral firmware versions. The format is left to the vendor.
            */
            [ResourceId(10), Operations("R")] string Additional_firmware_information;

            /**
            The precise date and UTC time during the year when Daylight Saving Time begins, represented as Unix Time.
            */
            [ResourceId(11), Operations("RW"), Units("s")] DateTime[,,] DST_Start;

            /**
            The precise date and UTC time during the year when Daylight Saving Time ends, represented as Unix Time.
            */
            [ResourceId(12), Operations("RW")] DateTime[,,] DST_End;

            /**
            The amount by which the UTC offset changes when Daylight Saving Time is in effect, represented as ISO 8601
            time offset format. A DST offset of one hour is represented as "01:00"
            */
            [ResourceId(13), Operations("RW")] string[,,] DST_Offset;

            /**
            Number of seconds since the last reboot of the device.
            */
            [ResourceId(14), Operations("R"), Units("s")] DurationInSeconds? Uptime;

            /**
            Set to true if the device is a Reduce Functional Device running on battery.
            */
            [ResourceId(15), Operations("R")] bool? RFD_device;

            /**
            Reset the configuration parameters (and only the configuration parameters) of the device. It does not clear
            any counter (e.g. kWh counter or operating hour counter).
            Execute operation on resource 8 (Configuration reset); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E")] public class Configuration_reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3411.xml: Battery (urn:oma:lwm2m:ext:3411:1.1) ═════════════════════════
        /**
        The uCIFI battery object provides attributes to monitor battery level and activity.
        */
        class Battery {
            public const ushort lwm2m_object_id          = 3411;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3411:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Level of charge of the battery in % of total possible charge.
            */
            [ResourceId(1), Operations("R"), Units("/100"), Mandatory] long Battery_level;

            /**
            Nominal capacity of the battery in Ampere hour.
            */
            [ResourceId(2), Operations("R"), Units("Ah")] double? Battery_capacity;

            /**
            Level of charge of the battery in Volts.
            */
            [ResourceId(3), Operations("R"), Units("V")] double? Battery_voltage;

            /**
            Describes the type of battery (e.g. Li-Ion rechargeable).
            */
            [ResourceId(4), Operations("RW")] string Type_of_battery;

            /**
            Threshold below which an event is generated by the device.
            */
            [ResourceId(5), Operations("RW"), Units("/100")] long? Low_battery_threshold;

            /**
            Set to True if battery level is below or equal the low battery threshold. Set to False otherwise.
            */
            [ResourceId(6), Operations("R")] bool? Battery_level_too_low;

            /**
            Indicates that the device has shut down due to battery discharge. Can be reset by central application.
            */
            [ResourceId(7), Operations("RW")] bool? Battery_shutdown;

            /**
            Number of times the battery has discharged and recharged.
            */
            [ResourceId(8), Operations("R")] long? Number_of_cycles;

            /**
            Applies for battery devices that are also connected to mains supply. Set to True when mains power is lost. Set
            to False when mains power is back.
            */
            [ResourceId(9), Operations("R")] bool? Supply_loss;

            /**
            Number of supply losses since last reset.
            */
            [ResourceId(10), Operations("R")] long? Supply_loss_counter;

            /**
            Reason identified by the device why the device has lost mains supply (e.g. lightning if the device measured a
            high voltage, accident if the device identified a move with an accelerometer).
            */
            [ResourceId(12), Operations("R")] string Supply_loss_reason;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;

            /**
            Reset the supply loss counter.
            Execute operation on resource 11 (Supply loss counter reset); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E")] public class Supply_loss_counter_reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3412.xml: LPWAN Communication (urn:oma:lwm2m:ext:3412:1.1) ═════════════════════════
        /**
        The uCIFI communication object provides attributes related to the communication on the LPWAN network,
        including multicast grouping.
        */
        class LPWAN_Communication {
            public const ushort lwm2m_object_id          = 3412;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3412:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Type of LPWAN communication network (e.g. LoRaWAN, NB-IoT, wireless mesh, power line).
            */
            [ResourceId(1), Operations("R")] string Type_of_network;

            /**
            Device’s IPv4 address.
            */
            [ResourceId(2), Operations("RW")] string[,,] IPv4_address;

            /**
            Device’s IPv6 address.
            */
            [ResourceId(3), Operations("RW")] string[,,] IPv6_address;

            /**
            Address of the device on the LPWAN network.
            */
            [ResourceId(4), Operations("RW")] string[,,] Network_address;

            /**
            Secondary address used to communicate with the device on the LPWAN network.
            */
            [ResourceId(5), Operations("RW")] string[,,] Secondary_network_address;

            /**
            IEEE MAC address of the device.
            */
            [ResourceId(6), Operations("RW"), Mandatory] string MAC_address;

            /**
            Address of a peer (e.g. a router, a mesh node, a gateway).
            */
            [ResourceId(7), Operations("R")] string[,,] Peer_address;

            /**
            Group address from which the  device should accept incoming messages and/or commands.
            */
            [ResourceId(8), Operations("RW")] string[,,] Multicast_group_address;

            /**
            Security key (e.g. AES128) to be shared with other members to be part of a multicast group.
            */
            [ResourceId(9), Operations("RW")] string[,,] Multicast_group_key;

            /**
            Data rate of the communication used on the LPWAN network.
            */
            [ResourceId(10), Operations("RW"), Units("B/s")] long? Data_rate;

            /**
            Transmit power (also called TxPower) used by the device on the LPWAN network in decibel per milliwatt.
            */
            [ResourceId(11), Operations("R"), Units("dBm")] double? Transmit_power;

            /**
            Frequency of the wireless communication used on the LPWAN network.
            */
            [ResourceId(12), Operations("RW"), Units("Hz")] double? Frequency;

            /**
            Starting time of the multicast session. The device shall not accept incoming messages before this time or
            after this time + session duration.
            */
            [ResourceId(13), Operations("RW")] DateTime? Session_time;

            /**
            Duration of the multicast session. The device shall accept incoming messages only during this session duration
            time, starting at "Session time".
            */
            [ResourceId(14), Operations("R"), Units("s")] DateTime? Session_duration;

            /**
            Set to True if the device is a mesh node that should repeat incoming messages on a mesh network.
            */
            [ResourceId(15), Operations("RW")] bool? Mesh_node;

            /**
            Maximum number of times a message should be repeated within a mesh network.
            */
            [ResourceId(16), Operations("RW")] long? Maximum_repeat_time;

            /**
            Number of mesh nodes between the device and the destination device (e.g. another device or a router) including
            the destination node, on a mesh network.
            */
            [ResourceId(17), Operations("R")] long? Number_of_repeats;

            /**
            Ratio of signal power to the noise power.
            */
            [ResourceId(18), Operations("R"), Units("dB")] double? Signal_to_noise_ratio;

            /**
            Set to True when the device can't communicate properly.
            */
            [ResourceId(19), Operations("R")] bool? Communication_failure;

            /**
            Signal strength of the communication network measured by the device (a.k.a. RSSI or signal level).
            */
            [ResourceId(20), Operations("R"), Units("dBm")] double? Received_Signal_Strength_Indication;

            /**
            Device’s International Mobile Subscriber Identity.
            */
            [ResourceId(21), Operations("R")] string IMSI;

            /**
            Device’s International Mobile Equipment Identity.
            */
            [ResourceId(22), Operations("R")] string IMEI;

            /**
            Device’s current communication operator. Communication operators could be private operators. Thus this
            resource is free text format and does not use Mobile Network Code or equivalent.
            */
            [ResourceId(23), Operations("R")] string Current_Communication_Operator;

            /**
            Unique identifier used to identify a communication SIM card. The ICCID is defined by the ITU-T recommendation
            E.118 as the Primary Account Number, composed of 19 or 20 characters containing the ISO Industry Identifier,
            country code, issuer identity, account ID, and other data which allows the network operator to identify the
            card.
            */
            [ResourceId(24), Operations("R")] string Integrated_Circuit_Card_Identifier;

            /**
            E-UTRA Operating Band.
            */
            [ResourceId(25), Operations("R")] long? LTE_Band_number;

            /**
            It assesses the ratio of the power of the desired signal to the sum of the power from all other interfering
            signals and background noise.
            */
            [ResourceId(26), Operations("R"), Units("dB")] double? LTE_Signal_to_Interference_plus_Noise_Ratio_SINR;

            /**
            RSRP measures the power of the reference signal received from a cell tower. This signal is used for various
            functions, including handover decisions and cell selection/reselection in cellular networks.
            */
            [ResourceId(27), Operations("R"), Units("dBm")] double? LTE_Reference_Signals_Received_Power_RSRP;

            /**
            RSRQ measures the ratio of the Reference Signal Received Power (RSRP) to the total received signal power
            (RSSI), effectively quantifying the quality of the signal relative to the noise and interference.
            */
            [ResourceId(28), Operations("R"), Units("dB")] double? LTE_Reference_Signal_Received_Quality_RSRQ;

            /**
            Seconds since the connection has been established
            */
            [ResourceId(29), Operations("R"), Units("s")] DurationInSeconds? LTE_Connection_Uptime;
        }

        // ═════════════════════════ 3413.xml: uCIFI Generic Actuator (urn:oma:lwm2m:ext:3413:1.1) ═════════════════════════
        /**
        The uCIFI generic actuator may be used for any actuator but not to replace Outdoor Lamp Controllers nor for an
        Irrigation Valves which have a specific device type in the uCIFI data model.
        */
        class uCIFI_Generic_Actuator {
            public const ushort lwm2m_object_id          = 3413;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3413:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Default dimming level that the generic actuator applies when the device is powered ON.
            */
            [MinMax(0, 100), ResourceId(1), Operations("RW"), Units("/100")] byte? Default_dimming_level;

            /**
            Actual dimming level (0 for OFF and 100% for ON) measured on the actuator.
            */
            [MinMax(0, 100), ResourceId(2), Operations("R"), Units("/100")] byte? Dimming_level;

            /**
            Command (e.g. manual override, scheduler) sent to the actuator.
            */
            [MinMax(0, 100), ResourceId(3), Operations("RW"), Units("/100")] byte? Command;

            /**
            For devices connected on slow LPWAN networks, the command in action (this resource) may differ from a command
            that was sent (resource ID: 3). The command in action is the actual value of the command in action in the
            actuator.
            */
            [MinMax(0, 100), ResourceId(4), Operations("R"), Units("/100")] byte? Command_in_action;

            /**
            The identifier of the schedulers that are assigned to the Command of this actuator.
            */
            [ResourceId(5), Operations("RW")] long[,,] Scheduler_ID;

            /**
            Set to True when one of the schedulers can’t be executed or is not supported by the actuator. Otherwise set to
            False.
            */
            [ResourceId(6), Operations("R")] bool? Invalid_scheduler;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;
        }

        // ═════════════════════════ 3414.xml: uCIFI data bridge (urn:oma:lwm2m:ext:3414:2.0) ═════════════════════════
