            */
            [ResourceId(26), Operations("R"), Units("A")] double? Minimum_inrush_Current;

            /**
            Maximum inrush current since last configuration.
            */
            [ResourceId(27), Operations("R"), Units("A")] double? Maximum_inrush_Current;

            /**
            Latest inrush current measured since last time the relay switched ON.
            */
            [ResourceId(28), Operations("R"), Units("A")] double? Latest_inrush_Current;

            /**
            Instantaneous reactive power measured by the device and its electrical load.
            */
            [ResourceId(29), Operations("R"), Units("var")] double? Reactive_power;

            /**
            Cumulative reactive power measured by the device and its electrical load since last energy counter reset.
            */
            [ResourceId(30), Operations("R"), Units("varh")] double? Reactive_energy;

            /**
            If the measured power when the dimming is between "Custom dim level min range" and "Custom dim level max
            range" is below this threshold, a low power alarm is set.
            */
            [ResourceId(31), Operations("RW"), Units("W")] double[,,] Low_power_threshold_at_custom_dim_level;

            /**
            If the measured power when the dimming is between "Custom dim level min range" and "Custom dim level max
            range" is above this threshold, a high power alarm is set.
            */
            [ResourceId(32), Operations("RW"), Units("W")] double[,,] High_power_threshold_at_custom_dim_level;

