            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Angle between the internal vertical line and the perpendicular to earth.
            */
            [ResourceId(1), Operations("R"), Units("rad"), Mandatory] double Angle;

            /**
            Minimum angle measured by the tilt sensor since last reset or since power ON if no reset.
            */
            [ResourceId(2), Operations("R"), Units("rad")] double? Minimum_measured_Angle;

            /**
            Maximum angle measured by the tilt sensor since last reset or since power ON if no reset.
            */
            [ResourceId(3), Operations("R"), Units("rad")] double? Maximum_measured_angle;

            /**
            The angle above which the device triggers an out of position event.
            */
            [ResourceId(5), Operations("RW"), Units("rad")] double? Out_of_position_threshold;

            /**
            Set to True if the angle is above the out of position threshold.
            */
            [ResourceId(6), Operations("R")] bool? Out_of_position;

            /**
            True if the calibration has been successfully completed.
            */
            [ResourceId(8), Operations("R")] bool? Calibration_Completed;

            /**
            Angle detected upon calibration.
            */
            [ResourceId(9), Operations("R"), Units("rad")] double? Angle_Zero_Calibration;

            /**
            Threshold for detecting shock events. If unit is not provided, g is assumed.
            */
            [ResourceId(10), Operations("RW")] double? Shock_Threshold;

            /**
            Unit related to Shock Threshold value
            */
            [ResourceId(11), Operations("RW")] string Shock_Unit;

            /**
            True if a Shock event has been detected
            */
            [ResourceId(12), Operations("R")] bool? Shock_Detected;

            /**
            The timestamp of when the measurement was performed.
            */
