            }
        }

        // ═════════════════════════ 3430.xml: Global Navigation Satellite System (urn:oma:lwm2m:ext:3430:2.0) ═════════════════════════
        /**
        More than a positioning object, the uCIFI global navigation satellite system object provides all the
        information required to calculate a position/location.
        */
        class Global_Navigation_Satellite_System {
            public const ushort lwm2m_object_id          = 3430;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3430:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Timestamp of when the location measurement was performed.
            */
            [ResourceId(0), Operations("R"), Units("s"), Mandatory] DateTime Fix_timestamp;

            /**
            Decimal notation of latitude, e.g. -43.5723 [World Geodetic System 1984]. This value ranges from [-90, 90].
            */
            [ResourceId(1), Operations("R"), Units("lat"), Mandatory] double Latitude;

            /**
            Decimal notation of longitude, e.g. 153.21760 [World Geodetic System 1984]. This value ranges from [-180,
            180].
            */
            [ResourceId(2), Operations("R"), Units("lon"), Mandatory] double Longitude;

            /**
            Altitude above mean sea level in meters.
            */
            [ResourceId(3), Operations("R"), Units("m")] double? Altitude;

            /**
            Horizontal speed calculated by the device.
            */
            [ResourceId(4), Operations("R"), Units("m/s")] long? Speed;

            /**
            Direction that the device is following
            */
            [ResourceId(5), Operations("R"), Units("deg")] double? Heading;

            /**
            Radius of a circular area corresponding to the location’s uncertainty (GPS data precision). Negative values
            indicate that the radius is not available.
            */
            [ResourceId(6), Operations("R"), Units("m")] double? Radius;

            /**
            Horizontal dilution of precision.
            */
            [ResourceId(7), Operations("R")] double? HDOP;

            /**
            Vertical dilution of precision.
            */
            [ResourceId(8), Operations("R")] double? VDOP;

            /**
            Estimated horizontal accuracy.
            */
            [ResourceId(9), Operations("R"), Units("m")] double? Estimated_horizontal_accuracy;

            /**
            Estimated vertical accuracy.
            */
            [ResourceId(10), Operations("R"), Units("m")] double? Estimated_vertical_accuracy;

            /**
            Estimated speed accuracy.
            */
            [ResourceId(11), Operations("R"), Units("m/s")] double? Estimated_speed_accuracy;

            /**
            Estimated heading accuracy.
            */
            [ResourceId(12), Operations("R"), Units("deg")] double? Estimated_heading_accuracy;

            /**
            Possible values are :
            0 = No fix
            1 = Autonomous GNSS fix
            2 = Differential GNSS fix
            3 = GPS PPS
            4 = RTK-fixed
            5 = RTK-floated
            6 = Estimated fix
            7 = Dead reckoning fix
            8 = Manual input, surveyed
            9 = Simulated mode
            If no fix is possible, but assisted position is provided, value can be returned as 8 = Manual input
            */
            [ResourceId(13), Operations("R")] long? Fix_type;

            /**
            Possible values are:
            0,1 = no fix
            2 = 2D fix
            3 = 3D fix
            As per NMEA-0183 GSA.
            */
            [ResourceId(14), Operations("R")] long? Fix_dimension;

            /**
            Number of satellites used for the fix.
            */
            [ResourceId(15), Operations("R")] long? Used_satellites;

            /**
            Number of satellites viewed. Represent all the satellites seen but some of them cannot be in use (e.g. bad
            signal).
            */
            [ResourceId(16), Operations("R")] long? Visible_satellites;

            /**
            Identifier of the satellite.
            */
            [ResourceId(17), Operations("R")] string[,,] Satellite_identifiers;

            /**
            Elevation of the satellite.
            */
            [ResourceId(18), Operations("R"), Units("deg")] double[,,] Satellite_identifiers_18;

            /**
            Azimuth of the satellite.
            */
            [ResourceId(19), Operations("R"), Units("deg")] double[,,] Satellite_azimuth;

            /**
            Validity of the almanac. Possible values are:
            0 = invalid
            1 = valid
            .
            */
            [ResourceId(20), Operations("R")] bool? Almanac;

            /**
            Validity of the ephemeris of each satellite. Possible values are :
            0 = invalid
            1 = valid
            .
            */
            [ResourceId(21), Operations("R")] bool[,,] Ephemeris;

            /**
            Strength of the signal for each satellite, also called carrier-to-noise.
            */
            [ResourceId(22), Operations("R"), Units("dB")] double[,,] Signal_to_noise_ratio;

            /**
            GNSS used for the fix. A mask is used with the following bit definition:
            0 = GPS (USA)
            1 = GALILEO (EU)
            2 = GLONASS (Russia)
            3 = BeiDou (China)
            4 = QZSS (Japan)
            5 = IRNSS/NAVIC (India)
            A 0 indicates that the GNSS is not used a 1 indicates it is used.
            */
            [ResourceId(23), Operations("R")] long[,,] GNSS;

            /**
            Time of the internal clock of the GNSS hardware.
            */
            [ResourceId(24), Operations("R"), Units("s")] DateTime? Hardware_RTC;

            /**
            Set to True if the almanac is obtained via a cellular connection. Set to False otherwise.
            */
            [ResourceId(25), Operations("RW")] bool? Assisted_GPS;

            /**
            Command to switch the hardware ON or OFF and status of the device.
            */
            [ResourceId(26), Operations("RW")] bool? Power_command;

            /**
            Dilution of precision (NMEA-0183 GSA).
            */
            [ResourceId(27), Operations("R")] double? PDOP;

            /**
            Status A=active or V=Void (NMEA-0183 RMC).
            */
            [ResourceId(28), Operations("R"), Mandatory] string Status;

            /**
            Expected latitude configured by the user. Ignored if 0 or NaN
            */
            [ResourceId(29), Operations("RW"), Units("lat")] double? Expected_latitude;

            /**
            Expected longitude configured by the user. Ignored if 0 or NaN
            */
            [ResourceId(30), Operations("RW"), Units("lon")] double? Expected_longitude;

            /**
            Expected altitude configured by the user. Ignored if 0 or NaN
            */
            [ResourceId(31), Operations("RW"), Units("m")] double? Expected_altitude;

            /**
            Distance threshold from the expected location beyond which the location changed resource will be set. Ignored
            if 0 or NaN
            */
            [ResourceId(32), Operations("RW"), Units("m")] double? Expected_location_threshold;

            /**
            True if the current position is distant more than the configured threshold from the expected location
            */
            [ResourceId(33), Operations("R")] bool? Out_of_position;

            /**
            Assisted latitude configured by the user, to be used in case of no coverage. Ignored if 0 or NaN
            */
            [ResourceId(34), Operations("RW"), Units("lat")] double? Assisted_latitude;

            /**
            Assisted longitude configured by the user, to be used in case of no coverage. Ignored if 0 or NaN
            */
            [ResourceId(35), Operations("RW"), Units("lon")] double? Assisted_longitude;

            /**
            Assisted altitude configured by the user, to be used in case of no coverage. Ignored if 0 or NaN
            */
            [ResourceId(36), Operations("RW"), Units("m")] double? Assisted_altitude;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;
        }

        // ═════════════════════════ 3431.xml: Parking Sensor (urn:oma:lwm2m:ext:3431:1.3) ═════════════════════════
        /**
        The uCIFI parking sensor provides actual and cumulated occupancy duration as well as forbidden parking
        detection.
        */
        class Parking_Sensor {
            public const ushort lwm2m_object_id          = 3431;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3431:1.3";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.3";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Set to True if the parking place is occupied. Set to False if the parking place is free.
            */
            [ResourceId(1), Operations("R"), Mandatory] bool Occupancy;

            /**
            Number of seconds since the parking place is occupied. If not occupied, duration shows the duration of the
            last occupation.
            */
            [ResourceId(2), Operations("R"), Units("s")] DurationInSeconds? Duration;

            /**
            Cumulated occupation time since beginning of the day.
            */
            [ResourceId(3), Operations("R"), Units("s")] DurationInSeconds? Daily_Duration;

            /**
            Set to True if the vehicle present on the parking place is not authorized. Set to False if parking place is
            free or if the vehicle is authorized.
            */
            [ResourceId(4), Operations("R")] bool? Forbidden_parking_detected;

            /**
            Type of sensor (e.g. PIR, camera).
            */
            [ResourceId(5), Operations("RW")] string Type_of_Sensor;

            /**
            Timestamp when the parking occupancy started. If not occupied, shows the starts of the last occupation.
            */
            [ResourceId(6), Operations("R")] DateTime? Occupancy_Start_Time;

            /**
            Identification of the parking area
            */
            [ResourceId(7), Operations("RW")] string Parking_Area;

            /**
            Identification of the parking lot
            */
            [ResourceId(8), Operations("RW")] string Parking_Lot;

            /**
            Identification of license plate of parked vehicle. If not occupied, shows the license plate of the last
            occupation
            If unkown, an empty string is returned
            */
            [ResourceId(9), Operations("R")] string License_Plate;

            /**
            Additional attributes that could be provided by vendor
            */
            [ResourceId(10), Operations("RW")] string Vendor_Attributes;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
