        // ═════════════════════════ 3435.xml: Filling level (urn:oma:lwm2m:ext:3435:2.0) ═════════════════════════
        /**
        The uCIFI filling level sensor measures how full and/or how empty a container (e.g. waste, fuel) is and
        reports it either in percentage or in centimeters. The filling level sensor may be complemented with a
        temperature sensor to compose a waste filling sensor that can also identify waste container fire.
        */
        class Filling_level {
            public const ushort lwm2m_object_id          = 3435;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3435:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Height of the container.
            */
            [ResourceId(1), Operations("RW"), Units("cm")] long? Container_height;

            /**
            Percentage of container filled with content.
            */
            [ResourceId(2), Operations("R"), Units("/100"), Mandatory] double Actual_filling_percentage;

            /**
            Height of content in the container.
            */
            [ResourceId(3), Operations("R"), Units("cm")] long? Actual_filling_level;

            /**
            Threshold above which the container is considered full.
            */
            [ResourceId(4), Operations("RW"), Units("/100")] double? High_threshold;

            /**
            Set to True if the actual filling percentage is above the high threshold.
            */
            [ResourceId(5), Operations("R"), Mandatory] bool Container_full;

            /**
            Threshold below which the container is considered empty.
            */
            [ResourceId(6), Operations("RW"), Units("/100")] double? Low_threshold;

            /**
            Set to True if the actual filling percentage is below the low threshold.
            */
            [ResourceId(7), Operations("R"), Mandatory] bool Container_empty;

            /**
            Average percentage filled per day.
            */
            [ResourceId(8), Operations("R"), Units("/100")] double? Average_filling_speed;

            /**
            Next date at which the container should reach the high threshold.
            */
            [ResourceId(10), Operations("R")] DateTime? Forecast_full_date;

            /**
            Next date at which the container should reach the low threshold.
            */
            [ResourceId(11), Operations("R")] DateTime? Forecast_empty_date;

            /**
            Set to True if the container is not at the location where it should be.
            */
            [ResourceId(12), Operations("R")] bool? Container_out_of_location;

            /**
            Set to True if the container is not in correct upright position.
            */
            [ResourceId(13), Operations("R")] bool? Container_out_of_position;

            /**
            Width of the container.
            */
            [ResourceId(14), Operations("RW"), Units("cm")] long? Container_width;

            /**
            Type of the container. Examples are underground, above ground.
            */
            [ResourceId(15), Operations("RW"), Units("cm")] string Container_installation_type;

            /**
            The maximum volume available in the container for waste items.
            */
            [ResourceId(16), Operations("RW"), Units("m3")] double? Container_volume_max;

            /**
            The position of the filling sensor inside the container.
            */
            [ResourceId(17), Operations("RW")] string Filling_sensor_position;

            /**
            The type of the materials the container can be filled with. Examples are plastic, glass.
            */
            [ResourceId(18), Operations("RW")] string Type_of_materials;

            /**
            Total amount of filling operations performed.
            */
            [ResourceId(19), Operations("R")] long? Filling_operations_counter;

            /**
            Set to true if the cover of the container is open and the filling level cannot be estimated. This is valid if
            the filling level sensor is installed under the cover of the bin.
            */
            [ResourceId(21), Operations("R")] bool? Cover_open;

            /**
            Set to true if the sensor detects a fire using either a temperature sensor object.and/or a gas detection
            object.
            */
            [ResourceId(22), Operations("R")] bool? Temperature_alarm;

            /**
            Set to true if the sensor detects water infiltration or a high humidity level.
            */
            [ResourceId(23), Operations("R")] bool? Water_infiltration_alarm;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;

            /**
            Reset average filling speed.
            Execute operation on resource 9 (Average filling speed reset); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Average_filling_speed_reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Total amount of filling operations performed.
            Execute operation on resource 20 (Reset filling operations counter); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E")] public class Reset_filling_operations_counter_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3436.xml: Edge computing manager (urn:oma:lwm2m:ext:3436) ═════════════════════════
        /**
        The uCIFI edge computing manager object defines the capability of a device to run scripts on the device
        itself.
        */
        class Edge_computing_manager {
            public const ushort lwm2m_object_id          = 3436;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3436";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Maximum number of scripts supported by the device.
            */
            [ResourceId(1), Operations("R")] long? Max_number_of_scripts;

            /**
            Number of free slots to store new scripts.
            */
            [ResourceId(2), Operations("R")] long? Number_of_free_slots_for_scripts;

            /**
            Maximum number of conditions supported by the device.
            */
            [ResourceId(3), Operations("R")] long? Max_number_of_conditions;

            /**
            Number of free slots to store new conditions.
            */
            [ResourceId(4), Operations("R")] long? Number_of_free_slots_for_conditions;

            /**
            Vendor-specific resource to share the capabilities of the devices as regards to edge computing.
            */
            [ResourceId(5), Operations("R")] string Edge_computing_capabilities;
        }

        // ═════════════════════════ 3437.xml: Edge computing script (urn:oma:lwm2m:ext:3437) ═════════════════════════
        /**
        The uCIFI edge computing scripts object defines a particular script to be executed by a device under a time or
        any other condition set by a "Edge Computing Time Condition" or "Edge Computing Generic Condition" object.
        */
        class Edge_computing_script {
            public const ushort lwm2m_object_id          = 3437;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3437";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Name of the script.
            */
            [ResourceId(1), Operations("RW")] string Name;

            /**
            Unique hash or signature associated to the script to be verified by the end-device before execution. The
            format of the hash or signature is vendor-specific.
            */
            [ResourceId(2), Operations("RW")] string Signature;

            /**
            Version of the script, as defined by the vendor.
            */
            [ResourceId(3), Operations("RW")] string Version;

            /**
            Vendor-specific script.
            */
            [D(65535), ResourceId(4), Operations("RW"), Mandatory] Binary[,,] Script;

            /**
            Script format to enable the device to select the script interpreter in case it supports multiple (e.g. LUA).
            The format of this resource is free to support vendor-specific formats.
            */
            [ResourceId(5), Operations("RW")] string Script_format;

            /**
            Set to True if the script is not supported or if the device has identified errors in the script.
            */
            [ResourceId(6), Operations("R")] bool? Non_supported_script;

            /**
            Set to True if the hash/signature is not correct.
            */
            [ResourceId(7), Operations("R")] bool? Non_authorized_script;
        }

        // ═════════════════════════ 3438.xml: Edge computing time condition (urn:oma:lwm2m:ext:3438) ═════════════════════════
        /**
        The uCIFI edge computing time condition object defines the day/time (defined as a CRON rule) at which a
        particular script should be executed by a device.
