            /**
            Set to True if the device can’t support the condition.
            */
            [ResourceId(3), Operations("R")] bool? Non_supported_time_condition;
        }

        // ═════════════════════════ 3439.xml: Edge computing generic condition (urn:oma:lwm2m:ext:3439) ═════════════════════════
        /**
        The uCIFI edge computing generic condition object defines a vendor-specific condition (e.g. when a resource or
