        // ═════════════════════════ 3441.xml: LwM2M v1.0 Test Object (urn:oma:lwm2m:ext:3441) ═════════════════════════
        /**
        This object is for use in interoperability tests of the LwM2M v1.0 technical specification. It contains
        resources for each available datatype.
        */
        class LwM2M_v1_0_Test_Object {
            public const ushort lwm2m_object_id          = 3441;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3441";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            List of Arguments from last execute on "Exec With Arguments"(3) resource. This resource is not affected by the
            "Randomize values"(1) executable resource.
            */
            [ResourceId(4), Operations("R")] string[,,] Arguments_List;

            /**
            Initial value must be "initial value".
            */
            [ResourceId(110), Operations("RW")] string String_Value;

            /**
            Initial value must be "1024".
            */
            [ResourceId(120), Operations("RW")] long? Integer_Value;

            /**
            Initial value must be "3.14159".
            */
            [ResourceId(130), Operations("RW")] double? Float_Value;

            /**
            Initial value must be "true".
            */
            [ResourceId(140), Operations("RW")] bool? Boolean_Value;

            /**
            Initial value must be the bytes sequence "0123456789ABCDEF" (Hexadecimal notation).
            */
            [D(65535), ResourceId(150), Operations("RW")] Binary[,,] Opaque_Value;

            /**
            Initial value must be the time to an 1st, 2000 in the UTC time zone. (Timestamp value : 946684800)
            */
            [ResourceId(160), Operations("RW")] DateTime? Time_Value;

            /**
            Initial value must be a link to instance 0 of Device Object 3 (3:0).
            */
            [ResourceId(170), Operations("RW")] ObjectLink? ObjLink_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "initial value".
            */
            [ResourceId(1110), Operations("RW")] string[,,] Multiple_String_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "1024".
            */
            [ResourceId(1120), Operations("RW")] long[,,] Multiple_Integer_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "3.14159".
            */
            [ResourceId(1130), Operations("RW")] double[,,] Multiple_Float_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "true".
            */
            [ResourceId(1140), Operations("RW")] bool[,,] Multiple_Boolean_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "0123456789ABCDEF"(Hexadecimal notation of the bytes
            sequence).
            */
            [ResourceId(1150), Operations("RW")] Blob[,,] Multiple_Opaque_Value;

            /**
            Initial value must be 1 instance with ID 0 and value 1st, 2000 in the UTC time zone (Timestamp value :
            946684800).
            */
            [ResourceId(1160), Operations("RW")] DateTime[,,] Multiple_Time_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "3:0".
            */
            [ResourceId(1170), Operations("RW")] ObjectLink[,,] Multiple_ObjLink_Value;

            /**
            Reset all resources of this object with their initial value.
            Execute operation on resource 0 (Reset values); sent by the Server to the Client.
            */
            [ResourceId(0), Operations("E")] public class Reset_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Set random value to all resources. For multi-instance resources, the number of resource instances is also
            randomized.
            Randomization should avoid to generate too big payload. We advice to limit value to something like :
            - 20 characters for String,
            - 20 bytes for Opaque,
            - 10 instances for multi-instance resources.
            Execute operation on resource 1 (Randomize values); sent by the Server to the Client.
            */
            [ResourceId(1), Operations("E")] public class Randomize_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Clear all values :
            - all multiple resource as empty resource
            - all number to 0
            - String to empty string
            - boolean to false,
            - opaque to empty byte array,
            - time to an 1st, 1970 in the UTC time zone
            - objlink to null link
            Execute operation on resource 2 (Clear values); sent by the Server to the Client.
            */
            [ResourceId(2), Operations("E")] public class Clear_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This resources can be used to test "Execute Operation" with Arguments.
            Sent Arguments can be read via "Arguments List"(4) resource.
            E.g. If you send an Exec /3441/0/3 with "3='stringValue',4" as arguments value,
            then /3441/0/4/3 will be 'stringValue' and /3441/0/4/4 will be an empty string.
            Execute operation on resource 3 (Exec With Arguments); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Exec_With_Arguments_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3442.xml: LwM2M v1.1 Test Object (urn:oma:lwm2m:ext:3442) ═════════════════════════
        /**
        This object aims to make easier to do interoperability tests about LWM2M v1.1. It contains resources for each
        available datatype.
