            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            List of Arguments from last execute on "Exec With Arguments"(3) resource. This resource is not affected by
            "Randomize values"(1) executable resource.
            */
            [ResourceId(4), Operations("R")] string[,,] Arguments_List;

            /**
            List of path to LWM2M node (Object / Object Instance / Resource / Resource Instance) used by "Send Data "(5)
            resource. This resource is not affected by "Randomize values"(1) executable resource.
            */
            [ResourceId(6), Operations("RW")] string[,,] Resources_to_Send;

            /**
            Initial value must be "initial value".
            */
            [ResourceId(110), Operations("RW")] string String_Value;

            /**
            Initial value must be "1024".
            */
            [ResourceId(120), Operations("RW")] long? Integer_Value;

            /**
            Initial value must be 2^63 (9223372036854775808).
            */
            [ResourceId(125), Operations("RW")] ulong? Unsigned_Integer_Value;

            /**
            Initial value must be "3.14159".
            */
            [ResourceId(130), Operations("RW")] double? Float_Value;

            /**
            Initial value must be "true".
            */
            [ResourceId(140), Operations("RW")] bool? Boolean_Value;

            /**
            Initial value must be the bytes sequence "0123456789ABCDEF" (Hexadecimal notation).
            */
            [D(65535), ResourceId(150), Operations("RW")] Binary[,,] Opaque_Value;

            /**
            Initial value must be the time to an 1st, 2000 in the UTC time zone. (Timestamp value : 946684800)
            */
            [ResourceId(160), Operations("RW")] DateTime? Time_Value;

            /**
            Initial value must be a link to instance 0 of Device Object 3 (3:0).
            */
            [ResourceId(170), Operations("RW")] ObjectLink? ObjLink_Value;

            /**
            Initial value must be a the "&lt;/3442&gt;".
            */
            [D(+4096), ResourceId(180), Operations("RW")] string CoreLnk_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "initial value".
            */
            [ResourceId(1110), Operations("RW")] string[,,] Multiple_String_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "1024".
            */
            [ResourceId(1120), Operations("RW")] long[,,] Multiple_Integer_Value;

            /**
            Initial value must be 1 instance with ID 0 and value 2^63 (9223372036854775808).
            */
            [ResourceId(1125), Operations("RW")] ulong[,,] Multiple_Unsigned_Integer_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "3.14159".
            */
            [ResourceId(1130), Operations("RW")] double[,,] Multiple_Float_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "true".
            */
            [ResourceId(1140), Operations("RW")] bool[,,] Multiple_Boolean_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "0123456789ABCDEF"(Hexadecimal notation of the bytes
            sequence).
            */
            [ResourceId(1150), Operations("RW")] Blob[,,] Multiple_Opaque_Value;

            /**
            Initial value must be 1 instance with ID 0 and value 1st, 2000 in the UTC time zone (Timestamp value :
            946684800).
            */
            [ResourceId(1160), Operations("RW")] DateTime[,,] Multiple_Time_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "3:0".
            */
            [ResourceId(1170), Operations("RW")] ObjectLink[,,] Multiple_ObjLink_Value;

            /**
            Initial value must be 1 instance with ID 0 and value "&lt;/3442&gt;".
            */
            [D(+4096), ResourceId(1180), Operations("RW")] string[,,] Multiple_CoreLnk_Value;

            /**
            Reset all resources of this object with their initial value.
            Execute operation on resource 0 (Reset values); sent by the Server to the Client.
            */
            [ResourceId(0), Operations("E")] public class Reset_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Set random value to all resources. For multi-instance resources, the number of resource instances is also
            randomized.
            Randomization should avoid to generate too big payload. We advice to limit value to something like :
            - 20 characters for String,
            - 20 bytes for Opaque,
            - 10 instances for multi-instance resources.
            Execute operation on resource 1 (Randomize values); sent by the Server to the Client.
            */
            [ResourceId(1), Operations("E")] public class Randomize_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Clear all values :
            - all multiple resource as empty resource
            - all number to 0
            - String to empty string
            - boolean to false,
            - opaque to empty byte array,
            - time to an 1st, 1970 in the UTC time zone
            - objlink to null link
            Execute operation on resource 2 (Clear values); sent by the Server to the Client.
            */
            [ResourceId(2), Operations("E")] public class Clear_values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This resources can be used to test "Execute Operation" with Arguments.
            Sent Arguments can be read via "Arguments List"(4) resource.
            E.g. If you send an Exec /3441/0/3 with "3='stringValue',4" as arguments value,
            then /3441/0/4/3 will be 'stringValue' and /3441/0/4/4 will be an empty string.
            Execute operation on resource 3 (Exec With Arguments); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Exec_With_Arguments_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            This resources can be used to test "Send Operation".
            When LWM2M client received the Execute Request, it must send data for each resources listed in "Resources to
            Send"(6) resource.
            By default LWM2M client chooses the Content format and Timeout to use for this Send Request, but Arguments can
            optionally be used to change it.
            Argument 0 must contain the Content Format code. e.g. 0='110' for SENML_JSON.
            Argument 1 must contain the request timeout in ms. e.g. 1='2000' for 2s timeout.
            Execute operation on resource 5 (Send Data); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Send_Data_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3443.xml: eSIM IoT (urn:oma:lwm2m:ext:3443) ═════════════════════════
        /**
        The interface between eIM and IPA as described in GSMA SGP.32.
        */
        class eSIM_IoT {
            public const ushort lwm2m_object_id          = 3443;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3443";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Status
            0  ready to receive eIM message
            1  not able to receive eIM message
            Note: In case value is &gt;0 then writing to resource 2 shall not be possible
            */
            [ResourceId(0), Operations("R"), Mandatory] long State;

            /**
            EID of the eUICC that is target of the object
            */
            [ResourceId(1), Operations("R"), Mandatory] string EID;

            /**
            The message from eIM to IPA. The message shall be in the ASN.1 DER format defined in SGP.32 Section 6.3.1
            */
            [D(65535), ResourceId(2), Operations("W"), Mandatory] Binary[,,] eIM_message;

            /**
            The message from IPA to eIM. The message shall be in the ASN.1 DER format defined in GSMA SGP.32 section 6.3.1
            */
            [D(65535), ResourceId(3), Operations("R"), Mandatory] Binary[,,] IPA_message;

            /**
            In case Send or Confirmable Notifications is not used to deliver IPA messsage then execution of this resource
            will confirm delivery of the IPA message and clear the resource 3.
            Execute operation on resource 4 (Clear IPA message); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E"), Mandatory] public class Clear_IPA_message_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3445.xml: Stream Gauge (urn:oma:lwm2m:ext:3445:1.1) ═════════════════════════
        /**
        The uCIFI Stream Gauge measures the elevation of the water level surface and/or volumetric discharge.
        */
        class Stream_Gauge {
            public const ushort lwm2m_object_id          = 3445;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3445:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Water level surface elevation.
            */
            [ResourceId(1), Operations("R"), Units("m"), Mandatory] double Water_Level;

            /**
            Volumetric flow rate of water that is transported through a given cross-sectional area.
            */
            [ResourceId(2), Operations("R"), Units("m3")] double? Volumetric_discharge;

            /**
            Type of stream gauge meter.
            */
            [ResourceId(3), Operations("RW")] string Type_of_meter;

            /**
            0 = OK, 1-255 = Error code.
            */
            [ResourceId(4), Operations("R")] byte? Status;

            /**
            If the water Level exceeds this value, the alarm A is set to True. This alarm has highest severity. A value of
            0 or less disables the alarm.
            */
            [ResourceId(6), Operations("RW"), Units("m")] double? Threshold_A;

            /**
            If the water Level exceeds the value in Threshold A, Alarm A is set to True. Alarm A is false otherwise.
            */
            [ResourceId(7), Operations("R")] bool? Alarm_A;

            /**
            Number of Alarm A events since reset.
            */
            [ResourceId(8), Operations("R")] long? Alarm_A_Counter;

            /**
            If the water Level exceeds this value, the alarm B is set to True. This alarm has lowest severity. A value of
            0 or less disables the alarm.
            */
            [ResourceId(9), Operations("RW"), Units("m")] double? Threshold_B;

            /**
            If the water Level exceeds the value in Threshold B, Alarm B is set to True. Alarm B is false otherwise.
            */
            [ResourceId(10), Operations("R")] bool? Alarm_B;

            /**
            Number of Alarm B events since reset.
            */
            [ResourceId(11), Operations("R")] long? Alarm_B_Counter;

            /**
            If the water Level exceeds this value, the alarm C is set to True. This alarm has lowest severity. A value of
            0 or less disables the alarm.
            */
            [ResourceId(12), Operations("RW"), Units("m")] double? Threshold_C;

            /**
            If the water Level exceeds the value in Threshold C, Alarm C is set to True. Alarm C is false otherwise.
            */
            [ResourceId(13), Operations("R")] bool? Alarm_C;

            /**
            Number of Alarm C events since reset.
            */
            [ResourceId(14), Operations("R")] long? Alarm_C_Counter;

            /**
            If the water Level exceeds this value, the alarm D is set to True. This alarm has lowest severity. A value of
            0 or less disables the alarm.
            */
            [ResourceId(15), Operations("RW"), Units("m")] double? Threshold_D;

            /**
            If the water Level exceeds the value in Threshold D, Alarm D is set to True. Alarm D is false otherwise.
            */
            [ResourceId(16), Operations("R")] bool? Alarm_D;

            /**
            Number of Alarm D events since reset.
            */
            [ResourceId(17), Operations("R")] long? Alarm_D_Counter;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;

            /**
            Reset alarm counts.
            Execute operation on resource 5 (Alarm Counter Reset); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Alarm_Counter_Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

