        // ═════════════════════════ 3447.xml: LPWAN Mesh Connectivity (urn:oma:lwm2m:ext:3447) ═════════════════════════
        /**
        The uCIFI LPWAN Mesh Connectivity object enables monitoring and management of parameters related with the
        operation of 802.15.4-based LPWAN devices.
        */
        class LPWAN_Mesh_Connectivity {
            public const ushort lwm2m_object_id          = 3447;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3447";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Provides information on the type or set of specifications on which the mesh Connectivity is based. This
            information is encoded as string to provide flexibility in the adoption of future mesh technologies. Examples:
            "802.15.4 proprietary", "Zigbee", "Bluetooth 5.0 Mesh", "Thread", "80215.4 6LowPAN", "Wi-SUN".
            */
            [ResourceId(0), Operations("R"), Mandatory] string Network_Type;

            /**
            0: End-Device, 1: Router, 2: Repeater, 3: Border Router, 4: Bridge, 5: Gateway.
            */
            [ResourceId(1), Operations("RW"), Mandatory] long Device_class;

            /**
            Frequency of the wireless communication used on the LPWAN network. Set as a Read-Writable attribute for those
            scenarios where the Radio can be configured to operate in different frequencies.
            */
            [ResourceId(2), Operations("R"), Units("MHz"), Mandatory] double Operating_Frequency;

            /**
            0: Disabled, 1: Connecting, 2: Connected, 3: Disconnecting, 4: Disconnected.
            */
            [ResourceId(3), Operations("R"), Mandatory] long Status;

            /**
            Display’s information on current errors affecting mesh connectivity.
            */
            [ResourceId(4), Operations("R")] string Connection_Errors;

            /**
            Represented in UTC.
            */
            [ResourceId(5), Operations("R")] DateTime? Last_Error_timestamp;

            /**
            Cumulative counter reporting on total observed errors.
            */
            [ResourceId(6), Operations("R")] long? Error_Counter;

            /**
            Transmit power used by the IoT device on the LPWAN network.
            */
            [ResourceId(8), Operations("RW"), Units("dBm")] double? Transmit_Power;

            /**
            Data rate of the communication used on the LPWAN network.
            */
            [ResourceId(9), Operations("RW"), Units("bit/s")] double? Data_Rate;

            /**
            Provides information on what mode of operation is in effect. The meaning of which is technology dependent.
            */
            [ResourceId(10), Operations("RW")] string Operation_Mode;

            /**
            The current channel used for the transfer of data frames. The LwM2M client may update this field to reflect
            changes in frequency if a frequency hopping mechanism is in use.
            */
            [ResourceId(11), Operations("RW")] long? Operating_Channel;

            /**
            The current Frequency hopping function in use by the device: 0: disabled, 1: Pseudo-Random, 2: Adaptative.
            */
            [ResourceId(12), Operations("RW")] long? Channel_Hopping_Function;

            /**
            Array of supported radio channels within the Regulatory Domain.
            */
            [ResourceId(13), Operations("RW")] string Available_Channels;

            /**
            Defined for those technologies that make use of a specific subset of channels for Unicast Datagram
            transmission.
            */
            [ResourceId(14), Operations("RW")] string Unicast_Channel_Plan;

            /**
            Defined for those technologies that make use of a specific subset of channels for Broadcast Datagram
            transmission.
            */
            [ResourceId(15), Operations("RW")] string Broadcast_Channel_Plan;

            /**
            Forward Error Correction may be enabled to improve datagram in noisy network conditions : 0: Disabled, 1:
            Enabled.
            */
            [ResourceId(16), Operations("RW")] bool? FEC;

            /**
            Data whitening may be enabled to ensure smother power distribution over the occupied bandwidth and improve the
            quality of the RF link : 0: Disabled, 1: Enabled.
            */
            [ResourceId(17), Operations("RW")] bool? Data_Whitening;

            /**
            Cipher suite string identifying the authentication and encryption algorithms used in mesh security. i.e: 
            TLS_ECDHE_ECDSA_WITH_AES_128_CCM.
            */
            [ResourceId(18), Operations("RW")] string Cipher_Suite;

            /**
            The 802.15.4 PAN ID used within the network.
            */
            [ResourceId(19), Operations("RW")] long[,,] PAN_Identifier;

            /**
            An operator defined network ID associated with the mesh cluster.
            */
            [ResourceId(20), Operations("RW")] string Network_Name;

            /**
            The hierarchy of the mesh router/end-device within the network. It may be expressed as the number of hops
            between the node and the Border Router/gateway or as the computed cost of the path connecting the node to the
            Border-Router/gateway.
            */
            [ResourceId(21), Operations("R")] long? Node_Rank;

            /**
            Address or identifier of the Border Router/ Gateway node providing connectivity outside the mesh cluster.
            */
            [ResourceId(22), Operations("R")] string[,,] Root_Address;

            /**
            Address or identifier of the node selected as the next hop on the optimal path towards the mesh Root.
            */
            [ResourceId(23), Operations("R")] string[,,] Parent_Address;

            /**
            The MAC address of the interface, in hexadecimal form.
            */
            [ResourceId(24), Operations("RW"), Mandatory] string Physical_interface;

            /**
            The IP addresses assigned to the connectivity interface. (e.g. IPv4, IPv6, etc.).
            */
            [ResourceId(25), Operations("RW")] string[,,] Logical_Address;

            /**
            The IP addresses assigned to the connectivity interface. (e.g. IPv4, IPv6, etc.).
            */
            [ResourceId(26), Operations("RW")] string[,,] IP_Address;

            /**
            Group address from which the IoT device should accept incoming messages and/or commands.
            */
            [ResourceId(27), Operations("RW")] string[,,] Multicast_Group_Address;

            /**
            Security key (e.g. AES128) to be shared with other members to be part of a multicast group. The opaque format
            enables to support non printable characters.
            */
            [ResourceId(28), Operations("RW")] Blob[,,] Multicast_group_key;

            /**
            Ratio of signal power to the noise power .
            */
            [ResourceId(29), Operations("R"), Units("dB")] double? Signal_to_noise_ratio;

            /**
            Signal strength of the communication network measured by the device (a.k.a. RSSI).
            */
            [ResourceId(30), Operations("R"), Units("dBm")] double? Received_Signal_Strength_Indication;

            /**
            Noise Floor of the communication network measured by the device.
            */
            [ResourceId(31), Operations("R"), Units("dBm")] double? Noise_Floor;

            /**
            Maximum number of times a message should be repeated within a mesh network (e.g. number of CoAP
            retransmissions)
            */
            [ResourceId(34), Operations("RW")] long? Maximum_repeat_time;

            /**
            The timestamp of when the measurement was performed.
            */
            [ResourceId(5518), Operations("R")] DateTime? Timestamp;

            /**
            Fractional part of the timestamp when sub-second precision is used (e.g., 0.23 for 230 ms).
            */
            [Range("0..1"), ResourceId(6050), Operations("R"), Units("s")] double? Fractional_Timestamp;

            /**
            Measurement quality indicator reported by a smart sensor. 0: UNCHECKED No quality checks were done because
            they do not exist or can not be applied. 1: REJECTED WITH CERTAINTY The measured value is invalid. 2: REJECTED
            WITH PROBABILITY The measured value is likely invalid. 3: ACCEPTED BUT SUSPICIOUS The measured value is likely
            OK. 4: ACCEPTED The measured value is OK. 5-15: Reserved for future extensions. 16-23: Vendor specific
            measurement quality.
            */
            [MinMax(0, 23), ResourceId(6042), Operations("R")] byte? Measurement_Quality_Indicator;

            /**
            Measurement quality level reported by a smart sensor. Quality level 100 means that the measurement has fully
            passed quality check algorithms. Smaller quality levels mean that quality has decreased and the measurement
            has only partially passed quality check algorithms. The smaller the quality level, the more caution should be
            used by the application when using the measurement. When the quality level is 0 it means that the measurement
            should certainly be rejected.
            */
            [MinMax(0, 100), ResourceId(6049), Operations("R")] byte? Measurement_Quality_Level;

            /**
            Resets "Error Counter" to zero.
            Execute operation on resource 7 (Error Counter Reset); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E")] public class Error_Counter_Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3448.xml: LPWAN Mesh Statistics (urn:oma:lwm2m:ext:3448) ═════════════════════════
        /**
        The uCIFI LPWAN Mesh Statistics object enables the client to collect statistical information specifically
        tailored to monitor performance of 805.15.4 mesh networks. The object encompasses resources that provide
        visibility over both MAC layer and Network Layer statistics, the applicability of which is dependent on the
        specific 802.15.4 technology.
        */
        class LPWAN_Mesh_Statistics {
            public const ushort lwm2m_object_id          = 3448;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3448";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
