        // ═════════════════════════ 3452.xml: Program Scheduler (urn:oma:lwm2m:ext:3452) ═════════════════════════
        /**
        Summary of the mapping between the various functions, eventual inputs and the target actuators, spanning
        multiple days or years.
        */
        class Program_Scheduler {
            public const ushort lwm2m_object_id          = 3452;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3452";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = true;

            /**
            Unique key identifying the Schedule
            */
            [ResourceId(0), Operations("RW")] string Schedule_Name;

            /**
            If disabled, the instance shall be ignored
            */
            [ResourceId(1), Operations("RW"), Mandatory] bool State;

            /**
            Integer representing the priority of the program within all program object instances.
            Lower number (with sign) correspond to higher priorities.
            Higher priority programs have pre-eminence over lower priority program schedule to be running in parallel in
            same day.
            For example: Program #11 is scheduled to run every day between Jan 1st and Dec 31st with a priority 7
            Program #22 is scheduled to run every Saturday between March 1st and June 30th with priority 3
            Program #22 should apply for all Saturdays between March 1st and June 30th
            Program #11 for all other Saturdays in the year
            If compound operation is supported, functions are executed in a order based on this priority field
            */
            [ResourceId(2), Operations("RW"), Mandatory] long Priority;

            /**
            Number of Calendar Rule object(s) instance containing information on which days in the week, months, year(s)
            is the program scheduled to run.
            */
            [ResourceId(3), Operations("RW")] long[,,] Calendar_Rules;

            /**
            Number of Program Function object instance containing information on how to control the output(s) based on
            time and sensor input(s)
            */
            [ResourceId(4), Operations("RW"), Mandatory] long Program_Function;

            /**
            List of sensors or input filters that can be referenced within the associated program.
            If more than one sensor/input filter has to be checked, multiple instances shall be used.
            Each one may be assigned a different input filter
            Resources are specified using Core Link syntax
            For example:
            Instance 0: &lt;/3302/0/5500&gt; (presence sensor #1)
            Instance 1: &lt;/3302/1/5500&gt; (presence sensor #2)
            Or:
            Instance 0: &lt;/3455/0/0/0&gt; (input filter #1)
            */
            [ResourceId(5), Operations("RW")] string[,,] Input_Sources;

            /**
            List of LWM2M &lt;/Object/Instance&gt; that will be controlled by the associated program.
            If more than one &lt;/Object/Instance&gt; pair shall be controlled, multiple instances shall be used.
            The target resource within each instance is specified in Output Targets.
            Instances are specified using Core Link syntax
            For example
            instance 0: &lt;/3416/0&gt; (lamp #0)
            instance 1: &lt;/3416/1&gt; (lamp #1)
            */
            [ResourceId(6), Operations("RW"), Mandatory] string[,,] Output_Instances;

            /**
            List of LWM2M resources that will be controlled by the associated program.
            If more than one resource shall be controlled, multiple instances shall be used.
            Each one may be assigned a different output filter
            For example
            instance 0: 1 (dimming)
            instance 1: 39 (colour temperature)
            Each target must be prepended with all the output instances to identify the full resource path
            */
            [ResourceId(7), Operations("RW"), Mandatory] string[,,] Output_Targets;

            /**
            The control Program is expected to be evaluated within a list of multiple control programs, where the
            evaluation occurs in an orderly fashion following the value set under its Priority resource. The compound
            operation resource, if set, will allow the output of the current control program acting on a given output#1 to
            be compounded with and output of a lower priority program acting on the same output #1. For example: 1) CP#1
            priority 100, outputs 50% dimming level for light #1 with operation SET (compound flag is enabled) 2) CP#11
            priority 500, outputs 10% dimming level for light #1 with operation ADD 3) Final light level on light#1 after
            CP list is executed is 60%
            */
            [ResourceId(8), Operations("RW")] bool? Compound_Operation;

            /**
            If true, allows to force an OFF behavior (for actuators that would support it) in case the run condition is
            not met.
            */
            [ResourceId(9), Operations("RW")] bool? Off_when_inactive;
        }

        // ═════════════════════════ 3453.xml: Calendar Rule (urn:oma:lwm2m:ext:3453) ═════════════════════════
        /**
        Allows to specify when to execute a particular function.
        */
        class Calendar_Rule {
            public const ushort lwm2m_object_id          = 3453;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3453";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Mnemonic name of the calendar
            */
            [ResourceId(0), Operations("RW")] string Calendar_Name;

            /**
            0 - Day time Gregorian calendar used to reference periods of 24h (00-24h) during the year
            1 - Night time calendar, a variation of the Gregorian calendar proposed by uCiFi to reference "night" periods
            of 24h during a year.
            Measured from 12:00 of one Gregorian calendar day to 12:00 of the next day.
            If omitted, 0 shall be assumed
            */
            [ResourceId(1), Operations("RW")] long? Calendar_Type;

            /**
            Start date formatted as yyyy-mm-dd.
            To define the same start date every year: --mm-dd (e.g. --01-01 for Jan 1st every year).
            Start date is optional.
            If no start date, no end date should be mentioned, and the scheduler should apply every day of every year.
            */
            [ResourceId(2), Operations("RW")] string[,,] Start_Date;

            /**
            End date formatted as yyyy-mm-dd.
            To define the same end date every year: --mm-dd (e.g. --03-31 for March 31st every year).
            End date is optional.
            If no start date is specified, no end date should be mentioned as well, and the scheduler should apply every
            day of every year.
            If the start date is specified but the end date is not, it shall be assumed to be equal to the start date
            */
            [ResourceId(3), Operations("RW")] string[,,] End_Date;

            /**
            Date string formatted as dom month dow, inspired from the CRON format without minutes and hours, that
            indicates the occurrence of the rule:
            dom = day of month (1-31)
            month = 1-12
            dow = day of week (0-7, where 0,7=Sunday)
            * * * means every day between "Start date" and "End date"
            1-10 * * means from the 1st to the 10th day of the month each month between "Start date" and "End date"
            * * 6,7 means every Saturday and Sunday, between "Start date" and "End date"
            The date rule is optional.
            If not present, it means every day between "Start date" and "End date".
            If present, it would be applied in AND to every instance of Start date and End date
            */
            [ResourceId(4), Operations("RW")] string Date_Rule;

            /**
            True if the calendar rule is currently active
            */
            [ResourceId(5), Operations("R")] bool? Calendar_Active;
        }

        // ═════════════════════════ 3454.xml: Program Function (urn:oma:lwm2m:ext:3454) ═════════════════════════
        /**
        Describes the behavior that controls the associated target based on time or sensor status.
        */
        class Program_Function {
            public const ushort lwm2m_object_id          = 3454;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3454";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = true;

            /**
            Mnemonic name of the function
            */
            [ResourceId(0), Operations("RW")] string Function_Name;

            /**
            Conditions that would cause the function to be effective (if at least one condition is met).
            Syntax of each condition is as follows:
            &lt;time&gt;,&lt;sensor #1&gt;,&lt;sensor #2&gt;,…,&lt;sensor #n&gt;
            hh:mm or S(unset), sun(R)ise /- minute offset
            Ranges are separated with a tilde character "~"
            Open ranges can be written as start~ (value &gt;= start) or ~end (value &lt;= end)
            Time should be a range, eg 18:00~04:00 or S~R
            And each sensor can be either a specific value or a range of values
            If omitted or not supported, function can be assumed to be effective 24/24
            */
            [ResourceId(1), Operations("RW")] string[,,] Run_Condition;

            /**
            Number of Output Filter object instances, each one being applied to the corresponding target output
            */
            [ResourceId(3), Operations("RW")] long[,,] Output_Filter;

            /**
            Sequence of fixed time and/or astronomical events separated by semicolons
            Each resource instance is specified as a sequence that will target the corresponding output
            hh:mm = fixed time
            S+30 = sunset plus 30 minutes
            R-20 = sunrise minus 20 minutes
            */
            [ResourceId(4), Operations("RW"), Mandatory] string[,,] Time_Input_Array;

            /**
            Sequence of arguments to be provided to the target.
            If strings have to be provided, they must be enclosed in double quotes
            e.g. 10;50;24
            "parking empty";"parking full"
            Any spacing provided outside double quotes can be safely ignored
            */
            [ResourceId(5), Operations("RW"), Mandatory] string[,,] Time_Output_Array;

            /**
            Allows to define multiple conditions based on sensor value.
            Only the first sensor is considered (in case multiple sensors are configured).
            This resource shall be used in mutual exclusion with the multi sensor input array.
            */
            [ResourceId(6), Operations("RW")] string[,,] Single_Sensor_Input_Array;

            /**
            Allows to define multiple conditions based on time and sensor values with a syntax similar to the one used for
            the Run condition
            Each condition shall be enclosed in brackets and separated by semicolons
            (&lt;time&gt;,&lt;sensor #1&gt;,&lt;sensor #2&gt;,…,&lt;sensor #n&gt;);(&lt;time&gt;,&lt;sensor
            #1&gt;,&lt;sensor #2&gt;,…,&lt;sensor #n&gt;);…
            The first condition matching would take precedence over the ones following
            Any spacing provided outside double quotes can be safely ignored
            When multiple output targets have to be managed, additional conditions will be provided in a separate resource
            instance
            */
            [ResourceId(7), Operations("RW")] string[,,] Multi_Sensor_Input_Array;

            /**
            Sequence of arguments to be provided to the target in a similar way of the time output array
            The sensor arrays can be used in conjunction of the time arrays and, in this case, would take precedence in
            case of matching
            This would allow to define both fixed time control and sensor based control in a single function
            If both single sensor input array and multi sensor input array are both specified, the multi sensor one would
            take precedence
            */
            [ResourceId(8), Operations("RW")] string[,,] Sensor_Output_Array;

            /**
            Sequence of arguments representing Output Filter instances to be applied to the corresponding target output
            e.g. 0;;1 means /3456/0;default;/3456/1
            If resource or specific entry is not specified, the default output filter, if present, would be applied
            */
            [ResourceId(9), Operations("RW")] string[,,] Output_Filter_for_Time_Output;

            /**
            Sequence of arguments representing Output Filter instances to be applied to the corresponding target output
            e.g. 0;;1 means 3456/0;default;3456/1
            If resource or specific entry is not specified, the default output filter, if present, would be applied
            */
            [ResourceId(10), Operations("RW")] string[,,] Output_Filter_for_Sensor_Output;
        }

        // ═════════════════════════ 3455.xml: Input Filter (urn:oma:lwm2m:ext:3455:2.0) ═════════════════════════
        /**
        The uCIFI Input Filter can be used to fine tune the sensor evaluation, in order to provide hold functionality
        or custom filtering. To be used in conjunction with a Program Scheduler.
        */
        class Input_Filter {
            public const ushort lwm2m_object_id          = 3455;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3455:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Current state captured on the corresponding input source instance
            */
            [ResourceId(0), Operations("R")] string[,,] Input_State;

            /**
            Resources are specified using Core Link syntax
            Example:
            Instance #0: &lt;/3302/0/5500&gt;
            Instance #1: &lt;/3302/1/5500&gt;
            */
            [ResourceId(1), Operations("RW")] string[,,] Input_Source;

            /**
            0 - opaque 1 - counter integer 2 - gauge integer 3 - gauge float 4 - Time 5 - String
            */
            [ResourceId(2), Operations("RW")] long? Data_Type;

            /**
            Sets the frequency at which the LwM2M resource identified as Source should be evaluated.
            Example, if set to 5000, the Program should evaluate the value reported by the LwM2M resource pointed by
            Source every 5 seconds.
            */
            [ResourceId(3), Operations("RW"), Units("s")] double? Evaluation_Interval;

            /**
            Sets a step interval, making the Program evaluate the LwM2M resource pointed by Source, only when its value
            changes by more than Step Filter.
            Example, if set to 1000, the Program should evaluate the value reported by the LwM2M resource pointed by
            Source only if it changes by more than 1000 units from the last evaluation.
            */
            [ResourceId(4), Operations("RW")] double? Step_Filter;

            /**
            Delay from the detection state to the clear state in ms.
            */
            [ResourceId(5903), Operations("RW"), Units("ms")] DurationInMilliseconds? Busy_to_Clear_delay;

            /**
            Delay from the clear state to the busy state in ms.
            */
            [ResourceId(5904), Operations("RW"), Units("ms")] DurationInMilliseconds? Clear_to_Busy_delay;
        }

        // ═════════════════════════ 3456.xml: Output Filter (urn:oma:lwm2m:ext:3456) ═════════════════════════
        /**
        The uCIFI Output Filter can be used to fine tune the output commands in order, for example, to achieve a
        prolonged fade. To be used in conjunction with a Program Scheduler.
        */
        class Output_Filter {
            public const ushort lwm2m_object_id          = 3456;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3456";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource defines an operation to be performed between the value of the Control Program output and the
            value currently store in the LwM2M resource pointed by 'Target'. Possible operations: 1 - set 2 - min 3 - max
            4 - add 5 - subtract 6 - multiply When operation or filter is not defined the default output operation is set
            */
            [ResourceId(0), Operations("RW"), Mandatory] long Operation;

            /**
            When defined the control output is not immediately applied and transaction time = delay is implemented between
            the current target resource value and the value of the control program output.  This can be also associated to
            Fade Time in smart lighting scenario
            */
            [ResourceId(1), Operations("RW"), Units("s")] double? Delay;

            /**
            Defines the type of progression to occur to  transition the current target resource value to the value defined
            by the of the control program output. Current options: 0 - Immediate 1 - linear 2 - exponential 3 - Device
            internal mechanism
            */
            [ResourceId(2), Operations("RW")] long? Transaction;

            /**
            Limit the time period for which the output command should be considered valid. This is to be used in scenarios
            where Control Programs are not under continuous re-evaluation and for which the output control action is not
            continuously re-calculated. In such scenarios, the expiration time resource can be used to limit the time
            frame that the control output should be applied to the target resource.
            */
            [ResourceId(3), Operations("RW")] double? Expiration_Time;
        }

        // ═════════════════════════ 3457.xml: Program Manager (urn:oma:lwm2m:ext:3457:1.1) ═════════════════════════
        /**
        The uCIFI Program Manager describes the scheduling capabilities of the device, referring to Program
        Schedulers, Program Functions, Calendar Rules and Filters.
        */
        class Program_Manager {
            public const ushort lwm2m_object_id          = 3457;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3457:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = true;

            /**
            Maximum number of program schedulers supported by the device.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(0), Operations("RW"), Mandatory] long Max_number_of_Program_Schedulers;

            /**
            Number of program schedulers currently allocated.
            */
            [ResourceId(1), Operations("R"), Mandatory] long Current_number_of_Program_Schedulers;

            /**
            Maximum number of program functions supported by the device.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(2), Operations("RW"), Mandatory] long Max_number_of_Program_Functions;

            /**
            Number of program functions currently allocated.
            */
            [ResourceId(3), Operations("R"), Mandatory] long Current_number_of_Program_Functions;

            /**
            Maximum number of calendars supported by the device.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(4), Operations("RW"), Mandatory] long Max_number_of_Calendars;

            /**
            Number of calendars currently allocated.
            */
            [ResourceId(5), Operations("R"), Mandatory] long Current_number_of_Calendar;

            /**
            Maximum number of target actuators supported.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(6), Operations("RW"), Mandatory] long Max_number_of_Actuators;

            /**
            Maximum number of input sources supported.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(7), Operations("RW")] long? Max_number_of_Input_Sources;

            /**
            Maximum number of start/end date in Calendar supported.
            Can be eventually adjusted in order to reserve more or less memory.
            */
            [ResourceId(8), Operations("RW")] long? Max_number_of_Dates_in_Calendar;

            /**
            Max flash memory (in bytes) to be allocated.
            Can be eventually adjusted in order to reserve more or less memory
            */
            [ResourceId(9), Operations("RW"), Units("B"), Mandatory] long Max_Flash_Memory_Allocated;

            /**
            Free flash memory in bytes
            */
            [ResourceId(10), Operations("R"), Units("B")] long? Flash_Memory_Free;

            /**
            Bitmap
            Bit 0: No valid program
            Bit 1: Missing configuration objects
            Bit 2: Missing configuration resources
            Bit 3: Invalid inputs
            Bit 4: Invalid outputs
            Bit 5: Invalid function format
            Bit 6: Out of storage memory
            Bit 7: Out of runtime memory
            Bit 8..31: reserved for future use
            */
            [ResourceId(11), Operations("R"), Mandatory] long Error_Conditions;

            /**
            Bitmap
            Bit 0: Astronomical Events
            Bit 1: Single sensor Inputs
            Bit 2: Multi Sensor Inputs
            Bit 3: Input Filters
            Bit 4: Output Filters
            Bit 5: Calendar
            Bit 6: Compound Operations
            Bit 7: Second granularity (for fixed time expressions)
            Bit 8: Astronomical Midnight
            Bit 9: Off when inactive
            Bit 10: Transaction support
            Bit 11: Transaction support - Automatic fallback
            */
            [ResourceId(13), Operations("R")] long? Supported_Capabilities;

            /**
            Max RAM memory (in bytes) to be allocated.
            Can be eventually adjusted in order to reserve more or less memory
            */
            [ResourceId(14), Operations("RW"), Units("B")] long? Max_Dynamic_Memory_Allocated;

            /**
            Free RAM memory in bytes
            */
            [ResourceId(15), Operations("R"), Units("B")] long? Dynamic_Memory_Free;

            /**
            If this resource is implemented, before altering any Schedule related object instance
            (Program Scheduler, Calendar Rule, Program Function, Input Filter, Output Filter)
            using a create, delete, or write operation, a transaction shall be initiated by writing a random value in this
            resource.
            If the transaction end is not written with the same value before the timeout expires, the transaction shall be
            aborted.
            */
            [ResourceId(100), Operations("RW")] long? Transaction_start;

            /**
            If this resource is implemented, it shall be written with the same value that has been previously written
            to the transaction start resorce in order to close the current transaction
            */
            [ResourceId(101), Operations("RW")] long? Transaction_end;

            /**
            The timeout in seconds after which a transaction that has not been closed shall be aborted. Default = 600 s.
            If a timeout happens the device will set an alarm status and may eventually revert, if supported, to the
            previous state
            */
            [ResourceId(102), Operations("RW"), Units("s")] DurationInSeconds? Transaction_timeout;

            /**
            This resource is set to true when a transaction is aborted and is automatically cleared when a new transaction
            is started
            */
            [ResourceId(103), Operations("R")] bool? Transaction_error;

            /**
            When executed, clears temporary error conditions.
            To be noted that some of the errors may require to change the content of other objects to be completely
            cleared.
            Execute operation on resource 12 (Clear errors); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E")] public class Clear_errors_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            When executed, trigger a complete wipe of schedules already commissioned
            Execute operation on resource 16 (Reset schedule objects); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E")] public class Reset_schedule_objects_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3458.xml: Program Monitor (urn:oma:lwm2m:ext:3458) ═════════════════════════
        /**
        The uCIFI Program Monitor exports some useful information related to program execution.
        */
        class Program_Monitor {
            public const ushort lwm2m_object_id          = 3458;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3458";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Name of the program
            */
            [ResourceId(0), Operations("R"), Mandatory] string Program_Name;

            /**
            Identifies the current status of the control program, taking the values: 0 - Disabled 1 - Inactive 2 - Running
            where 'Disabled' should be present whenever the CP has been administratively disabled. The state should be set
            to 'Inactive' if the calendar associated with the CP makes is NOT applicable for the current day. If the CP is
            administratively enabled, and either the associated calendar makes it valid for the current day or no Calendar
            is associated with it.
            */
            [ResourceId(1), Operations("R"), Mandatory] long Status;

            /**
            Bitmap
            Bit 0: Sensor syntax error
            Bit 1: Time syntax error
            Bit 2: Invalid program function
            Bit 3..31: reserved for future use
            */
            [ResourceId(2), Operations("R"), Mandatory] long Error_Conditions;

            /**
            Cumulative counter for the number of times the current control program has been evaluated
            */
            [ResourceId(4), Operations("R")] long? Evaluation_Counter;

            /**
            Cumulative counter for the number of times the current control program has ben executed after evaluation,
            triggering the corresponding action and output. With 'Execution counter' less than or equal to 'Evaluation
            counter'
            */
            [ResourceId(5), Operations("R")] long? Execution_Counter;

            /**
            Timestamp for the latest execution of the current CP
            */
            [ResourceId(7), Operations("R")] DateTime? Last_Execution;

            /**
            String identifying the control output enforced during last program execution. If the control program supports
            multiple ouputs, one instance of this resource should be created for each output.
            */
            [ResourceId(8), Operations("R")] string[,,] Last_Control_Output;

            /**
            When executed, clears temporary error conditions.
            To be noted that some of the errors may require to change the content of the corresponding program function
            object to be completely cleared.
            Execute operation on resource 3 (Clear errors); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Clear_errors_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Reset all counters under the current object
            Execute operation on resource 6 (Counter Reset); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E")] public class Counter_Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3459.xml: Distributed Sensor Group (urn:oma:lwm2m:ext:3459:2.0) ═════════════════════════
        /**
        The uCIFI Distributed Sensor Group allows to configure a device to publish or subscribe to device-to-device
        communication.
        */
        class Distributed_Sensor_Group {
            public const ushort lwm2m_object_id          = 3459;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3459:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The current output state of the sensor Group, derived either from the latest sensor state published to the
            group, or computed based on all sensor inputs when data Fusion Operation is used [default=NaN]
            */
            [ResourceId(0), Operations("R")] double? Group_State;

            /**
            SUBSCRIBER ONLY UNIX Timestamp for when the last activity in the group was recorded, either by the node
            sending a message to the group our retrieved from the "Publishing Timestamp" of the last message received from
            the group. [default=0]
            */
            [ResourceId(1), Operations("R")] DateTime? Most_recent_group_activity;

            /**
            SUBSCRIBER ONLY URI for the last sensor state value published within the group , in the format of
            &lt;/Object/Instance/Resource&gt; (using Core Link syntax), retrieved from the "Remote Sensor State URI" field
            of the last received or sent group message. [default=empty]
            */
            [ResourceId(2), Operations("R")] string Most_recent_Sensor_Notification;

            /**
            SUBSCRIBER ONLY The publisher sensor ID associated to the last registered sensor notification [default=0]
            */
            [ResourceId(3), Operations("R")] long? Most_recent_Sensor_Publisher_ID;

            /**
            PUBLISHER SUBSCRIBER The address where all devices that wish to be part of the group, need to communicate
            with, either by publishing sensor data to the address or by subscribing to sensor data from the address. In
            case IP multicast is used for exchange of data within a distributed sensor group, than this resource would be
            used to store the IPv4 or IPv6 multicast group address [default=empty]
            */
            [ResourceId(4), Operations("RW")] string[,,] Group_Address;

            /**
            PUBLISHER SUBSCRIBER A unique Identifier for the Group that should be present in every transmission of sensor
            data linked to the group. If specified, this identifier will be used as the Group ID in the "Distributed Group
            Message" payload, otherwise the Group address will be used. [default=empty]
            */
            [ResourceId(5), Operations("RW")] string Group_ID;

            /**
            PUBLISHER ONLY Sensor information to be included in the payload of the "Distributed Sensor Message"
            notifications sent within the group: 0: Sensor state information - Only the current state of a sensor is to be
            sent 1: All sensor information - A device publishing sensor updates into the group should include within the
            notification payload all sensor object resources. These will depend on the sensor but may include for example
            "sensor type", "reading timestamp", "hold time", etc.. When not defined the only sensor information to be sent
            to the group MUST be its up-to-date state information, no other sensor related information is to be sent.
            [default=0]
            */
            [ResourceId(6), Operations("RW")] long? Shared_Sensor_information;

            /**
            PUBLISHER ONLY If the underlying transport technology supports QoS, this resource can be used to set the
            buffering and forwarding priority of this sensor data within the network. [default=empty]
            */
            [ResourceId(7), Operations("RW")] string Quality_of_service;

            /**
            PUBLISHER ONLY Used by publishers nodes to set the hop limit to apply on the broadcast messages used to
            forward sensor information, in this way limiting the reach of the sensor data message forwarding within a
            group. [default=5]
            */
            [ResourceId(8), Operations("RW")] long? Hop_Limit;

            /**
            PUBLISHER ONLY 1 - On sensor state change, 2 - periodic, 3 - both [default=1]
            */
            [ResourceId(9), Operations("RW")] long? Broadcast_Criteria;

            /**
            PUBLISHER ONLY Used by publishers nodes, this resource limits the rate at which a sensor is allowed to
            broadcast messages to the sensor group. This is used to avoid message storming scenarios within the
            distributed sensor group. Ignored if 0 [default=0]
            */
            [ResourceId(10), Operations("RW"), Units("s")] DurationInSeconds? Min_Broadcast_Period;

            /**
            PUBLISHER ONLY Used by publishers nodes, this resource should be used when sensor Broadcast criteria is set to
            either 2 or 3, defining the maximum amount of time that can elapse before a sensor publishes is current state
            within the group. Ignored if 0 [default=0]
            */
            [ResourceId(11), Operations("RW"), Units("s")] DurationInSeconds? Max_Broadcast_Period;

            /**
            PUBLISHER ONLY Used by publishers nodes, the resource works as a filter, allowing only significant variations
            on the reading provided by local sensor (minimum step interval) to be forwarded to the sensor group
            [default=1].
            */
            [ResourceId(12), Operations("RW")] double? Publisher_Step_interval;

            /**
            PUBLISHER ONLY Data is sent only if greater than or equal min threshold. Ignored if omitted or NaN
            [default=NaN]
            */
            [ResourceId(13), Operations("RW")] double? Min_Threshold;

            /**
            PUBLISHER ONLY Data is sent only if less than or equal max threshold. Ignored if omitted or NaN [default=NaN]
            */
            [ResourceId(14), Operations("RW")] double? Max_Threshold;

            /**
            PUBLISHER ONLY Time for which the published sensor state shall be considered valid If Auto-clear capability is
            supported by the publisher, this value will be included in the messages being sent Ignored if 0 [default=0]
            */
            [ResourceId(15), Operations("RW"), Units("s")] long? Auto_Clear_Validity_Time;

            /**
            PUBLISHER ONLY Default value to be restored when the validity time is expired. The publisher may not include
            the validity time when the sensor state is already equal (or equivalent) to the default state. If not
            specified 0/false has to be assumed [default=0]
            */
            [ResourceId(16), Operations("RW")] double? Auto_Clear_Default_Value;

            /**
            SUBSCRIBER ONLY The data fusion operation to be performed between resources pointed by local sensor state URIs
            and remote sensor state URIs (or their implicitly allocated equivalent value). To be noted that the operation
            is normally applicable to numerical values only (for Boolean values, 0 = false, 1 = true) 0: No fusion is to
            be performed 1: OR 2: AND 3: ADD 4: MAX 5: MIN 6: LAST - The last value reported by any sensor in the group
            becomes the group state value 7: Reserved (Custom 1) 8: Reserved (Custom 2)
            */
            [ResourceId(17), Operations("RW")] long? Data_Fusion_Operation;

            /**
            SUBSCRIBER ONLY This resource controls how to locally map remote sensors and its configuration depends on the
            capabilities advertised within the Sensor Group Device Capabilities False: Static mapping is enforced. Only
            publishers listed in Remote Sensor State URI are accepted and take part into the fusion operation. True:
            Dynamic mapping is enforced. Any publisher belonging to the group is accepted and take part into the fusion
            operation [default=false]
            */
            [ResourceId(18), Operations("RW")] bool? Remote_Sensors_Dynamic_Mapping;

            /**
            SUBSCRIBER ONLY This resource controls how to locally map remote sensors and its configuration depends on the
            capabilities advertised within the Sensor Group Device Capabilities False: Explicit mapping is enforced.
            Remote sensor state is captured and maintained in the current device by updating local objects instances
            corresponding to remote publishers, allowing server endpoint visibility over individual remote sensor states.
            If dynamic mapping is not supported, object instances shall be created in advance True: Implicit mapping is
            enforced. Remote sensor state is captured and maintained on an implementation specific internal database. No
            external visibility is provided on the current state of remote sensor entries. [default=false]
            */
            [ResourceId(19), Operations("RW")] bool? Remote_Sensors_Implicit_Mapping;

            /**
            PUBLISHER ONLY URI in the format of &lt;/Object/Instance/Resource(/ResourceInstance)&gt; (using Core Link
            syntax) pointing to the LwM2M resource instance holding the sensor state that the device should publish into
            the group. This uses the real address of a local physical sensor, e.g. &lt;/3302/0/5500&gt; [default=empty]
            */
            [ResourceId(20), Operations("RW")] string[,,] Local_Sensor_State_URI;

            /**
            PUBLISHER ONLY The sensor ID that should be used to translate the instance specified within the corresponding
            "Local Sensor State URI" when publishing new data. In most scenarios Sensor publisher ID should be unique
            within the Group (unless if some type of overlap/overwrite of the information provided by the different
            sensors is intended) [default=empty]
            */
            [ResourceId(21), Operations("RW")] long[,,] Local_Sensor_Publisher_ID;

            /**
            SUBSCRIBER ONLY URI in the format of &lt;/Object/Instance/Resource(/ResourceInstance)&gt; (using Core Link
            syntax) identifying the publishers to be accepted when using static mapping. This also reflects where the
            sensor state information retrieved from the Sensor Group should be locally stored into. [default=empty]
            */
            [ResourceId(22), Operations("RW")] string[,,] Remote_Sensor_State_URI;

            /**
            PUBLISHER SUBSCRIBER This resource can be used to provide vendor specific information related to the
            operativity of the group, such as the remote publishers dynamically mapped [default=empty]
            */
            [ResourceId(23), Operations("R")] string Group_Log;

            /**
            Custom user defined description.
            */
            [ResourceId(24), Operations("RW")] string Group_Description;

            /**
            PUBLISHER ONLY 64-bit unique identifier associated to the specific Publisher ID, to be included when
            publishing new data [default=empty]
            */
            [ResourceId(25), Operations("RW")] string[,,] Local_Sensor_Publisher_EUI;
        }

        // ═════════════════════════ 3460.xml: Distributed Sensor Message (urn:oma:lwm2m:ext:3460:1.1) ═════════════════════════
        /**
        The uCIFI Distributed Sensor Message provides the format of data being exchanged within the Distributed Sensor
        Group communication.
        */
        class Distributed_Sensor_Message {
            public const ushort lwm2m_object_id          = 3460;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3460:1.1";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.1";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            The identifier of the group. This resource can be used to filter the incoming message.
            This resource should match the Group ID resource of the Distributed Sensor Group or, if not specified, the
            Group Address.
            */
            [ResourceId(0), Operations("R"), Mandatory] long Group_ID;

            /**
            UNIX timestamp related to the time when the measurement has been collected by the publisher.
            */
            [ResourceId(1), Operations("R"), Mandatory] DateTime Publishing_timestamp;

            /**
            URI of the resource that contains the status information, to be used for data fusion and to be eventually
            filtered upon reception
            */
            [ResourceId(2), Operations("R"), Mandatory] string Publisher_State_URI;

            /**
            If this resource is omitted, the Publisher State URI shall be properly translated in advance in order to map
            the physical sensor instance on the publisher to the corresponding publisher ID specified within the
            Distributed Sensor Group.
            Otherwise, the real physical sensor instance can be used and the translation has to be performed upon
            reception
            */
            [ResourceId(3), Operations("R")] long? Publisher_ID;

            /**
            If Auto-clear capability is supported by the subscriber, the validity of the attached data can be limited for
            the specified amount of time, after which it can be discarded or reset to a default value (see Auto Clear
            Default Value)
            */
            [ResourceId(4), Operations("R"), Units("s")] long? Auto_Clear_Validity_Time;

            /**
            Default value to be restored when the validity time is expired. If not specified 0/false has to be assumed
            */
            [ResourceId(5), Operations("R")] double? Auto_Clear_Default_Value;

            /**
            64-bit unique identifier associated to the Publisher
            */
            [ResourceId(6), Operations("R")] string Publisher_EUI;
        }

        // ═════════════════════════ 3461.xml: Sensor Group Device Capabilities (urn:oma:lwm2m:ext:3461:1.2) ═════════════════════════
        /**
        This object is used to notify the user about the capabilities supported by the device in respect to
        Distributed Sensot Group functionality.
        */
        class Sensor_Group_Device_Capabilities {
            public const ushort lwm2m_object_id          = 3461;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3461:1.2";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.2";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Specifies the capabilities supported by the device to manage and store remote sensors information retrieved
            from the sensor group as a Bit Mask:
            Bit 0: Dynamic mapping support - Remote sensors can be discovered as new messages are received. If explicit
            mapping is required, new corresponding object instances will be automatically created
            Bit 1: Implicit mapping support - Sensor state is maintained on an implementation specific internal database
            instead of being reflected into local objects
            Bit 2: Auto clear support - Automatic clear to the default value is supported after validity time is expired
            Bit 3: Transaction support
            Bit 4: Transaction support - Automatic fallback
            */
            [ResourceId(1), Operations("R")] long? Remote_Sensor_Management_capabilities;

            /**
            The maximum number of sensors and sensor states the device can instantiate.
            This value is calculated by the count of all different sensor objects associated with a sensor groups.
            This value shall be set to 0 if explicit mapping is not supported
            On uCiFi compliant devices support for static explicit mapping is mandatory.
            */
            [ResourceId(2), Operations("R")] long? Max_number_of_explicit_sensors;

            /**
            The maximum number of sensors and sensor states the device can keep in memory.
            This value is calculated by the count of all different sensor objects associated with a sensor groups.
            This value shall be set to 0 if implicit mapping is not supported.
            */
            [ResourceId(3), Operations("R")] long? Max_number_of_implicit_sensors;

            /**
            Specifies the data fusion algorithms supported by the device represented as a bitmask:
            Bit 0: OR
            Bit 1: AND
            Bit 2: ADD
            Bit 3: MAX
            Bit 4: MIN
            Bit 5: LAST - The last value reported by any sensor in the group becomes the group state value
            Bit 6: Reserved (Custom 1)
            Bit 7: Reserved (Custom 2)
            If the device supports no fusion capabilities, this resource should be set to 0.
            */
            [ResourceId(4), Operations("R")] long? Data_Fusion_Capabilities;

            /**
            Specifies the underlying implementations supported by the device to transfer the distributed messages using a
            Bit Mask:
            Bit 0: implementation supported: IPv6 - Multicast only - NoSec
            Bit 1: implementation supported: IPv6 - Unicast only - NoSec
            Bit 2: implementation supported: IPv6 - Multicast + Unicast - NoSec
            Bit 3: implementation supported: IPv4 - Multicast only - NoSec
            Bit 4: implementation supported: IPv4 - Unicast only - NoSec
            Bit 5: implementation supported: IPv4 - Multicast + Unicast - NoSec
            */
            [ResourceId(6), Operations("R")] long? Supported_implementations;

            /**
            Set which implementation to use among the supported ones.
            The value should correspond to the bit in resource Supported implementations
            e.g.
            0 = IPv6 - Multicast only - NoSec
            5 = IPv4 - Multicast + Unicast - NoSec
            Setting a value that is not supported shall be rejected
            */
            [ResourceId(7), Operations("RW")] long? Implementation;

            /**
            If this resource is implemented, before altering any Distributed Sensor Group instance
            using a create, delete, or write operation, a transaction shall be initiated by writing a random value in this
            resource.
            If the transaction end is not written with the same value before the timeout expires, the transaction shall be
            aborted.
            */
            [ResourceId(100), Operations("RW")] long? Transaction_start;

            /**
            If this resource is implemented, it shall be written with the same value that has been previously written
            to the transaction start resorce in order to close the current transaction
            */
            [ResourceId(101), Operations("RW")] long? Transaction_end;

            /**
            The timeout in seconds after which a transaction that has not been closed shall be aborted. Default = 600 s
            If a timeout happens the device will set an alarm status and may eventually revert, if supported, to the
            previous state
            */
            [ResourceId(102), Operations("RW"), Units("s")] DurationInSeconds? Transaction_timeout;

            /**
            This resource is set to true when a transaction is aborted and is automatically cleared when a new transaction
            is started
            */
            [ResourceId(103), Operations("R")] bool? Transaction_error;

            /**
            When executed, trigger a complete wipe of the distributed sensor groups already commissioned
            Execute operation on resource 5 (Reset DSG objects); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Reset_DSG_objects_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 3463.xml: uCIFI Test Object (urn:oma:lwm2m:ext:3463) ═════════════════════════
        /**
