        // ═════════════════════════ 3600.xml: AppMessaging (urn:oma:lwm2m:ext:3600) ═════════════════════════
        /**
        This LwM2M Object provides a bi-directional messaging facility for applications. Distinct resources are
        defined for Client to Server messaging and Server to Client messaging.
        */
        class AppMessaging {
            public const ushort lwm2m_object_id          = 3600;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3600";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Server to Client message.
            */
            [D(65535), ResourceId(0), Operations("W"), Mandatory] Binary[,,] Server_Message;

            /**
            Client to Server message.
            */
            [D(65535), ResourceId(1), Operations("R"), Mandatory] Binary[,,] Client_Message;

            /**
            Indicates the message priority:
            0:Immediate
            1:BestEffort
            2:Latest
            3-100: Reserved for future use.
            101-254: Proprietary mode.
            */
            [ResourceId(2), Operations("RW")] byte? Message_Priority;

            /**
            Indicates the message description:
            0:App Configuration
            1:App Data
            2-100: Reserved for future use.
            101-254: Proprietary use.
            */
            [ResourceId(3), Operations("RW"), Mandatory] ulong Message_Description;

            /**
            A unique local-scope identifier for distinguishing edge applications within a specific deployment environment.
            */
            [ResourceId(4050), Operations("RW"), Mandatory] ulong AppID;
        }

        // ═════════════════════════ 3601.xml: HostMonitoring (urn:oma:lwm2m:ext:3601) ═════════════════════════
        /**
        This LwM2M Object provides a facility for monitoring resource utilization of a GEISA edge environment.
        */
        class HostMonitoring {
            public const ushort lwm2m_object_id          = 3601;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3601";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Duration since last boot in integer seconds.
            */
            [ResourceId(0), Operations("R"), Units("s"), Mandatory] DurationInSeconds Uptime;

            /**
            Number of CPU Cores.
            */
            [ResourceId(1), Operations("R"), Mandatory] ulong CPU_Cores;

            /**
            Scaled integer value representing the CPU centi-load (Load = Value / 100) averaged over the last 1 minute.
            */
            [ResourceId(2), Operations("R")] ulong? CPU_Load;

            /**
            Scaled integer value representing deci-percentage (Usage = Value / 10) of current CPU utilization (user+system
            time).
            */
            [ResourceId(3), Operations("R"), Units("%")] ulong? CPU_Usage;

            /**
            Total physical RAM in bytes.
            */
            [ResourceId(4), Operations("R"), Units("B")] ulong? RAM_Total;

            /**
            Total Available RAM (free + reclaimable) in bytes that can be used without swapping.
            */
            [ResourceId(5), Operations("R"), Units("B")] ulong? RAM_Available;

            /**
            Number of runnable tasks, useful to detect CPU contention and scheduler saturation.
            */
            [ResourceId(6), Operations("R")] ulong? Processes_Running;

            /**
            Number of tasks blocked waiting on I/O. Sustained non-zero values can indicate I/O stalls, deadlocks or
            driver/storage issues.
            */
            [ResourceId(7), Operations("R")] ulong? Processes_Blocked;

            /**
            Number of context swicthes per second, useful to detect thread thrashing, lock contention, excessive
            interrupts, or scheduling overhead.
            */
            [ResourceId(8), Operations("R")] ulong? Context_Switches;

            /**
            Scaled integer file handle utilization in centi-percent of limit: used_int = (open / max) * 10000. used_pct =
            used_int / 100.
            Useful to detect file descriptor leaks, socket leaks, network connection storms, or misbehaving applications.
            */
            [ResourceId(9), Operations("R"), Units("%")] ulong? File_Handles_Used;
        }

        // ═════════════════════════ 3602.xml: AppAccounting (urn:oma:lwm2m:ext:3602) ═════════════════════════
        /**
        This LwM2M Object provides facilities for service flow level accounting and throttling per application.
        */
        class AppAccounting {
            public const ushort lwm2m_object_id          = 3602;
            public const string lwm2m_urn                = "urn:oma:lwm2m:ext:3602";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            A string in RFC 5545 Recurrence Rule (RRule) format defining the collection period (e.g.,
            "RRULE:FREQ=MINUTELY;INTERVAL=60").
            Collection period counters shall be automatically reset at the end of each collection period.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Collection_Period;

            /**
            Hard limit maximum number of bytes allowed per collection period, above which the device initiates throttling
            of the app referenced in resource 4050 without direction from the Server.
            */
            [ResourceId(1), Operations("RW")] ulong? Maximum_Bytes;

            /**
            Number of bytes transmitted so far during the collection period for the app referenced in resource 4050.
            */
            [ResourceId(2), Operations("R"), Mandatory] ulong TX_Bytes;

            /**
            Number of bytes received so far during the collection period for the app referenced in resource 4050.
            */
            [ResourceId(3), Operations("R"), Mandatory] ulong RX_Bytes;

            /**
            Number of bytes transmitted and received so far during the collection period for the app referenced in
            resource 4050.
            */
            [ResourceId(4), Operations("R"), Mandatory] ulong Total_Bytes;

            /**
            Number of packets transmitted so far during the collection period for the app referenced in resource 4050.
            */
            [ResourceId(5), Operations("R")] ulong? TX_Packets;

            /**
            Number of packets received so far during the collection period for the app referenced in resource 4050.
            */
            [ResourceId(6), Operations("R")] ulong? RX_Packets;

            /**
            A unique local-scope identifier for distinguishing edge applications within a specific deployment environment.
            */
            [ResourceId(4050), Operations("RW"), Mandatory] ulong AppID;

            /**
            Start throttling traffic for the app referenced in resource 4050.
            Execute operation on resource 7 (Start Throttling); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E")] public class Start_Throttling_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stop throttling traffic for the app referenced in resource 4050.
            Execute operation on resource 8 (Stop Throttling); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E")] public class Stop_Throttling_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

