        // ═════════════════════════ 10243.xml: Single-Phase Power Meter (urn:oma:lwm2m:x:10243:2.0) ═════════════════════════
        /**
        This Object provides the information to represent a generic Single-Phase Power Meter.
        */
        class Single_Phase_Power_Meter {
            public const ushort lwm2m_object_id          = 10243;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10243:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Human readable manufacturer name
            */
            [ResourceId(0), Operations("R")] string Manufacturer;

            /**
            A model identifier (manufacturer specified string)
            */
            [ResourceId(1), Operations("R")] string Model_Number;

            /**
            Serial number of the meter
            */
            [ResourceId(2), Operations("R")] string Serial_Number;

            /**
            Description of the meter
            */
            [ResourceId(3), Operations("R")] string Description;

            /**
            Voltage
            */
            [ResourceId(4), Operations("R"), Units("V"), Mandatory] double Tension;

            /**
            Current
            */
            [ResourceId(5), Operations("R"), Units("A"), Mandatory] double Current;

            /**
            Active Power
            */
            [ResourceId(6), Operations("R"), Units("kW")] double? Active_Power;

            /**
            Reactive Power
            */
            [ResourceId(7), Operations("R"), Units("kvar")] double? Reactive_Power;

            /**
            Inductive Reactive Power
            */
            [ResourceId(8), Operations("R"), Units("kvar")] double? Inductive_Reactive_Power;

            /**
            Capacitive Reactive Power
            */
            [ResourceId(9), Operations("R"), Units("kvar")] double? Capacitive_Reactive_Power;

            /**
            Apparent Power
            */
            [ResourceId(10), Operations("R"), Units("kVA")] double? Apparent_Power;

            /**
            Power Factor
            */
            [Range("-1..1"), ResourceId(11), Operations("R")] double? Power_Factor;

            /**
            Total Harmonic Distortion (Tension)
            */
            [ResourceId(12), Operations("R"), Units("/100")] double? THD_V;

            /**
            Total Harmonic Distortion (Current)
            */
            [ResourceId(13), Operations("R"), Units("/100")] double? THD_A;

            /**
            Active Energy
            */
            [ResourceId(14), Operations("R"), Units("kWh")] double? Active_Energy;

            /**
            Reactive Energy
            */
            [ResourceId(15), Operations("R"), Units("kvarh")] double? Reactive_Energy;

            /**
            Apparent Energy
            */
            [ResourceId(16), Operations("R"), Units("kVAh")] double? Apparent_Energy;

            /**
            Frequency
            */
            [ResourceId(17), Operations("R"), Units("Hz")] double? Frequency;
        }

        // ═════════════════════════ 10244.xml: VehicleControlUnit (urn:oma:lwm2m:x:10244) ═════════════════════════
        /**
        This Object provides the information to represent a generic VCU(vehicle control unit).
        */
        class VehicleControlUnit {
            public const ushort lwm2m_object_id          = 10244;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10244";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            The UI state of the vehicle. 0: idle 1: driving 2: charging 3: limp-home 4-15: reserved for future use
            */
            [MinMax(0, 15), ResourceId(0), Operations("R"), Mandatory] byte Vehicle_UI_State;

            /**
            Current speed of the vehicle.
            */
            [ResourceId(1), Operations("R"), Units("km/h"), Mandatory] long Vehicle_Speed;

            /**
            Current shift status of the vehicle. 0: Neutral 1: Forward 2: Reverse
            */
            [MinMax(0, 3), ResourceId(2), Operations("R"), Mandatory] byte Vehicle_Shift_Status;

            /**
            Current position of the accelerator pedal.
            */
            [MinMax(0, 100), ResourceId(3), Operations("R"), Units("/100"), Mandatory] byte Vehicle_AP_Position;

            /**
            Current power of drive output/regenerative braking.
            */
            [ResourceId(4), Operations("R"), Units("kW")] double? Vehicle_Power;

            /**
            Accumulated drive energy of the vehicle.
            */
            [ResourceId(5), Operations("R"), Units("Wh")] double? Vehicle_Drive_Energy;

            /**
            Energy consumption efficiency of the vehicle.
            */
            [ResourceId(6), Operations("R"), Units("Wh/km")] double? Vehicle_Energy_Consumption_Efficiency;

            /**
            Estimated mileage of current battery capacity.
            */
            [ResourceId(7), Operations("R"), Units("km")] long? Vehicle_Estimated_Mileage;

            /**
            Whether the charge cable is connected or not. 0: unconnected 1: connected
            */
            [ResourceId(8), Operations("R"), Mandatory] bool Vehicle_Charge_Cable_Status;

            /**
            Charging status of the vehicle. 1: non-charge mode 2: charging 3: charge completed 4: charging abort
            abnormally
            */
            [MinMax(0, 15), ResourceId(9), Operations("R"), Mandatory] byte Vehicle_Charge_Status;

            /**
            Charging voltage
            */
            [ResourceId(10), Operations("R"), Units("V"), Mandatory] double Vehicle_Charge_Voltage;

            /**
            Charging current
            */
            [ResourceId(11), Operations("R"), Units("A"), Mandatory] double Vehicle_Charge_Current;

            /**
            Remaining charging time
            */
            [ResourceId(12), Operations("R"), Units("min"), Mandatory] long Vehicle_Charge_Remaining_Time;

            /**
            Voltage of the battery pack
            */
            [ResourceId(13), Operations("R"), Units("V"), Mandatory] double Battery_Pack_Voltage;

            /**
            Current of the battery pack
            */
            [ResourceId(14), Operations("R"), Units("A"), Mandatory] double Battery_Pack_Current;

            /**
            Remaining capacity of the battery pack
            */
            [ResourceId(15), Operations("R"), Units("Ah"), Mandatory] long Battery_Pack_Remaining_Capacity;

            /**
            SOC(state of charge) of the battery pack
            */
            [MinMax(0, 100), ResourceId(16), Operations("R"), Units("/100"), Mandatory] byte Battery_Pack_SOC;

            /**
            SOH(state of health) of the battery pack
            */
            [MinMax(0, 100), ResourceId(17), Operations("R"), Units("/100"), Mandatory] byte Battery_Pack_SOH;

            /**
            Minimum voltage of the battery module (with parallel connection of cells)
            */
            [ResourceId(18), Operations("R"), Units("mV"), Mandatory] long Battery_Cell_MinVolt;

            /**
            Maximum voltage of the battery module (with parallel connection of cells)
            */
            [ResourceId(19), Operations("R"), Units("mV"), Mandatory] long Battery_Cell_MaxVolt;

            /**
            Minimum temperature of the battery module
            */
            [ResourceId(20), Operations("R"), Units("Cel"), Mandatory] long Battery_Module_MinTemp;

            /**
            Maximum temperature of the battery module
            */
            [ResourceId(21), Operations("R"), Units("Cel"), Mandatory] long Battery_Module_MaxTemp;

            /**
            Whether the battery is connected or not. 0: unconnected 1: connected
            */
            [ResourceId(22), Operations("R"), Mandatory] bool Battery_Connection_Status;

            /**
            Voltage of the MCU(motor control unit)
            */
            [ResourceId(24), Operations("R"), Units("V"), Mandatory] long MCU_Voltage;

            /**
            Temperature of MCU(motor control unit)
            */
            [ResourceId(25), Operations("R"), Units("Cel"), Mandatory] long MCU_Temperature;

            /**
            Rotational speed of the motor
            */
            [ResourceId(26), Operations("R"), Units("1/min"), Mandatory] long Motor_Speed;

            /**
            Temperature of the motor
            */
            [ResourceId(27), Operations("R"), Units("Cel"), Mandatory] long Motor_Temperature;

            /**
            Whether the motor is OT or not. 0: normal 1: OT warning
            */
            [ResourceId(28), Operations("R")] bool? Motor_OT_Warning;

            /**
            Whether the MCU is OT or not. 0: normal 1: OT warning
            */
            [ResourceId(29), Operations("R")] bool? MCU_OT_Warning;

            /**
            Whether the battery pack is OT or not. 0: normal 1: OT warning
            */
            [ResourceId(30), Operations("R")] bool? Battery_Pack_OT_Warning;

            /**
            Status of MCU. 0: normal 1: level 1 minor fault 2: level 2 critical fault
            */
            [ResourceId(31), Operations("R")] bool? MCU_fault;

            /**
            Status of the battery pack. 0: normal 1: level D25 minor fault 2: level 2 critical fault
            */
            [ResourceId(32), Operations("R")] bool? Motor_Error;
        }

        // ═════════════════════════ 10245.xml: Relay Management (urn:oma:lwm2m:x:10245) ═════════════════════════
        /**
        This LWM2M Object provides a range of eNB related measurements and parameters of which several are changeable.
        Furthermore, it includes Resources to enable/disable the eNB.
        */
        class Relay_Management {
            public const ushort lwm2m_object_id          = 10245;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10245";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            This field indicates to the CCC whether or not the eNB of the CrowdBox is available for activation: AVAILABLE
            = TRUE; UNAVAILABLE = FALSE This is set by the CrowdBox itself using an algorithm specific to the use case and
            based on parameters known to the CrowdBox which may not necessarily be signalled to the network. In the
            absence of a more specific algorithm, this parameter should be set to AVAILABLE, unless a fault is detected
            which would prevent activation of the eNB, in which case it should be set to UNAVAILABLE.
            */
            [ResourceId(0), Operations("R"), Mandatory] bool eNB_Availability;

            /**
            States whether the CrowdBox GPS receiver is synchronised to GPS time or not: UNSYCHRONISED = FALSE;
            SYNCHRONISED = TRUE If more than one GPS receiver is used by the CrowdBox, then SYNCHRONISED should be
            reported only if all receivers are synchronised.
            */
            [ResourceId(1), Operations("R"), Mandatory] bool GPS_Status;

            /**
            Orientation of CrowdBox with respect to magnetic north. The reference orientation of the CrowdBox shall be the
            pointing direction of the eNB antenna(s) or, in the case of an omni-directional CrowdBox antenna, as defined
            in the accompanying product documentation.
            */
            [MinMax(-180, 180), ResourceId(2), Operations("R"), Units("deg")] short? Orientation;

            /**
            EARFCN currently used by the eNB. Highest valid value in 3GPP is currently 46589. If the requested EARFCN is
            not supported by the eNB, the response should be "Bad Request". The CrowdBox shall only apply a change of this
            resource upon execution of the "Enable eNB" command.
            */
            [ResourceId(3), Operations("RW"), Mandatory] ushort eNB_EARFCN;

            /**
            Bandwidth of the currently used eNB carrier. If the requested bandwidth is not supported by the eNB, the
            response should be "Bad Request". The CrowdBox shall only apply a change of this resource upon execution of
            the "Enable eNB" command.
            */
            [Range("5, 10, 15, 20"), ResourceId(4), Operations("RW"), Mandatory] long eNB_Bandwidth;

            /**
            EARFCN of primary cell used for the backhaul. If the requested EARFCN is not supported by the CrowdBox UE, the
            response should be "Bad Request". The CrowdBox shall only apply a change of this resource upon execution of
            the "Enable eNB" command.
            */
            [ResourceId(5), Operations("RW"), Mandatory] ushort Backhaul_Primary_EARFCN;

            /**
            EARFCN of any secondary cells used for the backhaul, in the event that carrier aggregation is being used. If
            the requested EARFCN is not supported by the CrowdBox UE, the response should be "Bad Request". The CrowdBox
            shall only apply a change of this resource upon execution of the "Enable eNB" command.
            */
            [ResourceId(6), Operations("RW"), Mandatory] ushort[,,] Backhaul_Secondary_EARFCN;

            /**
            The current measurement interval over which cumulative statistics are collected for the following resources:
            Cumulative Number of Unique Users, Cumulative Downlink Throughput per Connected User, Cumulative Uplink
            Throughput per Connected User. Note that this measurement period is a sliding window rather than a granularity
            period. Measurements should never be reset, but rather old measurements should be removed from the cumulative
            total as they fall outside of the window. A value of 0 shall be interpreted as meaning only the current value
            should be reported. A value of 65535 shall be interpreted as an infinite window size (i.e. old measurements
            are never discarded).
            */
            [ResourceId(7), Operations("RW"), Units("s"), Mandatory] ushort Cumulative_Measurement_Window;

            /**
            A 28 bit E-UTRAN Cell Identifier (ECI) (range 0..2^28-1)
            */
            [MinMax(0, 268435455), ResourceId(8), Operations("R"), Mandatory] uint eNB_ECI;

            /**
            This resource indicates the current status of the eNB and can be used by the CCC to change the state from
            enabled to disabled. TRUE = eNB enabled FALSE = eNB disabled
            */
            [ResourceId(9), Operations("RW"), Mandatory] bool eNB_Status;

            /**
            Maximum power for the eNB measured as the sum of input powers to all antenna connectors. The maximum power per
            antenna port is equal to the maximum eNB power divided by the number of antenna ports. If the requested power
            is above or below the maximum or minimum power levels of the eNB, then the power level should be set to the
            maximum or minimum respectively. The CrowdBox shall only apply a change of this resource upon execution of the
            "Enable eNB" command.
            */
            [MinMax(0, 63), ResourceId(11), Operations("RW"), Units("dBm"), Mandatory] byte eNB_Maximum_Power;

            /**
            q-OffsetFreq parameter for the backhaul primary EARFCN in SIB5 of the CrowdBox eNB BCCH. See TS 36.331 for
            details. Range: dB-24; dB-22 .. dB24 The CrowdBox shall only apply a change of this resource upon execution of
            the "Enable eNB" command.
            */
            [MinMax(-24, 24), ResourceId(12), Operations("RW"), Units("dB"), Mandatory] sbyte Backhaul_Primary_q_OffsetFreq;

            /**
            q-OffsetFreq parameter for the backhaul secondary EARFCN in SIB5 of the CrowdBox eNB BCCH. See TS 36.331 for
            details Range: dB-24; dB-22 .. dB24 The CrowdBox shall only apply a change of this resource upon execution of
            the "Enable eNB" command.
            */
            [MinMax(-24, 24), ResourceId(13), Operations("RW"), Units("dB"), Mandatory] sbyte[,,] Backhaul_Secondary_q_OffsetFreq;

            /**
            EARFCN of a neighbour CrowdBox. Each instance of this resource relates to the same instance of resource ID 15.
            */
            [MinMax(0, 66635), ResourceId(14), Operations("RW"), Mandatory] uint[,,] Neighbour_CrowdBox_EARFCN;

            /**
            q-OffsetFreq parameter of the Neighbour CrowdBox EARFCN in SIB5 of the Neighbour CrowdBox eNB BCCH. See TS
            36.331 for details Range: dB-24; dB-22 .. dB24 Each instance of this resource relates to the same instance of
            resource ID 14. The CrowdBox shall only apply a change of this resource upon execution of the "Enable eNB"
            command.
            */
            [MinMax(-24, 24), ResourceId(15), Operations("RW"), Units("dB"), Mandatory] sbyte[,,] Neighbour_CrowdBox_q_OffsetFreq;

            /**
            Specifies the value of the cellIndividualOffset parameter applicable to the CrowdBox macro serving cell that
            is to be signalled to connected UEs in their measurement configuration information . See TS 36.331 for
            details. The CrowdBox shall only apply a change of this resource upon execution of the "Enable eNB" command.
            */
            [MinMax(-24, 24), ResourceId(16), Operations("RW"), Units("dB"), Mandatory] sbyte Serving_Macro_eNB_cellIndividualOffset;

            /**
            Enables the eNB. In addition the CrowdBox shall also update its configuration to reflect the current state of
            other relevant parameters. This might require a reboot.
            Execute operation on resource 10 (Enable eNB); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E"), Mandatory] public class Enable_eNB_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10246.xml: CrowdBox Measurements (urn:oma:lwm2m:x:10246) ═════════════════════════
        /**
        This LWM2M Object provides CrowdBox-related measurements such as serving cell parameters, backhaul timing
        advance, and neighbour cell reports.
        */
        class CrowdBox_Measurements {
            public const ushort lwm2m_object_id          = 10246;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10246";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Serving cell ID as specified by the cellIdentity field broadcast in SIB1 of the serving cell (see TS 36.331).
            */
            [ResourceId(0), Operations("R"), Mandatory] uint Serving_Cell_ID;

            /**
            Serving cell RSRP, as defined in TS 36.133, Section 9.1.4. Range: RSRP_00; RSRP_01 .. RSRP_97
            */
            [MinMax(0, 97), ResourceId(1), Operations("R"), Mandatory] byte Serving_Cell_RSRP;

            /**
            Serving cell RSRQ, as defined in TS 36.133, Section 9.1.7. Range: RSRQ_-30; RSRQ_-29 .. RSRQ_46
            */
            [MinMax(-30, 46), ResourceId(2), Operations("R"), Mandatory] sbyte Serving_Cell_RSRQ;

            /**
            SINR of serving cell as estimated by the CrowdBox. Note that this is a proprietary measurement dependent on
            the UE chipset manufacturer. The UE chipset used should be stated in the accompanying product documentation.
            */
            [MinMax(-10, 30), ResourceId(3), Operations("R"), Units("dB"), Mandatory] sbyte Serving_Cell_SINR;

            /**
            The cumulative timing advance signalled by the current serving cell to the CrowdBox. This is the sum of the
            initial timing advance signalled in the MAC payload of the Random Access Response (11 bits, 0 .. 1282) and
            subsequent adjustments signalled in the MAC PDU of DL-SCH transmissions (6 bits, -31 .. 32). See TS 36.321 for
            details.
            */
            [ResourceId(4), Operations("R")] ushort? Cumulative_Backhaul_Timing_Advance;

            /**
            A link to the "Neighbour Cell Report" object for each neighbour cell of the CrowdBox.
            */
            [ResourceId(5), Operations("R"), Mandatory] ObjectLink[,,] Neighbour_Cell_Report;
        }

        // ═════════════════════════ 10247.xml: Neighbour Cell Report (urn:oma:lwm2m:x:10247) ═════════════════════════
        /**
        This LWM2M Object provides the neighbour cell report. The CrowdBox Measurements Object and the Connected UE
        Report Object have both Objlnk Resources pointing to this Object.
        */
        class Neighbour_Cell_Report {
            public const ushort lwm2m_object_id          = 10247;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10247";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Physical Cell ID of neighbouring LTE cell, as defined in TS 36.211
            */
            [MinMax(0, 503), ResourceId(0), Operations("R"), Mandatory] ushort Neighbour_PCI;

            /**
            Neighbour cell ID as specified by the cellIdentity field broadcast in SIB1 of the neighbour cell (see TS
            36.331).
            */
            [ResourceId(1), Operations("R")] uint? Neighbour_Cell_ID;

            /**
            Current neighbour cell rank. Neighbour cells should be ordered (ranked) by the CrowdBox according to neighbour
            cell RSRP, with a higher RSRP corresponding to a lower index. Hence the neighbouring cell with the highest
            RSRP should be neighbour cell 0, the second neighbour cell 1, and so on.
            */
            [ResourceId(2), Operations("R"), Mandatory] byte Neighbour_Cell_Rank;

            /**
            Neighbour cell RSRP, as defined in TS 36.133, Section 9.1.4. Range: RSRP_00; RSRP_01 .. RSRP_97
            */
            [MinMax(0, 97), ResourceId(3), Operations("R"), Mandatory] byte Neighbour_Cell_RSRP;

            /**
            Neighbour cell RSRQ, as defined in TS 36.133, Section 9.1.7. Range: RSRQ_-30; RSRQ_-29 .. RSRQ_46
            */
            [MinMax(-30, 46), ResourceId(4), Operations("R"), Mandatory] sbyte Neighbour_Cell_RSRQ;
        }

        // ═════════════════════════ 10248.xml: Connected UE Measurements (urn:oma:lwm2m:x:10248) ═════════════════════════
        /**
        This LWM2M Object provides a range of measurements of connected UEs and provides an Object link to the
        Connected UE report.
        */
        class Connected_UE_Measurements {
            public const ushort lwm2m_object_id          = 10248;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10248";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            The number of different UEs currently connected to the eNB (i.e. in RRC_CONNECTED state).
            */
            [ResourceId(0), Operations("R"), Mandatory] byte Number_of_Connected_Users;

            /**
            The number of different UEs that have connected to the eNB over the immediately preceding period specified by
            the "Cumulative Measurement Window" field.
            */
            [ResourceId(1), Operations("R"), Mandatory] ushort Cumulative_Number_of_Unique_Users;

            /**
            Provides an Object link to the Connected UE Report which provides a range of information related to the
            connected UEs.
            */
            [ResourceId(2), Operations("R"), Mandatory] ObjectLink[,,] Connected_UE_Report;
        }

        // ═════════════════════════ 10249.xml: Connected UE Report (urn:oma:lwm2m:x:10249) ═════════════════════════
        /**
        This LWM2M Object provides a range of information related to the connected UEs.
        */
        class Connected_UE_Report {
            public const ushort lwm2m_object_id          = 10249;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10249";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            MMEC signalled by the UE to the eNB in the RRCConnectionRequest message (see TS 36.331).
            */
            [ResourceId(0), Operations("R"), Mandatory] byte Connected_User_MMEC;

            /**
            M-TMSI signalled by the UE to the eNB in the RRCConnectionRequest message (see TS 36.331).
            */
            [ResourceId(1), Operations("R"), Mandatory] uint Connected_User_M_TMSI;

            /**
            The RSRP of the CrowdBox eNB, as defined in TS 36.133, Section 9.1.4. Range: RSRP_00; RSRP_01 .. RSRP_97
            */
            [MinMax(0, 97), ResourceId(2), Operations("R"), Mandatory] byte Serving_Cell_CrowdBox_eNB_RSRP;

            /**
            The RSRQ of the CrowdBox eNB, as defined in TS 36.133, Section 9.1.7. Range: RSRQ_-30; RSRQ_-29 .. RSRQ_46
            */
            [MinMax(-30, 46), ResourceId(3), Operations("R"), Mandatory] sbyte Serving_Cell_CrowdBox_eNB_RSRQ;

            /**
            The cumulative timing advance signalled by the eNB to each currently connected UE. This is the sum of the
            initial timing advance signalled in the MAC payload of the Random Access Response (11 bits, 0 .. 1282) and
            subsequent adjustments signalled in the MAC PDU of DL-SCH transmissions (6 bits, -31 .. 32). See TS 36.321 for
            details.
            */
            [ResourceId(4), Operations("R")] ushort? Cumulative_Timing_Advance_per_Connected_User;

            /**
            The last downlink wideband CQI reported by a connected user the eNB. The CQI format is defined in Table
            7.2.3-1 of TS 36.213.
            */
            [ResourceId(5), Operations("R"), Mandatory] byte Last_downlink_CQI_report_per_Connected_User;

            /**
            The total number of MAC bytes sent to the connected user over the immediately preceding period specified by
            the "Cumulative Measurement Window" field. A 32 bit value with range 0..2^32-1.
            */
            [ResourceId(6), Operations("R"), Units("B"), Mandatory] uint Cumulative_Downlink_Throughput_per_Connected_User;

            /**
            The total number of MAC bytes received from the connected user over the immediately preceding period specified
            by the "Cumulative Measurement Window" field. A 32 bit value with range 0..2^32-1.
            */
            [ResourceId(7), Operations("R"), Units("B"), Mandatory] uint Cumulative_Uplink_Throughput_per_Connected_User;

            /**
            A link to the "Neighbour Cell Report" object for each neighbour cell reported to the CrowdBox by the connected
            UE
            */
            [ResourceId(8), Operations("R"), Mandatory] ObjectLink[,,] Neighbour_Cell_Report;
        }

        // ═════════════════════════ 10250.xml: App Data Container (urn:oma:lwm2m:x:10250) ═════════════════════════
        /**
        This LWM2M Object is used for reporting application data of a device.
        */
        class App_Data_Container {
            public const ushort lwm2m_object_id          = 10250;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10250";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Uplink application data, e.g. gas meter reporting data.
            */
            [D(65535), ResourceId(0), Operations("R"), Mandatory] Binary[,,] UL_data;

            /**
            Downlink application data, e.g. application response message of uplink data.
            */
            [D(65535), ResourceId(1), Operations("W"), Mandatory] Binary[,,] DL_data;
        }

        // ═════════════════════════ 10251.xml: AT Command (urn:oma:lwm2m:x:10251) ═════════════════════════
        /**
        Used to execute an AT command on a cellular modem
        */
        class AT_Command {
            public const ushort lwm2m_object_id          = 10251;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10251";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The AT command to run. Example: AT+CREG? to query registration status
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Command;

            /**
            Response to the AT command. Example: +CREG:0,5 If multiple lines are returned as the modem response, each line
            will be returned in a separate resource.
            */
            [ResourceId(1), Operations("R"), Mandatory] string[,,] Response;

            /**
            Status of the command execution as returned by the modem. Typical values:OK ERROR
            */
            [ResourceId(2), Operations("R"), Mandatory] string[,,] Status;

            /**
            Amount of time in seconds allowed for the modem to respond to the command.
            */
            [ResourceId(3), Operations("RW")] DurationInSeconds? Timeout;

            /**
            Executing this resource will cause the command to be sent to the modem. And the result to be populated using
            the Response (1) and Status (2) resources
            Execute operation on resource 4 (Run); sent by the Server to the Client.
            */
            [ResourceId(4), Operations("E"), Mandatory] public class Run_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10252.xml: Manifest (urn:oma:lwm2m:x:10252) ═════════════════════════
        /**
        This object provides a range of information related to updating packages on a device
        */
        class Manifest {
            public const ushort lwm2m_object_id          = 10252;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10252";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Content of a new manifest
            */
            [D(65535), ResourceId(1), Operations("W"), Mandatory] Binary[,,] Manifest_1;

            /**
            Current state of manifest processing
            0.	Uninitialised
            1.	Idle
            2.	Processing manifest
            3.	Awaiting download approval
            4.	Downloading
            5.	Downloaded
            6.	Awaiting application approval
            7.	Updating
            8.	Rebooting
            */
            [MinMax(0, 8), ResourceId(2), Operations("R"), Mandatory] byte State;

            /**
            Final result of the device processing a manifest.
            0.	Uninitialised
            1.	Success
            2.	Manifest timeout. The Manifest URI has timed-out.
            3.	Manifest not found. The Manifest URI not found.
            4.	Manifest failed integrity check. The manifest integrity check failed.
            5.	Manifest rejected. The Manifest attributes do not apply to this device.
            6.	Manifest certificate not found
            7.	Manifest signature failed. The Manifest signature is not recognised by this device.
            8.	Dependent manifest not found
            9.	Not enough storage for the new asset
            10.	Out of memory during download process
            11.	Connection lost during download process
            12.	Asset failed integrity check
            13.	Unsupported asset type
            14.	Invalid asset URI
            15.	Timed out downloading asset
            16.	Unsupported delta format
            17.	Unsupported encryption format
            18.	Asset update successfully completed
            19.	Asset updated successfully after recovery
            */
            [MinMax(0, 19), ResourceId(3), Operations("R"), Mandatory] byte Manifest_Result;

            /**
            Contains payload-specific errors or output.
            */
            [D(65535), ResourceId(4), Operations("R"), Mandatory] Binary[,,] Payload_Result;

            /**
            Hash of the installed asset.
            */
            [D(65535), ResourceId(5), Operations("R"), Mandatory] Binary[,,] Asset_Hash;

            /**
            Version of the current manifest.
            */
            [ResourceId(6), Operations("R"), Mandatory] long Manifest_version;

            /**
            Progress update of the asset installation process (in bytes).
            */
            [ResourceId(7), Operations("R"), Mandatory] long Asset_Installation_Progress;

            /**
            Id of campaign affecting this device. There currently isn’t any logic on the server or the client to handle
            this.
            */
            [ResourceId(8), Operations("RW"), Mandatory] string Campaign_Id;

            /**
            Manually apply the asset update. This will only have effect if the manifest requires this. The state resource
            must also be in the downloaded state for the execute command to be actioned.
            Execute operation on resource 9 (Manual Trigger); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E"), Mandatory] public class Manual_Trigger_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10253.xml: Confidential Data (urn:oma:lwm2m:x:10253) ═════════════════════════
        /**
