            Payload Resource. As an example, the Argument List to retrieve data from Midnight 2nd March (UTC+10) to
            Midnight 6rd March (UTC+10) for a specific instance of the interval data object, would be constructed as
            follows:- 0='1488463200',1='1488808800'
            Execute operation on resource 6008 (Interval Historical Read); sent by the Server to the Client.
            */
            [ResourceId(6008), Operations("E")] public class Interval_Historical_Read_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Change Interval Configuration is an executable resource designed to allow the Interval Period, Interval Start
            Offset and Interval UTC Offset to be reconfigured. The resource takes three arguments:- Argument 0:
            [Mandatory] Interval Period represented as an integer as defined in the Interval Period Resource. Argument 1:
            [Optional] Interval start offset represented as an integer as defined in the Interval Start Offset Resource.
            If not provided, leave the value as per the current configuration Argument 2: [Optional] Interval UTC offset
            represented as a String as defined in the Interval UTC Offset Resource. If not provided, leave the value as
            per the current configuration. Depending on the specifics of the implementation of this object, reconfiguring
            the Interval data object may result in the removal of all historical data for this Interval Data Object
            Instance. Please consult with your device vendor as to the implications of reconfiguring an Interval Data
            Object Instance. As an example, the Argument List to change an interval data object instance from its existing
            values to one hour intervals, midnight aligned in UTC+10 time zone:- 0='3600',1='0',1='UTC+10'
            Execute operation on resource 6010 (Interval Change Configuration); sent by the Server to the Client.
            */
            [ResourceId(6010), Operations("E")] public class Interval_Change_Configuration_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Start is an executable resource that enables the recording of interval data. The first interval recorded will
            have a timestamp based on the Interval Start Offset resource. This executable resource takes no arguments.
            Refer to re-usable resource LogStart for further details.
            Execute operation on resource 6026 (Start); sent by the Server to the Client.
            */
            [ResourceId(6026), Operations("E")] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stop (LogStop) is an executable resource that disables the recording of interval data for this object
            instance. This executable resource takes no arguments. Refer to re-usable resource LogStop for further
            details.
            Execute operation on resource 6027 (Stop); sent by the Server to the Client.
            */
            [ResourceId(6027), Operations("E")] public class Stop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10299.xml: HostDevice (urn:oma:lwm2m:x:10299) ═════════════════════════
        /**
        This LWM2M Object provides a range of host device related information which can be queried by the LWM2M
        Server. The host device is any integrated device with an embedded cellular radio module.
        */
        class HostDevice {
            public const ushort lwm2m_object_id          = 10299;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10299";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Host device manufacturers name (OEM).
            */
            [ResourceId(0), Operations("R"), Mandatory] string Manufacturer;

            /**
            Identifier of the model name or number determined by device manufacturer.
            */
            [ResourceId(1), Operations("R"), Mandatory] string Model;

            /**
            Unique ID assigned by an manufacturer or other body. Used to uniquely identify a host device. Examples include
            serial # or UUID.
            */
            [ResourceId(2), Operations("R"), Mandatory] string UniqueID;

            /**
            Current Firmware version of the host device. (manufacturer specified string).
            */
            [ResourceId(3), Operations("R"), Mandatory] string FirmwareVersion;

            /**
            Current software version of the host device. (manufacturer specified string).
            */
            [ResourceId(4), Operations("R")] string SoftwareVersion;

            /**
            Current hardware version of the host device. (manufacturer specified string).
            */
            [ResourceId(5), Operations("R")] string HardwareVersion;

            /**
            UTC value of the time and date of the last Firmware or Software update. Format:MM:DD:YYYY HH:MM:SS
            */
            [ResourceId(6), Operations("R")] string DateStamp;
        }

        // ═════════════════════════ 10300.xml: LWM2M Meta Object (urn:oma:lwm2m:x:10300) ═════════════════════════
        /**
        Use this meta object to provide one or more locations hosting XML data
        model definitions for reusable or private and vendor-specific devices,
        such as those in the range 26241-42768.
        */
        class LWM2M_Meta_Object {
            public const ushort lwm2m_object_id          = 10300;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10300";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Object ID of the vendor-specific object. If a finer granularity is
            needed to identify the object (for example, Object IDs in the range
            26241 - 32768), the optional ObjectInstanceHandle resource can also be
            used.
            */
            [ResourceId(0), Operations("R"), Mandatory] long ObjectID;

            /**
            Object URN of the vendor-specific object. URN-equivalence resolution
            must conform to Section 3 of RFC 8141.
            */
            [ResourceId(1), Operations("R"), Mandatory] string ObjectURN;

            /**
            The object link is used to refer an Instance of a given Object. An Object link value is composed of two
            concatenated 16-bit unsigned integers following the Network Byte Order convention. The Most Significant
            Halfword is an Object ID, the Least Significant Halfword is an Object Instance ID. An Object Link referencing
            no Object Instance will contain the concatenation of 2 MAX-ID values.
            */
            [ResourceId(4000), Operations("R")] ObjectLink? ObjectInstanceHandle;

            /**
            The full URI of the XML file containing the object definition of the
            vendor-specfic object. The URI must contain the scheme and authority
            components, and the URI syntax must conform to RFC 3986. If several
            alternative locations exist for the XML definition, multiple instances
            can be used, with each instance containing a single URI. In such
            cases, the URI selection is implementation-specific.
            */
            [ResourceId(2), Operations("R"), Mandatory] string[,,] URI;

            /**
            The Secure Hash Algorithm used to compute the message digest for the
            XML file in the URL(s). Currently defined values are "0" (no checksum
            used), "1" (for SHA224), "2" (for SHA256), "3" (for SHA384), "4" (for
            SHA512), "5" (SHA3-224), "6" (for SHA3-256), "7" (for SHA3-384) and
            "8" (for SHA3-512).
            */
            [MinMax(0, 8), ResourceId(3), Operations("R")] byte? SHAType;

            /**
            If the SHAType value is "0" then this string must be ignored. If the
            SHAType value is 1-8, this field contains a hexadecimal encoded
            checksum value based on the SHA function used. Valid characters for
            the string are: 0123456789abcdef. The length of the string must
            correspond exactly to the respective digest. Otherwise, the value must
            be ignored and no SHA computation should be performed. For instance, a
            file containing "foo" as its content would have the following value
            for SHAType 1 (SHA224) as a 56 character string representing 224 bits:
            e7d5e36e8d470c3e5103fedd2e4f2aa5c30ab27f6629bdc3286f9dd2
            */
            [ResourceId(4), Operations("R")] string ChecksumValue;
        }

        // ═════════════════════════ 10308.xml: AT&T Connectivity Extension (urn:oma:lwm2m:x:10308:2.0) ═════════════════════════
        /**
        The AT&amp;T Connectivity Extension Object will be used to gather information describing the UE and the
        operating state of the UE. The AT&amp;T Connectivity Extension Object is an open and standard object used by
        AT&amp;T.
        */
        class AT_T_Connectivity_Extension {
            public const ushort lwm2m_object_id          = 10308;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10308:2.0";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "2.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            T he ICCID resource is used to identify the UICC used by the IoT device or module for authentication by the
            network. Reference ITU-T recommendation E.118
            */
            [ResourceId(1), Operations("R"), Mandatory] string ICCID;

            /**
            The IMSI resource is used to log the IMSI used by the UE to identify itself to the network. The IMSI is
            defined in 3GPP TS 23.003 and is a combination of MCC (Mobile Country Code), MNC (Mobile Network Code), and
            MSIN (Mobile Subscriber Identification Number).
            */
            [ResourceId(2), Operations("R"), Mandatory] string IMSI;

            /**
            The MSISDN resource will indicate the MSISDN as assigned, if any, to the SIM card. In the case that no MSISDN
            is assigned to the SIM card the response should be zero.
            */
            [ResourceId(3), Operations("RW"), Mandatory] string MSISDN;

            /**
            The APN Retry multi instance resource will maintain the number of retries the device can attempt to activate a
            context on a particular APN. This resource should be defaulted to 2 retries. Should a device integrator wish
            to manipulate this the integrator should be able to do so.
            */
            [ResourceId(4), Operations("RW"), Mandatory] long APN_Retries;

            /**
            The APN retry period multi instance resource is the time in seconds between attempting a context activation on
            the APN. This should be defaulted to 0. Note that the IoT Module will be limited by the number retries and the
            periodicity of the retries by the DAM requirements in Chapter 28 of the AT&amp;T 13340. The resource is
            multi-instance to accommodate different periods of retries on different APNs.
            */
            [ResourceId(5), Operations("RW"), Units("s"), Mandatory] DurationInSeconds APN_Retry_Period;

            /**
            The APN Retry Back-Off Period is the period between a burst of attempts to activate a context on a particular
            APN. This resource is intended to be a longer period than the APN retry period to account for limitations on
            the numbers of times an authentication request can be made with the network. This should be defaulted to 86400
            seconds (1 Day). This resource is also a multiple instance resource to accommodate different retry periods
            amongst different APNs.
            */
            [ResourceId(6), Operations("RW"), Units("s"), Mandatory] DurationInSeconds APN_Retry_Back_Off_Period;

            /**
            This is the signal to noise ratio resource. This measurement should be measured over 10 sampled at a 400ms
            sample rate. Once the 10 samples are averaged the measurement should be reflected in the Signal to Noise Ratio
            resource. Reference: 3GPP TS 38.215, clause 5.1.
            */
            [Range("<7 to >12.5"), ResourceId(7), Operations("R"), Mandatory] long SINR;

            /**
            This resource indicates the cell selection receive value. See definition in 3GPP TS 36.304.
            */
            [ResourceId(8), Operations("R"), Mandatory] long SRXLEV;

            /**
            This resource indicates the Coverage Enhancement Level defined for LTE-M and NB-IoT. The Coverage Enhancement
            Level is on a range from 0-2. AT&amp;T NB-IoT supports CE MODE A and B (CE LEVEL 0,1,2) and AT&amp;T LTE-M
            supports CE MODE A (CE Level 0,1).
            */
            [Range("0,1,2"), ResourceId(9), Operations("R"), Mandatory] long CE_LEVEL;
        }

        // ═════════════════════════ 10309.xml: Shareparkinglot (urn:oma:lwm2m:x:10309) ═════════════════════════
        /**
        This LwM2M Object provides the keying material of our technology product-ShareParkingLock.
        */
        class Shareparkinglot {
            public const ushort lwm2m_object_id          = 10309;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10309";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Unique ID of the lock.
            */
            [ResourceId(1), Operations("R"), Mandatory] long LockID;

            /**
            Type of the lock.
            */
            [ResourceId(2), Operations("R")] string LockType;

            /**
            Infra-red sensor switch state.
            */
            [ResourceId(3), Operations("R")] bool[,,] LightSwitchState;

            /**
            Radio Received Signal Strength Indicator.
            */
            [Range("-30..-120"), ResourceId(4), Operations("R"), Units("dBm"), Mandatory] long[,,] RSSI;

            /**
            Current battery capacity in percentage Energy Level (EL).
            */
            [Range("0..100"), ResourceId(5), Operations("R"), Units("%EL")] double[,,] BatteryCapacity;

            /**
