        // ═════════════════════════ 10371.xml: Reboot Status (urn:oma:lwm2m:x:10371) ═════════════════════════
        /**
        This object provides features allowing to monitor Reboot and Reset Factory operation from LWM2M Device object.
        This LWM2M object provides features to monitor Reboot(/3/0/4) and Reset Factory(/3/0/5) operation available on
        LWM2M Device (3) Object, allowing to know if a reboot or a reset factory is a success or a failure and why it
        failed. This is strongly recommended to use separated response for those resources (/3/0/4 and /3/0/5) and
        wait for response ACK before to execute/schedule the operation (reboot or reset factory). This prevents LWM2M
        server to consider the request as a failure in case response is lost. This situation could be annoying as
        server could decide to resent the request later which could bring to unexpected reboot or reset factory.
        */
        class Reboot_Status {
            public const ushort lwm2m_object_id          = 10371;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10371";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Containing the state of reboot operation. At device start-up the value should be 0 (booted). Once a reboot
            process is scheduled (e.g. exec on /3/0/4), this value must be set to 1 (rebooting), it is adviced to do that
            before to send response of Reboot resource (/3/0/4) to avoid any race conditions. If rebooting failed for any
            reason value must be set to 2(reboot error). If reboot succeeds, at device start up, reboot state should be
            set to 0 (booted) as always.
            */
            [MinMax(0, 2), ResourceId(0), Operations("R"), Mandatory] byte Reboot_State;

            /**
            Containing the error message of the last reboot failure. This value MUST be set to an empty string on exec on
            /3/0/4, ideally before to send the response for Reboot resource (3/0/4) to avoid any race conditions
            */
            [ResourceId(1), Operations("R"), Mandatory] string Reboot_Error_Message;

            /**
            Containing the state of reset factory operation. At start-up the value should be 0 (initial-state). Once the
            reset factory process is scheduled (exec on /3/O/5), this value must be set to 1 (resetting), it is advised to
            do that before to send response of Reset Factory resource (/3/0/5) to avoid any race conditions. If reset
            fails for any reason value must be set to 2 (reset error). If reset succeeds, state should be set to 3
            (reset). If the reset factory need a reboot, reboot state(/10371/0/0) resource SHOULD also be updated
            accordingly. If reset factory need a reboot, in case of successful reset, the value MUST be set to 3 (reset)
            at device start-up. If it helps implementation, this is tolerated to have this resource set to 3 (reset) at
            first device start-up.
            */
            [MinMax(0, 3), ResourceId(2), Operations("R")] byte? Reset_Factory_State;

            /**
            Containing the error message of the last reset factory failure. This value MUST be set to an empty string on
            exec on /3/0/5, ideally before to send the response for Reset Factory resource (3/0/5) to avoid any race
            conditions
            */
            [ResourceId(3), Operations("R")] string Reset_Factory_Error_Message;
        }

        // ═════════════════════════ 10374.xml: Modbus Connection (urn:oma:lwm2m:x:10374) ═════════════════════════
        /**
        This LwM2M Object is used to configure a Modbus protocol connection.
        */
        class Modbus_Connection {
            public const ushort lwm2m_object_id          = 10374;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10374";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Address uniquely defining the Modbus connection within a given physical layer. The LwM2M Client is assumed to
            take the role of a Modbus client.
            For Modbus TCP, this is a hostname with optional port number, e.g. "10.11.12.13" or "example.com:502". Port
            number 502 is the default if not specified.
            For Modbus RTU, this is an implementation-defined unique identifier of a physical port. Suggested formats are
            UNIX-style device names (e.g. "/dev/tty1") or DOS-style port designations (e.g. "COM2"), but any strings may
            be used. Values that are valid for this LwM2M Client are listed in the "Available RTU ports" resource. The
            Client MAY treat configuration as invalid if Physical Layer Type is set to Modbus RTU and the Address is not
            equal to any of the "Available RTU ports".
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Address;

            /**
            Type of the physical layer to use for this connection.
            0: Modbus TCP
            1: Modbus RTU (RS-232)
            2: Modbus RTU (RS-485)
            Additional types MAY be specified in future revisions of this object.
            */
            [MinMax(0, 2), ResourceId(1), Operations("RW"), Mandatory] byte Physical_Layer_Type;

            /**
            Enables or disables this Modbus connection.
            When set to false, this Modbus connection is administratively disabled and shall not function. Upon setting it
            to true, the LwM2M Client shall attempt opening the relevant connection and report the result of that
            operation in the "State" resource.
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool Enable;

            /**
            Baudrate for the RTU link layer, e.g. 9600, 115200, etc.
            NOTE: 8 data bits are always used.
            Mandatory if Physical Layer Type is set to Modbus RTU.
            */
            [ResourceId(3), Operations("RW"), Units("bit/s")] long? Baudrate;

            /**
            Number of stop bits to use for the RTU link layer.
            Mandatory if Physical Layer Type is set to Modbus RTU.
            */
            [MinMax(1, 2), ResourceId(4), Operations("RW")] byte? Stop_Bits;

            /**
            Parity bit type to use for the RTU link layer.
            0: none
            1: even
            2: odd
            Mandatory if Physical Layer Type is set to Modbus RTU.
            */
            [MinMax(0, 2), ResourceId(5), Operations("RW")] byte? Parity;

            /**
            Type of hardware flow control to use for the RTU link layer.
            0: none
            1: Set RTS flag when sending data
            2: Set RTS flag when NOT sending data
            Mandatory if Physical Layer Type is set to Modbus RTU.
            */
            [MinMax(0, 2), ResourceId(6), Operations("RW")] byte? Hardware_Control_Flow_Mode;

            /**
            List of all valid values for the "Address" resource when Physical Layer Type is set to Modbus RTU. The
            Resource Instance IDs shall have no semantic meaning. The value of this resource shall be equal for all
            instances of this Object.
            Mandatory if this LwM2M Client has at least one physical port usable for Modbus RTU.
            */
            [ResourceId(7), Operations("R")] string[,,] Available_RTU_Ports;

            /**
            State of this Modbus connection.
            0: disabled (MUST NOT be used unless the "Enable" resource is set to false)
            1: connecting
            2: successfully connected
            3: invalid or unsupported configuration
            4: connection error
            If this resource reached the "connection error" state after having been successfully connected previously, the
            LwM2M Client SHOULD apply an implementation-specific deferred retry policy to try establishing the connection
            again.
            If the resource reached the "connection error" state as a direct result of setting the "Enable" resource to
            true or changing the configuration while in the enabled state, the LwM2M Client MAY apply an
            implementation-specific deferred retry policy to try establishing the connection again, or it MAY stay in the
            "connection error" state until further reconfiguration by the LwM2M Server.
            NOTE: The "connection error" state corresponds to any non-specific failure case. More specific error cases MAY
            be specified in future revisions of this object. LwM2M Server SHOULD interpret any unknown or invalid value
            reported by the LwM2M Client as equivalent to "connection error".
            */
            [MinMax(0, 4), ResourceId(8), Operations("R"), Mandatory] byte State;
        }

        // ═════════════════════════ 10375.xml: Modbus Register Cluster (urn:oma:lwm2m:x:10375) ═════════════════════════
        /**
        This LwM2M Object represents a set of Modbus registers and acts as an interface to read and write their
        values.
        */
        class Modbus_Register_Cluster {
            public const ushort lwm2m_object_id          = 10375;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10375";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Link to an instance of the "Modbus Connection" object to use.
            */
            [ResourceId(0), Operations("RW"), Mandatory] ObjectLink Connection;

            /**
            Type of Modbus objects to access.
            1: Coil
            2: Discrete Input
            3: Holding Register
            4: Input Register
            Note: For convenience, the values are equal to function codes corresponding to Modbus "read" operations for
            each object type.
            */
            [MinMax(1, 4), ResourceId(1), Operations("RW"), Mandatory] byte Register_Type;

            /**
            Server unit ID that this register cluster addresses.
            Special non-significant value of 255 is valid only for Modbus TCP connections.
            */
            [Range("0..247, 255"), ResourceId(2), Operations("RW"), Mandatory] long Unit_ID;

            /**
            Address of the first register that this register cluster addresses.
            */
            [ResourceId(3), Operations("RW"), Mandatory] ushort Starting_Register_Address;

            /**
            Number of registers in this register cluster.
            If the Register Type is Holding Register or Input Register, the valid range for this resource is 1..125.
            Larger values are only supported for Coils and Discrete Inputs.
            If this resource is not present, the default value of 1 is assumed.
            */
            [MinMax(1, 2000), ResourceId(4), Operations("RW")] ushort? Quantity_of_Registers;

            /**
            List of values of the registers addressed by this register cluster.
            The Resource Instance IDs shall range from 0 to "Quantity of Registers - 1" (note: absolute register address
            cannot be used, because 65535 is a valid Modbus register ID, but not a valid LwM2M Resource Instance ID).
            When the Register Type is Coil or Discrete Input, "0" and "1" are the only valid values for each of the
            Resource Instances.
            When the Register Type is Discrete Input or Input Register, this resource shall behave as a read-only
            resource, i.e. as if the "Operations" attribute was "R".
            Even if the Register Type is Coil or Holding Register, any write operation that would result in the set of
            valid Resource Instance IDs being changed, shall result in a Bad Request error.
            */
            [ResourceId(5), Operations("RW"), Mandatory] ushort[,,] Values;

            /**
            Minimum values recorded by each of the registers in this cluster.
            If this resource is supported, the Resource Instance IDs shall range from 0 to "Quantity of Registers - 1".
            Each Resource Instance shall hold the minimum value recorded by the corresponding Resource Instance of the
            "Values" resource since the configuration of this cluster (resources 0-4) has been last changed, or since the
            "Reset Minimum and Maximum Measured Values" resource has been last executed, whichever was later.
            */
            [ResourceId(6), Operations("R")] ushort[,,] Minimum_Measured_Values;

            /**
            Maximum values recorded by each of the registers in this cluster.
            If this resource is supported, the Resource Instance IDs shall range from 0 to "Quantity of Registers - 1".
            Each Resource Instance shall hold the maximum value recorded by the corresponding Resource Instance of the
            "Values" resource since the configuration of this cluster (resources 0-4) has been last changed, or since the
            "Reset Minimum and Maximum Measured Values" resource has been last executed, whichever was later.
            */
            [ResourceId(7), Operations("R")] ushort[,,] Maximum_Measured_Values;

            /**
            Resets the "Minimum Measured Values" and "Maximum Measured Values" resources.
            Execute operation on resource 8 (Reset Minimum and Maximum Measured Values); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E")] public class Reset_Minimum_and_Maximum_Measured_Values_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10376.xml: Periodic Activity (urn:oma:lwm2m:x:10376) ═════════════════════════
        /**
        Generic interface to set up periodic activity like hourly sensor reading/load activation and mechanism to
        retrieve the periodic data.
        */
        class Periodic_Activity {
            public const ushort lwm2m_object_id          = 10376;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10376";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource represents activity's name declared by device. It cannot be modified externally. Device can
            support multiple activities by declaring multiple instances of Periodic Activity object.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Activity_Name;

            /**
            This resource describes activity's operation including its supported options and data returned.
            */
            [ResourceId(1), Operations("R"), Mandatory] string Activity_Description;

            /**
            This resource allows activity to accept settings or input parameters when run. The available settings, if
            supported, should be described using Activity Description resource.
            */
            [D(65535), ResourceId(2), Operations("RW")] Binary[,,] Activity_Settings;

            /**
            This resource defines when to start the periodic activity. Start Mask needs to adhere to following string
            format:
            "YYMMDDHHmmss"
            YY: year, e.g 21
            MM: month, 01 to 12
            DD: day, 01 to 31
            HH: hour, 00 to 23
            mm: minute, 00 to 59
            ss: second, 00 to 59
            Any of the above can be replaced by character '-' for "don't care" masking.
            Example:
            1) "211027201801" the periodic activity will start at exactly 20:18:01 on 2021/10/27.
            2) "------201801" the periodic activity will start at the next 20:18:01.
            3) "------------" the periodic activity will start immediately.
            4) "------20--00" the periodic activity will start between 8pm to 8.59pm at exactly 00 seconds.
            5) "------01000000" the periodic activity will start at next 1st of the month at 12am.
            Start Mask is adjusted to UTC offset provided by Device [/3/0/14] object instance resource, or adjusted to UTC
            if the resource is not provided.
            */
            [ResourceId(3), Operations("RW"), Mandatory] string Start_Mask;

            /**
            This resource represents the time interval between the run of consecutive activities. The next activity will
            run after Periodic Interval resource value has elapsed.
            */
            [ResourceId(4), Operations("RW"), Units("s"), Mandatory] DurationInSeconds Periodic_Interval;

            /**
            This resource defines the period to run this periodic activity. Periodic activity will stop when the Run
            Period has elapsed from the start time. Depending on the Start Mask's "don't care" field, this periodic
            activity may re-start again.
            */
            [ResourceId(5), Operations("RW"), Units("s")] DurationInSeconds? Run_Period;

            /**
            Record resource enable the accumulation of returned data (if any) when the activity is run/called. The
            accumulated data or records is represented by a read-only serialized Opaque (Binary) value.
            The number of records available in this serialized resource can be calculated by Record Head Index - Record
            Current Read Index. Nevertheless, the number of records serialized is limited by device's memory allocation.
            After successful record read (manual read, observation or dispatch), device will increment Record Current Read
            Index as per how many already read.
            The record use CBOR format encoded as following:
            1. array(Record Index 1, Record Timestamp 1, Record Value 1)
            2. array(Record Index 2, Record Timestamp 2, Record Value 2)
            ...
            n. array(Record Index n, Record Timestamp n, Record Value n)
            Record Timestamp is a 32-bit integer representing the number of seconds since Jan 1st, 1970 in the UTC time
            zone. Record Value can be any type and described by CBOR type. Value can also be an array of sub-values.
            */
            [D(65535), ResourceId(6), Operations("R")] Binary[,,] Record;

            /**
            This resource represents the index of the latest record. This index is incremented upon every new activity's
            record. Total recordings inside the device can be calculated by Record Head Index - Record Tail Index.
            */
            [ResourceId(7), Operations("R")] long? Record_Head_Index;

            /**
            This resource represents the index of the oldest record stored in device. This index is adjusted (incremented)
            by device based on its memory space availability.
            */
            [ResourceId(8), Operations("R")] long? Record_Tail_Index;

            /**
            This resource represents the index of the last read record. Device will increment this index upon successful
            record delivery to server (via manual read or scheduled dispatch). Server may modify this index to traverse
            within available records in device.
            */
            [ResourceId(9), Operations("RW")] long? Record_Read_Index;

            /**
            This resource represents the start time to deliver Record resource. If Record resource is currently being
            observed, this resource enables accumulation of the Record changes before being dispatch (rather than
            delivering Record immediately as it changes). As per Start Mask, Dispatch Start Mask must adhere to following
            string format:
            "YYMMDDHHmmss".
            Dispatch Start Mask is adjusted to UTC offset provided by Device [/3/0/14] object instance resource, or
            adjusted to UTC if the resource is not provided.
            If this resource is used together with Dispatch Interval resource, it is possible to automatically deliver
            Record resource at specific time. For example, dispatch accumulated record every 6 hours, at minute 5 (00:05,
            06:05, 12:05, 18:05).
            */
            [ResourceId(10), Operations("RW")] string Record_Dispatch_Start_Mask;

            /**
            This resource represents the time interval between consecutive automatic Record dispatch. The next dispatch
            will run after Record Dispatch Interval resource value has elapsed.
            */
            [ResourceId(11), Operations("RW"), Units("s")] DurationInSeconds? Record_Dispatch_Interval;
        }

        // ═════════════════════════ 10377.xml: Data Monitoring (urn:oma:lwm2m:x:10377) ═════════════════════════
        /**
        Generic interface to set up data monitoring like sensor/log data and mechanism to receive alerts.
        */
        class Data_Monitoring {
            public const ushort lwm2m_object_id          = 10377;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10377";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            This resource is the Data Monitoring operation's name or string reference declared by device. It cannot be
            modified externally. Device can support multiple monitoring operation by declaring multiple instances of Data
            Monitoring object.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Monitoring_Name;

            /**
            This resource describes the monitoring operation including data type and supported settings/options, if any.
            */
            [ResourceId(1), Operations("R"), Mandatory] string Monitoring_Description;

            /**
            This resource allows the monitoring operation to accept settings or operation options. The available settings,
            if supported, should be described using Monitoring Description resource.
            */
            [D(65535), ResourceId(2), Operations("RW")] Binary[,,] Monitoring_Settings;

            /**
            This resource contains the current value of actual data being monitored/sampled in device. The data and data
            type is formatted as CBOR payload.
            */
            [D(65535), ResourceId(3), Operations("R"), Mandatory] Binary[,,] Data;

            /**
            This resource defines when to start data sampling. Data Sampling Start Mask needs to adhere to following
            string format:
            "YYMMDDHHmmss"
            YY: year, e.g 21
            MM: month, 01 to 12
            DD: day, 01 to 31
            HH: hour, 00 to 23
            mm: minute, 00 to 59
            ss: second, 00 to 59
            Any of the above can be replaced by character '-' for "don't care" masking.
            Example:
            1) "211027201801" data sampling will start at exactly 20:18:01 on 2021/10/27.
            2) "------201801" data sampling will start at the next 20:18:01.
            3) "------------" data sampling will start immediately.
            4) "------01000000" data sampling will start at next 1st of the month at 12am.
            If this resource is not present, data sampling starts at device's specific implementation.
            */
            [ResourceId(4), Operations("RW")] string Data_Sampling_Start_Mask;

            /**
            This resource represents the time interval between consecutive data samplings. After the sampling starts (via
            the start mask, if present), the next sampling will run after Data Sampling Interval resource value has
            elapsed.
            If this resource is not present, data sampling occurs at device's specific implementation.
            */
            [ResourceId(5), Operations("RW"), Units("s")] DurationInSeconds? Data_Sampling_Interval;

            /**
            This resource defines the period to run this data sampling. Data Sampling will stop when the Run Period has
            elapsed from the start time. Depending on the Data Sampling Start Mask's "don't care" field, sampling may
            re-start again.
            */
            [ResourceId(6), Operations("RW"), Units("s")] DurationInSeconds? Data_Sampling_Run_Period;

            /**
            This resource contains the value of reference data that is to be compared with Data resource in conjunction
            with Comparison A resource. The comparison result is flagged by Status resource. When Status resource is made
            observable, this effectively becomes a mechanism to signal the server on a hit. The reference data and data
            type is formatted as CBOR payload.
            */
            [D(65535), ResourceId(7), Operations("RW"), Mandatory] Binary[,,] Reference_A;

            /**
            This resource represents the logical statement to compare Data resource against Reference A resource. The
            statements are encoded as following:
            0: No Comparison
            1: Data &gt; Reference A
            2: Data &gt;= Reference A
            3: Data &lt; Reference A
            4: Data &lt;= Reference A
            5: Data equals Reference A
            6: Data not equal Reference A
            */
            [ResourceId(8), Operations("RW"), Mandatory] long Comparison_A;

            /**
            This resource contains the value of reference data that is to be compared with Data resource in conjunction
            with Comparison B resource. The comparison result is flagged by Status resource. When Status resource is made
            observable, this effectively becomes a mechanism to signal the server on a hit. The reference data and data
            type is formatted as CBOR payload.
            */
            [D(65535), ResourceId(9), Operations("RW")] Binary[,,] Reference_B;

            /**
            This resource represents the logical statement to compare Data resource against Reference B resource. The
            statements are encoded as following:
            0: No Comparison
            1: Data &gt; Reference B
            2: Data &gt;= Reference B
            3: Data &lt; Reference B
            4: Data &lt;= Reference B
            5: Data equals Reference B
            6: Data not equal Reference B
            */
            [ResourceId(10), Operations("RW")] long? Comparison_B;

            /**
            This resource contains the value of reference data that is to be compared with Data resource in conjunction
            with Comparison B resource. The comparison result is flagged by Status resource. When Status resource is made
            observable, this effectively becomes a mechanism to signal the server on a hit. The reference data and data
            type is formatted as CBOR payload.
            */
            [D(65535), ResourceId(11), Operations("RW")] Binary[,,] Reference_C;

            /**
            This resource represents the logical statement to compare Data resource against Reference B resource. The
            statements are encoded as following:
            0: No Comparison
            1: Data &gt; Reference C
            2: Data &gt;= Reference C
            3: Data &lt; Reference C
            4: Data &lt;= Reference C
            5: Data equals Reference C
            6: Data not equal Reference C
            */
            [ResourceId(12), Operations("RW")] long? Comparison_C;

            /**
            Monitoring Results resource is a serialized accumulation of comparison results of data and the references,
            represented by a read-only serialized Opaque (Binary).
            This resource use CBOR format encoded as following:
            1. array(Result Index 1, Result Timestamp 1, Result Value 1)
            2. array(Result Index 2, Result Timestamp 2, Result Value 2)
            ...
            n. array(Result Index n, Result Timestamp n, Result Value n)
            Result value is an integer containing bit flags described as per following:
            bit 0: 0(Comparison A statement is false), 1(Comparison A statement is true)
            bit 1: 0(Comparison B statement is false), 1(Comparison B statement is true)
            bit 2: 0(Comparison C statement is false), 1(Comparison C statement is true)
            other bits: unused
            New result will be added when there is a change of current Result Value. Result Timestamp is a 32-bit integer
            representing the number of seconds since Jan 1st, 1970 in the UTC time zone, sampled when the change occurs.
            Result Index is the running number of the recorded changes.
            Number of available results is up to device's implementation and maximum result that can be accumulated should
            be stated in Monitoring Description resource.
            */
            [D(65535), ResourceId(13), Operations("RW"), Mandatory] Binary[,,] Monitoring_Results;
        }

        // ═════════════════════════ 10378.xml: Edge Application Server Configuration (urn:oma:lwm2m:x:10378) ═════════════════════════
        /**
        This is used for UE to obtain information about suitable Edge Application Server in Edge Data Network, and to
        support service continuity for the UE to minimize service interruption.
        */
        class Edge_Application_Server_Configuration {
            public const ushort lwm2m_object_id          = 10378;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10378";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Identity of the Application Client used to distinguish multiple ACs if applicable, refer to [3GPP TS 23.558].
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Application_Client_ID;

            /**
            The identifier of the Edge Application Server, refer to [3GPP TS 23.558].
            */
            [ResourceId(1), Operations("RW"), Mandatory] string[,,] EAS_ID;

            /**
            The endpoint information (e.g. URI, FQDN, IP address) used to communicate with the Edge Application Server,
            refer to [3GPP TS 23.558].
            */
            [ResourceId(2), Operations("RW"), Mandatory] string[,,] EAS_Endpoint;

            /**
            Type of EAS that may be useful in service continuity scenario. UE may switch from source EAS (S-EAS) to target
            EAS (T-EAS) during mobility.
            1: S-EAS
            2: T-EAS
            refer to [3GPP TS 23.558]
            */
            [MinMax(1, 2), ResourceId(3), Operations("RW")] byte[,,] Type;
        }

        // ═════════════════════════ 10379.xml: Event Profile (urn:oma:lwm2m:x:10379) ═════════════════════════
        /**
        The Event Profile object manages capture of Events and Alarms based on related Event Codes. The Event Profile
        object also acts as an efficient aggregator for Events and Alarms, that can help to optimize their delivery.
        Note: this object does not intent to manage deliveries of Events and Alarms.
        */
        class Event_Profile {
            public const ushort lwm2m_object_id          = 10379;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10379";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            List of Event Codes for Events to capture in the Events Captured resource when the related Events are
            triggered.
            */
            [ResourceId(0), Operations("RW"), Mandatory] long[,,] Events_to_Capture;

            /**
            Triggered or raised Events are captured in this Events Captured resource. The triggered or raised Events must
            be listed in the Events to Capture resource to allow the capture.
            For Events structure definitions, a recommendation is to use the definitions for Events and related
            serialization as found in the shared resource 6025: Latest Eventlog Payload (with an Event Code, Event Type,
            Event Timestamp and optional data).
            The Events Captured list should be sorted by increasing Timestamps (oldest Events first).
            The maximum size of the Events Captured list is implementation specific.
            When the Events Captured list reaches the maximum size, it should roll-over and start back from the first
            entry (overwrites that first entry).
            On triggering or raising of an Event that needs to be captured (listed in the Events to Capture resource),
            that Event should be implicitly captured in (added to) the Events Captured resource.
            If the Capture resource is supported, an explicit capture of a triggered or raised Event can be accomplished
            via an execution of that Capture resource.
            */
            [ResourceId(1), Operations("R"), Mandatory] Blob[,,] Events_Captured;

            /**
            List of Event Codes for currently active Events. An Event is considered Active if it got raised or triggered
            and didn’t get de-asserted based on its trigger conditions. (example: a high flow event triggered on exceeding
            a certain threshold is considered active as long as it exceeds that threshold, below that threshold that event
            would not be considered active anymore).
            */
            [ResourceId(2), Operations("R")] long[,,] Active_Events;

            /**
            Event Codes for Events that are also configured as Alarms, that the device could send on the next best
            opportunity when the underlying Events are triggered (in real-time or near real-time).
            */
            [ResourceId(3), Operations("RW")] long[,,] Events_Configured_as_Alarm;

            /**
            Triggered or raised Alarms are captured in this Alarms Captured resource. The triggered or raised Alarms must
            be listed in the Alarms Events Configured as Alarm resource to allow the capture in this Alarms Captured
            resource.
            The management of the Alarms Captured list can follow the same rules as used for the management of Event
            Captured resource.
            */
            [ResourceId(4), Operations("R")] Blob[,,] Alarms_Captured;

            /**
            Maximum Event Count is a readable and writable resource used to provide a ceiling on the number of events that
            can be raised within the time period defined in Maximum Event Period resource. The intent of this resource is
            to control the number of events reported, particularly in the case of a faulty sensor.
            The Maximum Event Count and Maximum Event Period resources store values related to an Event Code present in
            the Event to Capture resource and are interpreted together, with matching indexes, and shall have the same
            number of entries.
            The first index values found in the Maximum Event Count and Maximum Event Period correspond to the first index
            value (Event Code) found in the Events to Capture resource, and so on.
            If the Maximum Event Count (for a given Event Code) is set to -1, the number of events recorded is
            unconstrained.
            */
            [ResourceId(8), Operations("RW")] long[,,] Maximum_Event_Count;

            /**
            Maximum Event Period is a readable and writable resource used in conjunction with the Maximum Event Count
            resource to control the number of events that can be raised in a given period. Maximum Event Period is an
            integer value representing the number of seconds for which the Maximum Event Count is measured.
            The Maximum Event Count and Maximum Event Period resources store values related to an Event Code present in
            the Event to Capture resource and are interpreted together, with matching indexes, and shall have the same
            number of entries.
            The first index values found in the Maximum Event Count and Maximum Event Period correspond to the first index
            value (Event Code) found in the Events to Capture resource, and so on.
            If the Maximum Event Period (for a given Event Code) is set to -1, the number of events recorded is
            unconstrained.
            */
            [ResourceId(9), Operations("RW"), Units("s")] DurationInSeconds[,,] Maximum_Event_Period;

            /**
            The Capture Event allows to capture an Event with associated parameters, based on the Event structure
            definition chosen (as defined for the Events Captured resource).
            The captured Event is added to the Event Captured resource.
            If that Event is also configured as an Alarm, it is also captured and added in the Alarms Captured resource.
            Assuming the use of an Event serialization as found in the shared resource 6025: Latest Eventlog Payload (with
            an Event Code, Event Type, Event Timestamp and optional data), the Capture Event method would use the
            following arguments:
            A mandatory Opaque argument (Order 0): an Event serialization structure as found in the shared resource 6025:
            Latest Eventlog Payload (with an Event Code, Event Type, Event Timestamp and optional data).
            Execute operation on resource 5 (Capture Event); sent by the Server to the Client.
            */
            [ResourceId(5), Operations("E")] public class Capture_Event_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Executing the Clear Events resource clears the Event Captured resource.
            Execute operation on resource 6 (Clear Events); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class Clear_Events_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Executing the Clear Alarms resource clears the Alarms Captured resource.
            Execute operation on resource 7 (Clear Alarms); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E"), Mandatory] public class Clear_Alarms_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10479.xml: Cellular Network and Bearer Control (urn:oma:lwm2m:x:10479) ═════════════════════════
        /**
        This LwM2M Object enables monitoring of available network bearers (or Radio Access Technologies - RATs) of
        cellular networks. Each instance of this Object holds information related to one network bearer incl. the
        associated PLMN.
        An object instance should be created for every RAT available for a PLMN, and for every PLMN visible to the
        device.
        The Object also allows steering the device towards a particular PLMN, or, to a particular PLMN+RAT
        combination.
        */
        class Cellular_Network_and_Bearer_Control {
            public const ushort lwm2m_object_id          = 10479;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10479";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            PLMN name e.g. "Vodafone UK"
            */
            [ResourceId(0), Operations("R"), Mandatory] string PLMN_Name;

            /**
            Serving Mobile Country Code.
            As specified in TS [3GPP 23.003].
            */
            [ResourceId(1), Operations("R"), Mandatory] string MCC;

            /**
            Mobile Network Code.
            As specified in TS [3GPP 23.003].
            */
            [ResourceId(2), Operations("R"), Mandatory] string MNC;

            /**
            Indicates the available network bearers.
            More specifically:
            0: GSM
            1: TD-SCDMA
            2: WCDMA
            3: CDMA2000
            4: WiMAX
            5: LTE-TDD
            6: LTE-FDD
            7: NB-IoT
            8: 5GNR TDD
            9: 5G-NR FDD
            10: CAT-M
            11 - 20: Reserved for other types of cellular network bearers
            */
            [MinMax(0, 50), ResourceId(3), Operations("R"), Mandatory] byte Network_Bearer;

            /**
            Indicates if this PLMN and network bearer is currently used e.g. for the current LwM2M communication (true).
            */
            [ResourceId(4), Operations("R"), Mandatory] bool Currently_In_Use;

            /**
            Indicates the average value of the received signal strength indication. The value is expressed in dBm. For the
            following network bearers the signal strength parameters indicated below are represented by this resource:
            GSM:    RSSI
            UMTS:   RSCP
            LTE:    RSRP
            NB-IoT: NRSRP
            CAT-M: RSRP
            For more details on Network Measurement Report, refer to the appropriate 3GPP  standards, (e.g. for LTE refer
            to 3GPP TS 36.133).
            */
            [ResourceId(5), Operations("R"), Units("dBm"), Mandatory] long Radio_Signal_Strength;

            /**
            This contains received link quality  e.g. RxQual Downlink for GSM (range 0...7, refer to 3GPP TS 44.018 for
            more details on Network Measurement Report encoding), RSRQ for LTE and Cat-M (refer to 3GPP TS 36.214), NRSRQ
            for NB-IoT (refer to 3GPP TS 36.214).
            */
            [ResourceId(6), Operations("R"), Mandatory] long Link_Quality;

            /**
            SINR: Signal to Interference plus Noise Ratio SINR is the ratio of the strength of the received signal to the
            strength of the received interference signal (noise and interference).
            */
            [ResourceId(7), Operations("R"), Units("dB")] long? SignalSNR;

            /**
            Indicates the Coverage Enhancement Level of the UE in the serving cell. The Coverage Enhancement levels are
            defined and specified in 3GPP TS 36.331 and 36.213.
            0: Coverage Enhancement level 0
            1: Coverage Enhancement level 1
            2: Coverage Enhancement level 2
            3: Coverage Enhancement level 3
            99: No Coverage Enhancement in the serving cell
            */
            [Range("0..3, 99"), ResourceId(8), Operations("R")] long? Coverage_Enhancement_Level;

            /**
            0=device does not support manual network selection (overwriting automatic network selection)
            1=device supports manual network selection
            This resource shall only be present in Object instance 0.
            */
            [ResourceId(11), Operations("R")] bool? Device_Supports_Manual_Network_Selection;

            /**
            0 = device is on automatic network selection mode.
            1=  device is on manual network selection mode and the network has been manually selected
            This resource shall only be present in Object instance 0.
            */
            [ResourceId(12), Operations("R")] bool? Network_Manually_Selected;

            /**
            0=device does not support manual bearer selection (overwriting automatic bearer selection)
            1=device supports manual bearer selection
            This resource shall only be present in Object instance 0.
            */
            [ResourceId(13), Operations("R")] bool? Device_Supports_Manual_Bearer_Selection;

            /**
            0 = device is on automatic bearer selection mode.
            1= device is on manual bearer selection mode and the bearer has been manually selected
            This resource shall only be present in Object instance 0.
            */
            [ResourceId(14), Operations("R")] bool? Bearer_Manually_Selected;

            /**
            Move to the network represented by this Object Instance. Only the network is selected and the Bearer selection
            is performed automatically.
            Device sets "network manually selected" = 1.
            Execute operation on resource 9 (Select Network); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Select_Network_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Move to the network and bearer represented by this Object Instance.
            Device sets "network manually selected" = 1
            Device sets "bearer manually selected" = 1
            Execute operation on resource 10 (Select Network And Bearer); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Select_Network_And_Bearer_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Perform a new network scan and populate the object instances accordingly.
            This resource shall only be present in Object instance 0.
            Execute operation on resource 15 (Perform Network Scan); sent by the Server to the Client.
            */
            [ResourceId(15), Operations("E"), Mandatory] public class Perform_Network_Scan_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Resets the device to automated network selection.
            Additionally,
            sets the "network manually selected" = 0
            and
            sets the "Bearer manually selected" = 0.
            This resource shall only be present in Object instance 0.
            Execute operation on resource 16 (Reset Network Selection); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E")] public class Reset_Network_Selection_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

