        // ═════════════════════════ 10483.xml: Thread Network (urn:oma:lwm2m:x:10483) ═════════════════════════
        /**
        This LWM2M object is used to describe and modify Thread network configurations
        */
        class Thread_Network {
            public const ushort lwm2m_object_id          = 10483;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10483";
            public const string lwm2m_version            = "1.1";
