        // ═════════════════════════ 10484.xml: Thread Commissioning (joiner add) (urn:oma:lwm2m:x:10484) ═════════════════════════
        /**
        This LwM2M Object enables commissioning (commissioner joiner add) of Thread devices on the Network. The target
        device must be have the "commissioner" and "joiner router" roles. Ex: "Border Router"
        */
        class Thread_Commissioning_joiner_add {
            public const ushort lwm2m_object_id          = 10484;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10484";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates the Extended Unique Identifier (EUI64) or discerner value that can be accepted by the thread
            commissioner. Use '*' to match any Joiner.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Joiner_eui64_discerner;

            /**
            Indicates the Pre Shared Key (PSK/PSKd) Identity shared between thread device and thread commisioner.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Joiner_PSK;

            /**
            Provides the commisioner state as Enumerated type:
            0: Disabled
            1: Active
            */
            [MinMax(0, 1), ResourceId(4), Operations("R")] byte? State;

            /**
            Reports the commissioner currently accepted (eui64 / discerner) IDs.
            */
            [ResourceId(5), Operations("R")] string[,,] Pending_joiners_IDs;

            /**
            Start the commisioning sequence with a default timeout. Using ot-br-posix, this is equivalent to issuing the
            "commissioner joiner add [Thread joiner eui64] [Pre Shared Key Identity]" command. Optionnal commissioning
            timeout in seconds can be specified using argument 0. Ex 0='60'
            Execute operation on resource 2 (Start); sent by the Server to the Client.
            */
            [ResourceId(2), Operations("E"), Mandatory] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stops the commissionning process immediatly.
            Execute operation on resource 3 (Cancel); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Cancel_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10485.xml: Thread Neighbor Information (urn:oma:lwm2m:x:10485) ═════════════════════════
        /**
        This LwM2M Object provides diagnostic information about Thread neighbors
        */
        class Thread_Neighbor_Information {
            public const ushort lwm2m_object_id          = 10485;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10485";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Provides the type of neighbor as Enumerated type:
            0: Child
            1: Router
            */
            [MinMax(0, 1), ResourceId(0), Operations("R")] byte? Neighbor_Role;

            /**
            The Routing Locator (RLOC16) identifies a Thread interface, based on its location in the network topology.
            */
            [ResourceId(1), Operations("R")] string RLOC16_Address;

            /**
            The age is a measure of how long it has been since the last communication or interaction with that particular
            network neighbor.
            */
            [ResourceId(2), Operations("R"), Units("s")] DurationInSeconds? Age;

            /**
            The average Received Signal Strength Indication (RSSI) over a specific period.
            */
            [ResourceId(3), Operations("R"), Units("dBm")] long[,,] Average_RSSI;

            /**
            The instantaneous Received Signal Strength Indication (RSSI).
            */
            [ResourceId(4), Operations("R"), Units("dBm")] long? Last_RSSI;

            /**
            Neighbor mode R represents "RX on when idle".
            */
            [ResourceId(5), Operations("R")] bool? Rx_On_When_Idle;

            /**
            Neighbor mode D represents "Full Thread device".
            */
            [ResourceId(6), Operations("R")] bool? Full_Thread_Device;

            /**
            Neighbor mode N represents "Full network data".
            */
            [ResourceId(7), Operations("R")] bool? Full_Network_Data;

            /**
            Extended Medium Access Control (MAC).
            */
            [ResourceId(8), Operations("R")] string Extended_MAC_Address;

            /**
            Neighbor Link quality In. Link Quality is an integer in [0, 3]. A higher link quality indicates a more usable
            link, with 0 indicating that the
            link is non-existent or unusable.
            */
            [MinMax(0, 3), ResourceId(9), Operations("R")] byte? Link_Quality_In;

            /**
            Neighbor Link quality Out. Link Quality is an integer in [0, 3]. A higher link quality indicates a more usable
            link, with 0 indicating that the
            link is non-existent or unusable.
            */
            [MinMax(0, 3), ResourceId(10), Operations("R")] byte? Link_Quality_Out;

            /**
            Frame error percentage.
            */
            [ResourceId(11), Operations("R"), Units("/100")] double? Frame_Error;

            /**
            Message error percentage.
            */
            [ResourceId(12), Operations("R"), Units("/100")] double? Message_Error;

            /**
            Queued Message count. A non-zero Queued Message Count indicates that there are messages waiting to be
            delivered, and it can be useful for assessing the network's communication efficiency and load.
            */
            [ResourceId(13), Operations("R"), Units("count")] long? Queued_Message_Count;
        }

        // ═════════════════════════ 10486.xml: Thread CLI Command (urn:oma:lwm2m:x:10486) ═════════════════════════
