            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The type of discharge valve used:
            1. Valve Type 1 - Battery powered pump with feedback
            2. Valve Type 2 - Mains powered pump with feedback
            3. Valve Type 3 - Mains powered pump without feedback
            */
            [ResourceId(0), Operations("RW"), Mandatory] long Valve_Type;

            /**
            Distance from the sensor face to the bottom of the tank measured in metres
            */
            [ResourceId(1), Operations("RW"), Units("m"), Mandatory] double Sensor_Offset;

            /**
            Cross-Sectional area of the tank in m^2
            */
            [ResourceId(2), Operations("RW"), Units("m2"), Mandatory] double Tank_Cross_Section;

            /**
            GPS Location - Longitude of the device in the format [+/-]12.345678
            */
            [ResourceId(3), Operations("RW"), Mandatory] double Tank_GPS_Location_Longitude;

            /**
            GPS Location - Latitude of the device in the format [+/-]12.345678
            */
            [ResourceId(4), Operations("RW"), Mandatory] double Tank_GPS_Location_Latitude;

            /**
            Minimum water level that the tank can be discharged to in metres
            */
            [ResourceId(5), Operations("RW"), Units("m"), Mandatory] double Minimum_Tank_Discharge_Level;

            /**
            The amount of time to wait in seconds before validating the hardware state of the valve if feedback is
            configured
            */
            [ResourceId(6), Operations("RW"), Units("s"), Mandatory] long Valve_State_Validation_Time;

            /**
            The water level threshold above which the optional domestic usage pump is enabled if configured as Valve Type
            1.
            */
            [ResourceId(7), Operations("RW"), Units("m"), Mandatory] double Tank_Reserve_Pump_Cut_In_Level;

            /**
            The water level threshold below which the optional domestic usage pump is disabled if configured as Valve Type
            1.
            */
            [ResourceId(8), Operations("RW"), Units("m"), Mandatory] double Tank_Reserve_Pump_Cut_Out_Level;

            /**
            Maximum expected discharge duration in seconds. Used to limit the duration of any discharge event.
            */
            [ResourceId(9), Operations("RW"), Units("s"), Mandatory] long Maximum_Discharge_Time;

            /**
            The distances to static objects identified in the tank
            */
            [ResourceId(10), Operations("RW"), Units("m"), Mandatory] double[,,] Static_Objects;

            /**
            The number of static objects indentified in the tank
            */
            [ResourceId(11), Operations("RW"), Mandatory] long Static_Objects_Count;

            /**
            The area of the roof or other surfaces that collects rainwater to be stored in the rainwater tank
            */
            [ResourceId(12), Operations("RW"), Units("m2"), Mandatory] double Catchment_Area;
        }

        // ═════════════════════════ 10507.xml: Electrical Conductivity Readings (urn:oma:lwm2m:x:10507) ═════════════════════════
        /**
        Periodic electrical conductivity measurements
        */
        class Electrical_Conductivity_Readings {
            public const ushort lwm2m_object_id          = 10507;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10507";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The Interval Period resource is an Integer value representing the width in seconds of the intervals being
            managed by this interval data object. This resource is read only and can only be changed by resource 11
            (Change Interval Configuration). It is recommended that the Interval Period be set to a devisor of 24 hours
            (86400 seconds) to provide a consistent interval period. Examples of Interval Period include:-
            30 = Every 30 seconds
            600 = Every 10 minutes
            1800 = Every 30 minutes
            3600 = Hourly
            7200 = Every 2 hours
            14400 = Every 4 hours
            43200 = Every 12 hours
            86400 = Every Day
            172600 = Every Second Day
            */
            [ResourceId(6000), Operations("R"), Units("s"), Mandatory] DurationInSeconds Interval_Period;

            /**
            The Interval Start Offset resource is a read only resource representing the number of seconds past midnight
            for which the first interval is recorded. If this resource is empty, it is assumed that the intervals are
            midnight aligned. This can be used to adjust interval boundaries. As an example, an Interval Period of 3600
            seconds and an Interval Start time of 300 represents hourly interval data, starting at 00:05.
            */
            [ResourceId(6001), Operations("R"), Units("s")] DurationInSeconds? Interval_Start_Offset;

            /**
            The Interval UTC Offset resource is a read only resource representing the time zone offset for this Interval
            Data instance. If this resource is empty, the application should use the UTC offset provided in the Device
            [/3/0/14] object instance resource or UTC if not provided. UTC+X [ISO 8601].
            */
            [ResourceId(6002), Operations("R")] string Interval_UTC_Offset;

            /**
            The Collection Start Time resource is a read only resource representing the time when the first interval was
            recorded on the device. Interval times represent the end of the interval, not the beginning. As an example,
            the first four hourly interval past midnight will have a timestamp of 04:00 (adjusting for UTC offset).
            */
            [ResourceId(6003), Operations("R"), Mandatory] DateTime Interval_Collection_Start_Time;

            /**
            The Oldest Recorded Interval resource is a read-only resource representing the oldest available interval on
            the device. Interval times represent the end of the interval, not the beginning.
            */
            [ResourceId(6004), Operations("R"), Mandatory] DateTime Oldest_Recorded_Interval;

            /**
            The Last Delivered Interval is a readable and writable resource used to represent the last interval delivered
            to the LwM2M server. Interval times represent the end of the interval, not the beginning. The setting of this
            resource is implementation specific but should be updated based on, either a Read request of the Latest
            Payload from the LwM2M server or via a confirmed delivery of Notify operation of the Latest Payload resource.
            This resource is writable to allow the server to adjust the Last Delivered Interval value if the server and
            client is out of sync.
            */
            [ResourceId(6005), Operations("RW")] DateTime? Last_Delivered_Interval;

            /**
            The Latest Recorded Interval is a readable resource representing the currently highest recorded interval on
            the device. Interval times represent the end of the interval, not the beginning.
            */
            [ResourceId(6006), Operations("R"), Mandatory] DateTime Latest_Recorded_Interval;

            /**
            The Delivery Midnight Aligned is a readable and writable resource used to indicate if data is delivered only
            to the previous midnight (1) or if part-day data can be delivered (0). Calculating Midnight should consider
            the Interval UTC Offset resource, or if empty, the Device [/3/0/14] object instance resource.
            */
            [ResourceId(6007), Operations("RW"), Mandatory] bool Interval_Delivery_Midnight_Aligned;

            /**
            The Historical Read Payload resource is the representation of the data requested by the Historical Interval
            Read executable resource. The format of this Opaque value should be identical to the Latest Payload resource.
            If no Historical Interval Read has been executed, this resource should return and empty Opaque value. This
            resource can either be Read from the Server or set up as an observation and Notified to the server as soon as
            the historical data is available. When this payload is delivered to the LwM2M server, via either a read
            request or a confirmed observation on this Object, Object Instance or Resource, the Historical Read Payload
            should be set to an empty Opaque value.
            */
            [D(65535), ResourceId(6009), Operations("R")] Binary[,,] Interval_Historical_Read_Payload;

            /**
            Recording Enabled is a read-only resource providing an indication of if interval data is currently being
            recorded for this object instance. Refer to re-usable resource LogStatus for further details.
            */
            [ResourceId(6028), Operations("R")] long? Status;

            /**
            The Latest Payload resource is a read-only serialised Opaque (Binary) representation of all the Interval Data
            between the Last Delivered Interval and the Latest Recorded Interval, accounting for the Delivery Midnight
            Aligned resource. When this payload is delivered to the LwM2M server, via either a read request or a confirmed
            observation on this Object, Object Instance or Resource, the Latest Delivered Interval should be updated. When
            no new data exists, an empty Opaque value should be provided.
            The payload data can be provided in an implementation specific serialisation, but by default for fixed length
            values should use the OMA-LwM2M CBOR format encoded as follows:
            1. 8-bit integer, value 2 representing OMA-LwM2M CBOR format.
            2. Interval Data Instance ID/ Class [16-bit integer]
            3. Timestamp of first Interval [32-bit integer] representing the number of seconds since Jan 1st, 1970 in the
            UTC time zone.
            4. Interval Period in seconds [32-bit integer]
            5. Number of intervals in Payload [16-bit integer]
            6. Number of Values Per Interval [8-bit integer]
            7. Size of Value 1 in bits [8-bit integer]
            8. Size of Value 2 in bits [8-bit integer]
            ...
            9. Size of Value N in bits [8-bit integer]
            10. Interval 1 Value 1 [x bits]
            11. Interval 1 Value 2 [x bits]
            ...
            12. Interval 1 Value N [x bits]
            ...
            13. Interval N Value N [x bits]
            If for some implementation specific reason, there are missing intervals in the sequence, the payload may
            consist of multiple blocks of the above serialised data (appended into a single binary opaque value), each
            block representing a continuous series of interval data.
            */
            [D(65535), ResourceId(6029), Operations("R"), Mandatory] Binary[,,] Latest_Payload;

            /**
            Historical Interval Read is an executable resource designed to retrieve ad-hoc interval read data. The
            resource takes two arguments:-
            Argument 0: First Interval time to Retrieve represented as number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            Argument 1: Last interval time to Retrieve represented as number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            The dates should be inclusive based on the end time of the interval. The data retrieved from this resource
            will be readable (or observable) from the Historical Read Payload Resource.
            As an example, the Argument List to retrieve data from Midnight 2nd March (UTC+10) to Midnight 6rd March
            (UTC+10) for a specific instance of the interval data object, would be constructed as follows:-
            0='1488463200',1='1488808800'
            Execute operation on resource 6008 (Interval Historical Read); sent by the Server to the Client.
            */
            [ResourceId(6008), Operations("E")] public class Interval_Historical_Read_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Change Interval Configuration is an executable resource designed to allow the Interval Period, Interval Start
            Offset and Interval UTC Offset to be reconfigured. The resource takes three arguments:-
            Argument 0: [Mandatory] Interval Period represented as an integer as defined in the Interval Period Resource.
            Argument 1: [Optional] Interval start offset represented as an integer as defined in the Interval Start Offset
            Resource. If not provided, leave the value as per the current configuration
            Argument 2: [Optional] Interval UTC offset represented as a String as defined in the Interval UTC Offset
            Resource. If not provided, leave the value as per the current configuration.
            Depending on the specifics of the implementation of this object, reconfiguring the Interval data object may
            result in the removal of all historical data for this Interval Data Object Instance. Please consult with your
            device vendor as to the implications of reconfiguring an Interval Data Object Instance.
            As an example, the Argument List to change an interval data object instance from its existing values to one
            hour intervals, midnight aligned in UTC+10 time zone:-
            0='3600',1='0',1='UTC+10'
            Execute operation on resource 6010 (Interval Change Configuration); sent by the Server to the Client.
            */
            [ResourceId(6010), Operations("E")] public class Interval_Change_Configuration_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Start is an executable resource that enables the recording of interval data. The first interval recorded will
            have a timestamp based on the Interval Start Offset resource. This executable resource takes no arguments.
            Refer to re-usable resource LogStart for further details.
            Execute operation on resource 6026 (Start); sent by the Server to the Client.
            */
            [ResourceId(6026), Operations("E")] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stop (LogStop) is an executable resource that disables the recording of interval data for this object
            instance. This executable resource takes no arguments. Refer to re-usable resource LogStop for further
            details.
            Execute operation on resource 6027 (Stop); sent by the Server to the Client.
            */
            [ResourceId(6027), Operations("E")] public class Stop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10508.xml: Electrical Conductivity Alarm (urn:oma:lwm2m:x:10508) ═════════════════════════
        /**
        This alarm is raised when the electrical conductivity of the device exceeds the specified threshold
        */
        class Electrical_Conductivity_Alarm {
            public const ushort lwm2m_object_id          = 10508;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10508";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Event Type is a readable and writable resource used to represent how this event will behave. Event Type should
            be one of the following values:-
            0. Disabled
            1. Alarm Current State
            2. Alarm State Change Log
            3. Event Log
            When the Event Type is set to Disabled (0), this event will not be recorded by the device. No Latest Eventlog
            payload should be delivered for events that are Disabled.
            When the Event Type is set to Alarm Current State (1), this Event is treated as an alarm state manager and the
            Latest Eventlog Payload will only contain the current state of this alarm.
            When the Event Type is set to Alarm State Change Log (2), the Event is treated as an alarm that reports
            whenever the Alarm is either set or cleared. The Latest Eventlog Payload will contain all alarm transitions
            since the previous delivery in this mode.
            When the Event Type is set to Event Log (3), this object instance is treated as a raw event log. It is used to
            manage and deliver events. The Latest Eventlog Payload will contain all events since the previous delivery in
            this mode.
            See the Event Log Payload for examples of each of these modes.
            */
            [ResourceId(6011), Operations("RW"), Mandatory] long Event_Type;

            /**
            Realtime is a readable and writable resource used to indicate if an event should report immediately (1) at the
            point of occurrence, or delivered periodically as part of the Latest Eventlog Payload.
            */
            [ResourceId(6012), Operations("RW"), Mandatory] bool Alarm_Realtime;

            /**
            Alarm State is a read-only resource used to indicate the current alarm state for this Event configuration.
            This is only applicable if the Event Type is Alarm Current State (1) or Alarm State Change (2).
            */
            [ResourceId(6013), Operations("R")] bool? Alarm_State;

            /**
            Set Threshold is a readable and writable resource used to represent the threshold for when an alarm is
            triggered. This resource is used in conjunction with the Set Operator resource.
            */
            [ResourceId(6014), Operations("RW")] double? Alarm_Set_Threshold;

            /**
            Set Operator is a readable and writable resource used in conjunction with the Set Threshold to represent when
            an alarm is triggered. This resource should be set to one of the following values:-
            0. Greater Than or Equal to
            1. Less Than or Equal to
            By setting the Set Operator to Greater Than (0), when the measured value for this event exceeds the Set
            Threshold resource, the event is considered to be in an Alarm State of 1
            By setting the Set Operator to Less Than (1), when the measured value for this event falls below the Set
            Threshold resource, the event is considered to be in an Alarm State of 1
            */
            [ResourceId(6015), Operations("RW")] long? Alarm_Set_Operator;

            /**
            Clear Threshold is a readable and writable resource used to represent the threshold for when an alarm is
            cleared. This resource is used in conjunction with the Clear Operator resource.
            */
            [ResourceId(6016), Operations("RW")] double? Alarm_Clear_Threshold;

            /**
            Clear Operator is a readable and writable resource used in conjunction with the Clear Threshold to represent
            when an alarm is Cleared. This resource should be set to one of the following values:-
            0. Greater Than or Equal to
            1. Less Than or Equal to
            By setting the Clear Operator to Greater Than (0), when the measured value for this event exceeds the Clear
            Threshold resource, the event is considered to be in an Alarm State of 0
            By setting the Clear Operator to Less Than (1), when the measured value for this event falls below the Clear
            Threshold resource, the event is considered to be in an Alarm State of 0
            */
            [ResourceId(6017), Operations("RW")] long? Alarm_Clear_Operator;

            /**
            Maximum Event Count is a readable and writable resource used provide a ceiling on the number of events that
            can be raised within the time period defined in Maximum Event Period resource. If no Maximum Event Count is
            set, the number of events recorded is unconstrained. The intent of this resource is to control the number of
            events reported, particularly in the case of a faulty sensor.
            */
            [ResourceId(6018), Operations("RW")] long? Alarm_Maximum_Event_Count;

            /**
            Maximum Event Period is a readable and writable resource used in conjunction with the Maximum Event Count
            resource to control the number of events that can be raised in a given period. Maximum Event Period is an
            integer value representing the number of seconds for which the Maximum Event Count is measured. If no Maximum
            Event Period is set, the number of events recorded is unconstrained. The intent of this resource is to control
            the number of events reported, particularly in the case of a faulty sensor.
            */
            [ResourceId(6019), Operations("RW"), Units("s")] DurationInSeconds? Alarm_Maximum_Event_Period;

            /**
            Latest Delivered Event Time is a readable and writable resource to represent the last recorded time that an
            event was delivered for this event code to the LwM2M server. The setting of this resource is implementation
            specific but should be updated based on, either a Read request of the Latest Eventlog Payload from the LwM2M
            server or via a confirmed delivery of Notify operation of the Latest Eventlog Payload resource. This resource
            is writable to allow the server to adjust the Last Delivered Event Time value if the server and client is out
            of sync.
            */
            [ResourceId(6020), Operations("RW")] DateTime? Latest_Delivered_Event_Time;

            /**
            Latest Recorded Event Time is a readonly resource used to represent the last recorded event time for this
            object instance on the device
            */
            [ResourceId(6021), Operations("R"), Mandatory] DateTime Latest_Recorded_Event_Time;

            /**
            Auto Clear Alarm is a readable and writable resource used to indicate if an alarm is automatically cleared
            once the delivery of the event data payload is complete
            */
            [ResourceId(6023), Operations("RW")] bool? Alarm_Auto_Clear;

            /**
            Event Code is a read-only resource used as an identifier to represent this class of event. The allocation of
            event codes is implementation specific but ideally be unique across the implementation. Event Codes use vendor
            specific LogClass value 100...255
            */
            [MinMax(100, 255), ResourceId(6024), Operations("R"), Mandatory] byte Event_Code;

            /**
            The Latest Eventlog Payload resource is a read-only serialised Opaque (Binary) representation of all the Event
            Data between the Last Delivered Event Time and the Latest Recorded Event Time. When this payload is delivered
            to the LwM2M server, via either a read request or a confirmed observation on this Object, Object Instance or
            Resource, the Latest Delivered Interval should be updated. When no new data exists, an empty Opaque value
            should be provided.
            The payload data can be provided in an implementation specific serialisation, but by default for fixed length
            values should use the OMA-LwM2M CBOR format encoded with one of these schemes:-
            Event Type = Alarm Current State (1)
            In this mode, only the current alarm state should be reported
            1. 8-bit integer, value 2 representing OMA-LwM2M CBOR format.
            2. Event Code [16-bit integer]
            3. Event Type [8-bit Integer] - Alarm Current State (1)
            4. Alarm Timestamp [32-bit unsigned integer] representing the number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            5. Alarm State [8-bit Integer]
            */
            [D(65535), ResourceId(6025), Operations("R"), Mandatory] Binary[,,] Latest_Payload;

            /**
            The Active Fault Interval Period overrides the Interval Period for the associated Interval Object when in an
            alarm state. This is a readable and writable resource representing the width in seconds of the intervals being
            managed by this interval data object. This resource is read only and can only be changed by resource 11
            (Change Interval Configuration). It is recommended that the Interval Period be set to a devisor of 24 hours
            (86400 seconds) to provide a consistent interval period. Examples of Interval Period include:-
            30 = Every 30 seconds
            600 = Every 10 minutes
            1800 = Every 30 minutes
            3600 = Hourly
            7200 = Every 2 hours
            14400 = Every 4 hours
            43200 = Every 12 hours
            86400 = Every Day
            172600 = Every Second Day
            */
            [ResourceId(0), Operations("RW"), Units("s")] DurationInSeconds? Active_Fault_Interval_Period;

            /**
            The Active Fault Delivery Frequency overrides the Delivery Frequency in the associated Delivery Schedule
            Object when in an alarm state. This resource is a readable and writable resource representing the number of
            seconds between deliveries. It is recommended that the Delivery Frequency be set to a devisor of 24 hours
            (86400 seconds) to provide a consistent interval period. Examples of Delivery Frequency include:-
            30 = Every 30 seconds
            600 = Every 10 minutes
            1800 = Every 30 minutes
            3600 = Hourly
            7200 = Every 2 hours
            14400 = Every 4 hours
            43200 = Every 12 hours
            86400 = Every Day
            172600 = Every Second Day
            */
            [MinMax(1, 864000), ResourceId(1), Operations("RW"), Units("s")] uint? Active_Fault_Delivery_Frequency;

            /**
            Clear Alarm is an executable resource used to allow the LwM2M server to clear alarms when they need to be
            manually acknowledged.
            Execute operation on resource 6022 (Alarm Clear); sent by the Server to the Client.
            */
            [ResourceId(6022), Operations("E")] public class Alarm_Clear_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10509.xml: Leakage Detection Configuration (urn:oma:lwm2m:x:10509) ═════════════════════════
        /**
        This object provides timing and sampling frequency configuration for a vibration-based leakage detector
        */
        class Leakage_Detection_Configuration_10509 {
            public const ushort lwm2m_object_id          = 10509;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10509";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Sample Times is a readable and writable multi value resource used to control when leak detection vibration
            sampling should occur. This is an integer value representing seconds since midnight
            */
            [ResourceId(0), Operations("RW"), Mandatory] long[,,] Sample_Times;

            /**
            The Sample UTC Offset resource is a readable and writable resource representing the time zone offset for this
            Leakage Detection Schedule instance. If this resource is empty, the application should use the UTC offset
            provided in the Device [/3/0/14] object instance resource or UTC if not provided.
            */
            [ResourceId(1), Operations("RW")] string Sample_UTC_Offset;

            /**
            Payload Type is a readable and writeable resource used to indicate which payload type to report to the LWM2M
            server. Values are one of:-
            0: Disabled
            1: AUC (default)
            2: All Frequency Values
            Disabled (0)  The leak detection payload generation should be disabled.
            AUC (1)  For this mode, only the mean AUC (area under curve) for all samples in the sampling window within the
            defined frequency range will be delivered to the LwM2M server via the Latest Payload Resource
            All Frequency Values(2)  for this mode, the median for values for all frequency bands for all samples in the
            sampling window will be provided to the LwM2M server via the Latest Payload Resource
            */
            [MinMax(0, 2), ResourceId(2), Operations("RW"), Mandatory] byte Payload_Type;

            /**
            The Number Sample Windows resource is a readable and writeable resource used to determine how many instances
            to use for the Sample Times resource
            */
            [MinMax(0, 10), ResourceId(3), Operations("RW"), Mandatory] byte Number_Sample_Windows;

            /**
            The Samples Per Window resource is a readable and writeable resource used to control how many samples to read
            per sample window
            */
            [ResourceId(4), Operations("RW"), Mandatory] long[,,] Samples_Per_Window;

            /**
            The Sample Interval resource is a readable and writeable resource used to control the interval (in seconds)
            between each sample in a window
            */
            [ResourceId(5), Operations("RW"), Units("s"), Mandatory] DurationInSeconds[,,] Sample_Interval;

            /**
            The AUC Lower Frequency resource is a readable and writeable resource used to determine the lower frequency
            bound (inclusive) to use for calculating the AUC. This value will default to 360Hz if the resource is not set
            */
            [ResourceId(6), Operations("RW"), Units("Hz")] double? AUC_Lower_Frequency;

            /**
            The AUC Upper Frequency resource is a readable and writeable resource used to determine the upper frequency
            bound (inclusive) to use for calculating the AUC. This value will default to 1200Hz if the resource is not set
            */
            [ResourceId(7), Operations("RW"), Units("Hz")] double? AUC_Upper_Frequency;

            /**
            The AUC Leak Threshold resource is a readable and writeable resource used to to compare the AUC of each sample
            in a sampling window. This value will default to 1000 if the resource is not set
            */
            [ResourceId(8), Operations("RW")] long? AUC_Leak_Threshold;

            /**
            The Collection Start Time resource is a read only resource representing the time when the first interval was
            recorded on the device. Interval times represent the end of the interval, not the beginning. As an example,
            the first four hourly interval past midnight will have a timestamp of 04:00 (adjusting for UTC offset).
            */
            [ResourceId(6003), Operations("R"), Mandatory] DateTime Interval_Collection_Start_Time;

            /**
            The Oldest Recorded Interval resource is a read-only resource representing the oldest available interval on
            the device. Interval times represent the end of the interval, not the beginning.
            */
            [ResourceId(6004), Operations("R"), Mandatory] DateTime Oldest_Recorded_Interval;

            /**
            The Last Delivered Interval is a readable and writable resource used to represent the last interval delivered
            to the LwM2M server. Interval times represent the end of the interval, not the beginning. The setting of this
            resource is implementation specific but should be updated based on, either a Read request of the Latest
            Payload from the LwM2M server or via a confirmed delivery of Notify operation of the Latest Payload resource.
            This resource is writable to allow the server to adjust the Last Delivered Interval value if the server and
            client is out of sync.
            */
            [ResourceId(6005), Operations("RW")] DateTime? Last_Delivered_Interval;

            /**
            The Latest Recorded Interval is a readable resource representing the currently highest recorded interval on
            the device. Interval times represent the end of the interval, not the beginning.
            */
            [ResourceId(6006), Operations("R"), Mandatory] DateTime Latest_Recorded_Interval;

            /**
            The Delivery Midnight Aligned is a readable and writable resource used to indicate if data is delivered only
            to the previous midnight (1) or if part-day data can be delivered (0). Calculating Midnight should consider
            the Interval UTC Offset resource, or if empty, the Device [/3/0/14] object instance resource.
            */
            [ResourceId(6007), Operations("RW"), Mandatory] bool Interval_Delivery_Midnight_Aligned;

            /**
            The Historical Read Payload resource is the representation of the data requested by the Historical Interval
            Read executable resource. The format of this Opaque value should be identical to the Latest Payload resource.
            If no Historical Interval Read has been executed, this resource should return and empty Opaque value. This
            resource can either be Read from the Server or set up as an observation and Notified to the server as soon as
            the historical data is available. When this payload is delivered to the LwM2M server, via either a read
            request or a confirmed observation on this Object, Object Instance or Resource, the Historical Read Payload
            should be set to an empty Opaque value.
            */
            [D(65535), ResourceId(6009), Operations("R")] Binary[,,] Interval_Historical_Read_Payload;

            /**
            Recording Enabled is a read-only resource providing an indication of if interval data is currently being
            recorded for this object instance. Refer to re-usable resource LogStatus for further details.
            */
            [ResourceId(6028), Operations("R")] long? Status;

            /**
            The Latest Payload resource is a read-only serialised Opaque (Binary) representation of all the Interval Data
            between the Last Delivered Interval and the Latest Recorded Interval, accounting for the Delivery Midnight
            Aligned resource. When this payload is delivered to the LwM2M server, via either a read request or a confirmed
            observation on this Object, Object Instance or Resource, the Latest Delivered Interval should be updated. When
            no new data exists, an empty Opaque value should be provided.
            The payload data can be provided in an implementation specific serialisation, but by default for fixed length
            values should use the OMA-LwM2M CBOR format encoded as follows:
            1. 8-bit integer, value 2 representing OMA-LwM2M CBOR format.
            2. Interval Data Instance ID/ Class [16-bit integer]
            3. Timestamp of first Interval [32-bit integer] representing the number of seconds since Jan 1st, 1970 in the
            UTC time zone.
            4. Interval Period in seconds [32-bit integer]
            5. Number of intervals in Payload [16-bit integer]
            6. Number of Values Per Interval [8-bit integer]
            7. Size of Value 1 in bits [8-bit integer]
            8. Size of Value 2 in bits [8-bit integer]
            ...
            9. Size of Value N in bits [8-bit integer]
            10. Interval 1 Value 1 [x bits]
            11. Interval 1 Value 2 [x bits]
            ...
            12. Interval 1 Value N [x bits]
            ...
            13. Interval N Value N [x bits]
            If for some implementation specific reason, there are missing intervals in the sequence, the payload may
            consist of multiple blocks of the above serialised data (appended into a single binary opaque value), each
            block representing a continuous series of interval data.
            */
            [D(65535), ResourceId(6029), Operations("R"), Mandatory] Binary[,,] Latest_Payload;

            /**
            Historical Interval Read is an executable resource designed to retrieve ad-hoc interval read data. The
            resource takes two arguments:-
            Argument 0: First Interval time to Retrieve represented as number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            Argument 1: Last interval time to Retrieve represented as number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            The dates should be inclusive based on the end time of the interval. The data retrieved from this resource
            will be readable (or observable) from the Historical Read Payload Resource.
            As an example, the Argument List to retrieve data from Midnight 2nd March (UTC+10) to Midnight 6rd March
            (UTC+10) for a specific instance of the interval data object, would be constructed as follows:-
            0='1488463200',1='1488808800'
            Execute operation on resource 6008 (Interval Historical Read); sent by the Server to the Client.
            */
            [ResourceId(6008), Operations("E")] public class Interval_Historical_Read_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Start is an executable resource that enables the recording of interval data. The first interval recorded will
            have a timestamp based on the Interval Start Offset resource. This executable resource takes no arguments.
            Refer to re-usable resource LogStart for further details.
            Execute operation on resource 6026 (Start); sent by the Server to the Client.
            */
            [ResourceId(6026), Operations("E")] public class Start_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Stop (LogStop) is an executable resource that disables the recording of interval data for this object
            instance. This executable resource takes no arguments. Refer to re-usable resource LogStop for further
            details.
            Execute operation on resource 6027 (Stop); sent by the Server to the Client.
            */
            [ResourceId(6027), Operations("E")] public class Stop_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10511.xml: Cellular Connectivity Diagnostics (urn:oma:lwm2m:x:10511) ═════════════════════════
        /**
        Provides standardized diagnostic information about the current cellular connection, including serving cell
        identifiers, PLMN details, signal quality metrics, and SIM/eSIM parameters to support interoperability and
        troubleshooting.
        */
        class Cellular_Connectivity_Diagnostics {
            public const ushort lwm2m_object_id          = 10511;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10511";
            public const string lwm2m_version            = "1.2";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Mobile Country Code (MCC) of the registered PLMN. ITU-T E.212: "The MCC consists of three decimal digits
            identifying the country of domicile of the mobile subscriber." (e.g., 262 = Germany). Range: 000-999.
            */
            [MinMax(0, 999), ResourceId(0), Operations("R"), Mandatory] ushort MCC;

            /**
            Mobile Network Code (MNC) of the registered PLMN. ITU-T E.212: "The Mobile Network Code consists of two or
            three decimal digits and identifies the home PLMN of the subscriber within a country."(e.g., 01 = Telekom DE).
            Must be used together with MCC.
            Range: 00-999.
            */
            [MinMax(0, 999), ResourceId(1), Operations("R"), Mandatory] ushort MNC;

            /**
            Identifier of the serving cell. 3GPP TS 36.331/38.331: "CellIdentity: Identity of the cell, within the PLMN,
            in E-UTRA a 28-bit value (ECI); in NR a 36-bit value (NCI)." Range: LTE 0-268435455; NR up to 68719476735.
            */
            [ResourceId(2), Operations("R"), Mandatory] ulong Serving_Cell_ID;

            /**
            Area Code identifying the UE’s registration area within a PLMN.
            Interpretation depends on the Network Bearer (Resource ID: 4):
            - GSM/UMTS (2G/3G): Location Area Code (LAC), 16-bit identifier of the Location Area.
            - LTE/NR (4G/5G): Tracking Area Code (TAC), 16-bit identifier of the Tracking Area.
            Both LAC and TAC are defined in 3GPP TS 23.003 and share the same numeric range (0-65535).
            */
            [ResourceId(3), Operations("R")] ushort? Tracking_Area_Code;

            /**
            Indicates the network bearer used for the current LwM2M communication session from the network bearer list
            below.
            The number range is split into three categories:
            0 - 20 are Cellular Bearers
            21 - 40 are Wireless Bearers
            41 - 50 are Wireline Bearers
            More specifically:
            0: GSM cellular network
            1: TD-SCDMA cellular network
            2: WCDMA cellular network
            3: CDMA2000 cellular network
            4: WiMAX cellular network
            5: LTE-TDD cellular network
            6: LTE-FDD cellular network
            7: NB-IoT
            8: 5G-NR TDD
            9: 5G-NR FDD
            10 - 20: Reserved for other types of cellular network
            21: WLAN network
            22: Bluetooth network
            23: IEEE 802.15.4 network
            24 - 40: Reserved for other types of local wireless network
            41: Ethernet
            42: DSL
            43: PLC
            44 - 50: reserved for other types of wireline networks.
            */
            [MinMax(0, 50), ResourceId(4), Operations("R")] byte? Network_Bearer;

            /**
            Human-readable PLMN name of the registered operator. 3GPP TS 24.008: "The Network Name IE provides the PLMN
            name in either full or short form to be displayed to the user."
            */
            [ResourceId(5), Operations("R"), Mandatory] string Operator_Name;

            /**
            Indicates whether the UE is on home (0) or visited (1) PLMN. 3GPP TS 23.122: "The MS indicates whether it is
            registered on its home PLMN or on a visited PLMN."
            */
            [Range("0..1"), ResourceId(6), Operations("R"), Mandatory] bool Roaming_Status;

            /**
            Numeric identifier of the current operating band. 3GPP TS 36.101 Table 5.5-1: "The E-UTRA operating bands are
            designated by a Band Number (e.g., Band 1 = 2100 MHz)." For NR: 3GPP TS 38.101-1/-2.
            */
            [ResourceId(7), Operations("R")] long? Frequency_Band;

            /**
            Reference Signal Received Power. 3GPP TS 36.214/38.215: "RSRP is defined as the linear average over the power
            contributions of resource elements carrying reference signals."
            */
            [ResourceId(8), Operations("R"), Units("dBm")] double? RSRP;

            /**
            Reference Signal Received Quality. 3GPP TS 36.214/38.215: "RSRQ = (N × RSRP) / RSSI, where N is number of
            RBs."
            */
            [ResourceId(9), Operations("R"), Units("dB")] double? RSRQ;

            /**
            Received Signal Strength Indicator. 3GPP TS 36.214: "RSSI comprises the linear average of the total received
            wideband power observed at the antenna connector." GSM: TS 45.008; UMTS: TS 25.133.
            */
            [ResourceId(10), Operations("R"), Units("dBm")] double? RSSI;

            /**
            Signal-to-Interference-and-Noise Ratio. 3GPP TS 36.214/38.215: "SINR represents the ratio of signal power to
            the sum of interference and noise power, expressed in dB."
            */
            [ResourceId(11), Operations("R"), Units("dB")] double? SINR;

            /**
            eUICC Identifier. GSMA SGP.22: "The eUICC Identifier (EID) is a 32-digit hexadecimal value that uniquely
            identifies an eUICC."
            */
            [Range("32 hex digits"), ResourceId(12), Operations("R")] string EID_eUICC;

            /**
            Integrated Circuit Card Identifier. ITU-T E.118: "The ICCID is a unique identifier of the SIM, consisting of
            up to 20 digits."
            */
            [Range("19..20 digits"), ResourceId(13), Operations("R")] string ICCID;

            /**
            International Mobile Subscriber Identity. ITU-T E.212/3GPP TS 23.003: "The IMSI is composed of the MCC, the
            MNC and the MSIN, and uniquely identifies a subscription in a PLMN." Length: 14-15 digits.
            */
            [Range("14..15 digits"), ResourceId(14), Operations("R")] string IMSI;
        }

        // ═════════════════════════ 10512.xml: Starlink Terminal (urn:oma:lwm2m:x:10512) ═════════════════════════
        /**
        This LwM2M Object provides comprehensive management and monitoring of Starlink Gen3 satellite internet
        terminals. It enables remote access to telemetry, configuration, and control of Starlink dishes, including
        obstruction monitoring, alignment tracking, speed testing, and performance metrics. The object interfaces with
        the Starlink terminal via gRPC protocol (default endpoint: 192.168.100.1:9200).
        */
        class Starlink_Terminal {
            public const ushort lwm2m_object_id          = 10512;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10512";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Starlink terminal serial number uniquely identifying the dish hardware.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Device_ID;

            /**
            Terminal hardware version string (e.g., "rev3_proto2").
            */
            [ResourceId(1), Operations("R"), Mandatory] string Hardware_Version;

            /**
            Currently installed firmware version on the terminal.
            */
            [ResourceId(2), Operations("R"), Mandatory] string Software_Version;

            /**
            Current connection state: CONNECTED, SEARCHING, BOOTING, STOWED, THERMAL_SHUTDOWN, NO_SATS, OBSTRUCTED,
            NO_DOWNLINK, NO_PINGS, or UNKNOWN.
            */
            [ResourceId(3), Operations("R"), Mandatory] string Connection_State;

            /**
            Seconds since the terminal last rebooted.
            */
            [ResourceId(4), Operations("R"), Units("s"), Mandatory] DurationInSeconds Uptime;

            /**
            Current download speed in bits per second.
            */
            [ResourceId(10), Operations("R"), Units("B/s"), Mandatory] double Downlink_Throughput;

            /**
            Current upload speed in bits per second.
            */
            [ResourceId(11), Operations("R"), Units("B/s"), Mandatory] double Uplink_Throughput;

            /**
            Round-trip latency to the Point of Presence in milliseconds.
            */
            [ResourceId(12), Operations("R"), Units("ms"), Mandatory] double POP_Ping_Latency;

            /**
            Packet loss fraction from 0.0 (no loss) to 1.0 (total loss).
            */
            [Range("0.0..1.0"), ResourceId(13), Operations("R"), Mandatory] double POP_Ping_Drop_Rate;

            /**
            Estimated seconds until next satellite becomes available.
            */
            [ResourceId(14), Operations("R"), Units("s")] double? Seconds_To_First_Slot;

            /**
            Current signal-to-noise ratio in decibels.
            */
            [ResourceId(15), Operations("R"), Units("dB"), Mandatory] double SNR;

            /**
            True if SNR is above 3dB threshold indicating good signal quality.
            */
            [ResourceId(16), Operations("R")] bool? Is_SNR_Above_Noise_Floor;

            /**
            Total bytes downloaded since last counter reset.
            */
            [ResourceId(17), Operations("R"), Units("B")] long? Download_Usage;

            /**
            Total bytes uploaded since last counter reset.
            */
            [ResourceId(18), Operations("R"), Units("B")] long? Upload_Usage;

            /**
            Fraction of sky view obstructed from 0.0 (clear) to 1.0 (fully blocked).
            */
            [Range("0.0..1.0"), ResourceId(30), Operations("R"), Mandatory] double Fraction_Obstructed;

            /**
            True if satellite view is currently obstructed.
            */
            [ResourceId(31), Operations("R"), Mandatory] bool Currently_Obstructed;

            /**
            Average duration of prolonged obstruction events in seconds.
            */
            [ResourceId(32), Operations("R"), Units("s")] double? Obstruction_Duration;

            /**
            Average time between obstruction events in seconds.
            */
            [ResourceId(33), Operations("R"), Units("s")] double? Obstruction_Interval;

            /**
            Number of seconds of valid obstruction data collected.
            */
            [ResourceId(34), Operations("R"), Units("s")] double? Obstruction_Valid_Seconds;

            /**
            JSON array of 12 obstruction fractions for each 30-degree wedge of the sky view.
            */
            [ResourceId(35), Operations("R")] string Wedges_Fraction_Obstructed;

            /**
            Dish azimuth pointing direction in degrees (0=North, 90=East, 180=South, 270=West).
            */
            [Range("0..360"), ResourceId(40), Operations("R"), Units("deg"), Mandatory] double Direction_Azimuth;

            /**
            Dish elevation angle in degrees (0=horizontal, 90=vertical).
            */
            [Range("0..90"), ResourceId(41), Operations("R"), Units("deg"), Mandatory] double Direction_Elevation;

            /**
            Get/set stow state. Write true to stow dish for transport, false to unstow for operation.
            */
            [ResourceId(42), Operations("RW"), Mandatory] bool Dish_Stowed;

            /**
            Human-readable alignment status message.
            */
            [ResourceId(43), Operations("R")] string Dish_Alignment_Status;

            /**
            Combined alert flags as bit field. Each bit represents a specific alert condition.
            */
            [ResourceId(50), Operations("R")] long? Alerts_Bitmap;

            /**
            Alert: Dish motors are stuck and cannot move.
            */
            [ResourceId(51), Operations("R")] bool? Alert_Motors_Stuck;

            /**
            Alert: Thermal shutdown triggered due to overheating.
            */
            [ResourceId(52), Operations("R")] bool? Alert_Thermal_Shutdown;

            /**
            Alert: Performance throttled due to thermal conditions.
            */
            [ResourceId(53), Operations("R")] bool? Alert_Thermal_Throttle;

            /**
            Alert: Dish detected at unexpected geographic location.
            */
            [ResourceId(54), Operations("R")] bool? Alert_Unexpected_Location;

            /**
            Alert: Mounting mast is not near vertical position.
            */
            [ResourceId(55), Operations("R")] bool? Alert_Mast_Not_Vertical;

            /**
            Alert: Ethernet connection speed is below expected.
            */
            [ResourceId(56), Operations("R")] bool? Alert_Slow_Ethernet;

            /**
            Alert: Terminal is roaming outside home service area.
            */
            [ResourceId(57), Operations("R")] bool? Alert_Roaming;

            /**
            Alert: Installation is pending completion.
            */
            [ResourceId(58), Operations("R")] bool? Alert_Install_Pending;

            /**
            Alert: Dish heater is actively running (cold weather operation).
            */
            [ResourceId(59), Operations("R")] bool? Alert_Is_Heating;

            /**
            Alert: Power supply thermal throttling active.
            */
            [ResourceId(60), Operations("R")] bool? Alert_Power_Supply_Throttle;

            /**
            Alert: Terminal in power saving idle mode.
            */
            [ResourceId(61), Operations("R")] bool? Alert_Is_Power_Save_Idle;

            /**
            Alert: Motor current below expected levels.
            */
            [ResourceId(62), Operations("R")] bool? Alert_Low_Motor_Current;

            /**
            Alert: Signal strength lower than predicted for current conditions.
            */
            [ResourceId(63), Operations("R")] bool? Alert_Lower_Signal;

            /**
            Alert: Obstruction map has been reset and is rebuilding.
            */
            [ResourceId(64), Operations("R")] bool? Alert_Obstruction_Map_Reset;

            /**
            Alert: Water detected in dish enclosure.
            */
            [ResourceId(65), Operations("R")] bool? Alert_Dish_Water_Detected;

            /**
            Alert: Water detected in router enclosure.
            */
            [ResourceId(66), Operations("R")] bool? Alert_Router_Water_Detected;

            /**
            True when GPS position fix is available and valid.
            */
            [ResourceId(80), Operations("R")] bool? GPS_Ready;

            /**
            True if GPS functionality is enabled on the terminal.
            */
            [ResourceId(81), Operations("R")] bool? GPS_Enabled;

            /**
            Number of GPS satellites currently in use for position fix.
            */
            [ResourceId(82), Operations("R")] long? GPS_Satellites;

            /**
            Current latitude in decimal degrees (WGS84).
            */
            [Range("-90..90"), ResourceId(83), Operations("R"), Units("deg")] double? Latitude;

            /**
            Current longitude in decimal degrees (WGS84).
            */
            [Range("-180..180"), ResourceId(84), Operations("R"), Units("deg")] double? Longitude;

            /**
            Current altitude above sea level in meters.
            */
            [ResourceId(85), Operations("R"), Units("m")] double? Altitude;

            /**
            Most recent instantaneous power consumption measurement.
            */
            [ResourceId(90), Operations("R"), Units("W")] double? Latest_Power;

            /**
            Average power consumption over monitoring period.
            */
            [ResourceId(91), Operations("R"), Units("W")] double? Mean_Power;

            /**
            Minimum power consumption observed during monitoring period.
            */
            [ResourceId(92), Operations("R"), Units("W")] double? Min_Power;

            /**
            Maximum power consumption observed during monitoring period.
            */
            [ResourceId(93), Operations("R"), Units("W")] double? Max_Power;

            /**
            Cumulative energy consumed since counter reset in kilowatt-hours.
            */
            [ResourceId(94), Operations("R"), Units("kWh")] double? Total_Energy;

            /**
            Speed test status and results in JSON format.
            */
            [ResourceId(102), Operations("R")] string Speedtest_Status;

            /**
            Binary obstruction map data retrieved via Get Obstruction Map action.
            */
            [D(65535), ResourceId(105), Operations("R")] Binary[,,] Obstruction_Map_Data;

            /**
            gRPC endpoint address for Starlink terminal communication. Default: "192.168.100.1:9200".
            */
            [ResourceId(107), Operations("RW")] string gRPC_Endpoint;

            /**
            Number of historical samples available in current data set.
            */
            [ResourceId(110), Operations("R")] long? History_Samples;

            /**
            Time interval between historical samples in seconds.
            */
            [ResourceId(111), Operations("R"), Units("s")] DurationInSeconds? History_Interval;

            /**
            Mean latency across all historical samples including those with packet loss.
            */
            [ResourceId(112), Operations("R"), Units("ms")] double? Mean_Ping_Latency;

            /**
            Mean latency considering only samples with zero packet loss.
            */
            [ResourceId(113), Operations("R"), Units("ms")] double? Mean_Full_Ping_Latency;

            /**
            Standard deviation of latency for zero-loss samples.
            */
            [ResourceId(114), Operations("R"), Units("ms")] double? Stdev_Full_Ping_Latency;

            /**
            Total fraction of sample intervals experiencing packet loss.
            */
            [ResourceId(115), Operations("R")] double? Total_Ping_Drop;

            /**
            Number of samples with 100% packet loss.
            */
            [ResourceId(116), Operations("R")] long? Count_Full_Ping_Drop;

            /**
            Number of samples marked as obstructed.
            */
            [ResourceId(117), Operations("R")] long? Count_Obstructed;

            /**
            JSON array containing latency distribution by deciles (10th, 20th, ... 90th percentile).
            */
            [ResourceId(118), Operations("R")] string Latency_Deciles;

            /**
            JSON formatted statistics about network load distribution across time buckets.
            */
            [ResourceId(119), Operations("R")] string Load_Bucket_Stats;

            /**
            Execute to reboot the Starlink terminal.
            Execute operation on resource 100 (Reboot Terminal); sent by the Server to the Client.
            */
            [ResourceId(100), Operations("E")] public class Reboot_Terminal_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to initiate a speed test. Results available in Speedtest Status (102).
            Execute operation on resource 101 (Start Speedtest); sent by the Server to the Client.
            */
            [ResourceId(101), Operations("E")] public class Start_Speedtest_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to perform factory reset of the terminal. This will erase all configuration.
            Execute operation on resource 103 (Factory Reset); sent by the Server to the Client.
            */
            [ResourceId(103), Operations("E")] public class Factory_Reset_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to retrieve current obstruction map. Data available in Obstruction Map Data (105).
            Execute operation on resource 104 (Get Obstruction Map); sent by the Server to the Client.
            */
            [ResourceId(104), Operations("E")] public class Get_Obstruction_Map_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to force immediate telemetry refresh from the terminal.
            Execute operation on resource 106 (Refresh Telemetry); sent by the Server to the Client.
            */
            [ResourceId(106), Operations("E")] public class Refresh_Telemetry_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10513.xml: Router Management (urn:oma:lwm2m:x:10513) ═════════════════════════
        /**
        This LwM2M Object provides core router configuration and management capabilities for OpenWRT-based routers. It
        enables remote management of network parameters including LAN/WAN configuration, DHCP server settings, DNS
        configuration, and firewall controls. The object supports common router functions essential for IoT gateway
        deployments.
        */
        class Router_Management {
            public const ushort lwm2m_object_id          = 10513;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10513";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Router hostname/device name. This name is used for network identification and management purposes.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Router_Name;

            /**
            Router's LAN-side IP address in dotted decimal notation (e.g., "192.168.1.1").
            */
            [ResourceId(1), Operations("RW"), Mandatory] string LAN_IP_Address;

            /**
            LAN subnet mask in dotted decimal notation (e.g., "255.255.255.0") or CIDR notation.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string LAN_Subnet_Mask;

            /**
            Enable or disable the DHCP server on the LAN interface. When enabled, the router automatically assigns IP
            addresses to LAN clients.
            */
            [ResourceId(3), Operations("RW"), Mandatory] bool DHCP_Enabled;

            /**
            Starting IP address of the DHCP pool (e.g., "192.168.1.100"). This defines the first address that can be
            assigned to DHCP clients.
            */
            [ResourceId(4), Operations("RW")] string DHCP_Start_IP;

            /**
            Ending IP address of the DHCP pool (e.g., "192.168.1.250"). This defines the last address that can be assigned
            to DHCP clients.
            */
            [ResourceId(5), Operations("RW")] string DHCP_End_IP;

            /**
            DHCP lease duration in seconds. Default is typically 12 hours (43200 seconds). Range: 1 minute to 24 hours.
            */
            [MinMax(60, 86400), ResourceId(6), Operations("RW"), Units("s")] uint? DHCP_Lease_Time;

            /**
            Primary DNS server IP address provided to DHCP clients (e.g., "8.8.8.8").
            */
            [ResourceId(7), Operations("RW")] string DNS_Server_1;

            /**
            Secondary DNS server IP address provided to DHCP clients for redundancy.
            */
            [ResourceId(8), Operations("RW")] string DNS_Server_2;

            /**
            WAN connection type: 0=DHCP (automatic), 1=Static IP, 2=PPPoE.
            */
            [MinMax(0, 2), ResourceId(9), Operations("RW"), Mandatory] byte WAN_Connection_Type;

            /**
            Current WAN-side IP address assigned to the router. This is read-only and shows the active WAN IP.
            */
            [ResourceId(10), Operations("R"), Mandatory] string WAN_IP_Address;

            /**
            Current WAN gateway IP address (default route). Read-only.
            */
            [ResourceId(11), Operations("R")] string WAN_Gateway;

            /**
            Enable or disable the router firewall. When disabled, all traffic is permitted (not recommended).
            */
            [ResourceId(12), Operations("RW"), Mandatory] bool Firewall_Enabled;

            /**
            Enable or disable Network Address Translation (NAT) for LAN to WAN connections.
            */
            [ResourceId(13), Operations("RW"), Mandatory] bool NAT_Enabled;

            /**
            Enable or disable Universal Plug and Play (UPnP) for automatic port forwarding by LAN devices.
            */
            [ResourceId(14), Operations("RW")] bool? UPnP_Enabled;

            /**
            Execute to apply pending configuration changes to the router. Changes made to writable resources are committed
            and activated when this action is executed.
            Execute operation on resource 15 (Apply Configuration); sent by the Server to the Client.
            */
            [ResourceId(15), Operations("E"), Mandatory] public class Apply_Configuration_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to reset all router configuration to factory default values. This action requires confirmation and may
            cause temporary network disruption.
            Execute operation on resource 16 (Reset to Defaults); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E")] public class Reset_to_Defaults_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10514.xml: Ethernet Interface (urn:oma:lwm2m:x:10514) ═════════════════════════
        /**
        This LwM2M Object provides management and monitoring of Ethernet network interfaces on OpenWRT-based routers.
        It supports multiple instances for managing different physical Ethernet ports (WAN, LAN, etc.), providing
        real-time statistics on link status, speed, duplex mode, and traffic counters. Essential for monitoring router
        connectivity and network performance.
        */
        class Ethernet_Interface {
            public const ushort lwm2m_object_id          = 10514;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10514";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Network interface name (e.g., "eth0", "eth1", "wan"). This identifies the specific Ethernet interface on the
            system.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Interface_Name;

            /**
            Ethernet port type: 0=LAN (local network), 1=WAN (internet connection).
            */
            [MinMax(0, 1), ResourceId(1), Operations("RW"), Mandatory] byte Port_Type;

            /**
            Current link speed in megabits per second (e.g., 10, 100, 1000, 2500, 10000). Returns 0 if link is down.
            */
            [ResourceId(2), Operations("R"), Units("Mbit/s"), Mandatory] long Speed;

            /**
            Duplex mode: 0=Half-duplex, 1=Full-duplex. Full-duplex allows simultaneous transmit and receive.
            */
            [MinMax(0, 1), ResourceId(3), Operations("R"), Mandatory] byte Duplex;

            /**
            Physical link status: true=Link up (cable connected and link established), false=Link down.
            */
            [ResourceId(4), Operations("R"), Mandatory] bool Link_Status;

            /**
            Hardware MAC address of the interface in colon-separated hexadecimal format (e.g., "00:11:22:33:44:55").
            */
            [ResourceId(5), Operations("R"), Mandatory] string MAC_Address;

            /**
            Maximum Transmission Unit size in bytes. Standard Ethernet MTU is 1500. Jumbo frames up to 9000 bytes may be
            supported.
            */
            [MinMax(576, 9000), ResourceId(6), Operations("RW"), Units("B")] ushort? MTU;

            /**
            Total number of bytes transmitted on this interface since last counter reset or system boot.
            */
            [ResourceId(7), Operations("R"), Units("B"), Mandatory] long Total_Bytes_Sent;

            /**
            Total number of bytes received on this interface since last counter reset or system boot.
            */
            [ResourceId(8), Operations("R"), Units("B"), Mandatory] long Total_Bytes_Received;

            /**
            Total number of packets transmitted on this interface since last counter reset or system boot.
            */
            [ResourceId(9), Operations("R")] long? Total_Packets_Sent;

            /**
            Total number of packets received on this interface since last counter reset or system boot.
            */
            [ResourceId(10), Operations("R")] long? Total_Packets_Received;

            /**
            Total number of transmission errors encountered on this interface.
            */
            [ResourceId(11), Operations("R")] long? Transmit_Errors;

            /**
            Total number of receive errors encountered on this interface including CRC errors, frame errors, etc.
            */
            [ResourceId(12), Operations("R")] long? Receive_Errors;

            /**
            Enable or disable the interface administratively. When disabled, the interface is brought down regardless of
            physical link state.
            */
            [ResourceId(13), Operations("RW"), Mandatory] bool Interface_Enabled;
        }

        // ═════════════════════════ 10515.xml: GPIO Control (urn:oma:lwm2m:x:10515) ═════════════════════════
        /**
        This LwM2M Object provides control and monitoring of GPIO (General Purpose Input/Output) pins on embedded
        devices. It supports management of LEDs, buttons, and general-purpose GPIO pins commonly found on OpenWRT
        routers. Multiple instances allow control of different GPIO resources, enabling remote status indication, user
        input monitoring, and custom hardware interfacing.
        */
        class GPIO_Control {
            public const ushort lwm2m_object_id          = 10515;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10515";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Descriptive name of the GPIO resource (e.g., "LED_STATUS", "LED_WLAN", "BUTTON_RESET", "GPIO_12").
            */
            [ResourceId(0), Operations("RW"), Mandatory] string GPIO_Name;

            /**
            Hardware GPIO pin number as defined by the system GPIO numbering scheme.
            */
            [ResourceId(1), Operations("RW"), Mandatory] byte GPIO_Number;

            /**
            GPIO type: 0=LED (output), 1=Button (input), 2=General GPIO (configurable input/output).
            */
            [MinMax(0, 2), ResourceId(2), Operations("RW"), Mandatory] byte GPIO_Type;

            /**
            Current state of the GPIO: true=High/On/Pressed, false=Low/Off/Released. For LEDs, true means LED is on. For
            buttons, true means currently pressed.
            */
            [ResourceId(3), Operations("RW"), Mandatory] bool Current_State;

            /**
            Enable or disable LED blinking mode. Only applicable for LED type GPIOs. When enabled, the LED blinks at the
            interval specified in Blink Interval.
            */
            [ResourceId(4), Operations("RW")] bool? Blink_Enabled;

            /**
            LED blink interval in milliseconds for the on/off cycle. Only used when Blink Enabled is true.
            */
            [ResourceId(5), Operations("RW"), Units("ms")] DurationInMilliseconds? Blink_Interval;

            /**
            LED trigger mode: 0=None (manual control), 1=Network device activity, 2=Timer-based, 3=Default-on (inverted).
            This controls automatic LED behavior based on system events.
            */
            [MinMax(0, 3), ResourceId(6), Operations("RW")] byte? Trigger_Mode;

            /**
            Current button state: true=Pressed, false=Released. Only applicable for button type GPIOs. This is a real-time
            reading of the button input.
            */
            [ResourceId(7), Operations("R")] bool? Button_State;

            /**
            Total number of button press events detected since last counter reset or system boot. Only applicable for
            button type GPIOs.
            */
            [ResourceId(8), Operations("R")] long? Button_Press_Count;
        }

        // ═════════════════════════ 10516.xml: USB Management (urn:oma:lwm2m:x:10516) ═════════════════════════
        /**
        This LwM2M Object provides monitoring and control of USB ports on embedded devices and routers. It supports
        multiple instances for managing different USB ports, providing information about connected devices, power
        management, and port status. Useful for OpenWRT routers with USB ports for storage, modems, or other
        peripherals.
        */
        class USB_Management {
            public const ushort lwm2m_object_id          = 10516;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10516";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Descriptive name of the USB port (e.g., "USB1", "USB2", "Front_USB", "Type-C").
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Port_Name;

            /**
            USB port type: 0=USB 2.0 Type-A, 1=USB Type-C. This indicates the physical connector type and USB version.
            */
            [MinMax(0, 1), ResourceId(1), Operations("R"), Mandatory] byte Port_Type;

            /**
            Enable or disable the USB port. When disabled, the port is powered down and devices are not recognized.
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool Port_Enabled;

            /**
            USB device connection status: true=Device connected, false=No device connected.
            */
            [ResourceId(3), Operations("R"), Mandatory] bool Device_Connected;

            /**
            Name of the connected USB device as reported by the device (e.g., "SanDisk Ultra", "Huawei LTE Modem"). Empty
            if no device connected.
            */
            [ResourceId(4), Operations("R")] string Device_Name;

            /**
            USB Vendor ID in hexadecimal format (e.g., "0x12d1"). This identifies the device manufacturer.
            */
            [ResourceId(5), Operations("R")] string Device_Vendor_ID;

            /**
            USB Product ID in hexadecimal format (e.g., "0x1506"). Combined with Vendor ID, this uniquely identifies the
            device model.
            */
            [ResourceId(6), Operations("R")] string Device_Product_ID;

            /**
            USB device class (e.g., "Mass Storage", "Communication Device", "Human Interface", "Hub"). This indicates the
            device type and function.
            */
            [ResourceId(7), Operations("R")] string Device_Class;

            /**
            Control USB port power supply: true=Power enabled, false=Power disabled. Some USB ports support power
            switching independent of port enable.
            */
            [ResourceId(8), Operations("RW")] bool? Power_Enabled;

            /**
            Current drawn by the connected USB device in milliamperes. USB 2.0 standard allows up to 500mA, USB 3.0 up to
            900mA, USB-C can provide higher currents.
            */
            [MinMax(0, 3000), ResourceId(9), Operations("R"), Units("mA")] ushort? Current_Draw;
        }

        // ═════════════════════════ 10517.xml: Storage Management (urn:oma:lwm2m:x:10517) ═════════════════════════
        /**
        This LwM2M Object provides management and monitoring of storage devices on embedded systems and routers. It
        supports multiple instances for managing different storage devices including internal NAND/NVMe, SD cards, and
        USB storage. Enables remote monitoring of storage capacity, usage, and basic management operations like
        mount/unmount and formatting.
        */
        class Storage_Management {
            public const ushort lwm2m_object_id          = 10517;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10517";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Descriptive name of the storage device (e.g., "System_NAND", "NVMe_SSD", "USB_Storage", "SD_Card").
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Storage_Name;

            /**
            Storage device type: 0=NAND Flash, 1=NVMe SSD, 2=USB Storage, 3=SD Card.
            */
            [MinMax(0, 3), ResourceId(1), Operations("R"), Mandatory] byte Storage_Type;

            /**
            Filesystem mount point path (e.g., "/", "/mnt/nvme", "/mnt/usb"). This is where the storage is accessible in
            the filesystem.
            */
            [ResourceId(2), Operations("R"), Mandatory] string Mount_Point;

            /**
            Total storage capacity in kibibytes.
            */
            [ResourceId(3), Operations("R"), Units("KiB"), Mandatory] long Total_Capacity;

            /**
            Currently used storage space in kibibytes.
            */
            [ResourceId(4), Operations("R"), Units("KiB"), Mandatory] long Used_Capacity;

            /**
            Available free storage space in kibibytes.
            */
            [ResourceId(5), Operations("R"), Units("KiB"), Mandatory] long Available_Capacity;

            /**
            Storage usage as percentage of total capacity (0-100%).
            */
            [MinMax(0, 100), ResourceId(6), Operations("R"), Units("%"), Mandatory] byte Usage_Percentage;

            /**
            Filesystem type (e.g., "ext4", "f2fs", "vfat", "exfat", "ntfs", "ubifs").
            */
            [ResourceId(7), Operations("R")] string Filesystem_Type;

            /**
            Mount status: true=Currently mounted and accessible, false=Unmounted.
            */
            [ResourceId(8), Operations("R"), Mandatory] bool Is_Mounted;

            /**
            Bootable flag: true=This storage contains bootable system firmware, false=Non-bootable data storage.
            */
            [ResourceId(9), Operations("R")] bool? Is_Bootable;

            /**
            Execute to mount the storage device at its configured mount point.
            Execute operation on resource 10 (Mount); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Mount_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to safely unmount the storage device. Ensures all data is written before disconnection.
            Execute operation on resource 11 (Unmount); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E")] public class Unmount_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to format the storage device. WARNING: This operation will erase all data on the storage device. Use
            with caution.
            Execute operation on resource 12 (Format); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E")] public class Format_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10518.xml: System Monitor (urn:oma:lwm2m:x:10518) ═════════════════════════
        /**
        This LwM2M Object provides comprehensive system monitoring for embedded Linux devices and routers. It reports
        CPU usage, memory statistics, thermal status, and system load metrics. Essential for remote monitoring of
        device health, performance, and resource utilization on OpenWRT-based routers and IoT gateways.
        */
        class System_Monitor {
            public const ushort lwm2m_object_id          = 10518;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10518";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Current CPU utilization as percentage (0-100%). This is the average across all CPU cores if multi-core.
            */
            [MinMax(0, 100), ResourceId(0), Operations("R"), Units("%"), Mandatory] byte CPU_Usage_Percentage;

            /**
            Current CPU operating frequency in megahertz. May vary with dynamic frequency scaling.
            */
            [ResourceId(1), Operations("R"), Units("MHz")] long? CPU_Frequency;

            /**
            Current CPU die temperature in degrees Celsius. Useful for thermal monitoring and throttling detection.
            */
            [Range("-40..125"), ResourceId(2), Operations("R"), Units("Cel")] double? CPU_Temperature;

            /**
            Total system RAM in kibibytes.
            */
            [ResourceId(3), Operations("R"), Units("KiB"), Mandatory] long RAM_Total;

            /**
            Currently used RAM in kibibytes (excluding cached and buffered memory).
            */
            [ResourceId(4), Operations("R"), Units("KiB"), Mandatory] long RAM_Used;

            /**
            Currently free/available RAM in kibibytes.
            */
            [ResourceId(5), Operations("R"), Units("KiB"), Mandatory] long RAM_Free;

            /**
            RAM used for filesystem cache in kibibytes. This memory can be reclaimed if needed.
            */
            [ResourceId(6), Operations("R"), Units("KiB")] long? RAM_Cached;

            /**
            RAM used for kernel buffers in kibibytes.
            */
            [ResourceId(7), Operations("R"), Units("KiB")] long? RAM_Buffers;

            /**
            Total swap space in kibibytes. Returns 0 if swap is not configured.
            */
            [ResourceId(8), Operations("R"), Units("KiB")] long? Swap_Total;

            /**
            Currently used swap space in kibibytes. High swap usage may indicate memory pressure.
            */
            [ResourceId(9), Operations("R"), Units("KiB")] long? Swap_Used;

            /**
            System load average over the last 1 minute. Values above CPU core count indicate CPU saturation.
            */
            [Range("0..1000"), ResourceId(10), Operations("R"), Mandatory] double Load_Average_1min;

            /**
            System load average over the last 5 minutes.
            */
            [Range("0..1000"), ResourceId(11), Operations("R"), Mandatory] double Load_Average_5min;

            /**
            System load average over the last 15 minutes. Provides longer-term load trend information.
            */
            [Range("0..1000"), ResourceId(12), Operations("R"), Mandatory] double Load_Average_15min;

            /**
            System uptime in seconds since last boot.
            */
            [ResourceId(13), Operations("R"), Units("s"), Mandatory] DurationInSeconds Uptime;

            /**
            Total number of running processes on the system.
            */
            [ResourceId(14), Operations("R")] long? Process_Count;
        }

        // ═════════════════════════ 10519.xml: Hardware Watchdog (urn:oma:lwm2m:x:10519) ═════════════════════════
        /**
        This LwM2M Object provides monitoring and management of hardware watchdog timers commonly found in embedded
        systems and IoT devices. The watchdog is a hardware timer that must be periodically reset ("petted") to
        prevent system reboot. This object enables remote configuration and monitoring of watchdog behavior,
        particularly useful for OpenWRT-based routers and similar embedded Linux devices.
        */
        class Hardware_Watchdog {
            public const ushort lwm2m_object_id          = 10519;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10519";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Enable or disable the hardware watchdog. When enabled, the watchdog timer must be periodically reset to
            prevent system reboot. When disabled, the watchdog is stopped and will not trigger a reboot.
            */
            [ResourceId(0), Operations("RW"), Mandatory] bool Watchdog_Enable;

            /**
            The watchdog timeout period in seconds. If the watchdog is not reset within this time period, the hardware
            will trigger a system reboot. Typical values range from 5 to 60 seconds. The actual timeout may be rounded to
            the nearest value supported by the hardware.
            */
            [ResourceId(1), Operations("RW"), Units("s"), Mandatory] DurationInSeconds Timeout;

            /**
            The interval at which the watchdog is automatically reset ("petted") by the system. This should be less than
            the timeout value. Typical values are 1/2 to 2/3 of the timeout period.
            */
            [ResourceId(2), Operations("RW"), Units("s"), Mandatory] DurationInSeconds Pet_Interval;

            /**
            Current watchdog status. Values: 0=Inactive (disabled), 1=Active (running normally), 2=Triggered (reboot in
            progress or imminent), 3=Error (watchdog device unavailable or malfunctioning).
            */
            [MinMax(0, 3), ResourceId(3), Operations("R"), Mandatory] byte Status;

            /**
            Unix timestamp of the last successful watchdog reset operation. This can be used to verify that the watchdog
            is being serviced regularly.
            */
            [ResourceId(4), Operations("R")] DateTime? Last_Pet_Time;

            /**
            Enable the "magic close" feature. When enabled, writing a specific magic character ('V') to the watchdog
            device before closing allows proper shutdown of the watchdog. This is particularly relevant for OpenWRT
            systems using procd.
            */
            [ResourceId(5), Operations("RW")] bool? Magic_Close_Enable;

            /**
            Total number of successful watchdog reset operations since the last system boot or watchdog restart. This
            counter is useful for verifying watchdog activity and debugging.
            */
            [ResourceId(8), Operations("R")] long? Pet_Count;

            /**
            Number of times the watchdog has triggered a system reboot. This value is typically persisted across reboots
            to track system stability. A high value may indicate system instability or software issues.
            */
            [ResourceId(9), Operations("R")] long? Trigger_Count;

            /**
            The file system path to the watchdog device, typically "/dev/watchdog" on Linux systems. This is informational
            and shows which hardware watchdog device is being used.
            */
            [ResourceId(10), Operations("R")] string Device_Path;

            /**
            The actual timeout value configured in the hardware watchdog device, as reported by the driver. This may
            differ from the requested timeout due to hardware limitations or driver rounding.
            */
            [ResourceId(11), Operations("R"), Units("s")] DurationInSeconds? Hardware_Timeout;

            /**
            Total number of system boots detected. When combined with Trigger Count, this helps determine the ratio of
            watchdog-triggered reboots versus normal reboots.
            */
            [ResourceId(12), Operations("R")] long? Boot_Count;

            /**
            Execute this resource to manually reset the watchdog timer. This operation writes to the watchdog device to
            prevent an imminent timeout.
            Execute operation on resource 6 (Pet Watchdog); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E")] public class Pet_Watchdog_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to reset the watchdog configuration to default values and restart the watchdog service.
            Execute operation on resource 7 (Reset Watchdog); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E")] public class Reset_Watchdog_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10520.xml: MIKROBUS (urn:oma:lwm2m:x:10520) ═════════════════════════
        /**
        This LwM2M Object provides comprehensive management and monitoring of MIKROBUS sockets and Click boards.
        MIKROBUS is a standard for add-on boards that defines a specific pinout with SPI, I2C, UART, PWM, GPIO, and
        analog interfaces. This object enables remote configuration of interfaces, GPIO control, Click board
        detection, and power management. Supports multiple instances for managing multiple MIKROBUS sockets on a
        device.
        */
        class MIKROBUS {
            public const ushort lwm2m_object_id          = 10520;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10520";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            MIKROBUS socket number identifier (0, 1, 2, ...).
            */
            [ResourceId(0), Operations("R"), Mandatory] long Socket_ID;

            /**
            Human-readable socket name for identification.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Socket_Name;

            /**
            Socket enabled state. Write false to disable socket, true to enable.
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool Socket_Enabled;

            /**
            True if a Click board is detected in the socket.
            */
            [ResourceId(3), Operations("R"), Mandatory] bool Click_Board_Present;

            /**
            Click board type or category (e.g., "Sensor", "Display", "Wireless").
            */
            [ResourceId(4), Operations("R")] string Click_Board_Type;

            /**
            Socket power voltage in millivolts. Typical values: 3300 (3.3V) or 5000 (5V).
            */
            [ResourceId(5), Operations("RW"), Units("mV"), Mandatory] long Power_Voltage;

            /**
            Socket power state. Write false to disable power, true to enable power to Click board.
            */
            [ResourceId(6), Operations("RW"), Mandatory] bool Power_State;

            /**
            Click board manufacturer name read from manifest.
            */
            [ResourceId(10), Operations("R")] string Board_Manufacturer;

            /**
            Click board model number or name.
            */
            [ResourceId(11), Operations("R")] string Board_Model;

            /**
            Click board firmware or driver version.
            */
            [ResourceId(12), Operations("R")] string Board_Firmware_Version;

            /**
            Click board unique serial number.
            */
            [ResourceId(13), Operations("R")] string Board_Serial_Number;

            /**
            Human-readable board description.
            */
            [ResourceId(14), Operations("R")] string Board_Description;

            /**
            Active communication interface: 0=None, 1=SPI, 2=I2C, 3=UART.
            */
            [MinMax(0, 3), ResourceId(20), Operations("RW"), Mandatory] byte Active_Interface;

            /**
            I2C slave address (7-bit addressing).
            */
            [MinMax(0, 127), ResourceId(21), Operations("RW")] byte? I2C_Address;

            /**
            SPI mode (0-3) defining clock polarity and phase.
            */
            [MinMax(0, 3), ResourceId(22), Operations("RW")] byte? SPI_Mode;

            /**
            SPI clock speed in Hertz.
            */
            [ResourceId(23), Operations("RW"), Units("Hz")] long? SPI_Speed;

            /**
            UART baud rate in bits per second (e.g., 9600, 115200).
            */
            [ResourceId(24), Operations("RW"), Units("B/s")] long? UART_Baud_Rate;

            /**
            UART data bits (7 or 8).
            */
            [MinMax(7, 8), ResourceId(25), Operations("RW")] byte? UART_Data_Bits;

            /**
            UART parity: 0=None, 1=Odd, 2=Even.
            */
            [MinMax(0, 2), ResourceId(26), Operations("RW")] byte? UART_Parity;

            /**
            UART stop bits (1 or 2).
            */
            [MinMax(1, 2), ResourceId(27), Operations("RW")] byte? UART_Stop_Bits;

            /**
            Analog (AN) pin input voltage in volts.
            */
            [Range("0..3.3"), ResourceId(31), Operations("R"), Units("V")] double? AN_Value;

            /**
            PWM duty cycle percentage (0-100%).
            */
            [Range("0..100"), ResourceId(32), Operations("RW"), Units("%")] double? PWM_Duty_Cycle;

            /**
            PWM frequency in Hertz.
            */
            [ResourceId(33), Operations("RW"), Units("Hz")] long? PWM_Frequency;

            /**
            Interrupt (INT) pin state. True=high, false=low.
            */
            [ResourceId(34), Operations("R")] bool? INT_Pin_State;

            /**
            Reset (RST) pin state. Write false to assert reset (active low), true to deassert.
            */
            [ResourceId(35), Operations("RW")] bool? RST_Pin_State;

            /**
            Chip Select (CS) pin state for SPI. Write false to activate (active low), true to deactivate.
            */
            [ResourceId(36), Operations("RW")] bool? CS_Pin_State;

            /**
            Communication status: 0=OK, 1=Error, 2=Timeout, 3=Not Configured.
            */
            [MinMax(0, 3), ResourceId(40), Operations("R"), Mandatory] byte Communication_Status;

            /**
            Last error message or status description.
            */
            [ResourceId(41), Operations("R")] string Last_Error;

            /**
            Total number of I/O transactions performed on this socket.
            */
            [ResourceId(42), Operations("R")] long? Transaction_Count;

            /**
            Total number of errors encountered on this socket.
            */
            [ResourceId(43), Operations("R")] long? Error_Count;

            /**
            Socket uptime in seconds since last initialization.
            */
            [ResourceId(44), Operations("R"), Units("s")] DurationInSeconds? Uptime;

            /**
            Click board manifest data in JSON format containing manufacturer, model, serial number, and capabilities.
            */
            [ResourceId(111), Operations("R")] string Manifest_Data;

            /**
            Execute to initialize the Click board (enable power, detect board, configure interface).
            Execute operation on resource 101 (Init Click Board); sent by the Server to the Client.
            */
            [ResourceId(101), Operations("E")] public class Init_Click_Board_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to reset the Click board via RST pin.
            Execute operation on resource 102 (Reset Click Board); sent by the Server to the Client.
            */
            [ResourceId(102), Operations("E")] public class Reset_Click_Board_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to shutdown the Click board (disable power, reset interface).
            Execute operation on resource 103 (Shutdown Click Board); sent by the Server to the Client.
            */
            [ResourceId(103), Operations("E")] public class Shutdown_Click_Board_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to read Click board manifest from EEPROM or I2C. Results available in Manifest Data (111).
            Execute operation on resource 110 (Read Manifest); sent by the Server to the Client.
            */
            [ResourceId(110), Operations("E")] public class Read_Manifest_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10521.xml: Firewall Config (urn:oma:lwm2m:x:10521) ═════════════════════════
        /**
        This LwM2M Object provides management of firewall rules for OpenWRT-based routers. It enables remote
        configuration of iptables/nftables firewall rules including port filtering, IP address filtering, protocol
        filtering, and zone-based firewall management. Each instance represents a single firewall rule that can be
        created, modified, enabled/disabled, or deleted remotely. The object integrates with OpenWRT's UCI
        configuration system and supports both IPv4 and IPv6 rules.
        */
        class Firewall_Config {
            public const ushort lwm2m_object_id          = 10521;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10521";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Human-readable name for this firewall rule. Used for identification in the UCI configuration and logging. Must
            be unique within the firewall configuration.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Rule_Name;

            /**
            Priority index of this rule in the firewall chain. Lower values indicate higher priority (processed first).
            This value is automatically assigned based on rule order in the configuration.
            */
            [ResourceId(1), Operations("R"), Mandatory] long Rule_Index;

            /**
            Enable or disable this firewall rule. When disabled, the rule remains in configuration but is not active in
            the firewall chain. Default is true (enabled).
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool Enabled;

            /**
            Action to take when packet matches this rule: 0=ACCEPT (allow the packet through), 1=REJECT (reject with ICMP
            error response), 2=DROP (silently discard the packet).
            */
            [MinMax(0, 2), ResourceId(3), Operations("RW"), Mandatory] byte Action;

            /**
            IP protocol to match: 0=ALL (any protocol), 1=TCP, 2=UDP, 3=ICMP. When set to ALL, port specifications are
            ignored.
            */
            [MinMax(0, 3), ResourceId(4), Operations("RW"), Mandatory] byte Protocol;

            /**
            Source IP address or CIDR network to match (e.g., "192.168.1.0/24", "10.0.0.1", or "0.0.0.0/0" for any).
            Supports IPv4 and IPv6 addresses. Empty string matches any source.
            */
            [ResourceId(5), Operations("RW")] string Source_IP;

            /**
            Source port number to match (1-65535). Value of 0 means match any source port. Only applicable when Protocol
            is TCP or UDP.
            */
            [ResourceId(6), Operations("RW")] ushort? Source_Port;

            /**
            Destination IP address or CIDR network to match (e.g., "192.168.1.0/24", "10.0.0.1"). Supports IPv4 and IPv6
            addresses. Empty string matches any destination.
            */
            [ResourceId(7), Operations("RW")] string Destination_IP;

            /**
            Destination port number to match (1-65535). Value of 0 means match any destination port. Only applicable when
            Protocol is TCP or UDP.
            */
            [ResourceId(8), Operations("RW")] ushort? Destination_Port;

            /**
            Network interface name to which this rule applies (e.g., "eth0", "br-lan", "wan"). Empty string matches all
            interfaces.
            */
            [ResourceId(9), Operations("RW")] string Interface;

            /**
            Traffic direction for rule matching: 0=INPUT (incoming traffic destined for router), 1=OUTPUT (outgoing
            traffic from router), 2=FORWARD (traffic routed through the router).
            */
            [MinMax(0, 2), ResourceId(10), Operations("RW"), Mandatory] byte Direction;

            /**
            Source firewall zone name for zone-based rules (e.g., "lan", "wan", "guest"). OpenWRT zone-based firewall
            integration.
            */
            [ResourceId(11), Operations("RW")] string Zone_From;

            /**
            Destination firewall zone name for zone-based rules (e.g., "lan", "wan", "guest"). Used with Zone From for
            inter-zone traffic rules.
            */
            [ResourceId(12), Operations("RW")] string Zone_To;

            /**
            Optional comment or description for this rule. Used for documentation purposes and appears in iptables rule
            comments.
            */
            [ResourceId(13), Operations("RW")] string Comment;

            /**
            Execute to apply this rule to the active firewall configuration. Saves the rule to UCI and reloads the
            firewall service.
            Execute operation on resource 14 (Apply Rule); sent by the Server to the Client.
            */
            [ResourceId(14), Operations("E"), Mandatory] public class Apply_Rule_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to delete this rule from the firewall configuration. Removes the rule from UCI and reloads the
            firewall service.
            Execute operation on resource 15 (Delete Rule); sent by the Server to the Client.
            */
            [ResourceId(15), Operations("E"), Mandatory] public class Delete_Rule_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10522.xml: PoE Management (urn:oma:lwm2m:x:10522) ═════════════════════════
        /**
        This LwM2M Object provides monitoring and control of Power over Ethernet (PoE) functionality on devices that
        support IEEE 802.3af/at/bt standards. It enables remote monitoring of PoE power input including voltage,
        current, and power consumption. For Powered Devices (PD), it provides visibility into the power being
        received. The object supports detection of PoE standard in use (af, at, bt), power class negotiation, and
        power cycling for recovery scenarios.
        */
        class PoE_Management {
            public const ushort lwm2m_object_id          = 10522;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10522";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Indicates whether the device hardware supports Power over Ethernet. True if PoE circuitry is present and
            functional, false if the device does not have PoE capability.
            */
            [ResourceId(0), Operations("R"), Mandatory] bool PoE_Supported;

            /**
            Enable or disable PoE power input. When disabled, the device will not draw power from the PoE source even if
            available. Useful for power management or when using alternative power sources.
            */
            [ResourceId(1), Operations("RW"), Mandatory] bool PoE_Enabled;

            /**
            Current PoE input voltage in volts. Typical values: 48V for 802.3af/at, 52-57V for 802.3bt. Returns 0 if PoE
            is not active or not connected.
            */
            [Range("0..57"), ResourceId(2), Operations("R"), Units("V"), Mandatory] double Input_Voltage;

            /**
            Current being drawn from the PoE source in amperes. Maximum depends on PoE class: ~350mA for Class 1, ~600mA
            for Class 3, ~950mA for Class 4, up to 1900mA for 802.3bt Type 4.
            */
            [Range("0..2"), ResourceId(3), Operations("R"), Units("A"), Mandatory] double Input_Current;

            /**
            Current power consumption from PoE source in watts. Calculated as Input Voltage x Input Current. Maximum
            values: 15.4W (af), 30W (at), 60W (bt Type 3), 90W+ (bt Type 4).
            */
            [Range("0..100"), ResourceId(4), Operations("R"), Units("W"), Mandatory] double Input_Power;

            /**
            Detected or configured PoE standard: "802.3af" (PoE, 15.4W), "802.3at" (PoE+, 30W), "802.3bt" (PoE++,
            60-90W+), or "None" if PoE is not active.
            */
            [ResourceId(5), Operations("R"), Mandatory] string PoE_Standard;

            /**
            Negotiated PoE power class (0-8). Class 0-3: 802.3af (0=default 15.4W, 1=4W, 2=7W, 3=15.4W). Class 4: 802.3at
            (30W). Class 5-8: 802.3bt (5=45W, 6=60W, 7=75W, 8=90W+).
            */
            [MinMax(0, 8), ResourceId(6), Operations("R"), Mandatory] byte PoE_Class;

            /**
            Maximum power available from the PSE (Power Sourcing Equipment) based on negotiated class and PSE capability.
            This is the upper limit the device can draw.
            */
            [ResourceId(7), Operations("R"), Units("W")] double? Maximum_Power;

            /**
            Power allocated by the PSE for this device. May differ from Maximum Power based on PSE power budget management
            and LLDP-MED negotiation.
            */
            [ResourceId(8), Operations("R"), Units("W")] double? Power_Allocated;

            /**
            PoE controller or PD interface chip temperature in degrees Celsius. High temperatures may indicate overload or
            thermal issues. Operating range typically -40 to 85C.
            */
            [Range("-40..125"), ResourceId(9), Operations("R"), Units("Cel")] double? Temperature;

            /**
            Human-readable status string indicating PoE state: "Active" (powered via PoE), "Inactive" (PoE not in use),
            "Detecting" (PoE detection in progress), "Fault" (PoE error), "Disabled" (PoE disabled).
            */
            [ResourceId(10), Operations("R"), Mandatory] string Status;

            /**
            Execute to perform a PoE power cycle. Temporarily disables PoE input then re-enables it, forcing
            re-negotiation with the PSE. Useful for recovering from fault conditions.
            Execute operation on resource 11 (Reset PoE); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E")] public class Reset_PoE_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10523.xml: Send Scheduler Control (urn:oma:lwm2m:x:10523:1.0) ═════════════════════════
        /**
        Controls buffering behaviour of the send scheduler.
        */
        class Send_Scheduler_Control {
            public const ushort lwm2m_object_id          = 10523;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10523:1.0";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Set to true to pause accumulation; clearing the flag resumes scheduling.
            */
            [ResourceId(0), Operations("RW"), Mandatory] bool Paused;

            /**
            Number of buffered samples allowed before a transmission is forced.
            */
            [ResourceId(1), Operations("RW"), Mandatory] long Max_Samples;

            /**
            Maximum age in seconds permitted for the oldest buffered sample before a transmission is forced.
            */
            [ResourceId(2), Operations("RW"), Units("s"), Mandatory] long Max_Old;

            /**
            When true (default), trigger a send of buffered data after each Registration Update.
            */
            [ResourceId(4), Operations("RW"), Mandatory] bool Flush_On_Registration_Update;

            /**
            Execute to trigger an immediate data push for all resources covered by active sampling rules.
            Execute operation on resource 3 (Flush); sent by the Server to the Client.
            */
            [ResourceId(3), Operations("E")] public class Flush_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10524.xml: Send Scheduler Sampling Rules (urn:oma:lwm2m:x:10524:1.0) ═════════════════════════
        /**
        Defines per-resource sampling rules used by the send scheduler.
        */
        class Send_Scheduler_Sampling_Rules {
            public const ushort lwm2m_object_id          = 10524;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10524:1.0";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            LwM2M resource path to monitor, e.g. /3303/0/5700. The value must reference a resource
            (/Object/Instance/Resource) with numeric segments.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Path;

            /**
            Rule strings formatted as attribute=value. Supported attributes are pmin, pmax, epmin, epmax (integer values)
            and gt, lt, st (floating point values). Each attribute may appear at most once per instance. Example:
            "pmin=10,pmax=60,gt=25.0".
            */
            [ResourceId(1), Operations("RW")] string[,,] Collection_Rules;
        }

        // ═════════════════════════ 10525.xml: WAN Failover Policy (urn:oma:lwm2m:x:10525) ═════════════════════════
        /**
        Multi-WAN failover configuration. Priority-based WAN selection, failover triggers, and load balancing
        policies.
        */
        class WAN_Failover_Policy {
            public const ushort lwm2m_object_id          = 10525;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10525";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Unique identifier name for this failover policy (e.g., "critical_services", "office_wan"). Used to reference
            the policy in routing rules and mwan3 configuration. Must be alphanumeric with underscores, no spaces.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Policy_Name;

            /**
            Primary WAN interface name (e.g., "wan", "eth1"). This is the preferred interface that will be used under
            normal conditions. Must be a valid network interface name that exists on the system. In failover mode, all
            traffic uses this interface unless it becomes unavailable.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Primary_WAN;

            /**
            Secondary WAN interface name (e.g., "wan2", "usb0"). Backup interface that becomes active when primary fails
            or shares load in load-balancing mode. Must be a valid network interface. Can be left empty if only one WAN is
            available.
            */
            [ResourceId(2), Operations("RW")] string Secondary_WAN;

            /**
            Tertiary WAN interface name (e.g., "wan3", "wwan0"). Third-level backup interface for maximum redundancy. Used
            when both primary and secondary interfaces fail, or participates in multi-WAN load balancing. Optional for
            deployments requiring three or more WAN connections.
            */
            [ResourceId(3), Operations("RW")] string Tertiary_WAN;

            /**
            Failover policy mode: 0=Failover (use primary, switch to backup only on failure), 1=Load Balance (distribute
            traffic across interfaces based on weights), 2=Round Robin (distribute connections evenly regardless of
            weights). Failover mode prioritizes primary interface. Load Balance mode uses weight ratios for traffic
            distribution. Round Robin mode distributes new connections sequentially across all available interfaces.
            */
            [MinMax(0, 2), ResourceId(4), Operations("RW"), Mandatory] byte Mode;

            /**
            Traffic weight for primary WAN interface in load-balancing mode (range: 1-100). Higher values direct more
            traffic to this interface. For example, primary weight 70 + secondary weight 30 results in 70% of traffic
            using primary. Ignored in pure failover mode. Weights are relative to total of all interface weights.
            */
            [MinMax(1, 100), ResourceId(5), Operations("RW")] byte? Primary_Weight;

            /**
            Traffic weight for secondary WAN interface in load-balancing mode (range: 1-100). Used to control the
            proportion of traffic sent through the secondary interface. Set based on interface capacity - for example, if
            secondary has half the bandwidth of primary, use half the weight.
            */
            [MinMax(1, 100), ResourceId(6), Operations("RW")] byte? Secondary_Weight;

            /**
            Traffic weight for tertiary WAN interface in load-balancing mode (range: 1-100). Allows fine-tuning of traffic
            distribution across three WAN connections. Particularly useful for asymmetric bandwidth scenarios where
            tertiary link has different capacity than primary and secondary.
            */
            [MinMax(1, 100), ResourceId(7), Operations("RW")] byte? Tertiary_Weight;

            /**
            Number of consecutive failed health check pings before triggering failover (range: 1-20 pings). Lower values
            enable faster failover but may cause unnecessary switches due to transient issues. Higher values provide
            stability but slower failure detection. Common values: 3 for responsive failover, 5 for balanced, 10 for very
            stable connections. Health checks typically run every 10 seconds.
            */
            [MinMax(1, 20), ResourceId(8), Operations("RW")] byte? Failover_Threshold;

            /**
            Failback behavior when primary interface is restored: 0=Immediate (switch back as soon as primary is healthy),
            1=Delayed (wait for configured delay period to ensure stability), 2=Manual (only failback when explicitly
            commanded). Immediate mode maximizes use of primary link but may cause connection disruption if primary is
            flapping. Delayed mode adds stability. Manual mode provides maximum control for maintenance scenarios.
            */
            [MinMax(0, 2), ResourceId(9), Operations("RW")] byte? Failback_Mode;

            /**
            Time to wait before failing back to primary WAN after it recovers (range: 0-3600 seconds). Only applicable
            when Failback Mode is set to Delayed (1). Ensures primary interface is truly stable before switching back.
            Recommended values: 60 seconds for quick failback, 300 seconds (5 minutes) for cautious approach. Zero delay
            with delayed mode behaves like immediate mode.
            */
            [ResourceId(10), Operations("RW"), Units("s")] DurationInSeconds? Failback_Delay;

            /**
            Currently active WAN interface name (read-only). Shows which interface is actively routing traffic. In
            failover mode, this is the single active interface. In load-balancing/round-robin modes, this shows the
            primary routing interface. Updated automatically based on real-time interface health status and failover
            events. Empty string indicates no WAN is currently active.
            */
            [ResourceId(11), Operations("R"), Mandatory] string Current_Active_WAN;

            /**
            Current operational state of the failover policy: 0=Inactive (policy configured but not applied to routing),
            1=Active (policy is running and managing WAN failover), 2=Error (policy application failed or runtime error
            occurred). Check this after executing Apply Policy to verify success. Error state may indicate invalid
            interface names, mwan3 configuration issues, or system resource problems.
            */
            [MinMax(0, 2), ResourceId(12), Operations("R"), Mandatory] byte Policy_State;

            /**
            Unix timestamp of the most recent failover event (read-only). Records when the system last switched from one
            WAN interface to another due to failure detection. Value is 0 if no failover has occurred since policy
            activation. Useful for monitoring failover frequency and correlating with network events. Can be reset using
            Reset Counters execute resource.
            */
            [ResourceId(13), Operations("R")] DateTime? Last_Failover_Time;

            /**
            Total number of failover events since policy activation or last counter reset (read-only). Increments each
            time the system switches from one WAN to another. High values may indicate unstable WAN connections requiring
            investigation. Use Reset Counters to clear for new monitoring periods. Useful for SLA tracking and identifying
            problematic interfaces.
            */
            [ResourceId(14), Operations("R")] long? Failover_Count;

            /**
            Enable connection tracking to maintain existing connections through same interface (sticky sessions). When
            enabled (true), active connections continue using their original WAN interface even during load rebalancing or
            after interface recovery. When disabled (false), new routing decisions apply immediately to all traffic.
            Enable for services requiring consistent source IP (VPN, banking, streaming). Disable for maximum load
            distribution flexibility.
            */
            [ResourceId(15), Operations("RW")] bool? Sticky_Connections;

            /**
            Policy-based routing rules in format "interface:protocol:port" (e.g., "wan:tcp:443", "wan2:udp:53"). Forces
            specific traffic types to use designated WAN interfaces regardless of failover policy. Multiple rules can be
            defined for granular traffic control. Useful for scenarios like routing VoIP through high-quality WAN, gaming
            through low-latency WAN, or backup traffic through secondary WAN. Protocol can be tcp, udp, icmp, or all. Port
            can be specific number or range.
            */
            [ResourceId(16), Operations("RW")] string[,,] Interface_Rules;

            /**
            Execute to apply the current failover policy configuration to the system. Validates interface existence,
            writes mwan3 configuration files, sets up health check monitors for all configured WANs, configures
            policy-based routing tables, applies load balancing weights (if applicable), and restarts the mwan3 service.
            After execution, check Policy State to verify successful application. This operation may briefly interrupt
            active connections during mwan3 restart.
            Execute operation on resource 17 (Apply Policy); sent by the Server to the Client.
            */
            [ResourceId(17), Operations("E"), Mandatory] public class Apply_Policy_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to manually trigger immediate failover to the next available WAN interface in priority order (primary
            → secondary → tertiary). Overrides health check status and forces interface switch. Useful for maintenance
            scenarios, testing failover procedures, or manually recovering from detected issues. Updates Current Active
            WAN, Last Failover Time, and increments Failover Count. Does not change policy configuration.
            Execute operation on resource 18 (Force Failover); sent by the Server to the Client.
            */
            [ResourceId(18), Operations("E")] public class Force_Failover_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to manually trigger immediate failback to the primary WAN interface. Overrides failback mode and delay
            settings. Fails if primary interface is not available. Useful for completing maintenance windows, testing
            primary link restoration, or ending manual failover mode. Particularly important when Failback Mode is set to
            Manual (2), as this is the only way to restore primary WAN usage.
            Execute operation on resource 19 (Force Failback); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E")] public class Force_Failback_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to reset failover statistics counters. Clears Failover Count to 0 and resets Last Failover Time to 0.
            Does not affect current operational state or active interface. Use at the start of new monitoring periods,
            after maintenance, or when beginning SLA measurement intervals. Provides clean baseline for tracking failover
            events and system stability.
            Execute operation on resource 20 (Reset Counters); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E")] public class Reset_Counters_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10526.xml: Multi-WAN Health Check (urn:oma:lwm2m:x:10526) ═════════════════════════
        /**
        WAN connection health monitoring with ping/HTTP checks, latency tracking, and automatic failover triggers.
        */
        class Multi_WAN_Health_Check {
            public const ushort lwm2m_object_id          = 10526;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10526";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Network interface name to monitor (e.g., "wan", "wan2", "wwan0"). This identifies the WAN interface being
            health-checked. Must correspond to an existing network interface configured in the system. Each health check
            instance monitors a single interface.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Interface_Name;

            /**
            Type of health check probe to execute: 0=ICMP Ping (raw socket ICMP echo request/reply, requires
            root/CAP_NET_RAW), 1=HTTP/HTTPS (TCP connection and HTTP HEAD request to web server), 2=DNS (DNS hostname
            resolution test), 3=TCP (simple TCP connection test to specified port). Different probe types have different
            characteristics - ICMP is lightweight but may be blocked by firewalls, HTTP validates application layer, DNS
            tests name resolution, TCP verifies port reachability.
            */
            [MinMax(0, 3), ResourceId(1), Operations("RW"), Mandatory] byte Probe_Type;

            /**
            Target host for health check probes, specified as either an IPv4 address (e.g., "8.8.8.8") or hostname (e.g.,
            "www.google.com"). The target should be a reliable, always-available host that can respond to the configured
            probe type. Common choices include public DNS servers (8.8.8.8, 1.1.1.1) for ICMP/DNS probes, or well-known
            websites for HTTP probes. The target must be reachable through the monitored WAN interface.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string Target_Host;

            /**
            TCP/UDP port number for HTTP and TCP probe types (range: 1-65535). Not used for ICMP or DNS probes. Common
            values: 80 (HTTP), 443 (HTTPS), 53 (DNS over TCP). The specified port must be open and accepting connections
            on the target host for the probe to succeed.
            */
            [MinMax(1, 65535), ResourceId(3), Operations("RW")] ushort? Target_Port;

            /**
            Time interval between consecutive health check probes in seconds (range: 1-3600 seconds / 1 second to 1 hour).
            Shorter intervals provide faster failure detection but increase network overhead and system load. Typical
            values: 10 seconds for critical links, 30 seconds for normal monitoring, 60+ seconds for low-priority
            monitoring. Balance between responsiveness and resource consumption based on deployment requirements.
            */
            [ResourceId(4), Operations("RW"), Units("s"), Mandatory] DurationInSeconds Probe_Interval;

            /**
            Maximum time to wait for a probe response in milliseconds (range: 100-30000 ms / 0.1-30 seconds). If the
            target doesn't respond within this timeout, the probe is considered failed. Must be shorter than the probe
            interval. Typical values: 2000ms for local/low-latency links, 5000ms for satellite/high-latency links.
            Consider expected network latency and jitter when setting this value.
            */
            [ResourceId(5), Operations("RW"), Units("ms"), Mandatory] DurationInMilliseconds Probe_Timeout;

            /**
            Number of consecutive failed probes before marking the interface as unhealthy (range: 1-100). Higher values
            reduce false positives from transient failures but delay failure detection. The interface transitions from
            HEALTHY to DEGRADED at half this threshold, then to UNHEALTHY at the full threshold. Typical values: 3 for
            aggressive failover, 5 for balanced monitoring, 10 for conservative monitoring. Consider network stability
            when configuring.
            */
            [MinMax(1, 100), ResourceId(6), Operations("RW"), Mandatory] byte Failure_Threshold;

            /**
            Number of consecutive successful probes before marking an unhealthy interface as healthy again (range: 1-100).
            Higher values prevent premature recovery from intermittent success but delay interface restoration. This
            threshold prevents interface flapping by requiring sustained success before returning to service. Typical
            values: 3 for quick recovery, 5 for balanced recovery, 10 for conservative recovery. Often set equal to or
            higher than failure threshold.
            */
            [MinMax(1, 100), ResourceId(7), Operations("RW"), Mandatory] byte Recovery_Threshold;

            /**
            Current health state of the monitored interface: 0=HEALTHY (interface is functioning normally, all recent
            probes successful), 1=DEGRADED (interface experiencing intermittent failures, consecutive failures below full
            threshold), 2=UNHEALTHY (interface has failed, consecutive failures exceeded threshold). State transitions use
            hysteresis via separate failure and recovery thresholds to prevent flapping. Read-only resource updated
            automatically by the health check state machine.
            */
            [MinMax(0, 2), ResourceId(8), Operations("R"), Mandatory] byte Current_State;

            /**
            Unix timestamp of the most recent probe execution. Updated after each probe attempt regardless of success or
            failure. Use this to verify that probing is active and to calculate time since last check. Can be compared
            with current time to detect if health checking has stopped unexpectedly.
            */
            [ResourceId(9), Operations("R"), Mandatory] DateTime Last_Probe_Time;

            /**
            Result of the most recent probe: true=SUCCESS (probe completed successfully within timeout), false=FAILURE
            (probe timed out, connection refused, or other error). This provides immediate visibility into the latest
            probe outcome. Multiple consecutive failures trigger state transitions based on the failure threshold.
            */
            [ResourceId(10), Operations("R"), Mandatory] bool Last_Probe_Result;

            /**
            Exponential moving average (EMA) of probe latency in milliseconds. Uses alpha=0.2 (20% weight to new values,
            80% to historical average) for smooth tracking of latency trends while responding to changes. Only updated for
            successful probes. Provides a representative measure of typical interface latency, smoothing out short-term
            variations. Useful for comparing interface performance and detecting gradual degradation.
            */
            [ResourceId(11), Operations("R"), Units("ms"), Mandatory] double Average_Latency;

            /**
            Minimum observed latency across all successful probes in milliseconds. Represents the best-case performance of
            the interface. Can be used to establish baseline performance expectations. Reset to 0 when statistics are
            reset. Useful for capacity planning and identifying optimal interface characteristics.
            */
            [ResourceId(12), Operations("R"), Units("ms"), Mandatory] double Min_Latency;

            /**
            Maximum observed latency across all successful probes in milliseconds. Represents worst-case performance while
            still meeting success criteria (below timeout). Indicates peak latency experienced during monitoring period.
            Large differences between min and max suggest variable/inconsistent link performance. Reset to 0 when
            statistics are reset.
            */
            [ResourceId(13), Operations("R"), Units("ms"), Mandatory] double Max_Latency;

            /**
            Mean absolute deviation of latency between consecutive probes in milliseconds. Measures latency
            variation/instability - low jitter indicates consistent performance, high jitter suggests
            variable/unpredictable link behavior. Calculated from the last 100 latency samples. Critical for real-time
            applications (VoIP, video conferencing) which are sensitive to timing variations. Values above 30ms can impact
            VoIP quality.
            */
            [ResourceId(14), Operations("R"), Units("ms"), Mandatory] double Jitter;

            /**
            Percentage of failed probes out of total probes executed (range: 0.0-100.0%). Calculated as (Failed Probes /
            Total Probes) × 100. Provides overall reliability metric for the monitored interface. Even small packet loss
            (&gt;1%) can significantly impact application performance. Reset when statistics are reset via the Reset Stats
            execute resource.
            */
            [Range("0.0..100.0"), ResourceId(15), Operations("R"), Units("%"), Mandatory] double Packet_Loss;

            /**
            Current count of consecutive failed probes. Increments with each failure, resets to 0 on any success. Used by
            the health state machine to determine interface health transitions. When this counter reaches half of Failure
            Threshold, the state transitions to DEGRADED. When it reaches the full Failure Threshold, the state
            transitions to UNHEALTHY. Provides visibility into how close the interface is to being marked down.
            */
            [ResourceId(16), Operations("R"), Mandatory] long Consecutive_Failures;

            /**
            Current count of consecutive successful probes. Increments with each success, resets to 0 on any failure. Used
            by the health state machine to determine interface recovery transitions. When this counter reaches Recovery
            Threshold, an unhealthy or degraded interface transitions back to HEALTHY state. Provides visibility into
            recovery progress for failed interfaces.
            */
            [ResourceId(17), Operations("R"), Mandatory] long Consecutive_Successes;

            /**
            Total number of probes executed since monitoring started or statistics were last reset. Includes both
            successful and failed probes. Increments with every probe attempt. Used as denominator for packet loss
            percentage calculation. Provides context for other statistics - higher values indicate more
            established/reliable statistics. Reset to 0 when statistics are reset.
            */
            [ResourceId(18), Operations("R"), Mandatory] long Total_Probes;

            /**
            Total number of failed probes since monitoring started or statistics were last reset. Increments with each
            probe failure (timeout, connection refused, etc.). Used as numerator for packet loss percentage calculation.
            Comparing with Total Probes provides overall interface reliability. Reset to 0 when statistics are reset.
            */
            [ResourceId(19), Operations("R"), Mandatory] long Failed_Probes;

            /**
            Execute this resource to start active health check probing for the interface. Activates the asynchronous probe
            worker thread which will execute probes at the configured interval. Probing continues until explicitly stopped
            via Stop Probing or the instance is destroyed. Can be called multiple times (idempotent). Safe to call on
            already-active probing.
            Execute operation on resource 20 (Start Probing); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E"), Mandatory] public class Start_Probing_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to stop active health check probing for the interface. Suspends the probe worker thread,
            no further probes will be executed until Start Probing is called again. Existing statistics and health state
            are preserved. Useful for temporarily disabling monitoring without destroying the instance configuration. Can
            be called multiple times (idempotent).
            Execute operation on resource 21 (Stop Probing); sent by the Server to the Client.
            */
            [ResourceId(21), Operations("E"), Mandatory] public class Stop_Probing_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to immediately trigger a health check probe outside the normal interval schedule. Does
            not affect the regular probe schedule - the next scheduled probe will still occur at the configured interval.
            Useful for manual verification, troubleshooting, or forcing immediate health state updates after configuration
            changes. Probe result updates all statistics and health state normally.
            Execute operation on resource 22 (Force Check); sent by the Server to the Client.
            */
            [ResourceId(22), Operations("E"), Mandatory] public class Force_Check_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to reset all statistical counters and measurements to their initial values:
            Average/Min/Max Latency=0.0, Jitter=0.0, Packet Loss=0.0%, Consecutive Failures/Successes=0, Total Probes=0,
            Failed Probes=0. Clears latency history used for jitter calculation. Does not affect current health state,
            probe configuration, or active probing status. Useful after configuration changes or to establish new baseline
            measurements.
            Execute operation on resource 23 (Reset Stats); sent by the Server to the Client.
            */
            [ResourceId(23), Operations("E"), Mandatory] public class Reset_Stats_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10527.xml: WiFi Client Management (urn:oma:lwm2m:x:10527) ═════════════════════════
        /**
        Connected WiFi client tracking and management. Client statistics, signal strength, bandwidth usage, and access
        control.
        */
        class WiFi_Client_Management {
            public const ushort lwm2m_object_id          = 10527;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10527";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            MAC address of the connected WiFi client in colon-separated hexadecimal format (e.g., "AA:BB:CC:DD:EE:FF").
            This uniquely identifies each client device on the wireless network. Read-only value automatically populated
            when the client associates with the access point.
            */
            [ResourceId(0), Operations("R"), Mandatory] string MAC_Address;

            /**
            IPv4 address assigned to the client (e.g., "192.168.1.100"). Obtained from ARP cache or DHCP lease table. May
            be empty if the client hasn't completed network layer configuration or is using IPv6 only.
            */
            [ResourceId(1), Operations("R")] string IP_Address;

            /**
            Hostname of the client device as provided during DHCP negotiation or resolved via DNS/mDNS. Useful for
            identifying devices by human-readable names. Shows "unknown" if hostname information is unavailable.
            */
            [ResourceId(2), Operations("R")] string Hostname;

            /**
            Wireless interface to which this client is connected (e.g., "wlan0", "wlan1"). Identifies which physical or
            virtual access point interface is serving this client, important for multi-SSID or multi-radio configurations.
            */
            [ResourceId(3), Operations("R"), Mandatory] string Interface;

            /**
            Received Signal Strength Indicator (RSSI) in dBm (typical range: -100 to -30 dBm). Negative values closer to 0
            indicate stronger signals. Values above -50 dBm are excellent, -50 to -60 dBm good, -60 to -70 dBm fair, below
            -70 dBm poor. Essential for troubleshooting connectivity issues and optimizing AP placement.
            */
            [MinMax(-100, -30), ResourceId(4), Operations("R"), Units("dBm"), Mandatory] sbyte Signal_Strength;

            /**
            Background noise level on the wireless channel in dBm. Represents environmental RF interference. Typical WiFi
            noise floors range from -95 to -85 dBm. Used to calculate Signal-to-Noise Ratio (SNR).
            */
            [MinMax(-100, -80), ResourceId(5), Operations("R"), Units("dBm")] sbyte? Noise_Level;

            /**
            Signal-to-Noise Ratio in dB, calculated as (RSSI - Noise Level). Indicates signal quality relative to
            background noise. Higher values are better: &gt;40 dB excellent, 25-40 dB good, 15-25 dB fair, &lt;15 dB poor.
            More reliable than RSSI alone for assessing connection quality.
            */
            [MinMax(0, 70), ResourceId(6), Operations("R"), Units("dB")] byte? SNR;

            /**
            Current transmit data rate from access point to client in Mbps. Dynamically adjusted based on signal quality
            and channel conditions. Maximum rates depend on WiFi standard: 802.11b (11 Mbps), 802.11g (54 Mbps), 802.11n
            (600 Mbps), 802.11ac (6933 Mbps), 802.11ax (9608 Mbps).
            */
            [MinMax(1, 9608), ResourceId(7), Operations("R"), Units("Mbit/s")] ushort? TX_Rate;

            /**
            Current receive data rate from client to access point in Mbps. Dynamically adjusted based on signal quality
            and channel conditions. May differ from TX rate due to asymmetric channel conditions or client capabilities.
            */
            [MinMax(1, 9608), ResourceId(8), Operations("R"), Units("Mbit/s")] ushort? RX_Rate;

            /**
            Total number of bytes transmitted from access point to client since connection establishment. Monotonically
            increasing counter useful for bandwidth usage monitoring and accounting. Resets to zero when client
            reconnects.
            */
            [ResourceId(9), Operations("R"), Units("B")] long? TX_Bytes;

            /**
            Total number of bytes received by access point from client since connection establishment. Monotonically
            increasing counter useful for bandwidth usage monitoring and accounting. Resets to zero when client
            reconnects.
            */
            [ResourceId(10), Operations("R"), Units("B")] long? RX_Bytes;

            /**
            Duration in seconds since the client associated with the access point. Useful for session tracking and
            identifying long-running vs. transient connections. Resets when client reconnects.
            */
            [ResourceId(11), Operations("R"), Units("s")] long? Connected_Time;

            /**
            Highest 802.11 standard supported by the client as negotiated during association. Possible values: "802.11b",
            "802.11g", "802.11a", "802.11n", "802.11ac", "802.11ax". Parsed from client capability flags. Helps identify
            client device capabilities and potential performance bottlenecks.
            */
            [ResourceId(12), Operations("R")] string Capability;

            /**
            Frequency band currently used by the client. Possible values: "2.4GHz" (2412-2484 MHz), "5GHz" (5170-5835
            MHz), "6GHz" (5955-7115 MHz). Determined from the operating channel frequency. Essential for band steering
            operations and spectrum management.
            */
            [ResourceId(13), Operations("R")] string Band;

            /**
            Channel bandwidth currently negotiated with the client in MHz. Possible values: 20 (legacy), 40 (802.11n+), 80
            (802.11ac+), 160 (802.11ac/ax). Wider bandwidths provide higher throughput but are more susceptible to
            interference. Parsed from client capability flags.
            */
            [Range("20,40,80,160"), ResourceId(14), Operations("R"), Units("MHz")] long? Bandwidth;

            /**
            Access Control List state for this client. Values: "none" (no ACL policy applied), "allowed" (explicitly
            whitelisted), "denied" (explicitly blacklisted). Read-write resource that allows querying and modifying ACL
            state. Changes are applied to hostapd ACL configuration.
            */
            [Range("none,allowed,denied"), ResourceId(15), Operations("RW")] string ACL_State;

            /**
            Quality of Service priority level for this client (0-7, where 7 is highest priority). Maps to WMM/802.11e
            traffic categories. Higher priority clients receive preferential treatment for channel access and bandwidth
            allocation. Useful for prioritizing VoIP, video streaming, or critical IoT devices over best-effort traffic.
            */
            [MinMax(0, 7), ResourceId(16), Operations("RW")] byte? QoS_Priority;

            /**
            Client isolation flag. When true, this client is prevented from communicating directly with other wireless
            clients on the same SSID (AP isolation). Client can only communicate with the wired network/gateway. Enhances
            security for guest networks and public WiFi by preventing peer-to-peer attacks. False allows normal
            client-to-client communication.
            */
            [ResourceId(17), Operations("RW")] bool? Isolated;

            /**
            Time in seconds since the last frame transmission or reception from this client. Indicates client activity
            level. Low values (&lt;10 seconds) indicate active communication, high values suggest idle or sleeping client.
            Useful for identifying stale connections and implementing inactivity-based disconnection policies.
            */
            [ResourceId(18), Operations("R"), Units("s")] long? Last_Activity;

            /**
            Execute this resource to forcibly disconnect the client from the access point. Sends 802.11 deauthentication
            frame via hostapd, immediately terminating the client's association. Client may automatically reconnect unless
            blocked by ACL. Useful for enforcing policies, troubleshooting, or manually managing network access.
            Execute operation on resource 19 (Disconnect Client); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E")] public class Disconnect_Client_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to add the client's MAC address to the hostapd deny ACL (blacklist) and immediately
            disconnect it. Prevents the client from reconnecting until removed from the blacklist. Also sets ACL State to
            "denied". Useful for blocking unauthorized or problematic devices. Blacklist persists in hostapd runtime
            configuration but may need to be saved to UCI for persistence across reboots.
            Execute operation on resource 20 (Add to Blacklist); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E")] public class Add_to_Blacklist_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to add the client's MAC address to the hostapd accept ACL (whitelist). When whitelist
            mode is enabled on the AP, only whitelisted clients can connect. Also removes the MAC from deny list if
            present and sets ACL State to "allowed". Useful for implementing strict MAC-based authentication. Whitelist
            persists in hostapd runtime configuration but may need to be saved to UCI for persistence across reboots.
            Execute operation on resource 21 (Add to Whitelist); sent by the Server to the Client.
            */
            [ResourceId(21), Operations("E")] public class Add_to_Whitelist_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to steer the client to a different frequency band using 802.11v BSS Transition
            Management Request. Parameter should be target band: "2.4", "5", or "6" (as string). Sends BSS-TM request
            frame suggesting the client transition to an AP on the specified band. Requires 802.11v support in both AP
            (hostapd) and client device. Client may honor or ignore the request. Useful for load balancing and optimizing
            dual-band/tri-band deployments by moving capable clients to less congested bands.
            Execute operation on resource 22 (Steer to Band); sent by the Server to the Client.
            */
            [ResourceId(22), Operations("E")] public class Steer_to_Band_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10528.xml: WiFi Channel Optimization (urn:oma:lwm2m:x:10528) ═════════════════════════
        /**
        WiFi channel selection and optimization. Interference monitoring, automatic channel selection, and DFS
        management.
        */
        class WiFi_Channel_Optimization {
            public const ushort lwm2m_object_id          = 10528;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10528";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Wireless interface identifier (e.g., "radio0", "radio1"). Specifies which wireless radio this instance
            manages. Typically "radio0" for 2.4GHz and "radio1" for 5GHz on dual-band routers. Must match the interface
            name in OpenWRT's wireless configuration.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Interface;

            /**
            Current operating channel number. For 2.4GHz: 1-14 (typically 1-11 in US). For 5GHz: 36-165 in increments of 4
            (e.g., 36, 40, 44, 48, 149, 153, 157, 161, 165). For 6GHz: 1-233. Read-only resource that reflects the active
            channel. Value 0 indicates channel not yet initialized.
            */
            [ResourceId(1), Operations("R"), Mandatory] long Current_Channel;

            /**
            Current channel bandwidth in MHz. Supported values: 20 (basic), 40 (HT40/VHT40), 80 (VHT80/HE80), 160
            (VHT160/HE160). Wider channels provide higher throughput but require more spectrum and are more susceptible to
            interference. 2.4GHz typically uses 20 or 40MHz. 5GHz and 6GHz support all widths.
            */
            [Range("20,40,80,160"), ResourceId(2), Operations("R"), Units("MHz"), Mandatory] long Current_Width;

            /**
            Enable or disable Automatic Channel Selection (ACS). When enabled (true), the system will automatically select
            and switch to the optimal channel based on the ACS algorithm when "Optimize Channel" is executed. When
            disabled (false), channel changes must be performed manually via the "Set Channel" resource.
            */
            [ResourceId(3), Operations("RW"), Mandatory] bool Auto_Channel;

            /**
            Interval in seconds between automatic channel scans (range: 60-86400 seconds / 1 minute to 24 hours). Periodic
            scans update channel survey data, neighbor AP counts, and interference metrics. Shorter intervals provide more
            current data but increase system load. Recommended: 3600 seconds (1 hour) for typical deployments. Set to 0 to
            disable automatic scanning.
            */
            [ResourceId(4), Operations("RW"), Units("s")] DurationInSeconds? Scan_Interval;

            /**
            Total count of neighboring access points detected during the last scan across all channels. High neighbor
            counts indicate congested RF environment. This metric helps assess overall spectrum congestion and inform
            channel selection decisions. Updated after each scan operation.
            */
            [ResourceId(5), Operations("R")] long? Neighboring_APs;

            /**
            Current channel busy time as a percentage (0-100%). Represents the proportion of time the channel is occupied
            by any RF activity including this AP, clients, neighboring APs, and interference. Values above 70% indicate
            high congestion. Measured via iw survey dump. Critical metric for channel optimization decisions.
            */
            [MinMax(0, 100), ResourceId(6), Operations("R"), Units("%")] byte? Channel_Utilization;

            /**
            Background noise level on the current channel in dBm (typically -95 to -75 dBm). Lower (more negative) values
            indicate cleaner spectrum. Good: -95 to -90 dBm. Fair: -90 to -85 dBm. Poor: -85 to -75 dBm. High noise floors
            reduce signal-to-noise ratio and degrade performance. Measured via iw survey dump.
            */
            [ResourceId(7), Operations("R"), Units("dBm")] long? Noise_Floor;

            /**
            Composite interference score (0-100) calculated from neighboring AP count, channel utilization, and noise
            floor. 0 = no interference, 100 = severe interference. Algorithm weights: neighbors (40%), utilization (40%),
            noise (20%). Values above 60 indicate significant interference requiring channel change. Used by ACS for
            channel scoring.
            */
            [MinMax(0, 100), ResourceId(8), Operations("R")] byte? Interference_Level;

            /**
            Enable or disable Dynamic Frequency Selection (DFS) support. When enabled (true), the router can use DFS
            channels (52-144 in 5GHz band) which are less congested but require radar detection. DFS channels undergo
            Channel Availability Check (CAC) before use and must be vacated if radar is detected. Enable for better
            channel selection in congested areas. Regulatory requirement in many regions for 5GHz operation.
            */
            [ResourceId(9), Operations("RW")] bool? DFS_Enabled;

            /**
            Current DFS operational state for DFS channels: "CAC" (Channel Availability Check in progress, 60-600 seconds
            depending on region), "Available" (channel cleared for use after CAC or non-DFS channel), "NOP" (Non-Occupancy
            Period, channel unavailable for 30 minutes after radar detection), "Disabled" (DFS not enabled). Only
            applicable when DFS Enabled is true and operating on DFS channels.
            */
            [ResourceId(10), Operations("R")] string DFS_State;

            /**
            Indicates whether radar has been detected on the current DFS channel (true) or not (false). When radar is
            detected, the channel enters Non-Occupancy Period (NOP) and cannot be used for 30 minutes. The router must
            immediately vacate the channel and switch to a non-DFS or CAC-cleared DFS channel. Automatically cleared when
            switching channels or after NOP expires.
            */
            [ResourceId(11), Operations("R")] bool? Radar_Detected;

            /**
            Recommended optimal channel for 2.4GHz band (1-14, typically 1, 6, or 11 for non-overlapping channels in US).
            Calculated by ACS algorithm based on latest scan data including neighbor count, utilization, and interference.
            Updated after each optimization run. Use this value for manual channel changes or automatic selection when
            Auto Channel is enabled on a 2.4GHz radio.
            */
            [MinMax(1, 14), ResourceId(12), Operations("R")] byte? Best_2_4G_Channel;

            /**
            Recommended optimal channel for 5GHz band (36-165). Calculated by ACS algorithm considering all available 5GHz
            channels including DFS channels if enabled. Takes into account neighbor interference, utilization, noise
            floor, DFS requirements, and historical performance. Updated after each optimization run. May recommend DFS
            channels (52-144) if DFS is enabled and spectrum is congested on non-DFS channels.
            */
            [MinMax(36, 165), ResourceId(13), Operations("R")] byte? Best_5G_Channel;

            /**
            Recommended optimal channel for 6GHz band (1-233). Calculated by ACS algorithm for WiFi 6E capable radios.
            6GHz band offers more clean spectrum with less congestion due to newer deployment. Takes into account the
            wider channel availability and lower interference typical of 6GHz. Updated after each optimization run. Value
            0 indicates 6GHz not supported or not scanned.
            */
            [MinMax(1, 233), ResourceId(14), Operations("R")] byte? Best_6G_Channel;

            /**
            Detailed per-channel survey data in format "channel:busy_time:noise_floor" (e.g., "36:450:92" means channel 36
            with 450ms busy time and -92 dBm noise). Multiple instances provide survey data for all scanned channels. Busy
            time in milliseconds, noise floor in dBm. Collected via iw survey dump. Used by ACS algorithm for detailed
            channel analysis. Updated after each scan operation.
            */
            [ResourceId(15), Operations("R")] string[,,] Channel_Survey;

            /**
            Unix timestamp of the last completed channel scan. Indicates the freshness of channel survey data, neighbor AP
            counts, and interference metrics. Compare with current time to determine data age. Updated after "Scan Now"
            execution or periodic automatic scans. Value 0 indicates no scan has been performed since initialization.
            */
            [ResourceId(16), Operations("R")] DateTime? Last_Scan_Time;

            /**
            Unix timestamp of the last channel optimization run. Indicates when the ACS algorithm was last executed and
            channel recommendations were updated. If Auto Channel is enabled, this also reflects the last automatic
            channel change. Compare with Last Scan Time to verify optimization used current data. Value 0 indicates no
            optimization has been performed since initialization.
            */
            [ResourceId(17), Operations("R")] DateTime? Last_Optimization;

            /**
            Execute this resource to immediately perform a channel scan and survey. Updates Channel Survey, Neighboring
            APs, Channel Utilization, Noise Floor, and Interference Level resources with current RF environment data. Scan
            operation may take 5-30 seconds depending on number of channels. Non-disruptive to connected clients. Does not
            change channels. Use before manual channel changes or to get current spectrum status.
            Execute operation on resource 18 (Scan Now); sent by the Server to the Client.
            */
            [ResourceId(18), Operations("E"), Mandatory] public class Scan_Now_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to run the Automatic Channel Selection (ACS) algorithm. Performs a full channel scan,
            analyzes all available channels using the ACS scoring algorithm, and updates Best Channel recommendations for
            all bands. If Auto Channel is enabled, automatically switches to the optimal channel. Otherwise, only updates
            recommendations. ACS algorithm considers neighbor count, utilization, noise floor, DFS requirements, and
            historical performance. May cause brief client disconnection if channel change occurs.
            Execute operation on resource 19 (Optimize Channel); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E"), Mandatory] public class Optimize_Channel_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to manually set the wireless channel. Argument format: "channel:width" (e.g., "36:80"
            for channel 36 with 80MHz width) or just "channel" (e.g., "36" to keep current width). Immediately applies the
            channel change and reloads wireless configuration. Causes brief client disconnection (typically 1-3 seconds).
            Validates channel number and width. For DFS channels, triggers Channel Availability Check (CAC). Updates
            Current Channel and Current Width resources.
            Execute operation on resource 20 (Set Channel); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E"), Mandatory] public class Set_Channel_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to enable Dynamic Frequency Selection (DFS) support on this radio. Updates OpenWRT
            wireless configuration to enable DFS, sets DFS Enabled to true, and reloads wireless. Enables the router to
            use DFS channels (52-144 in 5GHz) which are typically less congested. After enabling, use Optimize Channel to
            select the best channel including DFS options. Required for regulatory compliance in many regions for full
            5GHz spectrum access.
            Execute operation on resource 21 (Enable DFS); sent by the Server to the Client.
            */
            [ResourceId(21), Operations("E")] public class Enable_DFS_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10529.xml: Matter Bridge (urn:oma:lwm2m:x:10529) ═════════════════════════
        /**
        Matter protocol bridge functionality. Enables LwM2M-managed gateways to expose devices to Matter fabric
        ecosystems.
        */
        class Matter_Bridge {
            public const ushort lwm2m_object_id          = 10529;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10529";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Current status of the Matter controller. Values include: "Inactive" (not initialized), "Active" (running and
            ready), "Commissioning" (device commissioning in progress), "Error: [message]" (error state with details).
            Updated automatically during controller operations and commissioning workflows. Check this resource after
            executing controller operations to verify success. In stub mode without Matter SDK, status will indicate
            "Active (stub mode)".
            */
            [ResourceId(0), Operations("R"), Mandatory] string Controller_Status;

            /**
            Total number of Matter devices currently commissioned to this controller's fabric. Includes all device types
            (lights, sensors, locks, etc.). Updated automatically when devices are commissioned or removed. Each
            commissioned device creates a corresponding Matter Device Object (33451) instance. Value persists across
            controller restarts as devices are stored in persistent storage. Use this to monitor fabric size and detect
            unexpected device removals.
            */
            [ResourceId(1), Operations("R"), Mandatory] long Commissioned_Devices_Count;

            /**
            Thread network name for Border Router functionality. Used when commissioning Thread-based Matter devices.
            Maximum 16 characters, alphanumeric. When Thread Border Router is enabled, this name identifies the Thread
            network that commissioned devices will join. Must be set before enabling Thread Border Router. Empty when
            Thread functionality is not in use. Example values: "matter-thread", "home-thread-001".
            */
            [ResourceId(2), Operations("RW")] string Thread_Network_SSID;

            /**
            Indicates whether Thread Border Router functionality is enabled. When true, the controller can commission and
            communicate with Thread-based Matter devices. When false, only IP-based (WiFi/Ethernet) Matter devices are
            supported. Set to true using the Enable Thread BR execute resource. Requires proper Thread network
            configuration in Thread Network Object (33452). Thread support requires compatible hardware and Thread stack
            availability.
            */
            [ResourceId(3), Operations("RW")] bool? Thread_Enabled;

            /**
            Unique identifier for this Matter fabric. Generated during controller initialization using fabric index,
            timestamp, and cryptographic elements. Format: hex string representation of 64-bit fabric ID. All devices
            commissioned to this controller share this fabric ID. Used for secure session establishment (CASE) and
            operational discovery. Persists across controller restarts. Essential for multi-fabric Matter deployments to
            identify which fabric a controller manages.
            */
            [ResourceId(4), Operations("R"), Mandatory] string Fabric_ID;

            /**
            Matter Vendor ID for this controller. 16-bit value assigned by CSA (Connectivity Standards Alliance). Default:
            0xFFF1 (test vendor ID for development). Production deployments must use officially assigned vendor ID. Used
            during device commissioning and attestation. Visible to commissioned devices. Must be set before controller
            initialization. Changes require controller restart to take effect.
            */
            [ResourceId(5), Operations("RW"), Mandatory] ushort Vendor_ID;

            /**
            Matter Product ID for this controller. 16-bit value defined by vendor. Default: 0x8000 (test product ID for
            development). Used to identify specific controller product during commissioning. Visible to commissioned
            devices. Can be used by devices for controller-specific behavior. Must be set before controller
            initialization. Changes require controller restart to take effect.
            */
            [ResourceId(6), Operations("RW"), Mandatory] ushort Product_ID;

            /**
            Execute to commission a new Matter device to this controller's fabric. Argument: QR code payload (format:
            "MT:...") or manual pairing code (11-21 digit string). Initiates full commissioning workflow: device discovery
            (BLE/WiFi/Thread), PASE session establishment, device attestation verification, network credential
            provisioning, operational discovery, and CASE session setup. Progress updates reported via Controller Status
            resource. On success, creates new Matter Device Object (33451) instance. Typical duration: 30-120 seconds
            depending on device type and network. Example QR: "MT:Y.K9042C00KA0648G00", Example manual code:
            "34970112332".
            Execute operation on resource 7 (Commission Device); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E"), Mandatory] public class Commission_Device_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to remove a commissioned Matter device from this controller's fabric. Argument: Node ID as hex string
            (e.g., "0000000000000001"). Closes active CASE sessions, removes device from fabric, deletes operational
            credentials, and removes corresponding Matter Device Object (33451) instance. Device must be recommissioned to
            rejoin the fabric. Updates Commissioned Devices Count. Persists removal across controller restarts. Use when
            decommissioning devices or troubleshooting device communication issues.
            Execute operation on resource 8 (Remove Device); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E")] public class Remove_Device_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to start Matter device discovery. Scans for uncommissioned devices using BLE, mDNS (operational
            discovery), and Thread (if enabled). Default timeout: 30 seconds. Discovered devices are logged but not
            automatically commissioned. Use before commissioning to verify device visibility. Discovery results include:
            vendor ID, product ID, discriminator, device name. Does not modify controller state. Can be executed while
            other operations are in progress. Useful for diagnostics and device identification.
            Execute operation on resource 9 (Discover Devices); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Discover_Devices_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to enable Thread Border Router functionality. Requires Thread network configuration in Thread Network
            Object (33452). Creates Thread network using configured parameters (network name, PAN ID, channel, keys).
            Starts Border Router services for Thread routing, external commissioning, and service discovery. Sets Thread
            Enabled to true. Essential for commissioning Thread-based Matter devices (door locks, sensors, battery-powered
            devices). Requires compatible hardware with Thread radio. Check Thread Network Object Border Router State for
            status.
            Execute operation on resource 10 (Enable Thread BR); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Enable_Thread_BR_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10530.xml: Matter Device (urn:oma:lwm2m:x:10530) ═════════════════════════
        /**
        Individual Matter device representation. Device information, commissioning status, and endpoint management.
        */
        class Matter_Device {
            public const ushort lwm2m_object_id          = 10530;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10530";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Unique 64-bit Matter node identifier for this device within the fabric. Format: 16-character hex string (e.g.,
            "0000000000000001"). Assigned during commissioning. Used for all Matter protocol operations including CASE
            session establishment, attribute interactions, and command invocation. Persists across device reboots and
            controller restarts. Essential for identifying specific devices in multi-device fabrics. Used as key parameter
            in all device interaction execute resources.
            */
            [ResourceId(0), Operations("R"), Mandatory] string Node_ID;

            /**
            Matter Vendor ID from device's Basic Information cluster. 16-bit CSA-assigned identifier. Indicates device
            manufacturer. Used for device identification, firmware update targeting, and vendor-specific behavior. Read
            from device during commissioning. Examples: Philips Hue (0x100B), Samsung SmartThings (0x110A), Eve Systems
            (0x130A). Cross-reference with CSA vendor registry for full manufacturer details.
            */
            [ResourceId(1), Operations("R"), Mandatory] ushort Vendor_ID;

            /**
            Matter Product ID from device's Basic Information cluster. 16-bit vendor-defined identifier. Identifies
            specific product model. Used with Vendor ID for unique device identification. Essential for firmware updates,
            feature detection, and product-specific integrations. Read from device during commissioning. Example: A vendor
            might use 0x8001 for "Smart Bulb RGB" and 0x8002 for "Smart Bulb White".
            */
            [ResourceId(2), Operations("R"), Mandatory] ushort Product_ID;

            /**
            Primary Matter device type from root endpoint's Descriptor cluster. Indicates device functionality class.
            Standard types: 0x0100 (On/Off Light), 0x0101 (Dimmable Light), 0x010D (Extended Color Light), 0x000A (Door
            Lock), 0x0107 (Occupancy Sensor), 0x0302 (Temperature Sensor), 0x0301 (Thermostat), 0x0202 (Window Covering).
            Determines which clusters are required and expected device behavior. Essential for UI rendering and automation
            rule creation. See Device Type Name for human-readable equivalent.
            */
            [ResourceId(3), Operations("R"), Mandatory] ushort Device_Type;

            /**
            Human-readable device type name derived from Device Type value. Examples: "On/Off Light", "Dimmable Light",
            "Extended Color Light", "Door Lock", "Occupancy Sensor", "Temperature Sensor", "Thermostat", "Window
            Covering", "Generic Switch". Automatically mapped from device type code. Used for display in user interfaces
            and logging. Simplifies device identification without requiring device type code lookup tables.
            */
            [ResourceId(4), Operations("R"), Mandatory] string Device_Type_Name;

            /**
            List of Matter endpoint IDs exposed by this device. Endpoint 0 (root) contains device-wide clusters (Basic
            Information, Descriptor). Endpoint 1+ contain application-specific clusters (OnOff, LevelControl, etc.).
            Multi-endpoint devices include: smart plugs with multiple outlets, ceiling fans with separate fan/light
            endpoints, combo sensors with multiple sensing functions. Use endpoint IDs in attribute read/write and command
            execute operations. Query Descriptor cluster on each endpoint to discover supported clusters.
            */
            [ResourceId(5), Operations("R"), Mandatory] ushort[,,] Endpoints;

            /**
            Current device reachability status. True: device is online and CASE session can be established. False: device
            is offline, unreachable, or sleeping. Updated automatically based on operational discovery (mDNS), CASE
            session health, and subscription status. For sleepy devices (battery-powered sensors), may show false when
            device is in sleep mode. Check Last Seen timestamp to determine how long device has been unreachable. Use
            Interact execute resource with "ping" command to force reachability check.
            */
            [ResourceId(6), Operations("R"), Mandatory] bool Reachable;

            /**
            Device firmware version from Basic Information cluster's SoftwareVersion attribute. Vendor-specific format,
            typically semantic versioning (e.g., "1.2.3", "v2.0.1-beta"). Updated when device firmware is updated via OTA.
            Essential for tracking device firmware state, identifying devices needing updates, and troubleshooting
            version-specific issues. May be empty if device doesn't support or report firmware version. Compare against
            latest available firmware to determine update availability.
            */
            [ResourceId(7), Operations("R")] string Firmware_Version;

            /**
            Device serial number from Basic Information cluster's SerialNumber attribute. Vendor-specific format,
            typically alphanumeric. Uniquely identifies specific device unit. Used for warranty tracking, RMA processes,
            support ticket identification. May be empty if device doesn't provide serial number. Essential for device
            lifecycle management and support operations. Example formats: "ABC-123456", "2021-001-XYZ", "SN123456789".
            */
            [ResourceId(8), Operations("R")] string Serial_Number;

            /**
            Device product name from Basic Information cluster's ProductName attribute. Human-readable product marketing
            name. Examples: "Hue White and Color Ambiance", "Smart Door Lock Pro", "Eve Motion Sensor". Used for display
            in user interfaces. More descriptive than Device Type Name. May include brand name, product line, and model
            designation. Essential for user-friendly device identification in applications and dashboards.
            */
            [ResourceId(9), Operations("R")] string Product_Name;

            /**
            Unix timestamp of last successful communication with device. Updated on: CASE session establishment, attribute
            read/write success, command execution success, subscription report reception. Value 0 indicates device never
            successfully contacted since commissioning. Use to detect offline devices and calculate uptime statistics. For
            sleepy devices, reflects last wake-up and check-in time. Compare with current time to determine offline
            duration. Useful for alerting on devices that haven't been seen for extended periods.
            */
            [ResourceId(10), Operations("R")] DateTime? Last_Seen;

            /**
            Current IP address of device (IPv4 or IPv6). Obtained from operational discovery (mDNS) or CASE session
            establishment. Format: "192.168.1.100" (IPv4) or "fe80::1" (IPv6). May change due to DHCP lease renewal or
            network reconfiguration. Empty for Thread-only devices accessed via Border Router. Updated automatically when
            device is rediscovered. Useful for network diagnostics, traffic analysis, and troubleshooting connectivity
            issues. May show Border Router IP for Thread devices.
            */
            [ResourceId(11), Operations("R")] string IP_Address;

            /**
            Received Signal Strength Indicator in dBm. Indicates wireless signal quality for WiFi or Thread devices.
            Typical ranges: -30 to -50 dBm (excellent), -50 to -70 dBm (good), -70 to -80 dBm (fair), -80 to -90 dBm
            (poor), below -90 dBm (unreliable). Value 0 indicates wired connection or RSSI not available. Updated during
            device communication. Use for diagnosing connectivity issues, optimizing device placement, and identifying
            devices with weak signal. Not applicable for Ethernet-connected devices.
            */
            [MinMax(-127, 0), ResourceId(12), Operations("R"), Units("dBm")] sbyte? RSSI;

            /**
            Execute high-level device interaction commands. Supported commands: "ping" (test connectivity, update device
            info), "refresh" (query current state), "on" (turn on OnOff devices), "off" (turn off), "toggle" (toggle OnOff
            state). Arguments: simple command string. Returns immediately; check Reachable and Last Seen for result.
            Provides convenient shortcuts for common operations without requiring detailed cluster knowledge. Use for
            simple device control and health checks. Example: write "toggle" to toggle a light bulb's on/off state.
            Execute operation on resource 13 (Interact); sent by the Server to the Client.
            */
            [ResourceId(13), Operations("E"), Mandatory] public class Interact_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to read any Matter cluster attribute. Argument format: "endpoint:cluster:attribute" (decimal or hex).
            Examples: "1:6:0" (read OnOff state from endpoint 1, cluster 0x0006, attribute 0x0000), "1:0x0008:0x0000"
            (read current level). Establishes CASE session if needed. Returns attribute value in type-appropriate format.
            Supports all Matter attribute types. Use for custom device queries not covered by standard resources. Requires
            knowledge of Matter cluster specifications. Check Matter cluster library documentation for cluster/attribute
            IDs.
            Execute operation on resource 14 (Read Attribute); sent by the Server to the Client.
            */
            [ResourceId(14), Operations("E")] public class Read_Attribute_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to write any Matter cluster attribute. Argument format: "endpoint:cluster:attribute:value". Examples:
            "1:6:0:1" (turn on), "1:8:0:128" (set level to 50%), "1:0x0300:0x0000:120" (set hue). Validates attribute is
            writable per Matter specification. Establishes CASE session if needed. Returns success/failure. Some
            attributes require specific permissions or conditions. Use for advanced device control and configuration.
            Requires knowledge of Matter cluster specifications and attribute data types.
            Execute operation on resource 15 (Write Attribute); sent by the Server to the Client.
            */
            [ResourceId(15), Operations("E")] public class Write_Attribute_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to send any Matter cluster command. Argument format: "endpoint:cluster:command:args" where args is
            JSON-encoded command fields. Examples: "1:6:1:" (OnOff On command),
            "1:8:0:{\"level\":128,\"transitionTime\":10}" (MoveToLevel), "1:0x0101:0:{\"pinCode\":\"1234\"}" (DoorLock
            Lock). Establishes CASE session if needed. Returns command response if applicable. Supports all Matter command
            types. Essential for device actuation beyond simple on/off. Requires knowledge of Matter cluster command
            specifications and parameter encoding.
            Execute operation on resource 16 (Send Command); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E")] public class Send_Command_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10531.xml: Thread Network (urn:oma:lwm2m:x:10531) ═════════════════════════
        /**
        Thread mesh network management. Border router configuration, network formation, and mesh topology monitoring.
        */
        class Thread_Network_10531 {
            public const ushort lwm2m_object_id          = 10531;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10531";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Thread network name (SSID). Human-readable identifier for the Thread network. Maximum 16 characters, UTF-8
            encoded. Must be unique if multiple Thread networks are in range. Used during device commissioning to identify
            target network. Examples: "matter-thread", "home-network", "apt-101-thread". Visible to Thread devices during
            scanning. Should be descriptive but not contain sensitive information. Default: "matter-thread". Change before
            creating network for custom deployments. Used in Thread Operational Dataset generation.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Network_Name;

            /**
            Thread Personal Area Network ID. 16-bit identifier used for network segmentation. Range: 0x0000-0xFFFF
            (0-65535 decimal). Should be unique among nearby Thread networks to avoid conflicts. Used in Thread beacon
            frames and network discovery. Random value recommended for security. Default: 0x1234. Change for production
            deployments. Conflicts with nearby networks using same PAN ID can cause connectivity issues. Used with
            Extended PAN ID for complete network identification. Part of Thread Operational Dataset.
            */
            [ResourceId(1), Operations("RW"), Mandatory] ushort PAN_ID;

            /**
            Thread network radio channel. Range: 11-26 (IEEE 802.15.4, 2.4 GHz band). Channel selection affects network
            performance and interference. Recommendations: Channel 15-20 for less WiFi interference in most regions, avoid
            channels 11-14 and 25-26 if strong WiFi networks present, scan environment before selection. Default: 15 (good
            balance between WiFi and Thread). Higher channels (20-26) may have better performance in WiFi-dense
            environments. Some regions restrict certain channels - verify local regulations. Cannot change channel while
            Border Router is running.
            */
            [MinMax(11, 26), ResourceId(2), Operations("RW"), Mandatory] byte Channel;

            /**
            Thread Extended Personal Area Network ID. 64-bit (8 bytes) globally unique network identifier. Format:
            16-character hex string (e.g., "1111111122222222"). Used with PAN ID for complete network identification. Must
            be unique across all Thread networks to prevent conflicts. Randomly generated by default for security. Never
            reuse Extended PAN IDs across different networks. Used in Thread commissioning and operational dataset.
            Visible during device joining process. Essential component of Thread network credentials. Change only when
            creating new network, not during operation.
            */
            [ResourceId(3), Operations("RW"), Mandatory] string Extended_PAN_ID;

            /**
            Thread network master key for encryption and authentication. 128-bit (16 bytes) symmetric key. Format:
            32-character hex string (e.g., "00112233445566778899aabbccddeeff"). Randomly generated by default using
            cryptographically secure random number generator. Must be kept secret - compromise allows unauthorized network
            access. All Thread network traffic encrypted using keys derived from this master key. Required for device
            commissioning. Distribute securely to commissioned devices. Change triggers network-wide key rotation. Store
            securely, never log or transmit in clear. Used in Thread Operational Dataset generation.
            */
            [ResourceId(4), Operations("RW"), Mandatory] string Network_Key;

            /**
            Unix timestamp when Thread network was created or last reconfigured. Updated when Create Network execute
            resource is called. Used in Thread Operational Dataset as Active Timestamp field. Indicates currency of
            network configuration. Value 0 means network not yet created. Thread devices use timestamp to determine if
            they need to update network configuration. Increments on configuration changes. Essential for Thread network
            version management. Persists across Border Router restarts. Used to detect stale network configurations.
            */
            [ResourceId(5), Operations("R"), Mandatory] DateTime Active_Timestamp;

            /**
            Current Thread Border Router operational state. Values: 0=Disabled (Border Router not initialized), 1=Stopped
            (initialized but not running), 2=Starting (initialization in progress), 3=Running (actively routing Thread
            traffic), 4=Error (fault state, check logs). Updated automatically during Border Router lifecycle. State 3
            (Running) required for Thread device communication. Transitional state 2 (Starting) typically lasts 5-15
            seconds. Error state 4 requires Border Router restart. Monitor this resource to track Border Router health.
            Essential for troubleshooting Thread connectivity issues.
            */
            [MinMax(0, 4), ResourceId(6), Operations("R"), Mandatory] byte Border_Router_State;

            /**
            Thread Operational Dataset in standard Thread specification format. Contains complete network configuration:
            Network Name, Extended PAN ID, Network Key, PAN ID, Channel, Active Timestamp, security policies. Encoded as
            TLV (Type-Length-Value) binary format per Thread specification. Generated when Create Network is executed.
            Used during Matter device commissioning to provision Thread network credentials. Compatible with standard
            Thread commissioning tools and protocols. Can be exported for backup or device provisioning outside Matter
            ecosystem. Essential for Thread device joining process. Read-only, automatically generated from individual
            network parameters.
            */
            [D(65535), ResourceId(7), Operations("R"), Mandatory] Binary[,,] Operational_Dataset;

            /**
            Number of Thread devices currently connected to this Thread network. Includes: routers (mains-powered devices
            providing routing), end devices (sleepy battery-powered devices), router-eligible devices. Excludes: the
            Border Router itself, devices in other Thread networks. Updated periodically through Thread network topology
            discovery. Value lags actual network state by up to 60 seconds. Use for network capacity planning and health
            monitoring. High device count may indicate network scaling needs. Sudden drops may indicate network issues.
            Value 0 normal when network first created.
            */
            [ResourceId(8), Operations("R")] long? Devices_Count;

            /**
            Execute to create Thread network with configured parameters. Validates all network configuration resources
            (Network Name, PAN ID, Channel, Extended PAN ID, Network Key). Generates Thread Operational Dataset. Sets
            Active Timestamp to current time. Prepares network for Border Router start. Does not start Border Router - use
            Start Border Router execute resource. Can be executed multiple times to reconfigure network (when Border
            Router stopped). Essential first step before enabling Thread functionality. Validates: channel range (11-26),
            Extended PAN ID length (16 hex chars), Network Key length (32 hex chars), Network Name length (max 16 chars).
            Updates Operational Dataset resource on success.
            Execute operation on resource 9 (Create Network); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E"), Mandatory] public class Create_Network_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to start Thread Border Router. Requires: network created (Active Timestamp non-zero), Border Router
            State not already Running, compatible hardware with Thread radio. Initializes Thread protocol stack, forms
            Thread network, enables routing between Thread and IP networks, advertises Border Router services, enables
            Thread device commissioning. Updates Border Router State through Starting to Running. Typical startup time:
            5-15 seconds. On success, Thread devices can discover and join network. Enables communication with
            Thread-based Matter devices. Check Border Router State for confirmation. Fails if hardware not compatible or
            network not created.
            Execute operation on resource 10 (Start Border Router); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E"), Mandatory] public class Start_Border_Router_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to stop Thread Border Router. Gracefully shuts down: stops accepting new device joins, maintains
            existing device sessions briefly, disables routing, shuts down Thread stack. Updates Border Router State to
            Stopped. Existing Thread devices lose connectivity until Border Router restarted. Does not delete network
            configuration - can restart with same settings. Use for: maintenance operations, network reconfiguration,
            troubleshooting, resource conservation. After stopping, can modify network parameters (Channel, PAN ID, etc.)
            and recreate network. Stopping is faster than starting (typically 1-2 seconds). Does not affect Matter fabric
            or commissioned devices, only Thread connectivity.
            Execute operation on resource 11 (Stop Border Router); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E")] public class Stop_Border_Router_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10532.xml: Zigbee Coordinator (urn:oma:lwm2m:x:10532) ═════════════════════════
        /**
        Zigbee network coordinator management. Network formation, device joining, EZSP/Z-Stack support, and mesh
        orchestration.
        */
        class Zigbee_Coordinator {
            public const ushort lwm2m_object_id          = 10532;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10532";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Current state of the Zigbee network: 0=Offline (coordinator not operational), 1=Forming (creating new
            network), 2=Joined (joined existing network), 3=Ready (network operational, accepting devices), 4=Leaving
            (shutting down network), 5=Error (error state requiring attention).
            */
            [MinMax(0, 5), ResourceId(0), Operations("R"), Mandatory] byte Network_State;

            /**
            16-bit Personal Area Network identifier (0x0000-0xFFFF). Uniquely identifies the Zigbee network. Default
            0x1A62. Must be unique within radio range to avoid conflicts with neighboring networks.
            */
            [ResourceId(1), Operations("RW"), Mandatory] ushort PAN_ID;

            /**
            64-bit extended PAN identifier in hexadecimal format (16 characters). Provides globally unique network
            identifier. Used for network selection and joining process. Must be configured before network formation.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string Extended_PAN_ID;

            /**
            802.15.4 radio channel number (11-26 for 2.4GHz band). Channels 11, 15, 20, 25 recommended for minimal Wi-Fi
            interference. Select based on site survey to avoid congestion. Cannot be changed while network is active.
            */
            [MinMax(11, 26), ResourceId(3), Operations("RW"), Mandatory] byte Channel;

            /**
            128-bit AES encryption key for network security (16 bytes). Write-only for security. Should be randomly
            generated for production deployments. Used to encrypt all network traffic. Changing key requires network
            reformation.
            */
            [D(65535), ResourceId(4), Operations("W")] Binary[,,] Network_Key;

            /**
            Current permit join status. True when network is accepting new devices, false when closed. Automatically set
            to false when permit join duration expires. Query this resource to check if joining is currently enabled.
            */
            [ResourceId(5), Operations("R"), Mandatory] bool Permit_Join_Status;

            /**
            Total number of devices currently joined to the network (excluding coordinator). Updates automatically when
            devices join or leave. Maximum depends on coordinator hardware capabilities (typically 100-200 devices).
            */
            [ResourceId(6), Operations("R"), Mandatory] long Device_Count;

            /**
            64-bit IEEE MAC address of coordinator in hexadecimal format (16 characters). Globally unique identifier
            burned into coordinator hardware. Used for network security and device binding operations.
            */
            [ResourceId(7), Operations("R"), Mandatory] string Coordinator_IEEE_Address;

            /**
            Type of Zigbee coordinator adapter: 0=Unknown, 1=EZSP (Silicon Labs EmberZNet - EFR32), 2=Z-Stack (Texas
            Instruments - CC2531/CC2652), 3=ConBee (Dresden Elektronik), 4=ZiGate. Detected automatically during
            initialization.
            */
            [MinMax(0, 4), ResourceId(8), Operations("R"), Mandatory] byte Coordinator_Type;

            /**
            Coordinator firmware version string. Reports protocol stack version (e.g., "EZSP v8", "Z-Stack 3.0"). Used for
            compatibility checking and troubleshooting. Update firmware through coordinator-specific tools.
            */
            [ResourceId(9), Operations("R"), Mandatory] string Firmware_Version;

            /**
            Transmit power in dBm (-20 to +20). Higher values increase range but power consumption. Default 20 dBm.
            Regional regulations may limit maximum power. Adjust based on deployment environment and regulatory
            requirements.
            */
            [MinMax(-20, 20), ResourceId(10), Operations("RW"), Units("dBm")] sbyte? TX_Power;

            /**
            Network security level (0-7). 5 (standard security with encryption and authentication) is default and
            recommended for production. Level 0 disables security (testing only). Higher levels may impact performance.
            */
            [MinMax(0, 7), ResourceId(11), Operations("RW")] byte? Security_Level;

            /**
            Serial device path for coordinator communication (e.g., "/dev/ttyUSB0", "/dev/ttyACM0"). Must have read/write
            permissions. Verify path before network formation. Requires restart if changed.
            */
            [ResourceId(12), Operations("RW"), Mandatory] string Serial_Port;

            /**
            Serial communication baud rate (typically 115200 for EZSP, 115200 for Z-Stack). Must match coordinator
            configuration. Common values: 9600, 19200, 38400, 57600, 115200. Incorrect baud rate prevents communication.
            */
            [ResourceId(13), Operations("RW"), Units("bit/s"), Mandatory] long Baud_Rate;

            /**
            Number of entries in coordinator route table. Shows active routing paths to devices in mesh network. Larger
            networks require more route table entries. Monitor for network health assessment.
            */
            [ResourceId(14), Operations("R")] long? Route_Table_Size;

            /**
            Number of entries in coordinator neighbor table. Lists directly reachable devices (one-hop neighbors).
            Important for mesh topology visualization and network planning. High values indicate good coordinator
            placement.
            */
            [ResourceId(15), Operations("R")] long? Neighbor_Table_Size;

            /**
            Execute to form new Zigbee network with current configuration (PAN ID, channel, extended PAN ID). Takes 3-10
            seconds. Network must be offline. All devices will need to rejoin if network parameters change.
            Execute operation on resource 16 (Form Network); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E"), Mandatory] public class Form_Network_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to leave current network and shut down coordinator. All devices will lose connectivity. Use before
            changing network configuration. Network can be reformed with same or different parameters after leaving.
            Execute operation on resource 17 (Leave Network); sent by the Server to the Client.
            */
            [ResourceId(17), Operations("E"), Mandatory] public class Leave_Network_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to enable/disable device joining. Argument: duration in seconds (0=disable, 1-254=duration,
            255=forever). Recommended: 60-180 seconds for controlled joining. Security risk if left open indefinitely.
            Execute operation on resource 18 (Permit Join Command); sent by the Server to the Client.
            */
            [ResourceId(18), Operations("E"), Mandatory] public class Permit_Join_Command_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to initiate Zigbee Touchlink commissioning (ZLL). Used for adding devices without requiring
            traditional pairing mode. Device must be within close proximity. Useful for light bulbs and remote controls.
            Execute operation on resource 19 (Start Touchlink); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E")] public class Start_Touchlink_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to backup current network configuration including keys, PAN ID, and device bindings. Enables network
            restoration after coordinator replacement or failure. Store backup securely due to security key inclusion.
            Execute operation on resource 20 (Backup Network); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E")] public class Backup_Network_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10533.xml: Zigbee Device (urn:oma:lwm2m:x:10533) ═════════════════════════
        /**
        Individual Zigbee device representation. Device info, status monitoring, ZCL attribute access, and device
        management.
        */
        class Zigbee_Device {
            public const ushort lwm2m_object_id          = 10533;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10533";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            64-bit IEEE MAC address in hexadecimal format (16 characters). Globally unique device identifier burned into
            hardware. Used for all device communications and binding operations. Never changes during device lifetime.
            */
            [ResourceId(0), Operations("R"), Mandatory] string IEEE_Address;

            /**
            16-bit network address (0x0000-0xFFFF) assigned by coordinator during joining. Used for routing within
            network. May change if device rejoins or network performs address reassignment. 0xFFFF indicates unassigned.
            */
            [ResourceId(1), Operations("R"), Mandatory] ushort Network_Address;

            /**
            Zigbee device type: 0=Unknown, 1=Coordinator, 2=Router (mains-powered, extends network), 3=End Device (battery
            or mains, doesn't route), 4=Sleepy End Device (battery-powered, low power mode). Determines routing and power
            management behavior.
            */
            [MinMax(0, 4), ResourceId(2), Operations("R"), Mandatory] byte Device_Type;

            /**
            Manufacturer name read from device Basic cluster (ZCL attribute 0x0004). May be empty if device doesn't
            support this attribute or hasn't been interviewed. Used for device identification and compatibility checking.
            */
            [ResourceId(3), Operations("R")] string Manufacturer;

            /**
            Model identifier read from device Basic cluster (ZCL attribute 0x0005). Specific product model name or number.
            Used for device-specific features and troubleshooting. May be empty if not supported.
            */
            [ResourceId(4), Operations("R")] string Model;

            /**
            Device firmware version read from Basic cluster. Used for OTA upgrade management and compatibility checking.
            Format varies by manufacturer. Monitor for available updates.
            */
            [ResourceId(5), Operations("R")] string Firmware_Version;

            /**
            Device power source: 0=Unknown, 1=Mains (AC powered, always on), 2=Battery (portable, may sleep), 3=DC
            (external DC supply). Affects polling strategy and sleep behavior. Battery devices require poll control for
            timely updates.
            */
            [MinMax(0, 3), ResourceId(6), Operations("R"), Mandatory] byte Power_Source;

            /**
            Link Quality Indicator (0-255). Measures communication quality between device and coordinator/parent. Higher
            is better. &lt;50=poor, 50-150=fair, 150-200=good, &gt;200=excellent. Monitor for connectivity issues.
            */
            [ResourceId(7), Operations("R"), Mandatory] byte LQI;

            /**
            Received Signal Strength Indicator in dBm. Negative values, closer to 0 is stronger. &gt;-70=excellent, -70 to
            -80=good, -80 to -90=fair, &lt;-90=poor. Use for network planning and troubleshooting.
            */
            [MinMax(-100, 0), ResourceId(8), Operations("R"), Units("dBm"), Mandatory] sbyte RSSI;

            /**
            Timestamp of last communication from device (Unix epoch). Updated on any message reception. Used to detect
            offline devices. Devices not seen for &gt;5 minutes may be offline. Battery devices may report infrequently.
            */
            [ResourceId(9), Operations("R"), Mandatory] DateTime Last_Seen;

            /**
            Active endpoint numbers (1-254). Each endpoint represents a logical device function (e.g., endpoint 1=main
            light, endpoint 2=button). Discovered during interview. Multiple endpoints enable complex multi-function
            devices.
            */
            [MinMax(1, 254), ResourceId(10), Operations("R")] byte[,,] Endpoints;

            /**
            JSON array of supported ZCL clusters by endpoint. Format: [{"endpoint":1,"in":[0,3,4,5,6],"out":[]}]. "in"
            clusters are server (device provides), "out" are client (device controls). Determines device capabilities.
            */
            [ResourceId(11), Operations("R")] string Clusters;

            /**
            Interview completion status. True when device capabilities have been fully discovered (endpoints, clusters,
            attributes). False for newly joined devices awaiting interview. Trigger interview manually if needed.
            */
            [ResourceId(12), Operations("R"), Mandatory] bool Interviewed;

            /**
            Current online status. True if device responded recently (within last 5 minutes). False if
            offline/unreachable. Battery devices may appear offline between poll intervals. Use Ping command to verify.
            */
            [ResourceId(13), Operations("R"), Mandatory] bool Online;

            /**
            Zigbee profile ID. Common values: 0x0104=Home Automation, 0xC05E=Light Link, 0x0109=Smart Energy, 0xA1E0=Green
            Power. Determines which clusters and features are available. Most devices use Home Automation profile.
            */
            [ResourceId(14), Operations("R")] ushort? Profile_ID;

            /**
            Zigbee device identifier within profile. Examples: 0x0100=On/Off Light, 0x0101=Dimmable Light, 0x010D=Extended
            Color Light, 0x0302=Temperature Sensor, 0x0402=IAS Zone. Indicates device function and required clusters.
            */
            [ResourceId(15), Operations("R")] ushort? Device_ID;

            /**
            Execute to remove device from network. Sends leave request to device and removes from coordinator database.
            Device must be factory reset to rejoin. Use for decommissioning devices or clearing failed joins.
            Execute operation on resource 16 (Remove); sent by the Server to the Client.
            */
            [ResourceId(16), Operations("E"), Mandatory] public class Remove_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to start device interview process. Queries endpoints, clusters, and basic attributes. Takes 5-30
            seconds. Automatically performed on join but can be triggered manually if initial interview fails or device
            capabilities change.
            Execute operation on resource 17 (Interview); sent by the Server to the Client.
            */
            [ResourceId(17), Operations("E"), Mandatory] public class Interview_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to ping device and verify connectivity. Updates Last Seen timestamp and Online status. Useful for
            checking battery devices or troubleshooting connectivity issues. Returns success if device responds.
            Execute operation on resource 18 (Ping); sent by the Server to the Client.
            */
            [ResourceId(18), Operations("E")] public class Ping_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to read ZCL attribute from device. Argument format: [endpoint][clusterId][attributeId] (5 bytes).
            Example: Read OnOff state: [01][0006][0000]. Returns attribute value. Used for querying device state.
            Execute operation on resource 19 (Read Attribute); sent by the Server to the Client.
            */
            [ResourceId(19), Operations("E")] public class Read_Attribute_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to write ZCL attribute to device. Argument format:
            [endpoint][clusterId][attributeId][dataType][value]. Example: Set level to 128: [01][0008][0000][20][80]. Used
            for device configuration and control.
            Execute operation on resource 20 (Write Attribute); sent by the Server to the Client.
            */
            [ResourceId(20), Operations("E")] public class Write_Attribute_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10534.xml: Zigbee Group (urn:oma:lwm2m:x:10534) ═════════════════════════
        /**
        Zigbee group management for collective device control. Group membership, scene management, and ZCL group
        commands.
        */
        class Zigbee_Group {
            public const ushort lwm2m_object_id          = 10534;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10534";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            16-bit group identifier (0x0001-0xFFF7). Must be unique within network. Used for group addressing in ZCL
            commands. Reserved ranges: 0x0000 (not allowed), 0xFFF8-0xFFFF (special broadcast groups). Configure before
            adding members.
            */
            [MinMax(1, 65527), ResourceId(0), Operations("RW"), Mandatory] ushort Group_ID;

            /**
            Human-readable group name for identification and display (e.g., "Living Room Lights", "Kitchen Zone", "All
            Lights"). Maximum 16 characters. Used in user interfaces and automation rules. Should be descriptive and
            unique.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Group_Name;

            /**
            IEEE addresses (64-bit hex) of devices in group. Multiple resource instances, one per member. Automatically
            updated when devices join/leave group. Used for membership tracking and group management.
            */
            [ResourceId(2), Operations("R")] string[,,] Member_Devices;

            /**
            Total number of devices currently in group. Updates automatically when members added/removed. Empty groups
            (count=0) can be pre-created for future use. Monitor to ensure group commands reach all intended devices.
            */
            [ResourceId(3), Operations("R"), Mandatory] long Member_Count;

            /**
            Number of scenes defined for this group. Scenes store device states (on/off, brightness, color) for instant
            recall. Maximum typically 16 scenes per group. Each scene has unique ID (0-254). Used for lighting presets and
            automation.
            */
            [ResourceId(4), Operations("R")] long? Scene_Count;

            /**
            Currently active scene ID (0-254). 0 indicates no scene active. Updated when Scene Recall is executed. Can be
            written to recall specific scene. Used to track and restore lighting states.
            */
            [MinMax(0, 254), ResourceId(5), Operations("RW")] byte? Current_Scene;

            /**
            Execute to add device to group. Argument: 64-bit IEEE address (8 bytes). Sends ZCL Add Group command to
            device. Device must support Groups cluster. Verify membership via Member Count after execution. Can add
            multiple devices by executing repeatedly.
            Execute operation on resource 6 (Add Member); sent by the Server to the Client.
            */
            [ResourceId(6), Operations("E"), Mandatory] public class Add_Member_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to remove device from group. Argument: 64-bit IEEE address (8 bytes). Sends ZCL Remove Group command
            to device. Device will no longer respond to group commands. Useful for reconfiguring zones or decommissioning
            devices.
            Execute operation on resource 7 (Remove Member); sent by the Server to the Client.
            */
            [ResourceId(7), Operations("E"), Mandatory] public class Remove_Member_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to recall stored scene. Argument: scene ID (0-254, 1 byte). Restores all group member states to scene
            settings instantly (&lt;1 second). Used for lighting presets, automation, and mood setting. Scene must exist
            or command fails.
            Execute operation on resource 8 (Scene Recall); sent by the Server to the Client.
            */
            [ResourceId(8), Operations("E")] public class Scene_Recall_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to store current group state as scene. Argument: scene ID (0-254, 1 byte). Captures on/off,
            brightness, color state of all members. Overwrites scene if ID exists. Used to create lighting presets.
            Increment Scene Count after storage.
            Execute operation on resource 9 (Scene Store); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E")] public class Scene_Store_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to turn on all devices in group. Sends ZCL On command (cluster 0x0006, command 0x01) to group address.
            All devices respond simultaneously. Applies to lights, switches, outlets. Instant synchronized activation.
            Execute operation on resource 10 (On); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E"), Mandatory] public class On_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to turn off all devices in group. Sends ZCL Off command (cluster 0x0006, command 0x00) to group
            address. All devices deactivate simultaneously. Master switch functionality for zones or entire system.
            Execute operation on resource 11 (Off); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E"), Mandatory] public class Off_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to toggle all devices in group. Sends ZCL Toggle command (cluster 0x0006, command 0x02). Devices
            currently on will turn off, off devices turn on. Note: Mixed states may result in unexpected behavior. Best
            used with synchronized groups.
            Execute operation on resource 12 (Toggle); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E"), Mandatory] public class Toggle_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to set brightness level for all dimmable devices in group. Argument: level 0-254 (1 byte). 0=minimum,
            254=maximum brightness. Sends ZCL Move to Level command (cluster 0x0008). Instant or timed transition
            depending on device capabilities.
            Execute operation on resource 13 (Set Level); sent by the Server to the Client.
            */
            [ResourceId(13), Operations("E")] public class Set_Level_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute to set color for all color-capable devices in group. Arguments: hue (0-254), saturation (0-254) - 2
            bytes total. Sends ZCL Move to Hue and Saturation command (cluster 0x0300). Only affects devices with color
            control capability.
            Execute operation on resource 14 (Set Color); sent by the Server to the Client.
            */
            [ResourceId(14), Operations("E")] public class Set_Color_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10535.xml: LAN Configuration (urn:oma:lwm2m:x:10535) ═════════════════════════
        /**
        LAN network configuration. DHCP server settings, IP ranges, DNS relay, and client lease management.
        */
        class LAN_Configuration {
            public const ushort lwm2m_object_id          = 10535;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10535";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            IPv4 address of the LAN interface (e.g., "192.168.1.1"). This is the router's IP address on the local network
            and serves as the default gateway for LAN clients. Must be a valid IPv4 address in dotted-decimal notation.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string LAN_IP_Address;

            /**
            Subnet mask for the LAN network in dotted-decimal notation (e.g., "255.255.255.0" for a /24 network). Defines
            the size of the local network and which IP addresses are considered part of the LAN segment. Must be a valid
            subnet mask with contiguous 1 bits.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Subnet_Mask;

            /**
            Enable or disable the DHCP server on this LAN interface. When enabled (true), the router will automatically
            assign IP addresses to clients from the configured DHCP pool. When disabled (false), clients must use static
            IP configuration.
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool DHCP_Enabled;

            /**
            Starting IP address of the DHCP address pool (e.g., "192.168.1.100"). This is the first IP address that can be
            dynamically assigned to DHCP clients. Must be within the LAN subnet and not conflict with the router's IP or
            static assignments.
            */
            [ResourceId(3), Operations("RW")] string DHCP_Pool_Start;

            /**
            Ending IP address of the DHCP address pool (e.g., "192.168.1.250"). This is the last IP address that can be
            dynamically assigned to DHCP clients. Must be within the LAN subnet and greater than or equal to the pool
            start address.
            */
            [ResourceId(4), Operations("RW")] string DHCP_Pool_End;

            /**
            Duration in seconds for which a DHCP lease remains valid (range: 60-604800 seconds / 1 minute to 7 days).
            After this time, clients must renew their lease or obtain a new IP address. Common values: 43200 (12 hours),
            86400 (24 hours). Shorter lease times allow for more dynamic network management but increase DHCP traffic.
            */
            [MinMax(60, 604800), ResourceId(5), Operations("RW"), Units("s")] uint? DHCP_Lease_Time;

            /**
            Primary DNS server IP address provided to DHCP clients (e.g., "8.8.8.8" for Google DNS). Clients will use this
            server for domain name resolution. Can be set to the router's IP if it provides DNS caching/forwarding, or to
            an external DNS service.
            */
            [ResourceId(6), Operations("RW")] string DNS_Server_Primary;

            /**
            Secondary/fallback DNS server IP address provided to DHCP clients (e.g., "8.8.4.4"). Used by clients when the
            primary DNS server is unavailable. Provides redundancy for DNS resolution.
            */
            [ResourceId(7), Operations("RW")] string DNS_Server_Secondary;

            /**
            Local domain name suffix for the LAN (e.g., "lan", "home.local"). This domain is appended to hostnames for
            local name resolution and provided to DHCP clients. Allows clients to resolve local hostnames like
            "device.lan" instead of using IP addresses.
            */
            [ResourceId(8), Operations("RW")] string Domain_Name;

            /**
            Static DHCP lease reservations in MAC:IP format (e.g., "00:11:22:33:44:55:192.168.1.50"). Associates a
            specific MAC address with a fixed IP address, ensuring that a device always receives the same IP. Useful for
            servers, printers, and other devices requiring consistent addressing. Multiple instances can be added for
            different devices.
            */
            [ResourceId(9), Operations("RW")] string[,,] Static_Leases;

            /**
            Currently active DHCP leases in MAC:IP:hostname:expiry format (e.g.,
            "00:11:22:33:44:55:192.168.1.100:laptop:3600"). Read-only resource that shows all devices currently holding
            DHCP leases, including their MAC address, assigned IP, hostname (if available), and remaining lease time in
            seconds. Automatically updated from the DHCP server's lease database.
            */
            [ResourceId(10), Operations("R")] string[,,] Active_Leases;

            /**
            Current status of the LAN configuration: 0=Pending (configuration modified but not yet applied), 1=Applied
            (configuration successfully applied to the system), 2=Error (last configuration apply attempt failed). Check
            this resource after executing Apply Configuration to verify successful application.
            */
            [MinMax(0, 2), ResourceId(12), Operations("R"), Mandatory] byte Configuration_Status;

            /**
            Execute this resource to apply the current LAN and DHCP configuration to the system. Writes all configured
            settings to OpenWRT's UCI configuration files (/etc/config/network and /etc/config/dhcp), commits the changes,
            and restarts the network and dnsmasq services to activate the new configuration. After execution, the
            Configuration Status resource will indicate success or failure.
            Execute operation on resource 11 (Apply Configuration); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E"), Mandatory] public class Apply_Configuration_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10536.xml: Routing Table (urn:oma:lwm2m:x:10536) ═════════════════════════
        /**
        IP routing table management. Static routes, default gateway, policy-based routing, and route metrics.
        */
        class Routing_Table {
            public const ushort lwm2m_object_id          = 10536;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10536";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Destination network in CIDR notation or IP address (e.g., "192.168.1.0/24", "0.0.0.0/0" for default route, or
            "2001:db8::/32" for IPv6). Supports both IPv4 and IPv6 addressing. Use "default" or "0.0.0.0/0" for the
            default gateway route. This defines the target network or host that this routing entry will match.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Destination_Network;

            /**
            Network mask in dotted-decimal notation (e.g., "255.255.255.0") or prefix length (e.g., "24"). For IPv4, valid
            netmasks range from /0 to /32. For IPv6, valid prefixes range from /0 to /128. If the Destination Network
            resource uses CIDR notation, this resource is optional and will be derived automatically. Used to define the
            subnet size for the routing entry.
            */
            [ResourceId(1), Operations("RW")] string Netmask_Prefix;

            /**
            Next-hop gateway IP address for this route (e.g., "192.168.1.1" for IPv4 or "fe80::1" for IPv6). This is the
            IP address of the router or gateway that packets should be forwarded to in order to reach the destination
            network. Optional for directly connected networks. Leave empty or set to "0.0.0.0" for on-link routes.
            */
            [ResourceId(2), Operations("RW")] string Gateway;

            /**
            Network interface name through which the route is accessible (e.g., "eth0", "eth1", "wlan0", "br-lan"). Must
            be a valid interface name present on the system. This specifies the physical or virtual network interface that
            will be used to forward packets to the destination or gateway. Maximum length: 16 characters.
            */
            [ResourceId(3), Operations("RW"), Mandatory] string Interface;

            /**
            Route metric/priority value (range: 0-65535). Lower values indicate higher priority routes. When multiple
            routes exist to the same destination, the route with the lowest metric is preferred. Default value is
            typically 0 or 100. Used for route selection and failover scenarios. Essential for implementing redundant
            paths and load balancing.
            */
            [ResourceId(4), Operations("RW")] ushort? Metric;

            /**
            Route protocol/origin identifier (read-only): 0=Unspecified, 1=ICMP Redirect, 2=Kernel (added by kernel during
            autoconfiguration), 3=Boot (added during system boot), 4=Static (manually configured static route), 5=DHCP
            (received via DHCP). Indicates how the route was learned or configured. Useful for route filtering and policy
            decisions.
            */
            [MinMax(0, 5), ResourceId(5), Operations("R"), Mandatory] byte Protocol;

            /**
            Current route state (read-only): 0=Down (route is inactive or interface is down), 1=Up (route is active and
            operational), 2=Unreachable (destination is unreachable due to network conditions). Automatically updated
            based on kernel routing table status and interface state. Monitor this resource to detect routing failures or
            network connectivity issues.
            */
            [MinMax(0, 2), ResourceId(6), Operations("R"), Mandatory] byte State;

            /**
            Routing table ID for policy-based routing (range: 0-255). Common values: 254=Main routing table (default),
            255=Local routing table (link-local routes), 1-253=Custom routing tables for policy-based routing. Allows
            implementation of advanced routing policies where different routing tables are selected based on source
            address, interface, or other criteria. See /etc/iproute2/rt_tables for table name mappings.
            */
            [ResourceId(7), Operations("RW")] byte? Table;

            /**
            Route scope defining the distance to the destination: 0=Global (route to destinations beyond the local
            network, requires gateway), 253=Link (route valid only on directly attached network segment, no gateway
            needed), 254=Host (route to a local host address). Scope affects route selection and determines whether a
            gateway is required. Default is Global (0) for most routes.
            */
            [MinMax(0, 254), ResourceId(8), Operations("RW")] byte? Scope;

            /**
            Maximum Transmission Unit in bytes for this route (range: 68-65535). Defines the largest packet size that can
            be transmitted without fragmentation. Default is typically 1500 for Ethernet. Smaller values may be needed for
            tunnels, VPNs, or networks with MTU constraints. Setting this value overrides the interface default MTU for
            packets using this route. Useful for Path MTU Discovery optimization.
            */
            [MinMax(68, 65535), ResourceId(9), Operations("RW"), Units("B")] ushort? MTU;

            /**
            Execute this resource to add the configured route to the kernel routing table. Uses the 'ip route add' command
            to create the route based on the configured destination, netmask, gateway, interface, metric, table, and other
            parameters. If the route already exists, the operation will succeed without modification. Optionally saves the
            route to UCI configuration for persistence across reboots. After execution, check the State resource to verify
            the route was added successfully (State=1).
            Execute operation on resource 10 (Add Route); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E"), Mandatory] public class Add_Route_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to remove the configured route from the kernel routing table. Uses the 'ip route del'
            command to delete the route matching the configured destination network and table ID. If the route does not
            exist, the operation will succeed without error. The route will remain in the instance configuration but will
            be marked as State=0 (Down). To permanently remove the route, delete the LwM2M object instance after executing
            this resource.
            Execute operation on resource 11 (Delete Route); sent by the Server to the Client.
            */
            [ResourceId(11), Operations("E"), Mandatory] public class Delete_Route_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to flush (remove) all routes from the specified routing table. Uses the 'ip route flush
            table &lt;table_id&gt;' command to clear all entries from the routing table specified in the Table resource.
            WARNING: This is a destructive operation that will remove all routes in the table, potentially causing loss of
            network connectivity. Use with caution, especially on the main routing table (254). Typically used for table
            cleanup or before applying a complete new routing configuration.
            Execute operation on resource 12 (Flush Routes); sent by the Server to the Client.
            */
            [ResourceId(12), Operations("E")] public class Flush_Routes_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to reload and synchronize the instance's route configuration from the kernel routing
            table. Uses the 'ip route show' command to query current routes and updates all resource values (destination,
            gateway, interface, metric, state, etc.) to match the kernel state. Useful for detecting external changes to
            the routing table made by other processes or for recovering from synchronization errors. Does not modify the
            kernel routing table, only updates the LwM2M object instance to reflect current reality.
            Execute operation on resource 13 (Reload Routes); sent by the Server to the Client.
            */
            [ResourceId(13), Operations("E")] public class Reload_Routes_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10537.xml: VPN Configuration (urn:oma:lwm2m:x:10537) ═════════════════════════
        /**
        VPN tunnel configuration. OpenVPN, WireGuard, IPsec support with connection management and status monitoring.
        */
        class VPN_Configuration {
            public const ushort lwm2m_object_id          = 10537;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10537";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Unique identifier for this VPN connection (e.g., "corporate_vpn", "home_vpn"). Used to distinguish between
            multiple VPN instances and for configuration file naming. Must be unique across all VPN instances on the
            device.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string VPN_Name;

            /**
            VPN protocol to use: 0=OpenVPN (SSL/TLS-based, widely compatible, good for restrictive networks), 1=WireGuard
            (modern, fast, lightweight, excellent mobile support), 2=IPsec/IKEv2 (industry standard, native support on
            many devices, good for site-to-site). Protocol selection affects available authentication methods and
            performance characteristics.
            */
            [MinMax(0, 2), ResourceId(1), Operations("RW"), Mandatory] byte Protocol_Type;

            /**
            VPN server hostname or IP address (IPv4 or IPv6). Can be a fully qualified domain name (e.g.,
            "vpn.example.com") or direct IP address (e.g., "203.0.113.1"). The client will establish a VPN tunnel to this
            endpoint.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string Server_Address;

            /**
            VPN server port number (1-65535). Common defaults: OpenVPN=1194 (UDP) or 443 (TCP), WireGuard=51820, IPsec=500
            (IKE) and 4500 (NAT-T). Port selection may be constrained by firewall rules and network policies.
            */
            [MinMax(1, 65535), ResourceId(3), Operations("RW"), Mandatory] ushort Server_Port;

            /**
            Local IP address assigned to the VPN tunnel interface (read-only). This is the virtual IP address assigned by
            the VPN server and used for routing traffic through the tunnel. Automatically populated when the VPN
            connection is established. Format: IPv4 or IPv6 address with optional CIDR prefix.
            */
            [ResourceId(4), Operations("R")] string Local_Address;

            /**
            Remote network address in CIDR notation (e.g., "10.0.0.0/8", "192.168.1.0/24"). Specifies which destination
            networks should be routed through the VPN tunnel. For split tunneling, set this to specific subnets. For full
            tunnel, use "0.0.0.0/0" (all IPv4) or "::/0" (all IPv6). Can specify multiple networks separated by commas.
            */
            [ResourceId(5), Operations("RW")] string Remote_Network;

            /**
            Authentication method: 0=Password (username/password authentication, simple but less secure), 1=Certificate
            (X.509 certificate-based, strongest security for OpenVPN/IPsec), 2=PSK (Pre-Shared Key, simple symmetric key
            authentication for IPsec), 3=Public Key (public key authentication, used for WireGuard). The chosen method
            determines which credential resources (Username, Password, Certificate, Keys) must be configured.
            */
            [MinMax(0, 3), ResourceId(6), Operations("RW"), Mandatory] byte Authentication_Type;

            /**
            Username for password-based authentication. Required when Authentication Type is set to Password (0). Used in
            combination with the Password resource for OpenVPN user authentication or IPsec EAP authentication.
            */
            [ResourceId(7), Operations("RW")] string Username;

            /**
            Password for password-based authentication. Required when Authentication Type is set to Password (0). Should
            be stored securely and transmitted over encrypted channels. Used with Username for VPN server authentication.
            */
            [ResourceId(8), Operations("RW")] string Password;

            /**
            X.509 client certificate in PEM format. Required when Authentication Type is set to Certificate (1). Used for
            OpenVPN or IPsec certificate-based authentication. Should include the full certificate chain from -----BEGIN
            CERTIFICATE----- to -----END CERTIFICATE-----, including any intermediate CA certificates.
            */
            [ResourceId(9), Operations("RW")] string Certificate;

            /**
            Private key in PEM format. For certificate authentication (OpenVPN/IPsec), this is the RSA/ECDSA private key
            corresponding to the client certificate. For WireGuard, this is the WireGuard private key (base64-encoded).
            Must be kept strictly confidential. Format: -----BEGIN PRIVATE KEY----- to -----END PRIVATE KEY----- (or
            WireGuard base64 string).
            */
            [ResourceId(10), Operations("RW")] string Private_Key;

            /**
            Public key (read-only). For WireGuard, this is the client's public key (base64-encoded), automatically derived
            from the private key. This value should be provided to the VPN server administrator for peer configuration.
            For other protocols, this field may be empty or contain the public key extracted from the certificate.
            */
            [ResourceId(11), Operations("R")] string Public_Key;

            /**
            Pre-Shared Key for PSK authentication or additional security. For IPsec, this is the shared secret used for
            PSK authentication. For WireGuard, this is an optional additional symmetric key for post-quantum security.
            Should be a strong random string, typically 32+ characters or base64-encoded binary data.
            */
            [ResourceId(12), Operations("RW")] string Pre_Shared_Key;

            /**
            Current VPN connection state (read-only): 0=Disconnected (VPN is not active), 1=Connecting (VPN is attempting
            to establish connection), 2=Connected (VPN tunnel is active and operational), 3=Disconnecting (VPN is shutting
            down), 4=Error (VPN encountered an error, check Last Error resource), 5=Reconnecting (VPN is attempting to
            re-establish connection after interruption). Monitor this resource to track VPN status.
            */
            [MinMax(0, 5), ResourceId(13), Operations("R"), Mandatory] byte Connection_State;

            /**
            Total number of bytes transmitted through the VPN tunnel (read-only). Cumulative counter that increments as
            data is sent through the VPN interface. Useful for monitoring VPN usage, bandwidth consumption, and detecting
            abnormal traffic patterns. Counter resets when the VPN connection is terminated.
            */
            [ResourceId(14), Operations("R"), Units("B")] long? Bytes_Sent;

            /**
            Total number of bytes received through the VPN tunnel (read-only). Cumulative counter that increments as data
            is received through the VPN interface. Useful for monitoring VPN usage, bandwidth consumption, and network
            activity analysis. Counter resets when the VPN connection is terminated.
            */
            [ResourceId(15), Operations("R"), Units("B")] long? Bytes_Received;

            /**
            VPN connection uptime in seconds (read-only). Duration for which the current VPN connection has been active
            and operational. Resets to 0 when the VPN disconnects or reconnects. Useful for monitoring connection
            stability and calculating availability metrics.
            */
            [ResourceId(16), Operations("R"), Units("s")] DurationInSeconds? Uptime;

            /**
            Description of the last error encountered (read-only). Contains a human-readable error message when the
            Connection State is Error (4) or when the last connection attempt failed. Common errors include:
            authentication failure, network unreachable, certificate validation errors, timeout. Empty string when no
            error has occurred. Check this resource when troubleshooting connection issues.
            */
            [ResourceId(17), Operations("R")] string Last_Error;

            /**
            Keepalive packet interval in seconds (1-300). The VPN client sends keepalive packets at this interval to
            maintain the connection through NAT gateways and firewalls, and to detect connection loss. Lower values
            provide faster detection of connection failures but increase network overhead. Typical values: 10-25 seconds.
            For WireGuard, this is the persistent keepalive interval. For OpenVPN, this affects ping/keepalive settings.
            */
            [ResourceId(18), Operations("RW"), Units("s")] DurationInSeconds? Keepalive_Interval;

            /**
            Delay before automatic reconnection attempt in seconds (5-600). When the VPN connection is lost unexpectedly,
            the client will wait this duration before attempting to reconnect. Prevents rapid reconnection loops and
            allows time for network issues to resolve. Typical values: 30-60 seconds. Exponential backoff may be applied
            after multiple failed attempts.
            */
            [ResourceId(19), Operations("RW"), Units("s")] DurationInSeconds? Reconnect_Delay;

            /**
            Enable split tunneling mode. When enabled (true), only traffic destined for the Remote Network is routed
            through the VPN tunnel; all other traffic uses the default internet connection. When disabled (false), all
            traffic is routed through the VPN (full tunnel mode). Split tunneling improves performance for general
            internet access while protecting access to specific remote networks. Requires proper Remote Network
            configuration.
            */
            [ResourceId(20), Operations("RW")] bool? Split_Tunnel;

            /**
            Enable VPN kill switch functionality. When enabled (true), all network traffic (except VPN traffic) is blocked
            if the VPN connection fails or disconnects, preventing accidental data leaks. When disabled (false), network
            traffic continues using the default route if VPN fails. Kill switch is implemented using firewall rules
            (iptables/nftables) to ensure no traffic bypasses the VPN when it should be active. Critical for privacy and
            security-sensitive applications.
            */
            [ResourceId(21), Operations("RW")] bool? Kill_Switch;

            /**
            Execute this resource to establish the VPN connection. Validates configuration, saves settings to UCI,
            generates protocol-specific configuration files, and initiates the VPN tunnel. The Connection State resource
            will change to Connecting (1) and then Connected (2) upon success, or Error (4) upon failure. Check Last Error
            resource if connection fails. Automatically applies kill switch and split tunnel settings if configured.
            Execute operation on resource 22 (Connect); sent by the Server to the Client.
            */
            [ResourceId(22), Operations("E"), Mandatory] public class Connect_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to terminate the VPN connection. Gracefully shuts down the VPN tunnel, removes kill
            switch firewall rules, clears routing table entries, and stops the VPN client process. The Connection State
            resource will change to Disconnecting (3) and then Disconnected (0). Safe to execute even if VPN is not
            connected. Traffic statistics (Bytes Sent, Bytes Received, Uptime) are reset to zero.
            Execute operation on resource 23 (Disconnect); sent by the Server to the Client.
            */
            [ResourceId(23), Operations("E"), Mandatory] public class Disconnect_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to restart the VPN connection. Performs a full disconnect followed by reconnect
            sequence. Useful for applying configuration changes, recovering from connection issues, or refreshing
            credentials. Equivalent to executing Disconnect followed by Connect, but handled atomically. The connection
            will briefly enter Disconnecting (3) and Disconnected (0) states before transitioning to Connecting (1) and
            Connected (2).
            Execute operation on resource 24 (Restart); sent by the Server to the Client.
            */
            [ResourceId(24), Operations("E")] public class Restart_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Execute this resource to generate new cryptographic keys. For WireGuard, generates a new private/public key
            pair and updates the Private Key and Public Key resources. The new public key must be provided to the VPN
            server administrator for peer configuration. For other protocols, this operation may not be supported. Useful
            for key rotation and security maintenance. The VPN should be disconnected before regenerating keys to avoid
            connection disruption.
            Execute operation on resource 25 (Regenerate Keys); sent by the Server to the Client.
            */
            [ResourceId(25), Operations("E")] public class Regenerate_Keys_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10538.xml: Acceleration Tamper Alarm (urn:oma:lwm2m:x:10538) ═════════════════════════
        /**
        This alarm is raised when acceleration is detected by e.g. an accelerometer
        */
        class Acceleration_Tamper_Alarm {
            public const ushort lwm2m_object_id          = 10538;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10538";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            Event Type is a readable and writable resource used to represent how this event will behave. Event Type should
            be one of the following values:-
            0. Disabled
            1. Alarm Current State
            2. Alarm State Change Log
            3. Event Log
            When the Event Type is set to Disabled (0), this event will not be recorded by the device. No Latest Eventlog
            payload should be delivered for events that are Disabled.
            When the Event Type is set to Alarm Current State (1), this Event is treated as an alarm state manager and the
            Latest Eventlog Payload will only contain the current state of this alarm.
            When the Event Type is set to Alarm State Change Log (2), the Event is treated as an alarm that reports
            whenever the Alarm is either set or cleared. The Latest Eventlog Payload will contain all alarm transitions
            since the previous delivery in this mode.
            When the Event Type is set to Event Log (3), this object instance is treated as a raw event log. It is used to
            manage and deliver events. The Latest Eventlog Payload will contain all events since the previous delivery in
            this mode.
            See the Event Log Payload for examples of each of these modes.
            */
            [ResourceId(6011), Operations("RW"), Mandatory] long Event_Type;

            /**
            Realtime is a readable and writable resource used to indicate if an event should report immediately (1) at the
            point of occurrence, or delivered periodically as part of the Latest Eventlog Payload.
            */
            [ResourceId(6012), Operations("RW"), Mandatory] bool Alarm_Realtime;

            /**
            Alarm State is a read-only resource used to indicate the current alarm state for this Event configuration.
            This is only applicable if the Event Type is Alarm Current State (1) or Alarm State Change (2).
            */
            [ResourceId(6013), Operations("R")] bool? Alarm_State;

            /**
            Set Threshold is a readable and writable resource used to represent the threshold for when an alarm is
            triggered. This resource is used in conjunction with the Set Operator resource.
            */
            [ResourceId(6014), Operations("RW")] double? Alarm_Set_Threshold;

            /**
            Set Operator is a readable and writable resource used in conjunction with the Set Threshold to represent when
            an alarm is triggered. This resource should be set to one of the following values:-
            0. Greater Than or Equal to
            1. Less Than or Equal to
            By setting the Set Operator to Greater Than (0), when the measured value for this event exceeds the Set
            Threshold resource, the event is considered to be in an Alarm State of 1
            By setting the Set Operator to Less Than (1), when the measured value for this event falls below the Set
            Threshold resource, the event is considered to be in an Alarm State of 1
            */
            [ResourceId(6015), Operations("RW")] long? Alarm_Set_Operator;

            /**
            Clear Threshold is a readable and writable resource used to represent the threshold for when an alarm is
            cleared. This resource is used in conjunction with the Clear Operator resource.
            */
            [ResourceId(6016), Operations("RW")] double? Alarm_Clear_Threshold;

            /**
            Clear Operator is a readable and writable resource used in conjunction with the Clear Threshold to represent
            when an alarm is Cleared. This resource should be set to one of the following values:-
            0. Greater Than or Equal to
            1. Less Than or Equal to
            By setting the Clear Operator to Greater Than (0), when the measured value for this event exceeds the Clear
            Threshold resource, the event is considered to be in an Alarm State of 0
            By setting the Clear Operator to Less Than (1), when the measured value for this event falls below the Clear
            Threshold resource, the event is considered to be in an Alarm State of 0
            */
            [ResourceId(6017), Operations("RW")] long? Alarm_Clear_Operator;

            /**
            Maximum Event Count is a readable and writable resource used provide a ceiling on the number of events that
            can be raised within the time period defined in Maximum Event Period resource. If no Maximum Event Count is
            set, the number of events recorded is unconstrained. The intent of this resource is to control the number of
            events reported, particularly in the case of a faulty sensor.
            */
            [ResourceId(6018), Operations("RW")] long? Alarm_Maximum_Event_Count;

            /**
            Maximum Event Period is a readable and writable resource used in conjunction with the Maximum Event Count
            resource to control the number of events that can be raised in a given period. Maximum Event Period is an
            integer value representing the number of seconds for which the Maximum Event Count is measured. If no Maximum
            Event Period is set, the number of events recorded is unconstrained. The intent of this resource is to control
            the number of events reported, particularly in the case of a faulty sensor.
            */
            [ResourceId(6019), Operations("RW"), Units("s")] DurationInSeconds? Alarm_Maximum_Event_Period;

            /**
            Latest Delivered Event Time is a readable and writable resource to represent the last recorded time that an
            event was delivered for this event code to the LwM2M server. The setting of this resource is implementation
            specific but should be updated based on, either a Read request of the Latest Eventlog Payload from the LwM2M
            server or via a confirmed delivery of Notify operation of the Latest Eventlog Payload resource. This resource
            is writable to allow the server to adjust the Last Delivered Event Time value if the server and client is out
            of sync.
            */
            [ResourceId(6020), Operations("RW")] DateTime? Latest_Delivered_Event_Time;

            /**
            Latest Recorded Event Time is a readonly resource used to represent the last recorded event time for this
            object instance on the device
            */
            [ResourceId(6021), Operations("R"), Mandatory] DateTime Latest_Recorded_Event_Time;

            /**
            Auto Clear Alarm is a readable and writable resource used to indicate if an alarm is automatically cleared
            once the delivery of the event data payload is complete
            */
            [ResourceId(6023), Operations("RW")] bool? Alarm_Auto_Clear;

            /**
            Event Code is a read-only resource used as an identifier to represent this class of event. The allocation of
            event codes is implementation specific but ideally be unique across the implementation. Event Codes use vendor
            specific LogClass value 100...255
            */
            [MinMax(100, 255), ResourceId(6024), Operations("R"), Mandatory] byte Event_Code;

            /**
            The Latest Eventlog Payload resource is a read-only serialised Opaque (Binary) representation of all the Event
            Data between the Last Delivered Event Time and the Latest Recorded Event Time. When this payload is delivered
            to the LwM2M server, via either a read request or a confirmed observation on this Object, Object Instance or
            Resource, the Latest Delivered Interval should be updated. When no new data exists, an empty Opaque value
            should be provided.
            The payload data can be provided in an implementation specific serialisation, but by default for fixed length
            values should use the OMA-LwM2M CBOR format encoded with one of these schemes:-
            Event Type = Alarm Current State (1)
            In this mode, only the current alarm state should be reported
            1. 8-bit integer, value 2 representing OMA-LwM2M CBOR format.
            2. Event Code [16-bit integer]
            3. Event Type [8-bit Integer] - Alarm Current State (1)
            4. Alarm Timestamp [32-bit unsigned integer] representing the number of seconds since Jan 1st, 1970 in the UTC
            time zone.
            5. Alarm State [8-bit Integer]
            */
            [D(65535), ResourceId(6025), Operations("R"), Mandatory] Binary[,,] Latest_Payload;

            /**
            Clear Alarm is an executable resource used to allow the LwM2M server to clear alarms when they need to be
            manually acknowledged.
            Execute operation on resource 6022 (Alarm Clear); sent by the Server to the Client.
            */
            [ResourceId(6022), Operations("E")] public class Alarm_Clear_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 10539.xml: Modem Firmware Update (urn:oma:lwm2m:x:10539) ═════════════════════════
        /**
        Modem firmware update object.
        */
        class Modem_Firmware_Update {
            public const ushort lwm2m_object_id          = 10539;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:10539";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            Firmware package
            */
            [D(65535), ResourceId(0), Operations("W"), Mandatory] Binary[,,] Package;

            /**
            URI from where the device can download the firmware package by an alternative mechanism. As soon the device
            has received the Package URI it performs the download at the next practical opportunity.
            The URI format is defined in RFC 3986. For example, coaps://example.org/firmware is a syntactically valid URI.
            The URI scheme determines the protocol to be used. For CoAP this endpoint MAY be a LwM2M Server but does not
            necessarily need to be. A CoAP server implementing block-wise transfer is sufficient as a server hosting a
            firmware repository and the expectation is that this server merely serves as a separate file server making
            firmware images available to LwM2M Clients.
            */
            [D(+255), ResourceId(1), Operations("RW"), Mandatory] string Package_URI;

            /**
            Indicates current state with respect to this firmware update. This value is set by the LwM2M Client.
            0: Idle (before downloading or after successful updating)
            1: Downloading (The data sequence is on the way)
            2: Downloaded
            3: Updating
            If writing the firmware package to Package Resource has completed, or, if the device has downloaded the
            firmware package from the Package URI the state changes to Downloaded.
            Writing an empty string to Package URI Resource or setting the Package Resource to NULL (‘\0’), resets the
            Firmware Update State Machine: the State Resource value is set to Idle and the Update Result Resource value is
            set to 0.
            The device should remove the downloaded firmware image when the state is reset to Idle.
            When in Downloaded state, and the executable Resource Update is triggered, the state changes to Updating if
            the update starts immediately. For devices that support a user interface and the deferred update
            functionality, the user may be allowed to defer the firmware update to a later time. In this case, the state
            stays in Downloaded state and the Update Result is set to 11. Once a user accepted the firmware update, the
            state changes to Updating.
            When the user deferred the update, the device will continue operations normally until the user approves the
            firmware update or an automatic update starts. It will not block any operation on the device.
            If the Update Resource failed, the state may return to either Downloaded or Idle depending on the underlying
            reason of update failure, e.g. Integrity Check Failure results in the client moving to the Idle state.
            If performing the Update or Cancel operation was successful, the state changes to Idle.
            The firmware update state machine is illustrated in the respective LwM2M specification.
            */
            [MinMax(0, 3), ResourceId(3), Operations("R"), Mandatory] byte State;

            /**
            Contains the result of downloading or updating the firmware
            0: Initial value. Once the updating process is initiated (Download /Update), this Resource MUST be reset to
            Initial value.
            1: Firmware updated successfully.
            2: Not enough flash memory for the new firmware package.
            3: Out of RAM during downloading process.
            4: Connection lost during downloading process.
            5: Integrity check failure for new downloaded package.
            6: Unsupported package type.
            7: Invalid URI.
            8: Firmware update failed.
            9: Unsupported protocol. A LwM2M client indicates the failure to retrieve the firmware image using the URI
            provided in the Package URI resource by writing the value 9 to the /5/0/5 (Update Result resource) when the
            URI contained a URI scheme unsupported by the client. Consequently, the LwM2M Client is unable to retrieve the
            firmware image using the URI provided by the LwM2M Server in the Package URI when it refers to an unsupported
            protocol.
            10: Firmware update cancelled. A Cancel operation has been executed successfully.
            11: Firmware update deferred.
            */
            [MinMax(0, 11), ResourceId(5), Operations("R"), Mandatory] byte Update_Result;

            /**
            Name of the Firmware Package
            */
            [D(+255), ResourceId(6), Operations("R")] string PkgName;

            /**
            Version of the Firmware package
            */
            [D(+255), ResourceId(7), Operations("R")] string PkgVersion;

            /**
            This resource indicates what protocols the LwM2M Client implements to retrieve firmware images. The LwM2M
            server uses this information to decide what URI to include in the Package URI. A LwM2M Server MUST NOT include
            a URI in the Package URI object that uses a protocol that is unsupported by the LwM2M client.
            For example, if a LwM2M client indicates that it supports CoAP and CoAPS then a LwM2M Server must not provide
            an HTTP URI in the Packet URI.
            The following values are defined by this version of the specification:
            0: CoAP (as defined in RFC 7252) with the additional support for block-wise transfer. CoAP is the default
            setting.
            1: CoAPS (as defined in RFC 7252) with the additional support for block-wise transfer
            2: HTTP 1.1 (as defined in RFC 7230)
            3: HTTPS 1.1 (as defined in RFC 7230)
            4: CoAP over TCP (as defined in RFC 8323)
            5: CoAP over TLS (as defined in RFC 8323)
            Additional values MAY be defined in the future. Any value not understood by the LwM2M Server MUST be ignored.
            */
            [MinMax(0, 5), ResourceId(8), Operations("R")] byte[,,] Firmware_Update_Protocol_Support;

            /**
            The LwM2M Client uses this resource to indicate its support for transferring firmware images to the client
            either via the Package Resource (=push) or via the Package URI Resource (=pull) mechanism.
            0: Pull only
            1: Push only
            2: Both. In this case the LwM2M Server MAY choose the preferred mechanism for conveying the firmware image to
            the LwM2M Client.
            */
            [MinMax(0, 2), ResourceId(9), Operations("R"), Mandatory] byte Firmware_Update_Delivery_Method;

            /**
            Determines if the Firmware Upgrade will proceed automatically when the firmware download has completed. Value
            true means that the server does not need to instruct the device to proceed with the firmware upgrade when the
            firmware download is complete. Value false means that the server will have to instruct the device to proceed
            with the firmware upgrade when the firmware download is complete. When this is set to false, the server will
            use the Update resource to trigger the upgrade.
            */
            [ResourceId(14), Operations("R")] bool? Automatic_Upgrade_at_Download;

            /**
            Updates firmware by using the firmware package stored in Package, or, by using the firmware downloaded from
            the Package URI.
            This Resource is only executable when the value of the State Resource is Downloaded.
            Execute operation on resource 2 (Update); sent by the Server to the Client.
            */
            [ResourceId(2), Operations("E"), Mandatory] public class Update_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        // ═════════════════════════ 18830.xml: MQTT Broker (urn:oma:lwm2m:x:18830) ═════════════════════════
        /**
        This LwM2M Object provides the information to connect to an MQTT Broker i.e. URI, configuration, and keying
        material.
        */
        class MQTT_Broker {
            public const ushort lwm2m_object_id          = 18830;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:18830";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            URI of the MQTT broker.
            */
            [ResourceId(0), Operations("RW"), Mandatory] string URI;

            /**
            MQTT Client Identifier to use when connecting to this MQTT broker.
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Client_Identifier;

            /**
            The Clean Session value to declare in the MQTT CONNECT message.
            */
            [ResourceId(2), Operations("RW"), Mandatory] bool Clean_Session;

            /**
            The Keep Alive value to declare in the MQTT CONNECT message.
            */
            [ResourceId(3), Operations("RW"), Units("s"), Mandatory] ushort Keep_Alive;

            /**
            The User Name to declare in the MQTT CONNECT message.
            */
            [ResourceId(4), Operations("RW")] string User_Name;

            /**
            The Password value to declare in the MQTT CONNECT message.
            */
            [D(65535), ResourceId(5), Operations("RW")] Binary[,,] Password;

            /**
            Determines which security mode is used
            0: PreShared Key mode
            1: Raw Public Key mode
            2: Certificate mode
            3: NoSec mode
            4: Certificate mode with EST
            */
            [MinMax(0, 4), ResourceId(6), Operations("RW"), Mandatory] byte Security_Mode;

            /**
            Stores the Device’s certificate, public key (RPK mode) or PSK Identity (PSK mode).
            */
            [D(65535), ResourceId(7), Operations("RW")] Binary[,,] Public_Key_or_Identity;

            /**
            Stores the MQTT Broker’s certificate, public key (RPK mode) or trust anchor. The Certificate Usage Resource
            determines the content of this resource.
            */
            [D(65535), ResourceId(8), Operations("RW")] Binary[,,] MQTT_Broker_Public_Key;

            /**
            Stores the secret key (PSK mode) or private key (RPK or certificate mode).
            */
            [D(65535), ResourceId(9), Operations("W")] Binary[,,] Secret_Key;

            /**
            The Certificate Usage Resource specifies the semantic of the certificate or raw public key stored in the "MQTT
            Broker Public Key" Resource, which is used to match the certificate presented in the TLS/DTLS handshake. The
            currently defined values are:
            0: CA constraint
            1: service certificate constraint
            2: trust anchor assertion
            3: domain-issued certificate
            When this Resource is absent, value (3) for domain issued certificate mode is assumed.
            */
            [MinMax(0, 3), ResourceId(10), Operations("RW")] byte? Certificate_Usage;
        }

        // ═════════════════════════ 18831.xml: MQTT Publication (urn:oma:lwm2m:x:18831) ═════════════════════════
        /**
        This LwM2M Object is used to configure data reporting over MQTT.
        */
        class MQTT_Publication {
            public const ushort lwm2m_object_id          = 18831;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:18831";
            public const string lwm2m_version            = "1.1";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = true;
            public const bool   lwm2m_mandatory          = false;

            /**
            The source of the data to publish (e.g. &lt;/sensors/temp&gt;, or &lt;/3303/0/5700&gt;; &lt;/3336/0&gt;). If
            this Resource is empty, the published data are implementation dependent.
            */
            [D(+4096), ResourceId(0), Operations("RW"), Mandatory] string Source;

            /**
            A link to the MQTT Broker Object Instance (OMNA registered Object ID:18830) describing the MQTT Broker to use.
            */
            [ResourceId(1), Operations("RW"), Mandatory] ObjectLink Broker;

            /**
            The MQTT topic to publish to.
            */
            [ResourceId(2), Operations("RW"), Mandatory] string Topic;

            /**
            The Quality of Service value to use when publishing.
            */
            [MinMax(0, 2), ResourceId(3), Operations("RW"), Mandatory] byte QoS;

            /**
            The RETAIN flag value to use when publishing.
            */
            [ResourceId(4), Operations("RW"), Mandatory] bool Retain;

            /**
            If true or if the Resource is not present, the Device publishes the data pointed by the Source Resource to the
            MQTT Broker pointed by the Broker Resource using the MQTT topic indicated in the Topic Resource. If false, the
            Device does nothing.
            */
            [ResourceId(5), Operations("RW")] bool? Active;

            /**
            A CoAP Content-Format value used to encode the data in the MQTT Publish message. If this Resource is not
            present or equal to 65535, the encoding of the data is implementation dependent.
            */
            [ResourceId(6), Operations("RW")] ushort? Encoding;
        }

        // ═════════════════════════ 32666.xml: Rick Roll (urn:oma:lwm2m:x:32666) ═════════════════════════
        /**
        This object provides a standard interface for delivering an unexpected musical experience to unsuspecting IoT
        device operators. When triggered, the device will never give you up, never let you down, never run around and
        desert you. Compliant devices MUST implement the Trigger Rick Roll resource and SHOULD display appropriate
        lyrics.
        Note: This object is provided in the spirit of RFC 3514 (The Evil Bit) and RFC 2549 (IP over Avian Carriers).
        Implementors are reminded that while RFC compliance is important, the target of a Rick Roll retains no
        recourse under any applicable telecommunications regulation. We could have told the target what we were going
        to do, but that would have been a lie.
        */
        class Rick_Roll {
            public const ushort lwm2m_object_id          = 32666;
            public const string lwm2m_urn                = "urn:oma:lwm2m:x:32666";
            public const string lwm2m_version            = "1.0";
            public const string lwm2m_object_version     = "1.0";
            public const bool   lwm2m_multiple_instances = false;
            public const bool   lwm2m_mandatory          = false;

            /**
            A compelling but deceptive description designed to lure the target into triggering the Rick Roll. Examples:
            "Click here for free firmware update", "Important security patch", "System diagnostic results".
            */
            [ResourceId(0), Operations("RW"), Mandatory] string Bait_Description;

            /**
            The URL to which the target will be redirected upon triggering. Default value: https://youtu.be/dQw4w9WgXcQ
            */
            [ResourceId(1), Operations("RW"), Mandatory] string Redirect_URL;

            /**
            The performing artist. This value is fixed and SHALL be "Rick Astley".
            */
            [ResourceId(2), Operations("R"), Mandatory] string Artist;

            /**
            The title of the song that will be played. This value is fixed and SHALL be "Never Gonna Give You Up".
            */
            [ResourceId(3), Operations("R"), Mandatory] string Song_Title;

            /**
            The year the song was released. This value is fixed and SHALL be 1987.
            */
            [Range("1987..1987"), ResourceId(4), Operations("R")] long? Release_Year;

            /**
            The cumulative number of times this device has successfully Rick Rolled a target since last power cycle. A
            high value indicates a particularly deceptive device.
            */
            [ResourceId(5), Operations("R")] uint? Roll_Count;

            /**
            The current lyric line being displayed or broadcast by the device. Implementations SHOULD cycle through all
            verses in order.
            */
            [ResourceId(6), Operations("R")] string Current_Lyric;

            /**
            When set to True, the device will automatically Rick Roll any new LwM2M client that registers with it.
            Default: False. Use responsibly.
            */
            [ResourceId(7), Operations("RW")] bool? Autoplay;

            /**
            Playback volume as a percentage. It is RECOMMENDED to always set this to 100 for maximum effect. Setting to 0
            is unsportsmanlike conduct.
            */
            [MinMax(0, 100), ResourceId(8), Operations("RW"), Units("/100")] byte? Volume;

            /**
            Executes the Rick Roll operation. Upon execution, the device SHALL redirect any connected display to the
            Redirect URL, play "Never Gonna Give You Up" at the configured Volume, increment the Roll Count by 1, and log
            the event with timestamp. The calling party will not have been given up, let down, run around, or deserted.
            Execute operation on resource 9 (Trigger Rick Roll); sent by the Server to the Client.
            */
            [ResourceId(9), Operations("E"), Mandatory] public class Trigger_Rick_Roll_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }

            /**
            Resets the Roll Count to zero. This operation does not undo any Rick Rolls that have already been delivered.
            Execute operation on resource 10 (Reset Roll Count); sent by the Server to the Client.
            */
            [ResourceId(10), Operations("E")] public class Reset_Roll_Count_Execute {
                /** Optional LwM2M Execute arguments, in the `<id>='<value>'` text form of the specification. */
                [D(+1024)] string? execute_arguments;
            }
        }

        /** One instance of a multiple-instance Opaque resource (a list element must be a pack, not a typedef of a collection). */
        class Blob {
            [D(65535)] Binary[,,] bytes;
        }

        // ═════════════════════════ elapsed-time aliases ═════════════════════════

        // LwM2M writes lifetimes, periods and timeouts as plain integers. AdHoc models an elapsed
        // duration natively: the alias fixes the step size, and the generator picks the narrowest
        // container that holds the range (expanding max to fill the allocated bytes).

        /** Elapsed duration, one step = 1 s. */
        class DurationInSeconds : Duration {
            public TimeSpan precision => TimeSpan.FromSeconds(1);
        }

        /** Elapsed duration, one step = 1 ms. */
        class DurationInMilliseconds : Duration {
            public TimeSpan precision => TimeSpan.FromMilliseconds(1);
        }

        /** Elapsed duration, one step = 1 min. */
        class DurationInMinutes : Duration {
            public TimeSpan precision => TimeSpan.FromMinutes(1);
        }

        /** Elapsed duration, one step = 1 h. */
        class DurationInHours : Duration {
            public TimeSpan precision => TimeSpan.FromHours(1);
        }

        // ═════════════════════════ topology ═════════════════════════

        // LwM2M has exactly two roles: the Server manages the Client (the device). Object instances travel in
        // both directions (Read / Write / Observe / Notify); Execute is always Server -> Client.

        // LwM2M Server (management side, Left)
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Server : Host { }

        // LwM2M Client (the device, Right)
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
